def _divisors(value: int) -> List[int]:
    return [d for d in range(1, value + 1) if value % d == 0]


def _normalize_scale(scale: str) -> str:
    text = str(scale).strip()
    if text.lower().endswith("b") or text.lower().endswith("m"):
        text = text[:-1] + text[-1].upper()
    for candidate in PAPER_SCALES:
        if candidate.lower() == text.lower():
            return candidate
    raise ValueError(
        f"未知的论文规模 {scale!r}；可选："
        + ", ".join(PAPER_SCALES)
    )


def _normalize_sparsity(sparsity: object) -> int:
    text = str(sparsity).strip().rstrip("%")
    try:
        value = int(text)
    except ValueError as error:
        raise ValueError(
            f"未知的稀疏度 {sparsity!r}；可选：0, 85, 95, 97"
        ) from error
    if value not in PAPER_SPARSITIES:
        raise ValueError(
            f"未知的稀疏度 {sparsity!r}；可选：0, 85, 95, 97"
        )
    return value


def parse_paper_cell_label(label: str) -> Tuple[str, int]:
    """解析 ``200M:95`` / ``200M@95`` / ``200M-95`` / ``200M/95``。"""

    text = str(label).strip()
    if not text:
        raise ValueError("--paper-cell 不能为空")
    parts = re.split(r"[:@/\s-]+", text, maxsplit=1)
    if len(parts) != 2:
        # 兼容 "200M95" 这种紧凑写法。
        match = re.fullmatch(r"([0-9.]+[MmBb])([0-9]{1,2})%?", text)
        if not match:
            raise ValueError(
                f"--paper-cell 格式应为 规模:稀疏度（如 200M:95），"
                f"收到 {label!r}"
            )
        parts = [match.group(1), match.group(2)]
    return _normalize_scale(parts[0]), _normalize_sparsity(parts[1])


def paper_cell(
    scale: str,
    sparsity: object,
    arch: str = "smelt",
) -> PaperCell:
    arch_name = str(arch).strip().lower()
    if arch_name not in PAPER_ARCHS:
        raise ValueError(
            f"论文网格只有 {', '.join(PAPER_ARCHS)}，收到 {arch!r}"
        )
    key = (
        arch_name,
        _normalize_scale(scale),
        _normalize_sparsity(sparsity),
    )
    if key not in PAPER_CELLS:
        raise ValueError(f"论文附录 A 中没有单元 {key}")
    return PAPER_CELLS[key]


def _analytic_param_counts(cfg: Config) -> Dict[str, int]:
    """按本实现的结构精确统计非 embedding 参数。

    total  = L * (attn + 2*norm + router + E * expert) + final_norm
    active = L * (attn + 2*norm + router + top_k * expert) + final_norm

    其中 attn = 2*D^2 + 2*D*kv_dim（q/out 各 D^2，k/v 各 D*kv_dim），
    expert = 3*D*H_exp（SwiGLU 的 gate_up 为 D×2H、down 为 H×D）。
    ``_analytic_param_count_roundtrip`` 在自测里与本实现的
    ``nn.Module`` 参数计数逐位核对。
    """

    dim = int(cfg.d_model)
    head_dim = dim // int(cfg.n_heads)
    kv_dim = int(cfg.effective_n_kv_heads) * head_dim
    layers = int(cfg.n_layers)
    experts = int(cfg.n_experts)
    top_k = int(cfg.top_k)
    hidden = int(cfg.expert_hidden)
    per_layer_fixed = (
        2 * dim * dim
        + 2 * dim * kv_dim
        + 2 * dim
        + experts * dim
    )
    expert_params = 3 * dim * hidden
    total = layers * (
        per_layer_fixed + experts * expert_params
    ) + dim
    active = layers * (
        per_layer_fixed + top_k * expert_params
    ) + dim
    return {
        "total": int(total),
        "active": int(active),
        "kv_dim": int(kv_dim),
        "head_dim": int(head_dim),
        "expert_params": int(expert_params),
    }


def _paper_base_head_geometry(hidden: int) -> Tuple[int, int, int]:
    """Baseline 的 head 几何（论文未披露，按可复现规则选定）。

    取 head_dim 最接近 64 的整除组合；KV 头数取 Q 头数的一半
    （2:1 GQA）。论文只要求 GQA 与 KV cache 匹配，没有给出
    head 维度；该选择写入 ``derived`` 字段并在审计中标注来源。
    """

    best: Optional[Tuple[int, int, int]] = None
    for n_heads in _divisors(int(hidden)):
        if n_heads < 2:
            continue
        head_dim = int(hidden) // n_heads
        if not 32 <= head_dim <= 128:
            continue
        score = (abs(head_dim - 64), -head_dim, n_heads)
        if best is None or score < best[0]:
            best = (score, n_heads, head_dim)
    if best is None:
        raise ValueError(
            f"H={hidden} 找不到 32≤head_dim≤128 的整除 head 几何"
        )
    n_heads = best[1]
    head_dim = best[2]
    n_kv_heads = max(1, n_heads // 2)
    return n_heads, n_kv_heads, n_kv_heads * head_dim


def _paper_smelt_head_geometry(
    hidden: int,
    target_kv_dim: int,
) -> Tuple[int, int, int]:
    """SMELT 的 head 几何：以论文报告的 KV 比例为第一目标。

    在 H 的整除 head 划分与 1..n_heads 的 KV 头数中搜索，优先
    最小化 ``|kv_dim / target - 1|``，其次让 head_dim 接近 64。
    不强制 n_heads 整除 n_kv_heads：论文没有披露 head 几何，
    预算匹配需要任意 GQA 比例（见 CausalSelfAttention.core 的
    均匀映射）。
    """

    best: Optional[Tuple[Tuple[float, int, int], int, int, int]] = None
    for n_heads in _divisors(int(hidden)):
        if n_heads < 2:
            continue
        head_dim = int(hidden) // n_heads
        if not 32 <= head_dim <= 128:
            continue
        for n_kv_heads in range(1, n_heads + 1):
            kv_dim = n_kv_heads * head_dim
            error = abs(kv_dim / float(target_kv_dim) - 1.0)
            score = (round(error, 6), abs(head_dim - 64), n_heads)
            if best is None or score < best[0]:
                best = (score, n_heads, n_kv_heads, kv_dim)
    if best is None:
        raise ValueError(
            f"H={hidden} 找不到可用的 GQA head 几何"
        )
    return best[1], best[2], best[3]


def _paper_expert_hidden(
    hidden: int,
    layers: int,
    experts: int,
    total_params: float,
    kv_dim: int,
    active_experts: int = 8,
) -> int:
    """由论文的总参数目标反解专家中间维（按 8 对齐）。

    论文未披露专家中间维；预算匹配把它作为自由量，这里按
    「总非 embedding 参数与论文一致」求解，取 8 的倍数。
    """

    dim = int(hidden)
    per_layer_fixed = (
        2 * dim * dim
        + 2 * dim * int(kv_dim)
        + 2 * dim
        + int(experts) * dim
    )
    budget = float(total_params) * 1e9
    raw = (
        budget - dim - int(layers) * per_layer_fixed
    ) / (int(layers) * int(experts) * 3 * dim)
    if not math.isfinite(raw) or raw < 8.0:
        return 8
    return int(round(raw / 8.0)) * 8


def _paper_config_kwargs(
    cell: PaperCell,
    n_heads: int,
    n_kv_heads: int,
    expert_hidden: int,
) -> Dict[str, object]:
    return {
        "seq_len": int(PAPER_PROTOCOL["context_length"]),
        "d_model": int(cell.hidden),
        "n_heads": int(n_heads),
        "n_kv_heads": int(n_kv_heads),
        "n_layers": int(cell.layers),
        "n_experts": int(cell.total_experts),
        "expert_hidden": int(expert_hidden),
        "top_k": int(cell.active_experts),
        "k1": int(cell.active_experts),
        "k2": int(cell.active_experts),
        "mode": cell.arch,
        "residual_scaling": "paper",
        # 论文的 1/r 循环残差语义以全局 residual_scale=1.0 为
        # 前提；显式改成其它值会再乘一次，必须在预设冲突检查
        # 中拒绝，而不能让 fidelity 仍报告架构忠实。
        "residual_scale": 1.0,
    }


def paper_preset(
    scale: str,
    sparsity: object,
    arch: str = "smelt",
) -> Dict[str, object]:
    """构造论文附录 A 某个单元的可运行配置（含推导量）。

    论文只披露 H、L、专家总数、top-8、循环布局与参数/预算目标；
    head 几何与专家中间维未披露，本函数按固定规则推导并记录在
    ``derived`` 中，同时给出与论文目标相比的 measured 值，供
    ``paper_fidelity_report`` 审计。返回值中的 ``config`` 可直接
    作为 ``Config(**config)`` 的输入。
    """

    cell = paper_cell(scale, sparsity, arch)
    base_cell = paper_cell(cell.scale, cell.sparsity, "base")
    base_n_heads, base_n_kv, base_kv_dim = _paper_base_head_geometry(
        base_cell.hidden
    )
    if cell.arch == "base":
        n_heads, n_kv_heads, kv_dim = (
            base_n_heads,
            base_n_kv,
            base_kv_dim,
        )
        kv_target = None
    else:
        if cell.kv_ratio is None:
            raise ValueError(f"{cell} 缺少 KV 比例")
        kv_target = int(round(cell.kv_ratio * base_kv_dim))
        n_heads, n_kv_heads, kv_dim = _paper_smelt_head_geometry(
            cell.hidden,
            kv_target,
        )
    expert_hidden = _paper_expert_hidden(
        cell.hidden,
        cell.layers,
        cell.total_experts,
        cell.total_params,
        kv_dim,
        active_experts=cell.active_experts,
    )
    config = _paper_config_kwargs(
        cell,
        n_heads,
        n_kv_heads,
        expert_hidden,
    )
    cfg = Config(**config)
    counts = _analytic_param_counts(cfg)
    flops = int(
        mode_cost_profile(cfg)["analytic_flops_per_token"]
    )
    return {
        "paper": PAPER_ID,
        "arch": cell.arch,
        "scale": cell.scale,
        "sparsity": cell.sparsity,
        "cell": cell,
        "config": config,
        "derived": {
            "n_heads": int(n_heads),
            "n_kv_heads": int(n_kv_heads),
            "head_dim": int(cell.hidden) // int(n_heads),
            "kv_dim": int(kv_dim),
            "base_kv_dim": int(base_kv_dim),
            "kv_target": kv_target,
            "expert_hidden": int(expert_hidden),
            "top_k": int(cell.active_experts),
            "context_length": int(cfg.seq_len),
            "loop_span_layers": (
                cfg.middle_start + 1,
                cfg.middle_end,
            ),
        },
        "measured": {
            "total_params": int(counts["total"]),
            "active_params": int(counts["active"]),
            "flops_per_token": flops,
        },
        "targets": {
            "total_params": float(cell.total_params),
            "active_params": float(cell.active_params),
            "flops_ratio": cell.flops_ratio,
            "kv_ratio": cell.kv_ratio,
            "compute_equivalent_sparsity": cell.measured_sparsity,
        },
    }


def paper_cell_for_config(cfg: Config) -> Optional[PaperCell]:
    """把运行配置映射回论文附录 A 的网格单元（匹配不到返回 None）。"""

    if cfg.mode not in PAPER_ARCHS:
        return None
    for cell in PAPER_CELLS.values():
        if cell.arch != cfg.mode:
            continue
        if (
            cell.hidden == int(cfg.d_model)
            and cell.layers == int(cfg.n_layers)
            and cell.total_experts == int(cfg.n_experts)
            and cell.active_experts == int(cfg.top_k)
        ):
            return cell
    return None


def _paper_budget_audit(
    cfg: Config,
    cell: PaperCell,
) -> Dict[str, object]:
    """把实测的 FLOPs / 总参数 / KV cache / S 与论文目标对照。

    论文附录 A 的参数化来自未公开的 Transformer family；本仓库
    实现（SwiGLU 专家、RMSNorm、学习式位置编码）只能保证公开
    披露量的结构一致，不能保证逐位相同的参数/FLOPs。该审计
    如实报告偏差，不据此伪装成数值复现。
    """

    counts = _analytic_param_counts(cfg)
    flops = int(
        mode_cost_profile(cfg)["analytic_flops_per_token"]
    )
    base_cfg = Config(
        **paper_preset(cell.scale, cell.sparsity, "base")["config"]
    )
    base_counts = _analytic_param_counts(base_cfg)
    base_flops = int(
        mode_cost_profile(base_cfg)["analytic_flops_per_token"]
    )
    control_cfg = Config(
        **paper_preset(cell.scale, 0, "base")["config"]
    )
    control_counts = _analytic_param_counts(control_cfg)
    control_flops = int(
        mode_cost_profile(control_cfg)["analytic_flops_per_token"]
    )
    flops_ratio = flops / base_flops
    kv_ratio = counts["kv_dim"] / base_counts["kv_dim"]
    sparsity = 1.0 - (
        flops / control_flops
    ) * (control_counts["total"] / counts["total"])
    total_ratio = counts["total"] / (cell.total_params * 1e9)
    active_ratio = counts["active"] / (
        cell.active_params * 1e9
    )
    within: Dict[str, Optional[bool]] = {
        "total_params_within_1pct": bool(
            abs(total_ratio - 1.0) <= 0.01
        ),
        "active_params_within_5pct": bool(
            abs(active_ratio - 1.0) <= 0.05
        ),
        "sparsity_within_2pp": bool(
            abs(sparsity - cell.measured_sparsity) <= 0.02
        ),
        "flops_ratio_within_4pct": (
            None
            if cell.flops_ratio is None
            else bool(abs(flops_ratio - cell.flops_ratio) <= 0.04)
        ),
        "kv_ratio_within_4pct": (
            None
            if cell.kv_ratio is None
            else bool(abs(kv_ratio - cell.kv_ratio) <= 0.04)
        ),
    }
    return {
        "measured": {
            "total_params": int(counts["total"]),
            "active_params": int(counts["active"]),
            "flops_per_token": int(flops),
            "flops_ratio_vs_base": float(flops_ratio),
            "kv_ratio_vs_base": float(kv_ratio),
            "compute_equivalent_sparsity": float(sparsity),
            "total_params_ratio_vs_paper": float(total_ratio),
            "active_params_ratio_vs_paper": float(active_ratio),
        },
        "paper": {
            "total_params": float(cell.total_params),
            "active_params": float(cell.active_params),
            "flops_ratio": cell.flops_ratio,
            "kv_ratio": cell.kv_ratio,
            "compute_equivalent_sparsity": cell.measured_sparsity,
        },
        "tolerances": {
            "total_params_relative": 0.01,
            "active_params_relative": 0.05,
            "flops_ratio_absolute": 0.04,
            "kv_ratio_absolute": 0.04,
            "sparsity_absolute": 0.02,
        },
        "within_paper_tolerance": within,
        "all_within_tolerance": all(
            value is not False for value in within.values()
        ),
        "note": (
            "论文附录 A 的参数化未公开；本实现的参数统计口径为"
            "「非 embedding 参数」，total/active 与 FLOPs 由"
            "本仓库结构精确计算，S 按论文 Eq.1 由实测 FLOPs "
            "与总参数推出。偏差不是实现缺陷的充分证据，也不"
            "能把偏差忽略后声称数值复现"
        ),
    }


def _paper_protocol_checks(
    protocol: Dict[str, object],
) -> Dict[str, bool]:
    saved_steps = list(
        protocol.get("save_at_steps") or []
    )
    stable = int(protocol.get("stable_steps", 0))
    steps = int(protocol.get("steps", stable))
    stable_target = int(PAPER_PROTOCOL["stable_steps"])
    decay_steps = int(PAPER_PROTOCOL["decay_steps"])
    branch_points = {
        int(step) for step in PAPER_PROTOCOL["branch_steps"]
    }
    # 稳定期跑满 196075 步；或者从六个分支点之一分叉、
    # 再跑满 10B token（9537 步）的 cosine-decay 分支。
    # 196075 本身也是合法分支点（从完整稳定期末端进入 decay），
    # 不能把这条分支误判成「缺少稳定期」的稳定训练。
    branch_run = (
        stable in branch_points
        and steps == stable + decay_steps
    )
    checks = {
        "protocol_wsd_schedule": (
            str(protocol.get("lr_schedule", "")) == "wsd"
        ),
        "protocol_batch_256": (
            int(protocol.get("batch_size", 0)) == 256
        ),
        "protocol_stable_phase": (
            stable == stable_target and steps == stable_target
        ),
        "protocol_decay_branch": bool(
            stable == stable_target or branch_run
        ),
        "protocol_document_masks": bool(
            protocol.get("document_masks")
        ),
        "protocol_branch_checkpoints": bool(
            branch_points.issubset(
                {int(step) for step in saved_steps}
            )
            or branch_run
        ),
    }
    if branch_run:
        # 分支运行本身不包含稳定期；稳定期由它的父运行负责，
        # 不能把「这条分支没跑稳定期」记成协议偏离。
        checks.pop("protocol_stable_phase")
    return checks


def paper_fidelity_report(
    cfg: Config,
    protocol: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """对照 arXiv:2609.01343v1 审计当前配置的复现保真度。

    复现分为两层：

    1. **recipe（架构 + 协议）**：论文正文/附录 A 明确披露的量，
       包括 H/L/专家数/top-8、middle-50% 循环两次的层位置、循环
       区域子层残差 1/r、GQA、4096 上下文，以及 3.1 节的 WSD
       协议、全局 batch 256、稳定期 196 075 步、六个分支点与
       文档级 segment attention mask。``architecture_faithful``
       与 ``protocol_faithful`` 分别给出结论，``is_full_reproduction``
       仅在两者都成立时为真。
    2. **budget（预算）**：论文 3.2 节要求 FLOPs / 总参数 / KV
       cache 三者匹配，但附录 A 的参数化来自未公开 family，
       本实现只能报告实测偏差（``budget_audit``），不把偏差
       忽略后声称数值复现。

    未被论文披露的学习率、warmup、weight decay、betas、均衡
    损失系数、初始化、head 几何、专家中间维与语料列在
    ``undisclosed`` 中；沿用本仓库默认值不等于论文原值。
    """

    cell = paper_cell_for_config(cfg)
    arch = cfg.mode if cfg.mode in PAPER_ARCHS else None
    loop_span = int(cfg.middle_end - cfg.middle_start)
    expected_start = int(cfg.n_layers - loop_span) // 2
    checks: Dict[str, bool] = {
        "paper_cell_config": cell is not None,
        "top_k_8": int(cfg.top_k) == 8,
        "gqa": (
            cfg.n_kv_heads is not None
            and int(cfg.effective_n_kv_heads) < int(cfg.n_heads)
        ),
        "context_4096": int(cfg.seq_len) == int(
            PAPER_PROTOCOL["context_length"]
        ),
        "loop_span_middle_half": (
            loop_span == int(cfg.n_layers) // 2
        ),
        "loop_placement_paper": (
            int(cfg.middle_start) == expected_start
            and loop_span == int(cfg.n_layers) // 2
        ),
    }
    if cfg.mode == "smelt":
        checks["loop_twice"] = cfg.loop_count == 2
        checks["loop_residual_scaling_1_over_r"] = (
            cfg.residual_scaling == "paper"
        )
    elif cfg.mode == "base":
        checks["unlooped_baseline"] = cfg.loop_count == 1
    else:
        checks["paper_arch_mode"] = False

    preset_geometry: Optional[Dict[str, object]] = None
    if cell is not None:
        preset = paper_preset(
            cell.scale,
            cell.sparsity,
            cell.arch,
        )
        derived = preset["derived"]
        preset_geometry = {
            "n_heads": derived["n_heads"],
            "n_kv_heads": derived["n_kv_heads"],
            "expert_hidden": derived["expert_hidden"],
        }
        checks["preset_geometry_matches"] = bool(
            int(cfg.n_heads) == int(derived["n_heads"])
            and int(cfg.effective_n_kv_heads)
            == int(derived["n_kv_heads"])
            and int(cfg.expert_hidden)
            == int(derived["expert_hidden"])
        )

    protocol_checks: Dict[str, bool] = {}
    if protocol is not None:
        protocol_checks = _paper_protocol_checks(protocol)

    architecture_faithful = all(checks.values())
    protocol_faithful: Optional[bool] = (
        all(protocol_checks.values())
        if protocol is not None
        else None
    )
    is_full_reproduction = bool(
        architecture_faithful and protocol_faithful is True
    )
    deviations = [
        name for name, ok in checks.items() if not ok
    ] + [
        name for name, ok in protocol_checks.items() if not ok
    ]

    budget_audit: Optional[Dict[str, object]] = None
    budget_all_within: Optional[bool] = None
    if cell is not None and arch is not None:
        budget_audit = _paper_budget_audit(cfg, cell)
        budget_all_within = bool(
            budget_audit["all_within_tolerance"]
        )
    # 「recipe 复现」与「数值复现」分开：recipe 指附录 A 的结构
    # 与 3.1 节协议；数值复现还要求 FLOPs/参数/KV/S 都落在论文
    # 容差内，而附录 A 的参数化来自未公开 family，公开实现通常
    # 达不到。两个字段都不允许靠措辞合并。
    numerical_reproduction = bool(
        is_full_reproduction and budget_all_within
    )

    if numerical_reproduction:
        interpretation = (
            "recipe（架构+协议）与论文附录 A 的预算容差均对齐；"
            "未被论文披露的超参与语料仍不等价于原实现，结论"
            "应写成复现而非逐位相同"
        )
    elif is_full_reproduction:
        interpretation = (
            "recipe（附录 A 结构 + 3.1 节协议）复现完成；"
            "budget_audit 仍有偏差，numerical_reproduction=false，"
            "不能声称数值复现（偏差来源与推导规则见 "
            "docs/paper_reproduction.md）"
        )
    elif architecture_faithful and protocol is None:
        interpretation = (
            "架构对齐论文附录 A 的公开披露项，但训练协议未按"
            "3.1 节设置；不能称为完整复现"
        )
    elif cell is None:
        interpretation = (
            "当前配置不是论文附录 A 的任何网格单元；只能表述为"
            "「SMELT 风格架构」的原型实验，不能声称复现论文"
        )
    else:
        interpretation = (
            "存在偏离项："
            + ", ".join(deviations)
            + "；不能声称复现论文 SMELT"
        )

    return {
        "paper": PAPER_ID,
        "paper_url": PAPER_URL,
        "cell": (
            None
            if cell is None
            else {
                "arch": cell.arch,
                "scale": cell.scale,
                "sparsity": cell.sparsity,
                "hidden": cell.hidden,
                "layers": cell.layers,
                "total_experts": cell.total_experts,
                "active_experts": cell.active_experts,
            }
        ),
        "preset_geometry": preset_geometry,
        "checks": checks,
        "protocol_checks": protocol_checks,
        "deviations": deviations,
        "architecture_faithful": bool(architecture_faithful),
        "protocol_faithful": protocol_faithful,
        "is_full_reproduction": is_full_reproduction,
        "numerical_reproduction": numerical_reproduction,
        "budget_audit": budget_audit,
        "undisclosed": list(PAPER_UNDISCLOSED),
        "protocol": dict(PAPER_PROTOCOL),
        "interpretation": interpretation,
        "scale_note": (
            "论文标度 100M–1.6B、4096 上下文、top-8 + GQA；"
            "本仓库默认是小规模原型，规模外推需要另行验证"
        ),
    }


def _preset_summary(preset: Dict[str, object]) -> str:
    cell = preset["cell"]
    derived = preset["derived"]
    measured = preset["measured"]
    return (
        f"{cell.arch} {cell.scale} S≈{cell.sparsity}% | "
        f"H={cell.hidden} L={cell.layers} "
        f"E={cell.total_experts} top-{cell.active_experts} | "
        f"heads={derived['n_heads']}/"
        f"{derived['n_kv_heads']} "
        f"expert_hidden={derived['expert_hidden']} | "
        f"total={measured['total_params']/1e9:.3f}B "
        f"(paper {cell.total_params:.3f}B) "
        f"active={measured['active_params']/1e9:.3f}B "
        f"(paper {cell.active_params:.3f}B)"
    )


def _argv_has_flag(flag: str) -> bool:
    for token in sys.argv[1:]:
        if token == flag or token.startswith(flag + "="):
            return True
    return False


def apply_paper_cli(args, parser=None) -> None:
    """把 ``--paper-cell`` / ``--paper-protocol`` 落到 args 上。

    - 预设覆盖模型结构参数；若命令行显式给了冲突值则报错，
      避免「看起来按论文配置、实际被命令行改动」。
    - ``--paper-protocol`` 只在用户未显式给出对应命令行参数时
      套用 3.1 节的协议值，方便小规模冒烟测试但仍记录偏离。
    """

    def fail(message: str) -> None:
        if parser is not None:
            parser.error(message)
        raise ValueError(message)

    preset_report: Optional[Dict[str, object]] = None
    if getattr(args, "paper_cell", None):
        try:
            scale, sparsity = parse_paper_cell_label(
                args.paper_cell
            )
        except ValueError as error:
            fail(str(error))
            return
        arch = getattr(args, "paper_arch", None)
        if arch is None:
            arch = (
                args.mode
                if args.mode in PAPER_ARCHS
                else "smelt"
            )
        if arch not in PAPER_ARCHS:
            fail(
                "--paper-arch 必须是 base 或 smelt"
            )
        if (
            args.mode in PAPER_ARCHS
            and args.mode != arch
        ):
            fail(
                f"--mode {args.mode} 与 --paper-arch {arch} 冲突"
            )
        if args.mode not in PAPER_ARCHS and args.mode != "B":
            fail(
                "--paper-cell 只支持 base / smelt 两种论文架构"
            )
        if (
            args.mode == "B"
            and _argv_has_flag("--mode")
        ):
            fail(
                "--paper-cell 与显式 --mode B（延迟合并）冲突；"
                "论文网格只有 base / smelt"
            )
        try:
            preset = paper_preset(scale, sparsity, arch)
        except ValueError as error:
            fail(str(error))
            return
        conflict_keys = {
            "seq_len": "--seq-len",
            "d_model": "--d-model",
            "n_heads": "--n-heads",
            "n_kv_heads": "--n-kv-heads",
            "n_layers": "--n-layers",
            "n_experts": "--n-experts",
            "expert_hidden": "--expert-hidden",
            "top_k": "--top-k",
            "k1": "--k1",
            "k2": "--k2",
            # 论文网格的循环区域残差 1/r 是架构语义的一部分；
            # 显式 --residual-scaling global 不能被预设静默覆盖。
            "residual_scaling": "--residual-scaling",
            # residual_scale 会在 1/r 之外再乘一次；显式改成
            # 0.5 会让 loop_residual_scale 变成 0.25，必须拒绝。
            "residual_scale": "--residual-scale",
        }
        conflicts = []
        for key, flag in conflict_keys.items():
            if not _argv_has_flag(flag):
                continue
            current = getattr(args, key, None)
            expected = preset["config"][key]
            if current != expected:
                conflicts.append(
                    f"{flag}={current!r}（预设要求 {expected!r}）"
                )
        if conflicts:
            fail(
                "--paper-cell 的结构参数由论文附录 A 决定，"
                "不能同时覆盖：" + "; ".join(conflicts)
            )
        for key, value in preset["config"].items():
            setattr(args, key, value)
        args.mode = arch
        args.paper_cell = f"{scale}:{sparsity}"
        args.paper_arch = arch
        # 只保留 JSON 可序列化的字段（PaperCell dataclass 不能
        # 直接写进 config.json / 检查点元数据）。
        preset_report = {
            "paper": preset["paper"],
            "arch": preset["arch"],
            "scale": preset["scale"],
            "sparsity": preset["sparsity"],
            "config": dict(preset["config"]),
            "derived": dict(preset["derived"]),
            "measured": dict(preset["measured"]),
            "targets": dict(preset["targets"]),
        }
        args.paper_preset = preset_report
        print(f"[paper] {_preset_summary(preset)}")
        if args.seq_len != int(PAPER_PROTOCOL["context_length"]):
            print(
                "[paper][warn] 上下文长度不是论文的 "
                f"{PAPER_PROTOCOL['context_length']}；"
                "paper_fidelity 会记为偏离"
            )

    if getattr(args, "paper_protocol", False):
        protocol_defaults = {
            "seq_len": int(PAPER_PROTOCOL["context_length"]),
            "batch_size": int(
                PAPER_PROTOCOL["global_batch_sequences"]
            ),
            "steps": int(PAPER_PROTOCOL["stable_steps"]),
            # warmup / 评估间隔论文未披露（PAPER_UNDISCLOSED），
            # 不能借 --paper-protocol 静默改成任意常数；继续
            # 使用本仓库的命令行默认值，与文档和 fidelity 报告
            # 的「未披露项沿用默认」保持一致。
            "lr_schedule": "wsd",
            "save_at_steps": list(
                PAPER_PROTOCOL["branch_steps"]
            ),
            "document_masks": True,
        }
        for key, value in protocol_defaults.items():
            flag = "--" + key.replace("_", "-")
            if _argv_has_flag(flag):
                continue
            setattr(args, key, value)
        if getattr(args, "wsd_stable_steps", None) is None:
            args.wsd_stable_steps = int(args.steps)
        if not getattr(args, "group_separator", None):
            if not _argv_has_flag("--document-masks"):
                # 没有文档边界时无法构造 segment mask；不阻断
                # 运行，但把 protocol_document_masks 记为偏离，
                # 由 paper_fidelity 审计如实报告。
                args.document_masks = False
            print(
                "[paper][warn] 未提供 --group-separator：无法构造"
                "文档级 segment attention mask，论文 3.1 节协议"
                "不完整（protocol_document_masks=false）；"
                "忠实复现请用 --group-separator 标注文档边界"
            )
        print(
            "[paper][protocol] WSD + batch "
            f"{args.batch_size} + stable {args.wsd_stable_steps} "
            f"steps + ctx {args.seq_len} + document masks；"
            "学习率/warmup/weight decay 论文未披露，沿用本仓库"
            "默认值"
        )

    args.paper_preset_report = preset_report


# ============================================================
# Reproducibility
# ============================================================

# NumPy 的 legacy RandomState 只接受 [0, 2**32 - 1]。把 --seed
# 的合法域统一到这个范围，保证 Python / NumPy / torch 三个随机
# 流拿到的是同一个种子；否则负值或更大值会在 NumPy 播种时抛错，
# 而此前 Python/torch 已经被播种，进程会停在部分初始化的状态。
MAX_SEED = 2**32 - 1


def resume_data_change_error(
    saved_sha256: Optional[str],
    current_sha256: Optional[str],
) -> Optional[str]:
    """
    检查续跑检查点与当前数据文件是否仍是同一份内容。

    数据指纹不同意味着 train/val/test 的切分内容已经变化，
    检查点里的优化器状态、采样 RNG 与「验证集选出的最优步」
    都对应旧数据；继续训练会把两个数据版本混成一条训练轨迹，
    任何指标都无法归因。旧检查点没有数据指纹时无法核对，
    返回 None 由调用方保留兼容提示。
    """
    if saved_sha256 is None or saved_sha256 == "":
        return None
    if current_sha256 is None or current_sha256 == "":
        return None
    if not isinstance(saved_sha256, str) or not isinstance(
        current_sha256, str
    ):
        # 非字符串只可能来自损坏的检查点/config；不能因为
        # 无法切片比较就当成「没有变化」继续续跑。
        return (
            "resume 数据指纹记录格式损坏（不是字符串）："
            "无法核对检查点与当前数据是否同一份，拒绝续跑；"
            "请修复检查点或换用全新的 --out 目录从头训练。"
        )
    if saved_sha256 == current_sha256:
        return None
    return (
        "resume 数据文件内容已变化（数据指纹 "
        f"{saved_sha256[:12]}... -> {current_sha256[:12]}...）："
        "检查点的参数/优化器状态与采样轨迹对应旧数据，"
        "续跑会把两个数据版本混成一条训练轨迹。请换用全新的 "
        "--out 目录与检查点从头训练。"
    )


def resume_split_change_error(
    saved_split_sha256: Optional[object],
    current_split_sha256: Optional[Dict[str, str]],
) -> Optional[str]:
    """
    检查续跑检查点记录的逐 split 内容指纹与当前划分是否一致。

    数据文件整体 sha256 相同、划分比例也相同，仍可能因为群组
    吸附、去重/清洗开关或切分实现变化而产生不同的 train/val/
    test 字节段。整体 sha256 无法发现这种情况；逐 split 指纹
    不同意味着检查点的 RNG/优化器状态对应另一批训练样本，必须
    拒绝续跑而不是把两套划分混成一条轨迹。
    """
    if not isinstance(saved_split_sha256, dict):
        return None
    if not isinstance(current_split_sha256, dict):
        return None

    mismatched = []
    invalid = []
    for split, saved_hash in saved_split_sha256.items():
        if not isinstance(saved_hash, str) or not saved_hash:
            # 损坏的旧记录不能当作「没有变化」：无法核对时
            # 续跑会把两套划分混在一起。
            invalid.append(split)
            continue
        # 旧检查点记录过的 split 在当前划分中消失，同样说明
        # 划分口径已经变化；不能因为缺少可比对象就静默放行。
        if (
            split not in current_split_sha256
            or saved_hash != current_split_sha256[split]
        ):
            mismatched.append(split)
    if not mismatched and not invalid:
        return None

    details = []
    if mismatched:
        details.append(
            "变化的 split: "
            + ", ".join(
                sorted(
                    (str(split) for split in mismatched)
                )
            )
        )
    if invalid:
        details.append(
            "记录损坏的 split: "
            + ", ".join(
                sorted(str(split) for split in invalid)
            )
        )
    return (
        "resume 数据划分内容指纹已变化（"
        + "；".join(details)
        + "）：整体数据 sha256 虽相同，但 train/val/test 的"
        "实际字节段不同（群组吸附、清洗开关或切分实现变化）。"
        "检查点的参数/优化器状态对应旧划分，续跑会把两套"
        "数据混成一条训练轨迹。请换用全新的 --out 目录与"
        "检查点从头训练。"
    )


def resume_effective_train_change_error(
    saved_sha256: Optional[object],
    current_sha256: Optional[str],
) -> Optional[str]:
    """
    检查续跑检查点的有效训练集指纹是否与当前一致。

    整体数据 sha256 与 split 指纹相同、清洗开关也相同，仍可能
    因为清洗实现变化而剔除不同区间：网络窗口、unigram/n-gram
    计数与数据采样的有效范围都会变。此时续跑等于把旧检查点的
    优化器/RNG 轨迹接到另一套训练样本上，必须拒绝。
    """
    if not isinstance(saved_sha256, str) or not saved_sha256:
        return None
    if not isinstance(current_sha256, str) or not current_sha256:
        return None
    if saved_sha256 == current_sha256:
        return None

    return (
        "resume 有效训练集指纹已变化（"
        f"{saved_sha256[:12]}... -> "
        f"{current_sha256[:12]}...）：整体数据与 split 边界"
        "可能相同，但清洗剔除区间/实际参与训练的字节不同。"
        "检查点对应旧的训练样本集合，续跑会把两套数据混成"
        "一条轨迹。请换用全新的 --out 目录与检查点从头训练。"
    )


def resume_split_isolation_change_error(
    saved_isolation: Optional[object],
    current_isolation: Optional[object],
) -> Optional[str]:
    """
    检查续跑检查点的时序隔离记录是否一致。

    split 内容指纹相同仍可能掩盖边界顺序/绝对位置变化（例如
    重复内容使不同边界产生相同片段）；把边界、顺序与重叠
    记录一起核对，避免续跑接到另一套时间切分上。旧检查点
    没有该字段时返回 None，由调用方给出兼容提示。
    """
    if not isinstance(saved_isolation, dict) or not isinstance(
        current_isolation, dict
    ):
        return None

    def canonical(value):
        """把记录转成键类型安全的可比较结构。

        旧检查点可能混入 int/str 键；json.dumps(sort_keys=True)
        会直接抛 TypeError。字典按键的稳定文本排序后转成
        [键, 值] 列表，既保留键的类型信息，又保证比较确定性。
        """
        if isinstance(value, dict):
            return [
                [repr(key), canonical(item)]
                for key, item in sorted(
                    value.items(),
                    key=lambda pair: repr(pair[0]),
                )
            ]
        if isinstance(value, (list, tuple)):
            return [canonical(item) for item in value]
        if isinstance(value, (set, frozenset)):
            return sorted(
                (canonical(item) for item in value),
                key=repr,
            )
        return value

    saved_key = json.dumps(
        canonical(saved_isolation),
        ensure_ascii=False,
        sort_keys=True,
        default=str,
    )
    current_key = json.dumps(
        canonical(current_isolation),
        ensure_ascii=False,
        sort_keys=True,
        default=str,
    )
    if saved_key == current_key:
        return None

    return (
        "resume 时序隔离记录已变化：train/val/test 的顺序、"
        "绝对边界或重叠检查与检查点不一致。检查点对应另一套"
        "时间切分，续跑会把两套划分混成一条轨迹。请换用全新"
        "的 --out 目录与检查点从头训练。"
    )


def resume_amp_change_error(
    saved_args: object,
    current_amp_dtype: Optional[object],
) -> Optional[str]:
    """
    检查续跑检查点与当前的混合精度环境是否一致。
    """
    if (
        not isinstance(saved_args, dict)
        or "amp_dtype" not in saved_args
    ):
        return None

    saved_dtype = saved_args.get("amp_dtype")
    saved_text = (
        str(saved_dtype)
        if saved_dtype is not None
        else "float32"
    )
    current_text = (
        str(current_amp_dtype)
        if current_amp_dtype is not None
        else "float32"
    )
    if saved_text == current_text:
        return None

    return (
        "resume 检查点的混合精度环境为 "
        f"{saved_text}，当前设备会使用 {current_text}："
        "autocast dtype 与 GradScaler 状态会改变浮点路径和"
        "优化器轨迹。请在同一设备能力/同一 AMP 设置下续跑，"
        "或换用全新的 --out 目录从头训练。"
    )


def seed_error(seed: int) -> Optional[str]:
    """
    校验随机种子的统一合法域；返回错误消息或 None。
    """
    if isinstance(seed, bool) or not isinstance(seed, int):
        return "随机种子必须是整数"
    if seed < 0 or seed > MAX_SEED:
        return (
            f"随机种子必须落在 [0, {MAX_SEED}]（NumPy "
            "RandomState 的合法范围；Python/torch/CUDA 也使用"
            "同一个值以保持随机流一致）"
        )
    return None


def _seed_optional_accelerators(seed: int) -> List[str]:
    """
    固定 PyTorch 可选的 XPU / MPS 后端随机源。

    CUDA 由 set_seed 直接处理；XPU（Intel GPU）与 MPS（Apple
    GPU）在对应硬件上同样是训练随机性的来源。旧版 torch 没有
    这些命名空间或后端不可用时静默跳过，不影响 CPU/CUDA 路径。
    返回值只列出真正播种成功的后端，写进运行元数据。
    """
    seeded: List[str] = []

    xpu = getattr(torch, "xpu", None)
    if xpu is not None:
        try:
            if xpu.is_available():
                xpu.manual_seed_all(seed)
                seeded.append("xpu")
        except (AttributeError, RuntimeError):
            pass

    mps = getattr(torch, "mps", None)
    if mps is not None:
        try:
            mps_available = getattr(
                getattr(torch, "backends", None),
                "mps",
                None,
            )
            if (
                mps_available is not None
                and mps_available.is_available()
                and hasattr(mps, "manual_seed")
            ):
                mps.manual_seed(seed)
                seeded.append("mps")
        except (AttributeError, RuntimeError):
            pass

    return seeded


def set_seed(
    seed: int,
    *,
    strict_determinism: bool = False,
):
    """
    固定 Python / NumPy / PyTorch(CPU+CUDA) / cuDNN 的随机种子。

    数据采样不经过 DataLoader worker，而由显式的
    torch.Generator 承担（见 ByteDataset.batch 与 main 中的
    train_generator）：其初始种子同样来自 --seed，当前状态随
    检查点一起存档，恢复训练时逐位还原。

    strict_determinism=True 时，遇到没有确定性实现的算子直接
    报错（而不是只告警），供正式复现实验 fail-fast；默认
    warn_only 以兼容尚缺确定性内核的算子。

    跨硬件架构仍可能因浮点归约顺序产生微小差异；同一台机器
    上的多次运行应保持一致。
    """
    error = seed_error(seed)
    if error is not None:
        raise ValueError(error)

    random.seed(seed)

    if np is not None:
        np.random.seed(seed)

    torch.manual_seed(seed)

    if torch.cuda.is_available():
        # manual_seed_all 覆盖当前可见的所有 CUDA 设备。
        torch.cuda.manual_seed_all(seed)

    # XPU / MPS 等可选加速后端同样属于训练随机性来源。
    optional_backends = _seed_optional_accelerators(seed)

    cuda_initial_seeds: List[int] = []
    if torch.cuda.is_available():
        for device_index in range(torch.cuda.device_count()):
            try:
                with torch.cuda.device(device_index):
                    cuda_initial_seeds.append(
                        int(torch.cuda.initial_seed())
                    )
            except (AssertionError, RuntimeError):
                # 设备不可访问时不伪造读数；device_count 本身
                # 仍记录在清单里。
                continue

    global _LAST_SEED_MANIFEST
    _LAST_SEED_MANIFEST = {
        "seed": int(seed),
        "python_random": True,
        "numpy": np is not None,
        "torch_initial_seed": int(torch.initial_seed()),
        "cuda_available": torch.cuda.is_available(),
        "cuda_device_count": (
            torch.cuda.device_count()
            if torch.cuda.is_available()
            else 0
        ),
        "cuda_initial_seeds": cuda_initial_seeds,
        "optional_backends": optional_backends,
    }

    # PYTHONHASHSEED 只对之后启动的子进程（如 torch.compile 的
    # 编译进程）生效；当前解释器的哈希种子在启动时已经确定，
    # 需要严格复现时应在命令行显式设置该环境变量。
    #
    # 若启动时未显式设置，本函数就是该变量的所有者：之后再次
    # set_seed 必须把值更新为当前 seed，否则先 set_seed(42) 再
    # set_seed(7) 时子进程仍继承 42，和当前随机流不一致。用户
    # 启动时显式设置的值则不能被静默覆盖（尊重外部固定口径）。
    if _PYTHONHASHSEED_AT_START is None:
        os.environ["PYTHONHASHSEED"] = str(seed)
    else:
        os.environ.setdefault("PYTHONHASHSEED", str(seed))

    global _PYTHONHASHSEED_WARNED
    if (
        _PYTHONHASHSEED_AT_START is None
        and not _PYTHONHASHSEED_WARNED
    ):
        _PYTHONHASHSEED_WARNED = True
        print(
            "[repro] 提示: 进程启动时未设置 PYTHONHASHSEED，当前"
            "解释器的 hash 随机化未被固定（只影响依赖 hash() "
            "的代码与之后启动的子进程，其余随机流已按 --seed "
            "固定）。严格逐位复现可在命令前加 "
            f"PYTHONHASHSEED={seed}。"
        )

    # 要求 PyTorch 优先选用确定性实现。bincount、attention
    # 反向等 CUDA 算子若不存在确定性实现会明确告警，而不是
    # 静默产生跨重启不可复现的微小差异。严格模式直接失败，
    # 避免「带告警继续跑」的实验被误当成可复现结果。
    torch.use_deterministic_algorithms(
        True,
        warn_only=not strict_determinism,
    )

    # 本文件所有 torch.empty 缓冲在使用前都会被完整写入，
    # 不依赖未初始化缓冲的 NaN 填充来保证结果确定性。
    torch.utils.deterministic.fill_uninitialized_memory = False

    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


def configure_cuda_precision(allow_tf32: bool = False) -> None:
    """
    配置 CUDA 的 fp32 矩阵乘精度。

    TF32 用 10 位尾数代替 fp32 的 23 位尾数，能加速 Ampere 及
    更新架构上的矩阵乘，但会改变数值结果，且不同 GPU 架构 /
    cuBLAS 版本的 TF32 实现不完全一致。默认关闭（完整 fp32），
    需要吞吐量时用 --allow-tf32 显式开启；两种状态都会写入
    run_metadata 的 allow_tf32_matmul / allow_tf32_cudnn，供
    --compare 的复现性来源检查核对。

    CPU 或 MPS 路径同样可以安全调用：这两个后端标志始终存在，
    只是不生效。
    """
    torch.backends.cuda.matmul.allow_tf32 = bool(allow_tf32)
    torch.backends.cudnn.allow_tf32 = bool(allow_tf32)

    # float32_matmul_precision 与上面的 TF32 开关在部分版本里
    # 联动，但环境变量/用户代码可能把它留成别的档位。这里显式
    # 固定：关闭 TF32 时用 highest（完整 fp32），开启时用 high
    #（允许 TensorFloat32）。实际生效值仍写入 run_metadata。
    if hasattr(torch, "set_float32_matmul_precision"):
        torch.set_float32_matmul_precision(
            "high" if allow_tf32 else "highest"
        )


def pythonhashseed_error(
    require_pythonhashseed: bool,
) -> Optional[str]:
    """
    --require-pythonhashseed 的合法性检查：返回错误消息或
    None。当前解释器的哈希种子在进程启动时已确定，set_seed
    的 setdefault 无法追溯固定；需要严格逐位复现的正式运行
    必须由用户在命令行显式设置。
    """
    if not require_pythonhashseed:
        return None
    if _PYTHONHASHSEED_AT_START is None:
        return (
            "--require-pythonhashseed 要求进程启动前显式设置 "
            "PYTHONHASHSEED（例如 "
            "PYTHONHASHSEED=42 python experiment.py ...）；"
            "当前进程的 hash 随机化未被固定，严格逐位复现"
            "无法保证"
        )
    text = str(_PYTHONHASHSEED_AT_START).strip()
    # "random"/空字符串与超范围整数要么显式随机化、要么被
    # 解释器拒绝/回退；它们都不构成一个固定的 hash 种子。
    if (
        not text
        or text.lower() == "random"
        or not text.isdigit()
        or int(text) > MAX_SEED
    ):
        return (
            "--require-pythonhashseed 要求 PYTHONHASHSEED 是 "
            f"[0, {MAX_SEED}] 内的整数（当前值 "
            f"{_PYTHONHASHSEED_AT_START!r} 不能固定本进程的 "
            "hash 随机化）；请用如 PYTHONHASHSEED=42 重新启动"
        )
    return None


def configure_cpu_threads(num_threads: Optional[int]) -> None:
    """
    固定 PyTorch CPU 线程数（None=保持环境默认）。

    CPU 上的并行归约顺序可能随线程数变化，同一台机器上
    改变 OMP/MKL 线程数也可能让「同种子」结果出现末位差异。
    正式复现实验可显式固定线程数；实际生效值随 run_metadata
    存档，即使不固定也能追溯到当时的线程环境。
    """
    if num_threads is None:
        return

    if isinstance(num_threads, bool) or num_threads <= 0:
        raise ValueError("CPU 线程数必须为正整数")

    torch.set_num_threads(int(num_threads))


def _capture_rng_state() -> Dict[str, object]:
    """
    捕获当前进程的全部随机数状态，供临时代码（如 sanity check）
    运行后原样恢复，保证是否运行临时代码不影响主训练轨迹。
    """
    state: Dict[str, object] = {
        "python": random.getstate(),
        "torch": torch.get_rng_state(),
        "cuda": (
            torch.cuda.get_rng_state_all()
            if torch.cuda.is_available()
            else None
        ),
    }
    if np is not None:
        state["numpy"] = np.random.get_state()
    return state


def _restore_rng_state(state: Dict[str, object]) -> None:
    random.setstate(state["python"])
    torch.set_rng_state(state["torch"])

    cuda_state = state.get("cuda")
    if cuda_state is not None and torch.cuda.is_available():
        torch.cuda.set_rng_state_all(cuda_state)

    numpy_state = state.get("numpy")
    if numpy_state is not None and np is not None:
        np.random.set_state(numpy_state)


def _numpy_rng_state_payload() -> Optional[Dict[str, object]]:
    """
    把 NumPy 全局随机状态转成只含基本类型的可存档形式。

    检查点经 torch.load 读取；新版 PyTorch 默认
    weights_only=True，直接存 numpy ndarray 会被拒绝，因此
    key 数组转成 int 列表（恢复时按 uint32 重建）。
    """
    if np is None:
        return None

    name, keys, pos, has_gauss, cached = np.random.get_state()

    return {
        "name": str(name),
        "keys": [int(value) for value in keys.tolist()],
        "pos": int(pos),
        "has_gauss": int(has_gauss),
        "cached_gaussian": float(cached),
    }


def _restore_numpy_rng_state(
    payload: Optional[Dict[str, object]],
) -> None:
    if payload is None or np is None:
        return

    np.random.set_state((
        str(payload.get("name", "MT19937")),
        np.asarray(
            payload.get("keys", []),
            dtype=np.uint32,
        ),
        int(payload.get("pos", 0)),
        int(payload.get("has_gauss", 0)),
        float(payload.get("cached_gaussian", 0.0)),
    ))


# ============================================================
# Basic layers
# ============================================================

class RMSNorm(nn.Module):
    def __init__(self, dim: int, eps: float = 1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(dim))
        self.eps = eps

        # torch>=2.4 提供内置实现，内部使用高精度累加，
        # 语义与手动实现一致。
        self._fused = (
            F.rms_norm if hasattr(F, "rms_norm") else None
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self._fused is not None and (x.is_cuda or x.dtype == torch.float32):
            return self._fused(
                x,
                self.weight.shape,
                self.weight,
                self.eps,
            )

        input_dtype = x.dtype
        y = x.float()
        y = y * torch.rsqrt(
            y.square().mean(dim=-1, keepdim=True) + self.eps
        )
        # 在 fp32 下乘权重后再转回输入 dtype，
        # 与融合路径的输出 dtype 保持一致；
        # 否则 bf16 * fp32 权重会提升为 fp32 输出。
        return (y * self.weight).to(input_dtype)


class SegmentAttentionMask:
    """文档级 segment attention mask（论文 3.1 节）。

    输入是每个 token 的文档编号 ``[batch, time]``；注意力只允许
    同一文档内、且 key 位置不晚于 query 位置的 token 可见。

    实现有两条路径：

    - CUDA：``torch.nn.attention.flex_attention`` 的 BlockMask，
      不物化 [batch, time, time] 的掩码矩阵，能支撑论文的
      batch=256、context=4096 规模；
    - CPU（或 flex_attention 不可用）：物化 bool 掩码，仅用于
      小规模测试与评估；超过 1 GiB 时显式报错，而不是悄悄
      退化成无掩码的因果注意力。

    掩码在每次前向构造一次，随后共享给所有 Block（同一 batch
    的所有层/分支使用同一份文档边界）。
    """

    # 物化 bool 掩码的内存上限（字节）。B*T*T 超过它时
    # CPU 路径直接报错；论文规模请在 CUDA 上运行。
    DENSE_LIMIT_BYTES = 1 << 30

    def __init__(self, segment_ids: torch.Tensor):
        if (
            segment_ids.dim() != 2
            or segment_ids.dtype
            not in (torch.int32, torch.int64)
        ):
            raise ValueError(
                "segment_ids 必须是 [batch, time] 的整数张量"
            )
        self.segment_ids = segment_ids
        self.batch, self.length = segment_ids.shape
        self.dense: Optional[torch.Tensor] = None
        self.block_mask = None
        self.path = "dense"
        if segment_ids.device.type == "cuda":
            if self._build_flex():
                return
        self._build_dense()

    def _build_flex(self) -> bool:
        try:
            from torch.nn.attention.flex_attention import (
                create_block_mask,
            )
        except ImportError:
            return False

        segment = self.segment_ids

        def mask_mod(batch, head, q_index, kv_index):
            doc = segment[batch]
            return (q_index >= kv_index) & (
                doc[q_index] == doc[kv_index]
            )

        try:
            self.block_mask = create_block_mask(
                mask_mod,
                B=int(self.batch),
                H=None,
                Q_LEN=int(self.length),
                KV_LEN=int(self.length),
                device=segment.device,
            )
        except Exception:
            return False
        self.path = "flex"
        return True

    def _build_dense(self) -> None:
        needed = (
            int(self.batch)
            * int(self.length)
            * int(self.length)
        )
        if needed > self.DENSE_LIMIT_BYTES:
            raise RuntimeError(
                "文档级 segment mask 需要物化 "
                f"{self.batch}x{self.length}x{self.length} 的布尔"
                "掩码（超过 1 GiB）；CPU 上无法运行该规模的"
                "论文协议。请在 CUDA 上运行（走 flex_attention "
                "BlockMask 的稀疏路径），或减小 --batch-size / "
                "--seq-len"
            )
        segment = self.segment_ids
        causal = torch.ones(
            (self.length, self.length),
            dtype=torch.bool,
            device=segment.device,
        ).tril()
        same_doc = segment[:, None, :, None] == segment[
            :, None, None, :
        ]
        # [batch, 1, time, time]：可直接广播到 SDPA 的
        # (batch, heads, time, time)。
        self.dense = same_doc & causal
        self.path = "dense"

    def attention(self, q, k, v):
        if self.path == "flex":
            from torch.nn.attention.flex_attention import (
                flex_attention,
            )
            return flex_attention(
                q, k, v, block_mask=self.block_mask
            )
        return F.scaled_dot_product_attention(
            q,
            k,
            v,
            attn_mask=self.dense,
            is_causal=False,
        )


def document_segment_ids(
    input_ids: torch.Tensor,
    separator: Sequence[int],
) -> torch.Tensor:
    """从 token 流中检测文档分隔符，返回每 token 的文档编号。

    分隔符的起始字节处开启新文档（文档 0 从窗口起点开始）。
    多字节分隔符按完整字节串匹配；窗口边界处被截断的分隔符
    不计入（窗口外的文档边界本来就不影响窗口内可见性）。
    """

    batch, length = input_ids.shape
    byte_values = [int(byte) for byte in separator]
    if not byte_values or length <= 0:
        return torch.zeros(
            (batch, length),
            dtype=torch.long,
            device=input_ids.device,
        )
    span = length - len(byte_values) + 1
    if span <= 0:
        return torch.zeros(
            (batch, length),
            dtype=torch.long,
            device=input_ids.device,
        )
    starts = torch.ones(
        (batch, span),
        dtype=torch.bool,
        device=input_ids.device,
    )
    for offset, value in enumerate(byte_values):
        starts &= (
            input_ids[:, offset:offset + span] == value
        )
    separator_bytes = bytes(byte_values)
    # 分隔符自身有非空 border（如 "\n\n"、"aba"）时，候选匹配
    # 可能相互重叠；群组扫描（bytes.find）采用不重叠的贪心
    # 匹配，文档 mask 必须同口径，否则会在同一群组内部凭空
    # 插入边界。无 border 时任意两个匹配都不可能重叠，继续
    # 走全向量化路径。
    self_overlapping = any(
        separator_bytes[:border]
        == separator_bytes[-border:]
        for border in range(1, len(separator_bytes))
    )
    if self_overlapping and bool(starts.any()):
        starts_cpu = starts.cpu()
        selected_cpu = torch.zeros_like(starts_cpu)
        for row in range(batch):
            next_allowed = 0
            for position in torch.nonzero(
                starts_cpu[row], as_tuple=False
            ).flatten().tolist():
                if position < next_allowed:
                    continue
                selected_cpu[row, position] = True
                next_allowed = position + len(byte_values)
        starts = selected_cpu.to(input_ids.device)
    boundary = torch.zeros(
        (batch, length),
        dtype=torch.long,
        device=input_ids.device,
    )
    boundary[:, :span] = starts.to(torch.long)
    # 窗口首个 token 即使匹配分隔符也属于本窗口的第一篇
    # 文档（编号从 0 起），因此把第一个位置清零。
    boundary[:, 0] = 0
    return torch.cumsum(boundary, dim=1)


class CausalSelfAttention(nn.Module):
    def __init__(self, cfg: Config):
        super().__init__()

        self.n_heads = cfg.n_heads
        self.n_kv_heads = cfg.effective_n_kv_heads
        self.kv_repeat = self.n_heads // self.n_kv_heads
        self.head_dim = cfg.d_model // cfg.n_heads
        self.kv_dim = self.n_kv_heads * self.head_dim

        # n_kv_heads == n_heads 时保留融合 qkv 参数（历史检查点
        # 兼容，且 MHA 时更省一次 GEMM）；GQA 时 K/V 的投影宽度
        # 小于 Q，必须分开投影。
        if self.n_kv_heads == self.n_heads:
            self.qkv = nn.Linear(
                cfg.d_model,
                3 * cfg.d_model,
                bias=False,
            )
            self.q_proj = None
            self.k_proj = None
            self.v_proj = None
        else:
            self.qkv = None
            self.q_proj = nn.Linear(
                cfg.d_model,
                cfg.d_model,
                bias=False,
            )
            self.k_proj = nn.Linear(
                cfg.d_model,
                self.kv_dim,
                bias=False,
            )
            self.v_proj = nn.Linear(
                cfg.d_model,
                self.kv_dim,
                bias=False,
            )

        self.out = nn.Linear(
            cfg.d_model,
            cfg.d_model,
            bias=False,
        )

    def core(
        self,
        x: torch.Tensor,
        attn_mask: Optional["SegmentAttentionMask"] = None,
    ) -> torch.Tensor:
        """
        Attention 主体，返回输出投影之前的 [batch, length, dim]。
        调用方负责完成输出投影与残差相加。
        """
        batch, length, dim = x.shape

        if self.qkv is not None:
            q, k, v = F.linear(x, self.qkv.weight).view(
                batch, length, 3, self.n_heads, self.head_dim
            ).unbind(2)
        else:
            q = self.q_proj(x).view(
                batch,
                length,
                self.n_heads,
                self.head_dim,
            )
            k = self.k_proj(x).view(
                batch,
                length,
                self.n_kv_heads,
                self.head_dim,
            )
            v = self.v_proj(x).view(
                batch,
                length,
                self.n_kv_heads,
                self.head_dim,
            )

        q = q.transpose(1, 2)
        k = k.transpose(1, 2)
        v = v.transpose(1, 2)

        # GQA：整除时每个 KV 头被 kv_repeat 个连续 Q 头共享；
        # 不整除时按 floor(i * n_kv / n_heads) 均匀映射，保证
        # 任意 n_kv_heads 都能精确控制 KV cache（论文未披露
        # head 几何，预算匹配需要这一自由度）。
        if self.kv_repeat > 1 and self.n_heads % self.n_kv_heads == 0:
            k = k.repeat_interleave(self.kv_repeat, dim=1)
            v = v.repeat_interleave(self.kv_repeat, dim=1)
        elif self.n_kv_heads != self.n_heads:
            index = (
                (torch.arange(self.n_heads) * self.n_kv_heads)
                // self.n_heads
            ).to(device=k.device)
            k = k.index_select(1, index)
            v = v.index_select(1, index)

        if attn_mask is not None:
            # 文档级 segment mask 已包含因果约束；走掩码路径时
            # 不能再叠加 is_causal=True（否则两者不一致）。
            y = attn_mask.attention(q, k, v)
        else:
            y = F.scaled_dot_product_attention(
                q,
                k,
                v,
                dropout_p=0.0,
                is_causal=True,
            )

        y = y.transpose(1, 2).contiguous()
        return y.view(batch, length, dim)

    def forward(
        self,
        x: torch.Tensor,
        attn_mask: Optional[SegmentAttentionMask] = None,
    ) -> torch.Tensor:
        return F.linear(
            self.core(x, attn_mask), self.out.weight
        )


def _swiglu_backward(
    grad_hidden: torch.Tensor,
    gate_up: torch.Tensor,
    return_hidden: bool = False,
) -> torch.Tensor | Tuple[torch.Tensor, torch.Tensor]:
    """
    SwiGLU 的共用反向实现（供 _SwiGLUDown 使用）。

    gate_up 是 [.., 2*hidden] 的拼接张量（gate 在前、up 在
    后）。mul 反向给出两路梯度，gate 路再过 silu 反向；两路
    梯度分别写回 grad_gate_up 的对应半区（两半区互不相交且
    并集完整）。

    ``return_hidden=True`` 时同时返回由同一份 ``silu(gate)``
    重算的隐藏层，供下投影权重梯度使用。
    """
    gate, up = gate_up.chunk(2, dim=-1)

    grad_gate_up = torch.empty_like(gate_up)
    grad_gate, grad_up = grad_gate_up.chunk(2, dim=-1)

    # grad_up 半区先写入 grad_hidden * up 作为 silu 反向的输入。
    torch.mul(grad_hidden, up, out=grad_up)
    torch.ops.aten.silu_backward.grad_input(
        grad_up,
        gate,
        grad_input=grad_gate,
    )

    # grad_up = grad_hidden * silu(gate)。silu(gate) 先原地
    # 写入 grad_up 半区；需要隐藏层时在同一份 silu 结果上
    # 乘 up 得到 hidden。
    torch.ops.aten.silu.out(gate, out=grad_up)
    hidden = None
    if return_hidden:
        hidden = torch.mul(grad_up, up)
    torch.mul(grad_hidden, grad_up, out=grad_up)
    if return_hidden:
        return grad_gate_up, hidden
    return grad_gate_up


class _SwiGLUDown(torch.autograd.Function):
    """
    SwiGLU 与下投影的组合节点。

    前向与「silu(gate) * up 后接下投影」逐位一致；hidden
    中间结果不进入 autograd 的保存集合，反向时由 gate_up
    按前向同一算子重新算出。
    down_weight 支持两种布局：
    - [E, D, H]：批量专家，下投影为 bmm；
    - [D, H]：单专家，下投影为普通线性。
    """

    @staticmethod
    def forward(
        ctx,
        gate_up: torch.Tensor,
        down_weight: torch.Tensor,
    ) -> torch.Tensor:
        # gate/up 是 gate_up 的切片视图，保存 gate_up 即可同时
        # 覆盖两者且供反向重算隐藏层。forward 内 grad mode 默认
        # 关闭，因此以 requires_grad 判断是否需要保存。
        gate, up = gate_up.chunk(2, dim=-1)

        if gate_up.requires_grad:
            ctx.save_for_backward(gate_up, down_weight)

            # gate_up 需要保存供反向使用，SiLU 保持 out-of-place，
            # mul_ 原地写入其输出。
            hidden = F.silu(gate).mul_(up)
        else:
            # 无需反向时 gate_up 只是临时张量，SiLU 直接原地
            # 写入 gate（gate_up 的前半区），数值上与上面一致。
            hidden = F.silu(gate, inplace=True).mul_(up)

        # autocast 下单专家路径的权重与激活可能不同 dtype；与
        # 线性层的 autocast 语义一致，先按激活 dtype 对齐权重
        #（批量路径的权重 stack 本就缓存为 autocast dtype，
        # 此处为空操作）。
        if down_weight.dtype != hidden.dtype:
            down_weight = down_weight.to(hidden.dtype)

        if down_weight.dim() == 3:
            return torch.bmm(hidden, down_weight.transpose(1, 2))
        return F.linear(hidden, down_weight)

    @staticmethod
    def backward(
        ctx,
        grad_out: torch.Tensor,
    ) -> tuple:
        gate_up, down_weight = ctx.saved_tensors

        # autocast 下单专家路径的权重与激活可能不同 dtype，计算
        # 前对齐，返回梯度时再还原为权重的 dtype。
        compute_weight = down_weight
        if compute_weight.dtype != grad_out.dtype:
            compute_weight = compute_weight.to(grad_out.dtype)

        if down_weight.dim() == 3:
            # 与 bmm(hidden, W^T) 的反向同序：grad_hidden 来自
            # grad_out @ W；grad_W 来自 hidden^T @ grad_out 的
            # 转置视图。
            grad_hidden = torch.bmm(grad_out, compute_weight)
            grad_gate_up, hidden = _swiglu_backward(
                grad_hidden,
                gate_up,
                return_hidden=True,
            )
            grad_weight = torch.bmm(
                hidden.transpose(1, 2),
                grad_out,
            ).transpose(1, 2)
        else:
            # 与 F.linear(hidden, W) 的反向同序；输入允许带任意
            # 前导维（如 dense 模式的 [batch, time, dim]），权重的
            # 梯度按全部前导维求和，与线性层反向的展平口径一致。
            grad_hidden = torch.matmul(grad_out, compute_weight)
            grad_gate_up, hidden = _swiglu_backward(
                grad_hidden,
                gate_up,
                return_hidden=True,
            )
            grad_weight = torch.matmul(
                grad_out.reshape(
                    -1,
                    grad_out.size(-1),
                ).transpose(0, 1),
                hidden.reshape(-1, hidden.size(-1)),
            )

        if grad_weight.dtype != down_weight.dtype:
            grad_weight = grad_weight.to(down_weight.dtype)

        return grad_gate_up, grad_weight


class Expert(nn.Module):
    """
    SwiGLU Expert.
    """

    def __init__(self, dim: int, hidden: int):
        super().__init__()

        # [dim, 2*hidden] 线性层在最后一维按 [gate; up] 切分，
        # 每个输出仍是独立的点积。
        self.gate_up = nn.Linear(dim, 2 * hidden, bias=False)
        self.down = nn.Linear(hidden, dim, bias=False)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # gate 与 up 的融合输出直接进入 SwiGLU + 下投影的组合节点。
        gate_up = F.linear(x, self.gate_up.weight)

        # 无反向需求（no_grad/inference_mode 下的评估路径）时直接
        # 原地计算，数值上与组合节点的前向完全一致。
        if gate_up.requires_grad:
            return _SwiGLUDown.apply(gate_up, self.down.weight)

        gate, up = gate_up.chunk(2, dim=-1)
        hidden = F.silu(gate, inplace=True).mul_(up)
        return F.linear(hidden, self.down.weight)

    def _load_from_state_dict(
        self,
        state_dict: dict,
        prefix: str,
        *args,
        **kwargs,
    ):
        # 分开保存的 gate.weight / up.weight 按 [gate; up] 顺序
        # 拼接后并入 gate_up.weight，与 forward 中 chunk 的
        # 切分顺序一致。
        old_gate = prefix + "gate.weight"
        old_up = prefix + "up.weight"

        if old_gate in state_dict and old_up in state_dict:
            state_dict[prefix + "gate_up.weight"] = torch.cat(
                [
                    state_dict.pop(old_gate),
                    state_dict.pop(old_up),
                ],
                dim=0,
            )

        super()._load_from_state_dict(
            state_dict,
            prefix,
            *args,
            **kwargs,
        )


# ============================================================
# Sparse MoE
# ============================================================

# 填充缓冲的全局额度。
_MOE_PADDED_CACHE_MAX_BYTES = 64 * 1024 * 1024

# 填充缓冲账本：{模块: 已用字节数}。
_MOE_PADDED_CACHE_REGISTRY: (
    "weakref.WeakKeyDictionary[object, int]"
) = weakref.WeakKeyDictionary()


# dispatch 行下标的额度（每模块）。
_MOE_ARANGE_CACHE_MAX_BYTES = 1024 * 1024


@functools.lru_cache(maxsize=None)
def _dtype_element_size(dtype: torch.dtype) -> int:
    """dtype 的每元素字节数。"""
    return torch.empty(0, dtype=dtype).element_size()


class _StackedExpertWeights(torch.autograd.Function):
    """
    专家权重 stack 的梯度出口。

    forward 原样返回 stack；backward 按专家把上游梯度切成
    逐专家切片返回，与 torch.stack 反向的语义一致。autocast
    下 stack 为 autocast dtype（bf16/fp16），反向先把上游梯度
    转换回参数 dtype 再切分，与「参数 -> 转换 -> stack」
    计算图中转换节点反向的数值完全一致。
    """

    @staticmethod
    def forward(ctx, stacked: torch.Tensor, *weights: torch.Tensor):
        # 逐专家切片的形状；stack 要求各专家权重同形。
        ctx.shapes = [weight.shape for weight in weights]
        # 参数 dtype；stack 可能已是 autocast dtype。
        ctx.weight_dtype = (
            weights[0].dtype if weights else stacked.dtype
        )
        return stacked

    @staticmethod
    def backward(ctx, grad_stacked: torch.Tensor) -> tuple:
        if grad_stacked.dtype != ctx.weight_dtype:
            grad_stacked = grad_stacked.to(ctx.weight_dtype)

        return (None,) + tuple(
            grad_stacked[index].reshape(shape)
            for index, shape in enumerate(ctx.shapes)
        )


class _MergeExpertOutputs(torch.autograd.Function):
    """
    dispatch 的输出侧：把各专家输出散射回原始 assignment 顺序。

    forward 把各专家输出写回原始 assignment 顺序的缓冲；
    backward 按 perm 收集梯度，再按计数切成各专家输出的
    梯度视图。
    """

    @staticmethod
    def forward(
        ctx,
        perm: torch.Tensor,
        counts: list,
        *expert_outputs: torch.Tensor,
    ) -> torch.Tensor:
        ctx.counts = counts

        if any(t.requires_grad for t in expert_outputs):
            ctx.save_for_backward(perm)

        first = expert_outputs[0]

        # 输出缓冲按非空专家输出分配 dtype；空段是 dispatch
        # 输入的空切片占位，不参与 dtype 判定。
        output_dtype = next(
            (
                tensor.dtype
                for tensor, count in zip(expert_outputs, counts)
                if count > 0
            ),
            first.dtype,
        )

        outputs = torch.empty(
            perm.numel(),
            first.size(-1),
            dtype=output_dtype,
            device=first.device,
        )

        # 散射下标按计数切分，与各专家输出、计数对齐；
        # 空段仍按计数占位，不产生 index_copy_。
        for out, index, count in zip(
            expert_outputs,
            perm.split(counts),
            counts,
        ):
            if count == 0:
                continue

            outputs.index_copy_(0, index, out)

        return outputs

    @staticmethod
    def backward(
        ctx,
        grad_outputs: torch.Tensor,
    ) -> tuple:
        (perm,) = ctx.saved_tensors

        grad_sorted = grad_outputs.index_select(0, perm)

        segment_grads = grad_sorted.split(ctx.counts, dim=0)

        return (None, None) + tuple(segment_grads)


class _GatherPaddedExpertOutputs(torch.autograd.Function):
    """
    把填充缓冲中的各专家有效输出按原始 assignment 顺序取回。

    ``source[a]`` 是原始 assignment a 在填充缓冲中的行号；
    反向按同一映射把上游梯度写回填充缓冲，未使用的填充行
    梯度恒为 0。溢出路径中 ``source`` 的溢出行指向专家
    scratch 行，这些行的上游梯度在回退结果覆盖后恒为 0。
    """

    @staticmethod
    def forward(
        ctx,
        padded: torch.Tensor,
        source: torch.Tensor,
    ) -> torch.Tensor:
        ctx.shape = padded.shape
        ctx.dtype = padded.dtype
        ctx.device = padded.device

        final = padded.index_select(0, source)

        if ctx.needs_input_grad[0]:
            ctx.save_for_backward(source)
        return final

    @staticmethod
    def backward(
        ctx,
        grad_final: torch.Tensor,
    ) -> tuple:
        (source,) = ctx.saved_tensors

        grad_padded = torch.zeros(
            ctx.shape,
            dtype=ctx.dtype,
            device=ctx.device,
        )
        grad_padded.index_copy_(0, source, grad_final)

        return grad_padded, None


class SparseMoE(nn.Module):
    """
    Token-level top-k MoE。

    输入:
        x: [batch, time, dim]

    输出:
        merged: [batch, time, dim]
        aux_loss: scalar
    """

    def __init__(self, cfg: Config):
        super().__init__()

        self.n_experts = cfg.n_experts
        self.balance_coef = cfg.balance_coef
        self.router = nn.Linear(
            cfg.d_model,
            cfg.n_experts,
            bias=False,
        )

        self.experts = nn.ModuleList([
            Expert(
                cfg.d_model,
                cfg.expert_hidden,
            )
            for _ in range(cfg.n_experts)
        ])

        # 路由诊断探针（RQ3/RQ4）：默认 None，仅在
        # analyze_routing 的诊断前向中挂载。
        self._routing_probe = None

        # 路由干预（RQ4 功能验证）：默认 None。
        #   _routing_override(indices, weights, logits) 返回改写的
        #       (indices, weights)，用于「路由打乱」等反事实；
        #   _expert_drop_index 把指定专家的输出置零，用于
        #       「专家屏蔽」的因果重要性测量。
        # 只在显式启用的评估路径中挂载，训练路径不受影响。
        self._routing_override = None
        self._expert_drop_index: Optional[int] = None

        # 推理路径的零填充缓冲：grad 关闭时按
        # (device, dtype, rows, dim) 取用；训练（grad 开启）时
        # 填充缓冲会经 bmm 进入计算图，必须每次新建。
        self._padded_buffers: Dict[tuple, torch.Tensor] = {}

        # 批量专家路径的权重 stack：键为 "gate_up" / "down"，
        # 值为 (参数版本签名, 失效代数, stack 缓冲)。
        self._weight_stacks: Dict[
            str, Tuple[tuple, int, torch.Tensor]
        ] = {}

        # 失效代数：invalidate_weight_cache 每次递增。
        self._weight_cache_generation = 0

        # 专家权重参数引用。
        self._expert_gate_up_weights: List[torch.Tensor] = []
        self._expert_down_weights: List[torch.Tensor] = []
        self._refresh_expert_weight_lists()

        # dispatch 的行下标 arange：键 (device, n)。
        self._aranges: Dict[
            Tuple[torch.device, int], torch.Tensor
        ] = {}
        self._arange_bytes = 0

    def _refresh_expert_weight_lists(self) -> None:
        self._expert_gate_up_weights = [
            expert.gate_up.weight for expert in self.experts
        ]
        self._expert_down_weights = [
            expert.down.weight for expert in self.experts
        ]

    def _cached_arange(
        self,
        device: torch.device,
        n: int,
        dtype: torch.dtype = torch.int64,
    ) -> torch.Tensor:
        """
        返回 dispatch 的行下标 arange。

        张量只被读取（消费它的算术均为 out-of-place），总量受
        _MOE_ARANGE_CACHE_MAX_BYTES 限制，_apply 迁移设备时
        清空。CUDA 上用 int32 下标，CPU 保持 int64。
        """
        key = (device, dtype, n)
        cached = self._aranges.get(key)
        if cached is not None:
            return cached

        tensor = torch.arange(n, device=device, dtype=dtype)
        bytes_needed = n * tensor.element_size()
        if (
            self._arange_bytes + bytes_needed
            <= _MOE_ARANGE_CACHE_MAX_BYTES
        ):
            self._aranges[key] = tensor
            self._arange_bytes += bytes_needed
        return tensor

    def _apply(self, fn, recurse=True):
        # .to() / .float() 等可能整体替换参数张量（版本号不递增），
        # 相关的 stack、填充缓冲与行下标都必须重建。
        self._weight_stacks.clear()
        self.clear_padded_buffer_cache()
        self._aranges.clear()
        self._arange_bytes = 0
        result = super()._apply(fn, recurse=recurse)
        self._refresh_expert_weight_lists()
        return result

    def clear_padded_buffer_cache(self) -> None:
        """释放当前模块的推理填充缓冲并归还全局额度。"""
        self._padded_buffers.clear()
        _MOE_PADDED_CACHE_REGISTRY.pop(self, None)

    def invalidate_weight_cache(self) -> None:
        """声明 stack 已过期，后续前向在首次使用时刷新。"""
        self._weight_cache_generation += 1

    def _cached_weight_stack(
        self,
        key: str,
        weights: List[torch.Tensor],
    ) -> torch.Tensor:
        """
        返回 [n_experts, ...] 的专家权重 stack。

        stack 以 (autocast dtype, 版本号, 数据指针) 为签名：普通
        原地更新（如 load_state_dict）会推进版本号并触发刷新；
        但 fused AdamW 的原地更新不会推进版本号，因此训练循环
        在 optimizer.step() 后经 invalidate_weight_cache 递增
        失效代数，首次使用时把新参数写回既有缓冲。参数张量被
        替换或迁移设备时由 _apply 重建。CUDA autocast 下 stack
        使用 autocast dtype。需要反向时经 _StackedExpertWeights
        把梯度按专家散回参数，与「torch.stack + bmm」在 autocast
        下的计算图语义相同。
        """
        first = weights[0]
        target_dtype = self._autocast_target_dtype(first)
        if target_dtype is None:
            target_dtype = first.dtype

        shape = (len(weights), *first.shape)
        signature = (
            target_dtype,
            *(
                (weight._version, weight.data_ptr())
                for weight in weights
            ),
        )

        generation = self._weight_cache_generation
        cached = self._weight_stacks.get(key)

        # 反向路径不能使用 inference_mode 下创建的张量（不能
        # 作为保存张量入图），需要时重建。
        reusable_buffer = cached is not None and (
            not torch.is_grad_enabled()
            or not torch.is_inference(cached[2])
        )

        if (
            reusable_buffer
            and cached[0] == signature
            and cached[1] == generation
        ):
            stacked = cached[2]
        else:
            refreshable = (
                reusable_buffer
                and cached[2].shape == shape
                and cached[2].dtype == target_dtype
                and cached[2].device == first.device
            )

            # inference_mode(False) 保证缓冲不携带 inference 标记，
            # 之后可在 no_grad 与训练路径上原地刷新。
            with torch.inference_mode(False), torch.no_grad():
                if refreshable:
                    stacked = cached[2]
                else:
                    stacked = torch.empty(
                        shape,
                        dtype=target_dtype,
                        device=first.device,
                    )
                # 转换语义与 stack 后 .to() 相同；_foreach_copy_
                # 逐专家拷贝（不可用时回退循环）。
                if hasattr(torch, "_foreach_copy_"):
                    torch._foreach_copy_(
                        list(stacked.unbind(0)),
                        list(weights),
                    )
                else:
                    for index, weight in enumerate(weights):
                        stacked[index].copy_(weight)

            self._weight_stacks[key] = (
                signature,
                generation,
                stacked,
            )

        if not torch.is_grad_enabled() or not any(
            weight.requires_grad for weight in weights
        ):
            return stacked

        return _StackedExpertWeights.apply(stacked, *weights)

    def route(
        self,
        x: torch.Tensor,
        top_k: int,
    ) -> Tuple[
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
    ]:
        flat = self._cast_for_autocast(
            x.reshape(-1, x.size(-1))
        )

        router_logits = F.linear(
            flat,
            self.router.weight,
        ).float()

        top_values, top_indices = router_logits.topk(
            top_k,
            dim=-1,
        )

        # top-k 内部的 softmax 等价于完整 softmax 概率的
        # 重新归一化，直接对 top-k logits 求 softmax。
        #
        # top_k == 1 时不能把权重设成常数 1：离散 argmax 的选择
        # 本身不可导，常数权重会让 router 完全收不到语言建模损失
        # 的梯度（只有负载均衡损失还能训练它；balance_coef=0 的
        # 消融臂里 router 就永远停在上一步/初始化）。这里改用
        # Switch Transformer 的口径：取完整 softmax 中选中专家的
        # 概率作为门控权重，概率对 router logits 可导，梯度可以
        # 通过门控缩放回流。
        if top_k == 1:
            full_probs = router_logits.softmax(dim=-1)
            top_weights = full_probs.gather(-1, top_indices)
        else:
            top_weights = top_values.softmax(dim=-1)

        # 路由干预（只用于反事实评估）：在统计 counts / 计算
        # aux loss 之前改写选择，保证后续 dispatch 与负载统计
        # 都使用干预后的 assignment。
        if self._routing_override is not None:
            top_indices, top_weights = self._routing_override(
                top_indices,
                top_weights,
                router_logits,
            )

        # Top-k 版本的 Switch 风格负载均衡损失。
        # f_i 是「被分配给专家 i 的 token 比例」，以 token
        # 数量为分母；均匀路由时 E * sum(f_i * P_i) 恰好等于
        # top_k，均衡强度随路由宽度线性增大，跨 k 比较时
        # 应按比例折算 balance_coef（保持 balance_coef * k 不变）。
        # counts 用 bincount 统计（无 ones_like 分配），输出为
        # int64，后续 dispatch 的索引算术语义与逐 token 计数一致。
        assignment_indices = top_indices.reshape(-1)
        counts = torch.bincount(
            assignment_indices,
            minlength=self.n_experts,
        )

        # 辅助负载均衡项只在梯度开启时可能被消费（总损失、
        # 训练指标）；评估/推理路径（evaluate、measure_efficiency、
        # no_grad 自测）不读取该标量，直接返回零。
        # balance_coef=0 的消融臂仍在 no_grad 下计算同一数值，
        # 保持与训练指标一致。
        if torch.is_grad_enabled():
            if self.balance_coef > 0.0:
                router_probs = router_logits.softmax(dim=-1)
            else:
                with torch.no_grad():
                    router_probs = router_logits.softmax(dim=-1)

            # counts 显式转 fp32，与 soft_load（router_logits 已
            # .float()）保持同一 dtype；归一化就地完成。
            hard_load = counts.float()
            hard_load.div_(flat.size(0))

            soft_load = router_probs.mean(dim=0)

            # 逐专家 f_i * P_i 求和。
            aux_loss = self.n_experts * torch.dot(
                hard_load,
                soft_load,
            )
        else:
            aux_loss = router_logits.new_zeros(())

        # 路由诊断（RQ3/RQ4）：只在显式挂载探针的分析前向中记录；
        # 训练路径上 _routing_probe 为 None。
        if self._routing_probe is not None:
            self._routing_probe.record(
                self,
                x,
                top_indices,
                top_weights,
                router_logits,
            )

        return (
            flat,
            top_indices,
            top_weights,
            counts,
            aux_loss,
        )

    def _autocast_target_dtype(
        self,
        tensor: torch.Tensor,
    ) -> Optional[torch.dtype]:
        """
        CUDA autocast 下返回该张量应转换到的 autocast dtype；
        其余情况返回 None（无需转换）。
        """
        if not tensor.is_cuda or not torch.is_autocast_enabled():
            return None

        try:
            return torch.get_autocast_dtype("cuda")
        except AttributeError:
            return torch.get_autocast_gpu_dtype()

    def _cast_for_autocast(
        self,
        tensor: torch.Tensor,
    ) -> torch.Tensor:
        """
        CUDA autocast 下把张量转换为 autocast dtype；其余情况
        原样返回。
        """
        dtype = self._autocast_target_dtype(tensor)
        if dtype is None:
            return tensor
        return tensor.to(dtype)

    def _padded_buffer(
        self,
        dtype: torch.dtype,
        device: torch.device,
        rows: int,
        dim: int,
    ) -> Optional[torch.Tensor]:
        """
        grad 关闭时返回填充缓冲，否则返回 None（训练时填充缓冲
        会进入计算图，必须新建）。

        评估路径只读取被 index_copy_ 写入的行（其余行的 bmm
        输出不会被收集），旧缓冲中的陈旧值（含 NaN/Inf）不会
        进入任何结果。
        """
        if torch.is_grad_enabled():
            return None

        key = (device, dtype, rows, dim)
        buffer = self._padded_buffers.get(key)
        if buffer is not None:
            return buffer

        bytes_needed = (
            rows * dim * _dtype_element_size(dtype)
        )
        cached_total = sum(_MOE_PADDED_CACHE_REGISTRY.values())
        if (
            cached_total + bytes_needed
            > _MOE_PADDED_CACHE_MAX_BYTES
        ):
            return None

        # inference_mode(False) 保证缓冲不携带 inference 标记，
        # 可在 inference_mode 与 no_grad 下使用。
        with torch.inference_mode(False), torch.no_grad():
            buffer = torch.zeros(
                rows,
                dim,
                dtype=dtype,
                device=device,
            )

        self._padded_buffers[key] = buffer
        _MOE_PADDED_CACHE_REGISTRY[self] = (
            _MOE_PADDED_CACHE_REGISTRY.get(self, 0) + bytes_needed
        )
        return buffer

    def _batched_experts_forward(
        self,
        inputs: torch.Tensor,
    ) -> torch.Tensor:
        """
        对 [n_experts, rows, dim] 的批量输入执行专家计算。

        各专家权重 stack 成批量矩阵后用 bmm 完成两层 GEMM；
        反向按切片把梯度散回各专家参数，参数与检查点格式不变。
        SwiGLU 语义与 Expert.forward 完全一致。填充行的输入是
        精确的 0：其前向输出为 0，对权重梯度的贡献也恒为 0。
        """
        gate_up_weight = self._cached_weight_stack(
            "gate_up",
            self._expert_gate_up_weights,
        )

        gate_up = torch.bmm(
            inputs,
            gate_up_weight.transpose(1, 2),
        )

        down_weight = self._cached_weight_stack(
            "down",
            self._expert_down_weights,
        )

        if gate_up.requires_grad:
            # SwiGLU 与下投影的组合节点。
            return _SwiGLUDown.apply(gate_up, down_weight)

        gate, up = gate_up.chunk(2, dim=-1)
        hidden = F.silu(gate, inplace=True).mul_(up)

        return torch.bmm(
            hidden,
            down_weight.transpose(1, 2),
        )

    def dispatch(
        self,
        flat: torch.Tensor,
        top_indices: torch.Tensor,
        counts: torch.Tensor,
    ) -> torch.Tensor:
        """
        对每个 token-expert assignment 执行专家计算。

        一般路径（n_experts > 1 且 top_k != n_experts）给每个
        专家分配容量 cap（均衡路由下即实际最大桶，倾斜路由
        下为有界的均值上界，见下方注释）：排序后的专家段散射
        进 [n_experts, cap, dim] 的零填充缓冲，经批量 bmm 完成
        容量内的全部专家；超出容量的 assignment 由对应专家的
        2D 前向单独计算。语义与逐专家循环一致（容量内
        为 bmm、溢出为逐专家线性层，均为精确结果）。

        返回:
            [num_tokens, top_k, dim]
        """
        num_tokens, top_k = top_indices.shape
        dim = flat.size(-1)

        # 单专家时所有 token 都路由到同一个专家，
        # 排序等价于恒等排列。
        if self.n_experts == 1:
            expert_flat = self._cast_for_autocast(flat)

            if top_k == 1:
                return self.experts[0].forward(expert_flat).unsqueeze(1)

            # 所有 assignment 指向同一专家：对 [N, dim] 计算后
            # expand 出 slot 维。
            # expand 是 stride=0 视图，后面用 reshape 而不能用 view。
            return self.experts[0].forward(expert_flat).unsqueeze(
                1
            ).expand(
                num_tokens,
                top_k,
                dim,
            )

        # 稠密路由（top_k == n_experts）：每个 token 被分配给
        # 所有专家。所有专家共用同一份输入，expand 出
        # 批量维后经批量 bmm 完成全部专家计算，再按路由下标
        # gather 回 [token, slot] 位置。
        if top_k == self.n_experts:
            expert_flat = self._cast_for_autocast(flat)

            per_expert = self._batched_experts_forward(
                expert_flat.unsqueeze(0).expand(
                    self.n_experts,
                    num_tokens,
                    dim,
                )
            ).transpose(0, 1)
            gather_index = top_indices.unsqueeze(-1).expand(
                num_tokens,
                top_k,
                dim,
            )
            return per_expert.gather(1, gather_index)

        assignment_experts = top_indices.reshape(-1)

        # 收窄仅作用于排序键本身：torch.sort 返回的排序下标
        # 始终是 int64（与其键 dtype 无关），后续 index_select
        # 收集与 index_copy_ 散射的下标不受此处影响；CPU 侧
        # 下标须保持 int64，因此仅在 CUDA 上收窄。
        if assignment_experts.is_cuda:
            assignment_experts = assignment_experts.to(torch.int32)

        # 按 expert id 排序：每个专家的输入在排序后连续，
        # 按段切片分发。同一专家内部的行序不影响结果
        #（专家按行独立计算，散射下标互不重复），因此无需
        # 稳定排序；torch.sort 在相同输入上是确定性的。
        # 排序值即排序后每行所属专家（seg_id）。
        seg_id, perm = torch.sort(assignment_experts)

        # 展平后的 assignment 下标 j 对应 token j // top_k；
        # top_k == 1 时排序下标本身就是 token 下标。
        if top_k == 1:
            sorted_token_ids = perm
        elif top_k == 2:
            # 非负 int64 整除 2 与算术右移等价（精确、向下取整）。
            sorted_token_ids = perm >> 1
        else:
            sorted_token_ids = perm.div(
                top_k,
                rounding_mode="floor",
            )

        # 按排序下标收集输入。autocast 下先转换再收集：
        # 收集结果直接就是目标 dtype，与收集后转换的取值一致。
        gather_source = self._cast_for_autocast(flat)
        gathered = gather_source.index_select(0, sorted_token_ids)

        total = gathered.size(0)
        device = gathered.device
        n_experts = self.n_experts

        # 容量上界：基础容量取均值上界 ceil(total / n_experts)，
        # 再加 1 倍标准差的静态余量（只依赖 assignment 总数）。
        # 实际容量再按本步最大桶收紧，并按 32 对齐。多出的行是
        # 精确 0 填充，不改变任何输出；最大桶超过静态上界时，
        # 下面的逐专家回退路径保证语义不变。
        static_cap = -(-total // n_experts)
        static_cap += math.isqrt(max(1, static_cap)) + 1

        # 各专家段在排序序列中的起始行（exclusive 前缀和）。
        starts = torch.cumsum(counts, dim=0)
        starts.sub_(counts)

        # CUDA 上下标收窄为 int32（与上面的排序键一致）。
        # 行数达到 int32 上限的极端情况仍用 int64，避免溢出。
        index_dtype = (
            torch.int32
            if device.type == "cuda" and total < 2 ** 31
            else torch.int64
        )
        if index_dtype == torch.int32:
            starts = starts.to(index_dtype)

        # 溢出判定只需要看每专家的 assignment 数：同一专家的段在
        # 排序序列中连续，段内局部行号为 0..counts[e]-1，因此
        # 「存在溢出」等价于 counts 的最大值超过容量。
        counts_list = counts.tolist()
        bucket = max(counts_list) if counts_list else 0
        cap = static_cap
        if bucket > 0:
            cap = min(
                static_cap,
                -(-bucket // 32) * 32,
            )
        has_overflow = bucket > cap

        # 行下标。
        row_ids = self._cached_arange(
            device,
            total,
            index_dtype,
        )

        # 每个专家在填充缓冲中的跨度。有溢出时额外留一行
        # scratch：溢出行写入该专家的 scratch 行（有效行不受
        # 影响），其输出随后被回退结果覆盖。
        stride = cap + 1 if has_overflow else cap

        # 目标行号 dest[j] = seg_id[j] * stride + local[j]；
        # 溢出路径把 local 夹到 cap，让溢出行落到 scratch 行。
        if has_overflow:
            local = (
                row_ids
                - starts.index_select(0, seg_id)
            )
            dest = (
                seg_id.to(index_dtype) * stride
                + local.clamp_(max=cap)
            )
        else:
            expert_offsets = (
                self._cached_arange(
                    device,
                    n_experts,
                    index_dtype,
                ) * stride
                - starts
            ).index_select(0, seg_id)
            dest = row_ids + expert_offsets

        padded = self._padded_buffer(
            gathered.dtype,
            device,
            n_experts * stride,
            dim,
        )
        if padded is None:
            padded = gathered.new_zeros(
                n_experts * stride,
                dim,
            )

        padded.index_copy_(0, dest, gathered)

        if not has_overflow:
            # 常规路径到此 gathered 的数据不再被任何一方引用
            #（index_select / index_copy_ 的反向只保存下标）；
            # 溢出路径下方回退仍需读取 gathered，保持引用。
            del gathered

        out = self._batched_experts_forward(
            padded.view(n_experts, stride, dim)
        ).view(n_experts * stride, dim)

        # 散射回原始（未排序）assignment 顺序：perm[j] 是排序
        # 行 j 的原始位置，因此 source[perm[j]] = dest[j]。
        source = dest.new_empty(total)
        source.scatter_(0, perm, dest)
        final = _GatherPaddedExpertOutputs.apply(
            out,
            source,
        )

        # 溢出回退：容量外的 assignment 由对应专家的 2D 前向计算
        # 后写入同一缓冲。排序后每个专家的段连续，溢出行恰为段
        # 尾的 count-cap 行。
        if has_overflow:
            experts = self.experts
            segment_start = 0
            for expert_index, count in enumerate(counts_list):
                if count > cap:
                    rows = slice(
                        segment_start + cap,
                        segment_start + count,
                    )
                    final.index_copy_(
                        0,
                        perm[rows],
                        experts[expert_index].forward(
                            gathered[rows]
                        ),
                    )
                segment_start += count

        return final.view(num_tokens, top_k, dim)

    def unmerged(
        self,
        x: torch.Tensor,
        top_k: int,
    ) -> Tuple[
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
    ]:
        flat, top_indices, top_weights, counts, aux_loss = self.route(
            x,
            top_k,
        )

        expert_outputs = self.dispatch(
            flat,
            top_indices,
            counts,
        )

        # dispatch 的 n_experts == 1 分支返回 expand 视图，
        # 此处用 reshape 处理非连续输入。
        expert_outputs = expert_outputs.reshape(
            *x.shape[:-1],
            top_k,
            x.size(-1),
        )

        top_weights = top_weights.view(
            *x.shape[:-1],
            top_k,
        )

        top_indices = top_indices.view(
            *x.shape[:-1],
            top_k,
        )

        # 专家屏蔽干预：把指定专家的输出置零（路由与门控保持
        # 不变），用于测量「该专家对当前 token 的因果贡献」。
        # 不做均值替换，以免引入额外的分布外输入；屏蔽后的
        # 损失上升幅度是专家功能重要性的直接证据。
        if self._expert_drop_index is not None:
            drop = int(self._expert_drop_index)
            mask = (top_indices == drop).to(
                expert_outputs.dtype
            )
            expert_outputs = expert_outputs * (
                1.0 - mask.unsqueeze(-1)
            )

        return (
            expert_outputs,
            top_weights,
            top_indices,
            aux_loss,
        )

    def merge(
        self,
        expert_outputs: torch.Tensor,
        top_weights: torch.Tensor,
        out_shape: torch.Size,
        residual: Optional[torch.Tensor] = None,
        residual_scale: float = 1.0,
    ) -> torch.Tensor:
        """
        门控加权合并 […, top_k, dim] 的专家输出。

        加权和以逐 slot 的 mul + addcmul 累加实现，
        等价于广播乘后沿 top_k 维求和；dtype 不匹配
        （autocast 残差流精度更高）时同一路径靠类型提升
        合并残差，语义不变。所有路径均为 out-of-place，
        不修改调用方传入的张量。
        """
        top_k = expert_outputs.size(-2)
        dim = expert_outputs.size(-1)

        # top_k == 1 时门控权重是选中专家的完整 softmax 概率
        # （Switch 风格，见 route 注释），不能当成恒等 1.0；
        # 加权和退化为逐行乘概率后再加残差。
        if top_k == 1:
            output = expert_outputs.reshape(-1, dim)
            weights = top_weights.reshape(-1, 1).to(output.dtype)
            output = output * weights

            if residual is not None:
                flat_residual = residual.reshape(-1, dim)

                # dtype 一致时「缩放 + 残差相加」仍保持
                # out-of-place：不修改调用方传入的张量。
                if output.dtype == flat_residual.dtype:
                    if residual_scale != 1.0:
                        output = output.mul(residual_scale)
                    return output.add(flat_residual).view(out_shape)

                return torch.add(
                    flat_residual,
                    output,
                    alpha=residual_scale,
                ).view(out_shape)

            return output.view(out_shape)

        # 权重补出 slot 维并转换 dtype。
        weights = top_weights.to(
            expert_outputs.dtype
        ).unsqueeze(-1)

        # 对 expert_outputs / weights 保持 out-of-place；
        # unbind 出的 slot 视图与逐次 select 等价。
        slots = expert_outputs.unbind(-2)
        weight_slots = weights.unbind(-2)

        merged = slots[0].mul(weight_slots[0])
        for index in range(1, top_k):
            merged.addcmul_(
                slots[index],
                weight_slots[index],
            )

        merged = merged.reshape(out_shape)

        if residual is not None:
            # dtype 一致时原地累加；dtype 不匹配（autocast）时
            # 用 add(alpha=) 完成「缩放 + 残差相加」。
            if merged.dtype == residual.dtype:
                if residual_scale != 1.0:
                    merged.mul_(residual_scale)
                return merged.add_(residual)

            merged = torch.add(
                residual,
                merged,
                alpha=residual_scale,
            )

        return merged

    def forward(
        self,
        x: torch.Tensor,
        top_k: int,
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        expert_outputs, top_weights, _, aux_loss = self.unmerged(
            x,
            top_k,
        )

        merged = self.merge(
            expert_outputs,
            top_weights,
            x.shape,
        )

        return merged, aux_loss


# ============================================================
# Transformer block
# ============================================================

class TransformerBlock(nn.Module):
    def __init__(self, cfg: Config):
        super().__init__()

        self.norm_attn = RMSNorm(cfg.d_model)
        self.attn = CausalSelfAttention(cfg)

        self.norm_moe = RMSNorm(cfg.d_model)

        # dense 基线模式：用单个稠密 SwiGLU FFN 替代 SparseMoE，
        # 其余结构（注意力、残差、归一化）与 MoE 模式完全一致，
        # 用于隔离「MoE + 中间层循环」本身带来的收益。
        self.is_dense = cfg.mode == "dense"

        if self.is_dense:
            self.ffn = Expert(
                cfg.d_model,
                cfg.effective_dense_fnn_hidden,
            )
            self.moe = None
        else:
            self.ffn = None
            self.moe = SparseMoE(cfg)

        self.residual_scale = cfg.residual_scale

    def attention_step(
        self,
        x: torch.Tensor,
        scale: Optional[float] = None,
        attn_mask: Optional[SegmentAttentionMask] = None,
    ) -> torch.Tensor:
        # scale 由 LanguageModel 按区域传入：循环区域内使用
        # loop_residual_scale（paper 口径为 residual_scale/r），
        # 区域外与历史行为一致使用 residual_scale。
        scale = self.residual_scale if scale is None else scale
        core = self.attn.core(self.norm_attn(x), attn_mask)

        # dtype 一致（非 autocast，如 CPU/fp32）时以 addmm
        # 计算「投影 + 缩放 + 残差相加」；autocast 下 dtype
        # 不匹配，改用普通投影加残差。
        if core.dtype == x.dtype:
            batch, length, dim = x.shape
            return torch.addmm(
                x.reshape(-1, dim),
                core.reshape(-1, dim),
                self.attn.out.weight.t(),
                beta=1.0,
                alpha=scale,
            ).view(batch, length, dim)

        # add(alpha=) 完成「缩放 + 相加」。
        return torch.add(
            x,
            F.linear(core, self.attn.out.weight),
            alpha=scale,
        )

    def moe_step(
        self,
        x: torch.Tensor,
        top_k: int,
        scale: Optional[float] = None,
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        scale = self.residual_scale if scale is None else scale
        # dense 基线：无路由，无辅助损失；top_k 参数被忽略，
        # 保持与 MoE 模式一致的调用签名。
        if self.is_dense:
            y = self.ffn(self.norm_moe(x))
            return (
                torch.add(
                    x,
                    y,
                    alpha=scale,
                ),
                x.new_zeros(()),
            )

        expert_outputs, top_weights, _, aux_loss = (
            self.moe.unmerged(
                self.norm_moe(x),
                top_k,
            )
        )

        x = self.moe.merge(
            expert_outputs,
            top_weights,
            x.shape,
            residual=x,
            residual_scale=scale,
        )
        return x, aux_loss

    def forward(
        self,
        x: torch.Tensor,
        top_k: int,
        scale: Optional[float] = None,
        attn_mask: Optional[SegmentAttentionMask] = None,
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        x = self.attention_step(x, scale, attn_mask)
        return self.moe_step(x, top_k, scale)

    def first_branch_step(
        self,
        x: torch.Tensor,
        k1: int,
        scale: Optional[float] = None,
        attn_mask: Optional[SegmentAttentionMask] = None,
    ) -> Tuple[
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
    ]:
        """
        B 的第一轮第一个 Block。

        输入:
            x: [batch, time, dim]

        输出:
            branches:
                [batch, k1, time, dim]

            gates:
                [batch, time, k1]

            indices:
                [batch, time, k1]

            aux_loss:
                scalar
        """
        scale = self.residual_scale if scale is None else scale
        x = self.attention_step(x, scale, attn_mask)

        expert_outputs, gates, indices, aux_loss = self.moe.unmerged(
            self.norm_moe(x),
            k1,
        )

        # expert_outputs:
        # [batch, time, k1, dim]
        #
        # 每个分支保留完整残差：x + scale * expert。
        # gate 只在这里为 k1==1 预乘：单分支最终收缩是恒等，
        # 不预乘会丢掉 Switch 风格的门控概率。k1>1 时最终
        # 跨分支收缩已经按同一组 gate 加权，这里再乘会让第一
        # 轮专家贡献变成 p_i²·expert（门控被应用两次）。
        branch_experts = expert_outputs
        if int(k1) == 1:
            branch_experts = expert_outputs * gates.to(
                expert_outputs.dtype
            ).unsqueeze(-1)
        branches = torch.add(
            x.unsqueeze(1),
            branch_experts.permute(0, 2, 1, 3),
            alpha=scale,
        )

        return (
            branches,
            gates,
            indices,
            aux_loss,
        )

    def local_two_stage(
        self,
        x: torch.Tensor,
        k1: int,
        k2: int,
        delayed: bool,
        scale: Optional[float] = None,
        second_round_width: Optional[int] = None,
        attn_mask: Optional[SegmentAttentionMask] = None,
    ) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        """
        A/local_base/local_base_k2 的局部对照。

        返回值固定为张量三元组 (x, aux1, aux2)，与
        _BlockCheckpoint 的「输出是张量元组」约定一致。

        second_round_width:
            None  —— local_base 的等专家计算量口径：第二轮
                     宽度取 min(n_experts, k1*k2)；
            显式值 —— 机制对照 local_base_k2 取 k2，只改变
                     合并时机，不把第二轮宽度一起改掉。
        """
        scale = self.residual_scale if scale is None else scale
        x = self.attention_step(x, scale, attn_mask)

        if not delayed:
            # 等专家计算量对照：A 在 k1 个分支上各路由 k2 个
            # 专家，单分支的第二轮相应取 min(E, k1*k2) 个专家。
            # 机制对照则固定第二轮为 k2（见 second_round_width）。
            matched_k2 = (
                min(self.moe.n_experts, k1 * k2)
                if second_round_width is None
                else int(second_round_width)
            )
            x, aux1 = self.moe_step(x, k1, scale)
            x, aux2 = self.moe_step(x, matched_k2, scale)
            # 第二轮宽度是计算量对齐的产物；aux loss 约随
            # 路由宽度线性增长（见 SparseMoE.route 注释）。
            # 把 local_base 的 aux2 折算回 A/B 的单分支宽度
            # k2，保证全因子消融中 balance_coef 代表同一均衡
            # 强度，而不是让「立即合并」臂意外多受均衡压力。
            # local_base_k2 的第二轮本来就是 k2，无需折算。
            if (
                second_round_width is None
                and matched_k2 != k2
            ):
                aux2 = aux2 * (
                    float(k2) / float(matched_k2)
                )
            return x, aux1, aux2

        expert_outputs, gates, _, aux1 = self.moe.unmerged(
            self.norm_moe(x),
            k1,
        )

        # k1==1 时最终收缩是恒等，必须在这里乘第一轮门控
        # （top_k=1 时是选中概率，不是 1）；k1>1 时最终收缩
        # 会按同一组 gate 加权，预乘会让第一轮专家贡献变成
        # p_i²·expert（门控被应用两次）。
        if int(k1) == 1:
            expert_outputs = expert_outputs * gates.to(
                expert_outputs.dtype
            ).unsqueeze(-1)

        # 残差并入 expert_outputs：dtype 一致时原地完成
        # x + scale * (gate*expert)；dtype 不匹配时用
        # add(alpha=) 合并。
        if expert_outputs.dtype == x.dtype:
            if scale != 1.0:
                expert_outputs.mul_(
                    scale,
                )
            expert_outputs.add_(
                x.unsqueeze(-2),
            )
            branches = expert_outputs
        else:
            branches = torch.add(
                x.unsqueeze(-2),
                expert_outputs,
                alpha=scale,
            )

        # branches:
        # [batch, time, k1, dim]
        #
        # SparseMoE 支持任意前置维度，因此每个 branch
        # 的 token 会独立经过 Router。
        expert_outputs2, gates2, _, aux2 = self.moe.unmerged(
            self.norm_moe(branches),
            k2,
        )

        branches = self.moe.merge(
            expert_outputs2,
            gates2,
            branches.shape,
            residual=branches,
            residual_scale=scale,
        )

        # 第一轮门控权重在第二轮结束后使用。
        if branches.size(-2) == 1:
            # k1 == 1 时分支已包含完整残差，第一轮专家输出
            # 已按 p1 缩放；不能再乘一次 p1（会缩放残差）。
            x = branches.squeeze(-2)
        else:
            # 跨分支的门控加权和：逐分支 mul + addcmul 累加，
            # 对 branches / gates 保持 out-of-place。
            weights = gates.to(branches.dtype).unsqueeze(-1)

            x = branches.select(-2, 0).mul(
                weights.select(-2, 0)
            )
            for index in range(1, branches.size(-2)):
                x.addcmul_(
                    branches.select(-2, index),
                    weights.select(-2, index),
                )

        return x, aux1, aux2


# ============================================================
# Model
# ============================================================

def _checkpoint_discard(tensor: torch.Tensor):
    """
    前向期间丢弃全部中间激活：占位符不持有数据，前向图在
    _BlockCheckpoint.forward 返回时连同占位符一起释放。
    """
    return None


def _checkpoint_restore(packed):
    # 占位符不会被解包：反向走 _BlockCheckpoint 自己的重算
    # 路径；若被解包说明有代码试图使用被丢弃的前向图。
    raise RuntimeError(
        "_BlockCheckpoint 的中间激活占位符不可解包"
    )


def _autocast_snapshot() -> List[Tuple[str, bool, torch.dtype, bool]]:
    """
    记录当前进程的 autocast 状态（CUDA / CPU 各一份）。

    _BlockCheckpoint 的前向可能在外层 autocast 上下文中执行，
    而反向重算发生在 loss.backward()（autocast 上下文之外）。
    必须按前向时记录的状态重入 autocast，否则 AMP 训练开启
    grad checkpoint 后，重算图走了 fp32 的 dtype 路径，梯度与
    不开启 checkpoint 的同一训练不同（torch.utils.checkpoint
    的非重入实现同样保存并恢复 autocast 状态）。
    """
    states: List[Tuple[str, bool, torch.dtype, bool]] = []

    for device_type in ("cuda", "cpu"):
        try:
            available = torch.amp.is_autocast_available(device_type)
        except AttributeError:
            # 旧版 torch 没有 torch.amp.is_autocast_available。
            available = (
                device_type == "cpu" or torch.cuda.is_available()
            )
        if not available:
            continue

        try:
            enabled = torch.is_autocast_enabled(device_type)
        except TypeError:
            # 旧版 torch 的 is_autocast_enabled 不接受设备参数。
            enabled = (
                torch.is_autocast_cpu_enabled()
                if device_type == "cpu"
                else torch.is_autocast_enabled()
            )

        try:
            dtype = torch.get_autocast_dtype(device_type)
        except AttributeError:
            dtype = (
                torch.get_autocast_cpu_dtype()
                if device_type == "cpu"
                else torch.get_autocast_gpu_dtype()
            )

        states.append(
            (
                device_type,
                enabled,
                dtype,
                torch.is_autocast_cache_enabled(),
            )
        )

    return states


class _BlockCheckpoint(torch.autograd.Function):
    """
    Block 前向的非重入 activation checkpointing。

    与 torch.utils.checkpoint(use_reentrant=False) 语义一致：
    前向在梯度开启下按原样执行——依赖梯度状态的算子（如
    route 的辅助负载均衡损失）取值与直接调用完全一致——
    但经 saved_tensors_hooks 把全部中间激活替换为占位符，
    因此前向不保留任何反向所需的激活；反向用同一输入、
    同一算子顺序重算前向，并把梯度同时回传给输入与重算图
    中的参数叶子。

    所有 Block 内都没有 dropout 等随机算子，输出固定为张量
    元组。
    """

    @staticmethod
    def forward(ctx, fn, *args):
        ctx.fn = fn
        ctx.args = args
        ctx.autocast_states = _autocast_snapshot()
        ctx.save_for_backward(
            *(arg for arg in args if torch.is_tensor(arg))
        )

        # autograd.Function.forward 默认在 no_grad 下执行；Block
        # 内存在依赖梯度状态的算子（route 的辅助负载均衡损失
        # 按 torch.is_grad_enabled() 分支返回零），必须显式开启
        # 梯度，否则前向数值与被记录的训练损失和直接调用不一致
        #（torch.utils.checkpoint(use_reentrant=False) 同样如此）。
        with torch.enable_grad(), (
            torch.autograd.graph.saved_tensors_hooks(
                _checkpoint_discard,
                _checkpoint_restore,
            )
        ):
            outputs = fn(*args)

        if not isinstance(outputs, tuple):
            outputs = (outputs,)

        # 与前向图脱钩后只保留数值；requires_grad 由 autograd
        # 依据输入设置，梯度完全来自反向的本节点重算。
        return tuple(
            output.detach()
            if torch.is_tensor(output)
            else output
            for output in outputs
        )

    @staticmethod
    def backward(ctx, *grad_outputs):
        saved = iter(ctx.saved_tensors)
        rebuilt: List[object] = []
        grad_flags: List[bool] = []
        inputs: List[torch.Tensor] = []

        # 需要梯度的输入张量重建成新的叶子，其余参数原样传入；
        # 重算路径与直接调用逐位一致。
        for arg in ctx.args:
            if not torch.is_tensor(arg):
                rebuilt.append(arg)
                grad_flags.append(False)
                continue

            tensor = next(saved)
            if tensor.requires_grad:
                tensor = tensor.detach().requires_grad_(True)
                inputs.append(tensor)
                grad_flags.append(True)
            else:
                grad_flags.append(False)
            rebuilt.append(tensor)

        with contextlib.ExitStack() as stack:
            stack.enter_context(torch.enable_grad())
            # 恢复前向时的 autocast 状态：AMP 下重算图的 dtype
            # 路径必须与前向一致，梯度才与不开启 checkpoint 的
            # 同一训练相同。
            for (
                device_type,
                enabled,
                dtype,
                cache_enabled,
            ) in ctx.autocast_states:
                stack.enter_context(
                    torch.autocast(
                        device_type=device_type,
                        dtype=dtype,
                        enabled=enabled,
                        cache_enabled=cache_enabled,
                    )
                )
            recomputed = ctx.fn(*rebuilt)

        # 反传放在 autocast 上下文之外：与直接调用路径一致
        # （训练循环的 loss.backward() 就在 autocast 之外执行），
        # 也与 torch.utils.checkpoint 的非重入实现一致——重算在
        # autocast 内、重算图的反向在 autocast 外。
        if not isinstance(recomputed, tuple):
            recomputed = (recomputed,)

        # 只对「需要梯度且收到了上游梯度」的输出反传；其余
        # 输出（如整数下标张量）没有梯度项。
        pairs = [
            (output, grad)
            for output, grad in zip(recomputed, grad_outputs)
            if grad is not None
            and torch.is_tensor(output)
            and output.requires_grad
        ]

        if pairs:
            torch.autograd.backward(
                [output for output, _ in pairs],
                grad_tensors=[grad for _, grad in pairs],
            )

        grad_iter = iter(inputs)
        arg_grads = tuple(
            next(grad_iter).grad if flag else None
            for flag in grad_flags
        )

        return (None,) + arg_grads


def _tensor_content_sha256(tensor: torch.Tensor) -> str:
    """张量内容的稳定 sha256（先转 CPU fp32 连续布局）。"""
    array = (
        tensor.detach()
        .to(device="cpu", dtype=torch.float32)
        .contiguous()
    )
    try:
        payload = array.numpy().tobytes()
    except (TypeError, RuntimeError):
        payload = bytes(
            array.reshape(-1).view(torch.uint8).tolist()
        )
    return hashlib.sha256(payload).hexdigest()


class LanguageModel(nn.Module):
    def __init__(self, cfg: Config):
        super().__init__()

        cfg.validate()

        if cfg.mode not in Config.MODEL_MODES:
            raise ValueError(
                f"LanguageModel 不支持 mode={cfg.mode}"
                "（ngram 等统计基线不走本类）"
            )

        self.cfg = cfg

        self.token_embedding = nn.Embedding(
            cfg.vocab_size,
            cfg.d_model,
        )

        self.position_embedding = nn.Embedding(
            cfg.seq_len,
            cfg.d_model,
        )

        self.blocks = nn.ModuleList([
            TransformerBlock(cfg)
            for _ in range(cfg.n_layers)
        ])

        self.final_norm = RMSNorm(cfg.d_model)

        self.lm_head = nn.Linear(
            cfg.d_model,
            cfg.vocab_size,
            bias=False,
        )

        # 共享输入 embedding 和输出 projection。
        self.lm_head.weight = self.token_embedding.weight

        self.middle_start = cfg.middle_start
        self.middle_end = cfg.middle_end

        # 中间区域 Block 的元组。
        self.middle_blocks = tuple(
            self.blocks[i]
            for i in range(self.middle_start, self.middle_end)
        )

        # 与 position_embedding.weight 指向同一参数（共享存储）。
        # 经 object.__setattr__ 写入实例字典，不重复注册到
        # _parameters。
        object.__setattr__(
            self,
            "position_embedding_weight",
            self.position_embedding.weight,
        )

        self.middle_blocks_rest = self.middle_blocks[1:]

        # 是否对每个 Block 使用 activation checkpointing：
        # 开启后反向时重算前向激活。
        # 由训练入口根据命令行参数开启，默认关闭。
        self.grad_checkpoint = False

        if cfg.init_scheme == "name_hash":
            self._init_weights_by_name()
        else:
            self.apply(self._init_weights)

        # 初始化指纹在训练前计算，用于同种子跨结构核对：
        # shared 覆盖所有模式共有的参数，moe/ffn 分别记录
        # 两条结构分支独有的参数。指纹不进入 state_dict。
        self.init_fingerprints = self._initialization_fingerprints()

    @staticmethod
    def _init_weights(module: nn.Module):
        if isinstance(module, (nn.Linear, nn.Embedding)):
            nn.init.normal_(
                module.weight,
                mean=0.0,
                std=0.02,
            )

    def _init_weights_by_name(self) -> None:
        """
        初始化不依赖模块构造顺序，只依赖运行种子与参数名。

        同一参数名在不同 mode 中会得到完全相同的初始权重，
        A/B/local_base 的共享层因此可以在同种子下逐位配对；
        mode 独有的参数按各自名字取独立随机流。使用 CPU
        generator 生成后再搬运，保证同一份代码在 CPU/CUDA
        上得到相同的初始值。
        """
        base_seed = int(torch.initial_seed())
        seen: set = set()
        for module_name, module in self.named_modules():
            if not isinstance(module, (nn.Linear, nn.Embedding)):
                continue
            weight = module.weight
            if id(weight) in seen:
                continue
            seen.add(id(weight))
            name = (
                f"{module_name}.weight"
                if module_name
                else "weight"
            )
            digest = hashlib.sha256(
                f"{base_seed}:{name}".encode("utf-8")
            ).digest()
            generator = torch.Generator(device="cpu")
            generator.manual_seed(
                int.from_bytes(digest[:8], "little")
                & ((1 << 63) - 1)
            )
            values = torch.empty(
                weight.shape,
                dtype=torch.float32,
            )
            values.normal_(
                0.0,
                0.02,
                generator=generator,
            )
            with torch.no_grad():
                weight.copy_(
                    values.to(
                        device=weight.device,
                        dtype=weight.dtype,
                    )
                )

    def _initialization_fingerprints(self) -> Dict[str, object]:
        """按参数类别计算训练前初始权重的 sha256。"""
        buckets: Dict[str, List[Tuple[str, str]]] = {
            "shared": [],
            "moe": [],
            "ffn": [],
        }
        for name, parameter in self.named_parameters():
            if ".moe." in name:
                bucket = "moe"
            elif ".ffn." in name:
                bucket = "ffn"
            else:
                bucket = "shared"
            buckets[bucket].append(
                (name, _tensor_content_sha256(parameter))
            )

        fingerprints: Dict[str, object] = {
            "scheme": self.cfg.init_scheme,
        }
        for bucket, entries in buckets.items():
            digest = hashlib.sha256()
            for name, content_digest in sorted(entries):
                digest.update(name.encode("utf-8"))
                digest.update(b"\0")
                digest.update(content_digest.encode("ascii"))
                digest.update(b"\n")
            fingerprints[f"{bucket}_sha256"] = (
                digest.hexdigest() if entries else None
            )
            fingerprints[f"{bucket}_tensors"] = len(entries)
        return fingerprints

    def _call(self, fn, *args):
        """
        统一所有 Block 调用的入口。

        开启 grad_checkpoint 时对 Block 前向使用
        _BlockCheckpoint 的非重入 activation checkpointing，
        数值结果与直接调用一致。
        """
        # 梯度关闭时（evaluate 的 inference_mode / no_grad、以及
        # 纯前向探测）checkpoint 只会原样调用 fn，此时直接调用，
        # 数值结果完全一致。
        if self.grad_checkpoint and torch.is_grad_enabled():
            return _BlockCheckpoint.apply(fn, *args)
        return fn(*args)

    def invalidate_weight_caches(self) -> None:
        """
        使所有 MoE Block 的专家权重 stack 缓存失效。

        fused AdamW 原地更新参数时不会推进张量的版本号，
        _cached_weight_stack 的版本签名无法感知更新，因此
        optimizer.step() 后必须显式声明失效，否则后续前向会
        复用更新前的专家权重。
        """
        for block in self.blocks:
            if block.moe is not None:
                block.moe.invalidate_weight_cache()

    def run_independent_blocks(
        self,
        block: TransformerBlock,
        branches: torch.Tensor,
        top_k: int,
        scale: Optional[float] = None,
        attn_mask: Optional[SegmentAttentionMask] = None,
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        """
        对每个 branch 独立执行完整 Transformer Block。

        输入:
            [batch, n_branches, time, dim]

        将 branch 维并入 batch 维以后：
            [batch * n_branches, time, dim]

        因而不同 branch 不会互相做 self-attention。
        """
        batch, n_branches, time, dim = branches.shape

        flat = branches.reshape(
            batch * n_branches,
            time,
            dim,
        )

        flat, aux_loss = block(
            flat,
            top_k,
            scale,
            attn_mask,
        )

        branches = flat.view(
            batch,
            n_branches,
            time,
            dim,
        )

        return branches, aux_loss

    def forward(
        self,
        input_ids: torch.Tensor,
        targets: Optional[torch.Tensor] = None,
        segment_ids: Optional[torch.Tensor] = None,
    ) -> Dict[str, torch.Tensor]:
        cfg = self.cfg

        batch, time = input_ids.shape

        if time > cfg.seq_len:
            raise ValueError(
                f"序列长度 {time} 超过 cfg.seq_len={cfg.seq_len}"
            )

        # token embedding 与按序列长度切片的位置 embedding 相加。
        x = F.embedding(input_ids, self.token_embedding.weight)
        x.add_(
            self.position_embedding_weight[:time]
        )

        # 文档级 segment attention mask（论文 3.1 节）。显式传入
        # segment_ids 时优先使用（测试/分析）；否则在启用
        # cfg.document_masks 时从 token 流里的文档分隔符推导。
        # B/B_early 把分支并入 batch 维，需要一份按 k1 复制的
        # 掩码；其余模式的 Attention 在原始 batch 上执行。
        if segment_ids is None and cfg.document_masks:
            segment_ids = document_segment_ids(
                input_ids,
                cfg.document_separator or (),
            )
        attn_bias: Optional[SegmentAttentionMask] = None
        branch_attn_bias: Optional[SegmentAttentionMask] = None
        if segment_ids is not None:
            attn_bias = SegmentAttentionMask(segment_ids)
            if cfg.mode in ("B", "B_early"):
                # k1==1 时分支仍会把 branch 维并入 batch 维执行
                # 后续中间 Block；掩码必须同样按 k1 复制，否则
                # 除第一个中间 Block 外的所有 Block 都会退化为
                # 跨文档的普通因果注意力。
                branch_attn_bias = SegmentAttentionMask(
                    segment_ids.repeat_interleave(
                        int(cfg.k1), 0
                    )
                )

        aux_losses: List[torch.Tensor] = []

        blocks = self.blocks
        call = self._call

        # dense 模式没有中间循环区域，全部 Block 由下面的 dense
        # 分支统一执行；跳过前后区域循环，避免边界 Block 重复执行。
        pre_end = 0 if cfg.mode == "dense" else self.middle_start

        # 残差缩放：循环区域外的子层用 residual_scale；循环
        # 区域内的子层在 paper 口径下额外除以循环次数 r。
        global_scale = cfg.residual_scale
        loop_scale = cfg.loop_residual_scale

        # 中间区域之前的层。
        for index in range(pre_end):
            x, aux = call(
                blocks[index],
                x,
                cfg.top_k,
                global_scale,
                attn_bias,
            )
            aux_losses.append(aux)

        middle = self.middle_blocks

        # ----------------------------------------------------
        # Dense baseline: 纯稠密 Transformer，每个 Block 只
        # 执行一次，无 MoE、无中间层循环。
        # ----------------------------------------------------
        if cfg.mode == "dense":
            for index in range(cfg.n_layers):
                x, aux = call(
                    blocks[index],
                    x,
                    cfg.top_k,
                    global_scale,
                    attn_bias,
                )
                aux_losses.append(aux)

        # ----------------------------------------------------
        # 论文的未循环 MoE 基线：middle 只执行一次。
        # ----------------------------------------------------
        elif cfg.mode == "base":
            for block in middle:
                x, aux = call(
                    block,
                    x,
                    cfg.top_k,
                    global_scale,
                    attn_bias,
                )
                aux_losses.append(aux)

        # ----------------------------------------------------
        # Original SMELT：middle 循环两次，循环区域内每个子层
        # 的残差更新按 1/r 缩放（paper 口径）。
        # ----------------------------------------------------
        elif cfg.mode == "smelt":
            for _ in range(2):
                for block in middle:
                    x, aux = call(
                        block,
                        x,
                        cfg.top_k,
                        loop_scale,
                        attn_bias,
                    )
                    aux_losses.append(aux)

        # ----------------------------------------------------
        # Scheme B / B 的等计算量机制对照 B_early
        # ----------------------------------------------------
        elif cfg.mode in ("B", "B_early"):
            if len(middle) == 0:
                raise RuntimeError(
                    "中间层不能为空"
                )

            # 第一轮：
            # 在第一个中间 Block 的 MoE 处创建 k1 个分支。
            branches, gates, _, aux = call(
                middle[0].first_branch_step,
                x,
                cfg.k1,
                loop_scale,
                attn_bias,
            )
            aux_losses.append(aux)

            # 第一轮剩余中间 Block。
            for block in self.middle_blocks_rest:
                branches, aux = call(
                    self.run_independent_blocks,
                    block,
                    branches,
                    cfg.k1,
                    loop_scale,
                    branch_attn_bias,
                )
                aux_losses.append(aux)

            # B_early：分支数与后续 Attention/MoE 执行次数保持
            # 与 B 一致，只在第一轮结束后提前合并，再把合并状态
            # 复制回 k1 个分支继续第二轮。这样合并位置是唯一
            # 改变的因素；第二轮各分支状态相同是提前合并的
            # 直接后果，而不是额外减少了计算量。
            if cfg.mode == "B_early":
                if branches.size(1) == 1:
                    merged = branches.squeeze(1)
                else:
                    branch_weights = gates.to(
                        branches.dtype
                    ).unsqueeze(-1).unbind(-2)
                    merged = branches[:, 0].mul(
                        branch_weights[0]
                    )
                    for index in range(1, len(branch_weights)):
                        merged.addcmul_(
                            branches[:, index],
                            branch_weights[index],
                        )
                branches = merged.unsqueeze(1).expand(
                    -1,
                    cfg.k1,
                    -1,
                    -1,
                ).contiguous()

            # 第二轮完整执行整个中间区域。
            for block in middle:
                branches, aux = call(
                    self.run_independent_blocks,
                    block,
                    branches,
                    cfg.k2,
                    loop_scale,
                    branch_attn_bias,
                )
                aux_losses.append(aux)

            # 只有第二轮结束后，才跨第一轮分支合并。
            #
            # gates:
            # [batch, time, k1]
            #
            # branches:
            # [batch, k1, time, dim]
            #
            if branches.size(1) == 1:
                # k1 == 1 时分支已包含完整残差，且第一轮专家
                # 输出已按选中概率 p1 缩放（Switch 风格）；
                # 不能再把整条分支乘一次 p1，否则残差也会被
                # 缩放。单个分支求和等价于恒等。
                x = branches.squeeze(1)
            else:
                # 归一化后的 top-k gate 在每个 token 上和为 1。
                # 跨分支收缩按分支顺序加权累加。
                branch_weights = gates.to(
                    branches.dtype
                ).unsqueeze(-1).unbind(-2)

                x = branches[:, 0].mul(
                    branch_weights[0]
                )

                for index in range(1, len(branch_weights)):
                    x.addcmul_(
                        branches[:, index],
                        branch_weights[index],
                    )

        # ----------------------------------------------------
        # Local base / Scheme A / local_base_k2
        # ----------------------------------------------------
        else:
            delayed = cfg.mode == "A"
            # local_base_k2 是「只改变合并时机」的机制对照：
            # 第二轮固定 k2，不跟随 A 的 k1*k2 专家计算量。
            second_round_width = (
                cfg.k2 if cfg.mode == "local_base_k2" else None
            )

            for block in middle:
                x, aux1, aux2 = call(
                    block.local_two_stage,
                    x,
                    cfg.k1,
                    cfg.k2,
                    delayed,
                    loop_scale,
                    second_round_width,
                    attn_bias,
                )
                aux_losses.extend((aux1, aux2))

        # 中间区域之后的层（dense 模式已在上面统一执行）。
        post_start = (
            cfg.n_layers if cfg.mode == "dense" else self.middle_end
        )
        for index in range(post_start, cfg.n_layers):
            x, aux = call(
                blocks[index],
                x,
                cfg.top_k,
                global_scale,
                attn_bias,
            )
            aux_losses.append(aux)

        x = self.final_norm(x)
        logits = F.linear(x, self.lm_head.weight)

        aux_loss = torch.stack(aux_losses).mean()

        output = {
            "logits": logits,
            "aux_loss": aux_loss,
        }

        if targets is not None:
            lm_loss = F.cross_entropy(
                logits.reshape(
                    -1,
                    cfg.vocab_size,
                ),
                targets.reshape(-1),
            )

            total_loss = (
                lm_loss
                + cfg.balance_coef * aux_loss
            )

            output.update({
                "lm_loss": lm_loss,
                "loss": total_loss,
            })

        return output


# ============================================================
# Dataset
# ============================================================

# 近重复（near-duplicate）群组审计/清洗口径。
#
# 精确群组指纹与内容定义分块只能发现「完全相同」的内容；同一篇
# 文档的两次修订、转载时改标题/改一两句话，shingle 集合仍高度
# 重合但指纹不同。这里用字节 k-shingle 的 Jaccard 相似度定义
# 近重复：|S_a ∩ S_b| / |S_a ∪ S_b|。为把成本压到与语料大小线性
# 相关，先对每个群组取 shingle 哈希的 bottom-k 草图（MinHash
# 家族的最小哈希样本），用草图哈希做倒排索引生成候选，再对候选
# 用完整 shingle 集合复核精确 Jaccard；只有精确值达到阈值才删除。
# 同一口径也用于评估集内部/val↔test 的只读近重复审计（不删除）。
_NEAR_DUP_DEFAULT_THRESHOLD = 0.8
_NEAR_DUP_DEFAULT_SHINGLE_BYTES = 8
_NEAR_DUP_DEFAULT_SKETCH_SIZE = 128
_NEAR_DUP_MAX_SHINGLE_BYTES = 64
_NEAR_DUP_MAX_SKETCH_SIZE = 4096
# 单个群组过大时完整 shingle 集合的内存不可控；显式跳过并在
# 审计里记录，而不是静默截断内容（截断会把长文档误判为短文档）。
_NEAR_DUP_MAX_GROUP_BYTES = 4 * 1024 * 1024
# 精确复核缓存：候选对很少，但同一评估群组可能被很多训练群组
# 比较；缓存按近似字节数限界，避免大语料把内存吃满。
_NEAR_DUP_EXACT_CACHE_BYTES = 64 * 1024 * 1024
# 64 位滚动多项式哈希（模 2^64）。碰撞概率在千万级 shingle 下
# 约 1e-6 量级；审计同时记录这是近似哈希而非逐字节比较。
_NEAR_DUP_HASH_BASE = 0x100000001B3
_NEAR_DUP_HASH_MASK = (1 << 64) - 1


# 群组分隔符允许的反斜杠转义：\n / \t / \r / \0 / \\ / \xHH / \uXXXX。
_GROUP_SEPARATOR_SIMPLE_ESCAPES = {
    "n": 10,
    "t": 9,
    "r": 13,
    "0": 0,
    "\\": 92,
    "'": 39,
    '"': 34,
}


def parse_group_separator(text: str) -> bytes:
    """
    把命令行传入的群组分隔符解析为字节序列。

    支持常见反斜杠转义（\\n、\\t、\\r、\\0、\\\\、\\xHH、\\uXXXX），
    其余字符按 UTF-8 编码；解析结果不能为空。分隔符用于把语料
    切成「群组」（如同一文档/同一用户的一段内容），群组是划分
    的最小单位，绝不允许跨 train/val/test 边界。
    """
    result = bytearray()
    index = 0
    length = len(text)

    while index < length:
        char = text[index]

        if char != "\\":
            try:
                result.extend(char.encode("utf-8"))
            except UnicodeEncodeError as error:
                raise ValueError(
                    "分隔符包含无法编码为 UTF-8 的字符: "
                    f"U+{ord(char):04X}"
                ) from error
            index += 1
            continue

        if index + 1 >= length:
            raise ValueError("分隔符不能以单个反斜杠结尾")

        escape = text[index + 1]

        if escape in _GROUP_SEPARATOR_SIMPLE_ESCAPES:
            result.append(_GROUP_SEPARATOR_SIMPLE_ESCAPES[escape])
            index += 2
            continue

        if escape in ("x", "u"):
            digits = 2 if escape == "x" else 4
            hex_part = text[index + 2:index + 2 + digits]
            if (
                len(hex_part) != digits
                or any(
                    digit not in "0123456789abcdefABCDEF"
                    for digit in hex_part
                )
            ):
                raise ValueError(
                    f"\\{escape} 转义需要 {digits} 位十六进制数字"
                )
            codepoint = int(hex_part, 16)
            if escape == "u":
                try:
                    result.extend(
                        chr(codepoint).encode("utf-8")
                    )
                except UnicodeEncodeError as error:
                    raise ValueError(
                        "\\u 转义指向无法编码为 UTF-8 的"
                        f"码点: U+{codepoint:04X}"
                    ) from error
            else:
                result.append(codepoint)
            index += 2 + digits
            continue

        raise ValueError(
            f"不支持的分隔符转义: \\{escape}"
        )

    if not result:
        raise ValueError("群组分隔符不能为空")

    return bytes(result)


# `--clean-train-against-test` 与
# `--allow-eval-content-for-cleaning` 是同义入口：只要任一为真，
# 训练集清洗就会读取 test 内容。所有下游（ByteDataset、resume、
# comparison_protocol、外部预注册核对）必须看到同一个归一化值，
# 否则同一种清洗口径会因使用不同别名被误报为协议不一致。
_CLEAN_AGAINST_TEST_ALIASES = (
    "clean_train_against_test",
    "allow_eval_content_for_cleaning",
)


def _clean_against_test_effective(args: object) -> bool:
    return bool(
        getattr(args, "clean_train_against_test", False)
        or getattr(args, "allow_eval_content_for_cleaning", False)
    )


def _normalize_clean_against_test(args: object) -> bool:
    effective = _clean_against_test_effective(args)
    setattr(args, "clean_train_against_test", effective)
    setattr(args, "allow_eval_content_for_cleaning", effective)
    return effective


def _saved_clean_against_test_effective(
    saved_args: object,
) -> bool:
    """
    从检查点/配置的 args 快照还原「清洗是否读取 test」。

    旧代码可能只记录了两个同义入口中的一个（且另一个为
    False）；必须按任一为真归一化，不能因为
    ``clean_train_against_test`` 键存在就忽略
    ``allow_eval_content_for_cleaning=True``。两个键都缺的
    更老检查点按历史行为回退：启用了去重/共享块清洗即读取
    test。
    """
    if not isinstance(saved_args, dict):
        return False
    if (
        "clean_train_against_test" in saved_args
        or "allow_eval_content_for_cleaning" in saved_args
    ):
        return bool(
            saved_args.get("clean_train_against_test", False)
            or saved_args.get(
                "allow_eval_content_for_cleaning", False
            )
        )
    return bool(
        saved_args.get("deduplicate_train_groups", False)
        or saved_args.get("drop_train_shared_chunks", False)
        or saved_args.get(
            "drop_train_near_duplicate_groups", False
        )
    )


def _iter_group_boundaries(
    buf: bytearray,
    separator: bytes,
    start: int = 0,
):
    """
    依次产出群组边界位置（每个分隔符之后的字节位置）与文件末尾。

    边界是群的起始字节；文件末尾 N 永远是一个合法边界。
    只产出 > start 的边界。
    """
    if not separator:
        # bytes.find(b"") 永远返回 position，len=0 会让循环原地
        # 踏步；调用方必须先拒绝空分隔符，而不是挂死进程。
        raise ValueError("群组分隔符不能为空字节串")
    position = start

    while True:
        found = buf.find(separator, position)
        if found < 0:
            break
        end = found + len(separator)
        if start < end < len(buf):
            yield end
        position = end

    if len(buf) > start:
        yield len(buf)


def _iter_group_spans(
    buf: bytearray,
    separator: bytes,
    start: int,
    end: int,
):
    """
    依次产出 [start, end) 内每个群组的内容区间（不含分隔符本身）。

    与 _iter_group_boundaries 同一口径：群组以分隔符之后的位置
    为起点（首个群组为 start），以分隔符起点或 end 为终点；空
    群组不产出区间。文本完整性审计用它把用户显式配置的群组
    分隔符（可能是 NUL 或非 UTF-8 字节）排除在损坏统计之外。
    """
    if not separator:
        raise ValueError("群组分隔符不能为空字节串")
    position = start

    while position < end:
        found = buf.find(separator, position, end)
        if found < 0:
            yield position, end
            return
        if found > position:
            yield position, found
        position = found + len(separator)


def _count_groups(
    buf: bytearray,
    separator: bytes,
    cuts: List[int],
) -> List[int]:
    """
    统计每个 split 内部的完整（非空）群组数量（cuts 必须落在
    群组边界上）。

    与 _iter_group_spans 同一口径：空群组（前导/连续分隔符
    之间）不计入「完整群组」；群组按起始字节归属 split，cuts
    本身是群组起点，因此恰好等于切分点的群组只计入右侧
    split。末尾分隔符之后的空群组同样不计入。
    """
    first, second = cuts[0], cuts[-1]
    counts = [0, 0, 0]

    for span_start, _ in _iter_group_spans(
        buf,
        separator,
        0,
        len(buf),
    ):
        if span_start < first:
            counts[0] += 1
        elif span_start < second:
            counts[1] += 1
        else:
            counts[2] += 1

    return counts


def _group_content_digest(
    raw: memoryview,
    start: int,
    end: int,
) -> bytes:
    """
    群组内容的精确指纹（blake2b-128）。

    群组级去重/泄露审计使用完整内容指纹，不受窗口采样步长
    影响：短群组、跨 split 错位重复和窗口审计抽不到的重复
    文档都能被精确识别。指纹只用于审计/清洗决策，不进入
    模型特征。
    """
    return hashlib.blake2b(
        raw[start:end],
        digest_size=16,
    ).digest()


def _merge_byte_intervals(
    intervals: List[Tuple[int, int]],
) -> List[Tuple[int, int]]:
    """合并重叠/相邻的 [start, end) 区间，输出按起点升序。"""
    if not intervals:
        return []

    ordered = sorted(
        (start, end)
        for start, end in intervals
        if end > start
    )
    if not ordered:
        return []

    merged = [ordered[0]]
    for start, end in ordered[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged


def _effective_train_fingerprint(
    raw: memoryview,
    train_end: int,
    excluded_spans: List[Tuple[int, int]],
) -> str:
    """
    对「实际进入训练的 train 内容」做独立指纹。

    只比对整体数据 sha256、split 边界与清洗开关还不够：同一份
    数据、同一组开关下，清洗实现变化（或 bug）会剔除不同区间，
    实际参与训练/计数的字节随之改变，resume 或跨运行对比却仍
    显示协议一致。这里把 train 的原始区间、清洗区间清单与保留
    内容的长度前缀一起哈希，任何一项变化都会得到不同指纹。
    """
    merged = _merge_byte_intervals(excluded_spans)
    manifest = json.dumps(
        {
            "train_end": int(train_end),
            "excluded_spans": [
                [int(start), int(end)]
                for start, end in merged
            ],
        },
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")

    hasher = hashlib.sha256()
    hasher.update(len(manifest).to_bytes(8, "little"))
    hasher.update(manifest)

    for start, end in _subtract_byte_intervals(
        0,
        train_end,
        merged,
    ):
        hasher.update(
            (end - start).to_bytes(8, "little")
        )
        hasher.update(raw[start:end])

    return hasher.hexdigest()


def _valid_window_start_intervals(
    total_starts: int,
    seq_len: int,
    excluded_spans: List[Tuple[int, int]],
) -> Optional[List[Tuple[int, int]]]:
    """
    计算「窗口完全不触碰被清洗字节」的合法起点区间。

    窗口起点 s 覆盖训练字节 [s, s + seq_len]（含下一 token
    监督位），因此与排除区间 [start, end) 相交当且仅当
    s ∈ [start - seq_len, end - 1]。返回按起点升序的闭区间
    列表；没有排除区间时返回 None（调用方走无掩码快路径）。
    """
    if not excluded_spans:
        return None

    blocked: List[Tuple[int, int]] = []
    for start, end in _merge_byte_intervals(excluded_spans):
        low = max(0, start - seq_len)
        high = min(total_starts - 1, end - 1)
        if low <= high:
            blocked.append((low, high))

    if not blocked:
        return None

    valid: List[Tuple[int, int]] = []
    cursor = 0
    for low, high in blocked:
        if cursor < low:
            valid.append((cursor, low - 1))
        cursor = max(cursor, high + 1)
    if cursor < total_starts:
        valid.append((cursor, total_starts - 1))

    return valid


def _plan_train_group_dedup(
    raw: bytearray,
    separator: bytes,
    train_end: int,
    eval_ranges: Dict[str, Tuple[int, int]],
) -> Tuple[List[Tuple[int, int]], Dict[str, object]]:
    """
    规划训练集群组清洗：只从 train 中剔除群组，绝不改动
    val/test。

    剔除规则：
    - 内容与 val 或 test 中任一完整群组完全相同（跨 split
      重复，属于泄露）；
    - 与训练集中更早出现的群组完全相同（保留第一次出现）。
    返回被剔除群的字节区间与可追踪的统计。调用方只会在
    训练窗口采样时屏蔽这些区间，验证/测试数据保持原样。
    """
    eval_digests: Dict[str, set] = {
        "val": set(),
        "test": set(),
    }
    for split, (begin, end) in eval_ranges.items():
        if end <= begin:
            continue
        for span_start, span_end in _iter_group_spans(
            raw,
            separator,
            begin,
            end,
        ):
            eval_digests[split].add(
                _group_content_digest(raw, span_start, span_end)
            )

    seen = set()
    excluded: List[Tuple[int, int]] = []
    stats: Dict[str, object] = {
        "enabled": True,
        "policy": (
            "drop train groups duplicated in val/test or earlier "
            "in train; val/test untouched"
        ),
        "groups_total": 0,
        "groups_kept": 0,
        "groups_dropped": 0,
        "dropped_bytes": 0,
        "dropped_duplicate_of": {
            "val": 0,
            "test": 0,
            "train": 0,
        },
        "examples": [],
    }

    for span_start, span_end in _iter_group_spans(
        raw,
        separator,
        0,
        train_end,
    ):
        stats["groups_total"] += 1
        digest = _group_content_digest(
            raw,
            span_start,
            span_end,
        )

        reason: Optional[str] = None
        if digest in eval_digests["val"]:
            reason = "val"
        elif digest in eval_digests["test"]:
            reason = "test"
        elif digest in seen:
            reason = "train"

        if reason is None:
            seen.add(digest)
            stats["groups_kept"] += 1
            continue

        excluded.append((span_start, span_end))
        stats["groups_dropped"] += 1
        stats["dropped_bytes"] += span_end - span_start
        stats["dropped_duplicate_of"][reason] += 1
        if len(stats["examples"]) < 5:
            stats["examples"].append(
                [span_start, span_end, reason]
            )

    stats["post_clean_train_bytes"] = (
        train_end - int(stats["dropped_bytes"])
    )
    return excluded, stats


def _snap_group_split(
    buf: bytearray,
    separator: bytes,
    nominal_train: int,
    nominal_val_end: int,
    min_len: int,
    has_test: bool,
) -> Tuple[int, int]:
    """
    把名义切分位置吸附到群组边界：train/val/test 的分界点都是
    某个群组的起始字节，任何群组整体落在一个 split 内。

    在全部群组边界上求全局最优的可行组合（目标为
    |cut_train - nominal_train| + |cut_val - nominal_val_end|），
    找不到合法组合时抛出 ValueError（宁可报错，也不产生一个
    拆散群组的划分）。

    对全部候选组合按偏离量取全局最小。
    """
    if buf.find(separator) < 0:
        raise ValueError(
            "语料中没有出现群组分隔符，无法按群组划分；"
            "请检查 --group-separator 是否正确"
        )

    total = len(buf)

    # val 右端上界：有 test 时 test 也要至少 min_len 字节；
    # 无 test 时 val 延伸到文件末尾（cut_val = total 是离
    # nominal_val_end = total 最近的边界）。
    upper_val = total if not has_test else total - min_len

    best: Optional[Tuple[int, int]] = None
    best_key: Optional[Tuple[int, int, int, int, int]] = None

    # 窗口内是「> 当前 cut_val - min_len」的边界；被移出窗口的
    # 边界里，最后一个 >= min_len 的可作 train 右端。
    window: deque = deque()
    trailing: Optional[int] = None
    left_candidate: Optional[int] = None
    right_candidate: Optional[int] = None

    def _consider(cut_val: int) -> None:
        nonlocal best, best_key

        if cut_val > upper_val:
            return
        # 没有 test split 时 val 必须延伸到文件末尾：否则
        # ByteDataset 会把 cut_val 之后的字节当成 test，凭空
        # 产生一个 test_fraction=0 却非空的测试集。这里不能
        # 只把 total 当作上界，必须把 cut_val 固定为 total。
        if not has_test and cut_val != total:
            return

        lower = cut_val - min_len
        candidates: List[int] = []

        for candidate in (left_candidate, right_candidate):
            if candidate is not None and candidate <= lower:
                candidates.append(candidate)

        if trailing is not None:
            candidates.append(trailing)

        if not candidates:
            return

        cut_train = min(
            candidates,
            key=lambda cut: (abs(cut - nominal_train), cut),
        )
        deviation_train = abs(cut_train - nominal_train)
        deviation_val = abs(cut_val - nominal_val_end)
        key = (
            deviation_train + deviation_val,
            deviation_train,
            cut_train,
            deviation_val,
            cut_val,
        )

        if best_key is None or key < best_key:
            best_key = key
            best = (cut_train, cut_val)

    for boundary in _iter_group_boundaries(buf, separator, 0):
        # 先把已进入「cut_val - min_len」之内的边界移出窗口；
        # 最后一个移出的边界就是当前 cut_val 下最右的可行
        # 左侧 train 右端。
        while window and window[0] <= boundary - min_len:
            popped = window.popleft()
            if popped >= min_len:
                trailing = popped

        _consider(boundary)

        # 该边界之后可作 train 右端（需要 >= min_len）。
        if boundary >= min_len:
            if boundary <= nominal_train:
                left_candidate = boundary
            elif right_candidate is None:
                right_candidate = boundary

        window.append(boundary)

    if best is None:
        raise ValueError(
            "语料按群组分隔符划分后，无法同时保证 train/val/test "
            f"各自至少 {min_len} 字节（seq_len + 1）；"
            "请调整 --val-fraction / --test-fraction、减小 "
            "--seq-len、检查分隔符，或合并过小的群组"
        )

    return best


def _split_isolation_record(
    split_bounds: Dict[str, Tuple[int, int]],
    total_bytes: int,
) -> Dict[str, object]:
    """
    生成可复现的时序隔离记录：三段的绝对字节边界、顺序、
    是否首尾相接且覆盖全文、任意两段的重叠字节数。

    只记录边界与结构，不读取或改变数据；写入 config 的
    data.split_isolation 并作为受控变量核对。这样即使源文件
    sha256 相同，切分顺序/群组吸附/边界实现变化也能被对比
    与 resume 发现。
    """
    order = ("train", "val", "test")
    bounds = {
        split: [
            int(split_bounds[split][0]),
            int(split_bounds[split][1]),
        ]
        for split in order
    }
    contiguous = bounds["train"][0] == 0
    for left, right in zip(order, order[1:]):
        if bounds[left][1] != bounds[right][0]:
            contiguous = False
    covers_all = (
        contiguous
        and bounds["test"][1] == int(total_bytes)
        and all(
            start <= end
            for start, end in bounds.values()
        )
    )
    # 逐对求交，而不是 covered - span：后者在同时存在空隙与
    # 重叠时会相互抵消（例如 train=[0,30)、val=[20,50)、
    # test=[60,70) 会被算成 0，而 train∩val 实际为 10 字节）。
    ranges = list(bounds.values())
    overlap_bytes = 0
    for left_index in range(len(ranges)):
        for right_index in range(left_index + 1, len(ranges)):
            left_start, left_end = ranges[left_index]
            right_start, right_end = ranges[right_index]
            overlap_bytes += max(
                0,
                min(left_end, right_end)
                - max(left_start, right_start),
            )

    return {
        "split_order": list(order),
        "bounds": bounds,
        "contiguous": contiguous,
        "covers_all_bytes": covers_all,
        "overlap_bytes": overlap_bytes,
        "policy": "prefix_contiguous_no_shuffle",
    }


def audit_entity_manifest(
    buf: bytes,
    group_separator: Optional[bytes],
    split_bounds: Dict[str, Tuple[int, int]],
    manifest_path: str,
) -> Dict[str, object]:
    """用显式实体 ID 检查同一实体是否跨越 split。

    ``--group-separator`` 只保证「分隔符之间的连续片段」不被
    切开，不能识别同一用户/作者/文档版本在不相邻片段中的
    重复出现。实体清单按群组序号（0 基）给出 entity_id
    （JSON 数组或 {"groups": [...]}）；审计把同一 entity 的
    全部群组映射到 split，任何实体同时出现在两个 split 即
    报告为泄露级问题。

    没有群组分隔符时无法建立群组序号，直接返回 skipped。
    """
    if group_separator is None:
        return {
            "available": False,
            "reason": "需要 --group-separator 才能建立群组序号",
        }
    with open(manifest_path, encoding="utf-8") as handle:
        payload = json.load(handle)
    if isinstance(payload, dict):
        values = payload.get("groups") or payload.get("entity_ids")
    else:
        values = payload
    if not isinstance(values, list) or not values:
        raise ValueError(
            "实体清单必须是非空 JSON 数组（按群组序号给 entity_id）"
        )
    spans = list(
        _iter_group_spans(
            buf,
            group_separator,
            0,
            len(buf),
        )
    )
    if len(values) != len(spans):
        raise ValueError(
            "实体清单条目数（"
            f"{len(values)}）与群组数（{len(spans)}）不一致"
        )
    split_of = {}
    ordered = sorted(
        split_bounds.items(), key=lambda item: item[1][0]
    )
    for index, (start, _end) in enumerate(spans):
        split_name = None
        for name, (begin, finish) in ordered:
            if begin <= start < finish:
                split_name = name
                break
        split_of[index] = split_name
    entities: Dict[str, set] = {}
    for index, entity in enumerate(values):
        entity_id = str(entity)
        entities.setdefault(entity_id, set()).add(
            split_of.get(index)
        )
    crossing = {
        entity: sorted(
            str(split) for split in splits if split is not None
        )
        for entity, splits in entities.items()
        if len([split for split in splits if split is not None]) > 1
    }
    return {
        "available": True,
        "manifest": manifest_path,
        "groups": len(spans),
        "entities": len(entities),
        "cross_split_entities": len(crossing),
        "examples": list(crossing.items())[:20],
        "note": (
            "实体 ID 来自外部清单；分隔符本身不提供实体隔离。"
            "跨 split 实体是泄露级问题，应重新切分或剔除，"
            "而不是声称「群组不跨界」已足够"
        ),
    }


def read_time_order_manifest(
    path: str,
) -> Dict[str, object]:
    """读取并校验时间顺序清单（每行一个时间戳）。

    支持 JSONL（``{"timestamp": "..."}``）或纯文本
    （每行一个 ISO-8601 时间戳）。用于 --split-policy
    chronological：只有清单按文件顺序单调不减时，前缀切分
    才可以称为「按时间切分」；否则拒绝启动。
    """
    records: List[str] = []
    parsed: List[datetime.datetime] = []
    with open(path, encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, 1):
            text = line.strip()
            if not text:
                continue
            try:
                payload = json.loads(text)
            except json.JSONDecodeError:
                # 纯文本清单：整行就是一个 ISO-8601 时间戳。
                payload = text
            if isinstance(payload, dict):
                value = payload.get("timestamp")
            elif isinstance(payload, str):
                value = payload
            else:
                # 全数字的 ISO-8601 basic 日期（如 20200101）会被
                # json.loads 解析成整数；它不是 JSON 清单，仍应
                # 按纯文本时间戳回退，而不是报「缺少 timestamp」。
                value = text
            if not isinstance(value, str) or not value:
                raise ValueError(
                    f"时间清单第 {line_number} 行缺少 timestamp"
                )
            try:
                timestamp = datetime.datetime.fromisoformat(
                    value.replace("Z", "+00:00")
                )
            except ValueError as error:
                raise ValueError(
                    f"时间清单第 {line_number} 行不是 ISO-8601: "
                    f"{value!r}（{error}）"
                )
            records.append(value)
            parsed.append(timestamp)
    if not records:
        raise ValueError("时间清单为空")

    # 带时区与不带时区的时间戳不能直接比较（Python 会抛
    # TypeError）。这里显式拒绝混合清单，要求用户统一口径，
    # 而不是假定 naive 时间戳的时区或让进程裸崩溃。
    awareness = {
        "aware"
        if timestamp.tzinfo is not None
        and timestamp.utcoffset() is not None
        else "naive"
        for timestamp in parsed
    }
    if len(awareness) > 1:
        raise ValueError(
            "时间清单不能混用带时区与不带时区的 ISO-8601 "
            "时间戳；请统一写成同一时区（或全部省略时区）"
        )

    violations = [
        index
        for index in range(1, len(parsed))
        if parsed[index] < parsed[index - 1]
    ]
    min_index = min(
        range(len(parsed)),
        key=parsed.__getitem__,
    )
    max_index = max(
        range(len(parsed)),
        key=parsed.__getitem__,
    )
    return {
        "path": path,
        "records": len(records),
        "min_timestamp": records[min_index],
        "max_timestamp": records[max_index],
        "monotonic_non_decreasing": not violations,
        "order_violations": violations[:20],
        "order_violation_count": len(violations),
        "note": (
            "清单按语料文件顺序逐条给出时间戳；只有单调不减时"
            "前缀切分才是时间切分。文件顺序本身不构成时间证据"
        ),
    }


# 固定评估批设备侧结果的总字节上限。
_EVAL_BATCH_CACHE_MAX_BYTES = 64 * 1024 * 1024


class ByteDataset:
    """
    字节级语言模型数据集。

    数据协议（防止数据泄露）：
    - 先划分、后处理：按原始字节流的时间先后顺序切成
      train / val / test 三段，三个 split 在原语料中前后相邻、
      互不重叠，切分全程不随机打乱（时序数据用过去训练、用未来
      验证和测试）；训练阶段的批级 shuffle 由随机采样窗口起点
      承担，不改变 split 边界；
    - 群组整体不跨界：传入 group_separator 时，切分位置吸附到
      群组边界（同一文档/同一用户的内容不会被拆到两个 split），
      train/val/test 任意两侧之间都不共享半个群组；
    - 训练期间 test 保持尘封：训练循环只访问 train，周期性验证
      只访问 val，test 仅在最终评估（--evaluate-test）时访问一次；
      训练集清洗默认也只对照 val 与更早的 train 群组，绝不用
      test 内容决定剔除哪些训练样本（那会让训练数据依赖 test）；
    - 本管线不做任何依赖全局统计量的预处理（标准化、归一化、
      缺失值填充等）；若后续扩展为连续值特征，必须只在 train 上
      fit，再 transform val/test，禁止在划分前用全量数据统计。

    token id 范围固定为 0..255；验证/测试窗口固定，避免不同实验
    之间采样噪声过大。
    """

    def __init__(
        self,
        filename: str,
        seq_len: int,
        val_fraction: float = 0.05,
        test_fraction: float = 0.05,
        device: Optional[torch.device] = None,
        group_separator: Optional[bytes] = None,
        deduplicate_train_groups: bool = False,
        drop_train_shared_chunks: bool = False,
        drop_train_near_duplicate_groups: bool = False,
        near_duplicate_audit: bool = False,
        near_duplicate_threshold: float = (
            _NEAR_DUP_DEFAULT_THRESHOLD
        ),
        near_duplicate_shingle_bytes: int = (
            _NEAR_DUP_DEFAULT_SHINGLE_BYTES
        ),
        drop_train_corrupt_groups: bool = False,
        drop_train_corrupt_bytes: bool = False,
        drop_train_degenerate_groups: bool = False,
        drop_train_degenerate_runs: bool = False,
        clean_train_against_test: bool = False,
        include_test_in_cleaning: bool = False,
    ):
        # 两个入口名都保留：远程分支的 clean_train_against_test
        # 与本次修正的 include_test_in_cleaning 语义相同。
        include_test_in_cleaning = bool(
            include_test_in_cleaning or clean_train_against_test
        )
        data_path = Path(filename)

        if not 0.0 < val_fraction < 1.0:
            raise ValueError(
                "val_fraction 必须落在 (0, 1)（验证集用于"
                "选型/早停，不能为空）"
            )

        if not 0.0 <= test_fraction < 1.0:
            raise ValueError("test_fraction 必须落在 [0, 1)")

        if val_fraction + test_fraction >= 1.0:
            raise ValueError(
                "val_fraction + test_fraction 必须小于 1"
                "（训练集不能为空）"
            )

        # 文件在读取期间被截断时按实际读入长度处理。
        buf = bytearray(data_path.stat().st_size)
        with open(data_path, "rb") as handle:
            filled = handle.readinto(buf)

        if filled != len(buf):
            del buf[filled:]

        if len(buf) < seq_len + 2:
            raise ValueError(
                "数据文件太小，至少需要 seq_len + 2 个字节"
            )

        # 语料内容指纹：恢复训练时用来确认数据文件没有变化。
        self.data_sha256 = hashlib.sha256(buf).hexdigest()
        self.num_bytes = len(buf)
        self.val_fraction = val_fraction
        self.test_fraction = test_fraction

        tokens = torch.frombuffer(buf, dtype=torch.uint8)

        # 数据审计（重复窗口扫描）直接读取原始字节缓冲区；
        # _raw_buffer 保留 bytearray 本身，供按分隔符切段扫描
        #（memoryview 不提供 find）。
        self._raw = memoryview(buf)
        self._raw_buffer = buf

        _ = device

        if group_separator is not None and len(group_separator) == 0:
            raise ValueError("group_separator 不能为空字节串")

        self.group_separator = group_separator
        self.group_cuts: Optional[Dict[str, int]] = None
        self.groups_per_split: Optional[Dict[str, int]] = None

        if deduplicate_train_groups and group_separator is None:
            raise ValueError(
                "deduplicate_train_groups 需要 group_separator："
                "没有显式的群组边界就无法在不改动 val/test 的"
                "前提下做内容级去重"
            )

        if drop_train_shared_chunks and group_separator is None:
            raise ValueError(
                "drop_train_shared_chunks 需要 group_separator："
                "没有显式的群组边界就无法整组剔除与 val/test "
                "共享内容的训练样本，也无法保证 val/test 不变"
            )
        self.drop_train_shared_chunks = bool(
            drop_train_shared_chunks
        )

        if (
            drop_train_near_duplicate_groups
            and group_separator is None
        ):
            raise ValueError(
                "drop_train_near_duplicate_groups 需要 "
                "group_separator：没有显式的群组边界就无法在"
                "不改动 val/test 的前提下整组剔除近重复训练"
                "样本"
            )
        self.drop_train_near_duplicate_groups = bool(
            drop_train_near_duplicate_groups
        )
        if near_duplicate_audit and group_separator is None:
            raise ValueError(
                "near_duplicate_audit 需要 group_separator："
                "近重复按群组定义，没有群组边界就无法区分"
                "文档/记录"
            )
        self.near_duplicate_audit = bool(near_duplicate_audit)
        try:
            checked_threshold = float(
                near_duplicate_threshold
            )
        except (TypeError, ValueError, OverflowError) as error:
            raise ValueError(
                "near_duplicate_threshold 必须是数值"
            ) from error
        if (
            not math.isfinite(checked_threshold)
            or not 0.0 < checked_threshold <= 1.0
        ):
            raise ValueError(
                "near_duplicate_threshold 必须落在 (0, 1]"
            )
        if (
            not isinstance(
                near_duplicate_shingle_bytes, int
            )
            or isinstance(near_duplicate_shingle_bytes, bool)
            or not 1
            <= near_duplicate_shingle_bytes
            <= _NEAR_DUP_MAX_SHINGLE_BYTES
        ):
            raise ValueError(
                "near_duplicate_shingle_bytes 必须是 1.."
                f"{_NEAR_DUP_MAX_SHINGLE_BYTES} 的整数"
            )
        self.near_duplicate_threshold = checked_threshold
        self.near_duplicate_shingle_bytes = int(
            near_duplicate_shingle_bytes
        )

        if drop_train_corrupt_groups and group_separator is None:
            raise ValueError(
                "drop_train_corrupt_groups 需要 group_separator："
                "没有显式的群组边界就无法在不改动 val/test 的"
                "前提下整组剔除标签噪声"
            )
        self.drop_train_corrupt_groups = bool(
            drop_train_corrupt_groups
        )

        if (
            drop_train_corrupt_bytes
            and group_separator is not None
        ):
            raise ValueError(
                "drop_train_corrupt_bytes 仅用于无群组边界的"
                "连续字节流；有 --group-separator 时请使用 "
                "--drop-train-corrupt-groups 以保持群组完整"
            )
        self.drop_train_corrupt_bytes = bool(
            drop_train_corrupt_bytes
        )

        if (
            drop_train_degenerate_runs
            and group_separator is not None
        ):
            raise ValueError(
                "drop_train_degenerate_runs 仅用于无 "
                "--group-separator 的连续字节流；有群组边界时"
                "请使用 --drop-train-degenerate-groups 以保持"
                "群组完整"
            )
        self.drop_train_degenerate_runs = bool(
            drop_train_degenerate_runs
        )

        if (
            drop_train_degenerate_groups
            and group_separator is None
        ):
            raise ValueError(
                "drop_train_degenerate_groups 需要 "
                "group_separator：没有显式的群组边界就无法在"
                "不改动 val/test 的前提下整组剔除异常值"
            )
        self.drop_train_degenerate_groups = bool(
            drop_train_degenerate_groups
        )

        # test 只用于最终评估。训练集清洗若读取 test 群组/内容，
        # 训练样本集合就会依赖 test，「只解封一次」的协议被绕过；
        # 默认只对照 val 与更早的 train，旧行为必须显式开启并被
        # 记录。未启用任何对照 eval split 的清洗时该开关无效果。
        # include_test_in_cleaning 与 clean_train_against_test 是
        # 同义入口；两者任一为真都必须同时驱动清洗范围、校验
        # 与披露，不能只改 eval_content_access 造成假披露。
        self.clean_train_against_test = bool(
            include_test_in_cleaning
        )
        if self.clean_train_against_test and not (
            deduplicate_train_groups
            or drop_train_shared_chunks
            or drop_train_near_duplicate_groups
        ):
            raise ValueError(
                "clean_train_against_test 需要同时启用 "
                "deduplicate_train_groups、"
                "drop_train_shared_chunks 或 "
                "drop_train_near_duplicate_groups"
            )

        # 训练集清洗（可选的群组级/字节级）：只剔除 train 中
        # 与 val/test 或更早训练群组完全重复的群组、损坏字节或
        # 退化群组。被剔除的字节不会进入任何训练窗口；val/test
        # 的字节与切分位置保持完全不变。
        self.train_excluded_spans: List[Tuple[int, int]] = []
        self.train_cleaning: Optional[Dict[str, object]] = None
        self._train_start_intervals: Optional[
            List[Tuple[int, int]]
        ] = None
        self._train_interval_lows: Optional[torch.Tensor] = None
        self._train_interval_lengths: Optional[torch.Tensor] = None
        self._train_interval_cumulative: Optional[torch.Tensor] = None
        self.train_num_valid_starts: Optional[int] = None

        # 仅做时间顺序上的连续切分，不计算统计量、不打乱：
        # [0, n_train) 训练，[n_train, n_train + n_val) 验证，
        # 其余为测试。
        n_val = int(len(tokens) * val_fraction)
        n_test = int(len(tokens) * test_fraction)
        n_train = len(tokens) - n_val - n_test
        n_val_end = n_train + n_val

        if group_separator is not None:
            # 群组数据的防泄露协议：切分位置吸附到群组边界，
            # 同一群组的全部字节整体落在同一个 split，任何两侧
            # 之间都不交叉。吸附后会验证三段长度，宁可在划分
            # 阶段显式报错（避免无法对齐的评估协议）。
            cut_train, cut_val = _snap_group_split(
                buf,
                group_separator,
                n_train,
                n_val_end,
                min_len=seq_len + 1,
                has_test=test_fraction > 0.0,
            )
            n_train = cut_train
            n_val_end = cut_val
            self.group_cuts = {
                "train": cut_train,
                "val": cut_val,
            }
            self.groups_per_split = dict(
                zip(
                    ("train", "val", "test"),
                    _count_groups(
                        buf,
                        group_separator,
                        [cut_train, cut_val],
                    ),
                )
            )
            # 群组完整性由构造保证：分界点要么是分隔符之后的群组
            # 起始字节，要么是文件末尾（仅在 test_fraction=0 时
            # 作为 val 的右端）。这里再做一次防御性断言，任何
            # 重构错误的划界都会在数据加载阶段立刻暴露，而不是
            # 悄悄泄露。
            for cut in (cut_train, cut_val):
                if 0 < cut < len(buf):
                    if (
                        buf[cut - len(group_separator):cut]
                        != group_separator
                    ):
                        raise AssertionError(
                            "群组切分边界不在分隔符之后："
                            "内部错误，拒绝继续"
                        )

        self.split_bounds = {
            "train": (0, n_train),
            "val": (n_train, n_val_end),
            "test": (n_val_end, len(tokens)),
        }
        self.split_isolation = _split_isolation_record(
            self.split_bounds,
            len(tokens),
        )
        if (
            not self.split_isolation["contiguous"]
            or not self.split_isolation["covers_all_bytes"]
            or int(self.split_isolation["overlap_bytes"]) != 0
        ):
            raise AssertionError(
                "split 时序隔离检查失败：train/val/test 必须"
                "按时间顺序首尾相接、覆盖全部字节且互不重叠"
            )

        # 逐 split 内容指纹：整体数据 sha256 相同时，群组吸附/
        # 清洗/切分实现变化仍可能改变各段实际字节范围。把每段
        # 内容单独指纹化，resume 与跨运行核对才能确认 train/val/
        # test 仍是同一批字节，而不是只看整体文件与比例。
        self.split_sha256 = {
            split: hashlib.sha256(
                self._raw[begin:end]
            ).hexdigest()
            for split, (begin, end) in self.split_bounds.items()
        }

        # 训练集清洗的评估内容访问口径：默认只用 val 决定
        # 删除哪些训练群组。test 内容参与删除决策会让「测试集
        # 全程尘封」不再成立（即使 test 字节本身不被修改）：
        # 数据集构建已经根据 test 内容筛掉了特定训练样本。
        # 只有显式 --allow-eval-content-for-cleaning 才把 test
        # 纳入清洗参照，并把访问事实写入 data_audit。
        self.eval_content_access = {
            "splits": (
                ["val", "test"]
                if include_test_in_cleaning
                else ["val"]
            ),
            "purpose": "train_cleaning_reference",
            "test_content_used": bool(include_test_in_cleaning),
            "note": (
                "默认只用 val 决定训练集删除；test 内容不参与"
                "数据集构建。启用 --allow-eval-content-for-cleaning "
                "后 test 内容会参与删除决策，必须披露且不能"
                "同时声称 test 全程未被读取"
            ),
        }
        dedup_excluded: List[Tuple[int, int]] = []
        dedup_stats: Optional[Dict[str, object]] = None

        # 默认只用 val（验证集用于选型/早停）作为训练集清洗的
        # 对照；test 必须保持尘封，不能参与「剔除哪些训练群组」
        # 的决定。显式 clean_train_against_test 才恢复旧行为，
        # 并把该事实写入 train_cleaning 供审计/对比核对。
        cleaning_eval_ranges: Dict[
            str, Tuple[int, int]
        ] = {"val": (n_train, n_val_end)}
        if self.clean_train_against_test:
            cleaning_eval_ranges["test"] = (
                n_val_end,
                len(tokens),
            )

        if deduplicate_train_groups:
            dedup_excluded, dedup_stats = (
                _plan_train_group_dedup(
                    self._raw_buffer,
                    group_separator,
                    n_train,
                    cleaning_eval_ranges,
                )
            )

        shared_chunk_excluded: List[Tuple[int, int]] = []
        shared_chunk_stats: Optional[Dict[str, object]] = None

        if drop_train_shared_chunks:
            shared_min_chunk = max(
                _AUDIT_CHUNK_MIN_BYTES,
                seq_len + 1,
            )
            shared_chunk_excluded, shared_chunk_stats = (
                _plan_train_shared_chunk_cleaning(
                    self._raw_buffer,
                    group_separator,
                    n_train,
                    cleaning_eval_ranges,
                    shared_min_chunk,
                    max(
                        _AUDIT_CHUNK_MAX_BYTES,
                        shared_min_chunk * 4,
                    ),
                    dedup_excluded,
                )
            )

        near_duplicate_excluded: List[Tuple[int, int]] = []
        near_duplicate_stats: Optional[Dict[str, object]] = None

        if drop_train_near_duplicate_groups:
            (
                near_duplicate_excluded,
                near_duplicate_stats,
            ) = _plan_train_near_duplicate_cleaning(
                self._raw_buffer,
                group_separator,
                n_train,
                cleaning_eval_ranges,
                dedup_excluded + shared_chunk_excluded,
                threshold=self.near_duplicate_threshold,
                shingle_bytes=(
                    self.near_duplicate_shingle_bytes
                ),
                apply_cleaning=True,
            )

        corrupt_excluded: List[Tuple[int, int]] = []
        corrupt_stats: Optional[Dict[str, object]] = None

        if drop_train_corrupt_groups:
            corrupt_excluded, corrupt_stats = (
                _plan_train_corruption_cleaning(
                    self._raw_buffer,
                    group_separator,
                    n_train,
                    (
                        dedup_excluded
                        + shared_chunk_excluded
                        + near_duplicate_excluded
                    ),
                )
            )

        corrupt_byte_excluded: List[Tuple[int, int]] = []
        corrupt_byte_stats: Optional[Dict[str, object]] = None

        if drop_train_corrupt_bytes:
            (
                corrupt_byte_excluded,
                corrupt_byte_stats,
            ) = _plan_train_corruption_cleaning_bytes(
                self._raw_buffer,
                n_train,
            )

        degenerate_run_excluded: List[Tuple[int, int]] = []
        degenerate_run_stats: Optional[Dict[str, object]] = None

        if drop_train_degenerate_runs:
            (
                degenerate_run_excluded,
                degenerate_run_stats,
            ) = _plan_train_degenerate_run_cleaning(
                self._raw_buffer,
                n_train,
                _AUDIT_DEGENERATE_RUN_MIN_BYTES,
                corrupt_byte_excluded,
            )

        degenerate_excluded: List[Tuple[int, int]] = []
        degenerate_stats: Optional[Dict[str, object]] = None

        if drop_train_degenerate_groups:
            degenerate_excluded, degenerate_stats = (
                _plan_train_degenerate_cleaning(
                    self._raw_buffer,
                    group_separator,
                    n_train,
                    (
                        dedup_excluded
                        + shared_chunk_excluded
                        + near_duplicate_excluded
                        + corrupt_excluded
                    ),
                )
            )

        # 不同清洗项可能产生相邻区间（例如损坏字节后面紧跟
        # 退化段）；相邻区间合并是等价的排除集合，因此这里统一
        # 归并，而不是要求各规划器拼出的列表恰好首尾不相接。
        combined_excluded = _merge_byte_intervals(
            sorted(
                dedup_excluded
                + shared_chunk_excluded
                + near_duplicate_excluded
                + corrupt_excluded
                + corrupt_byte_excluded
                + degenerate_run_excluded
                + degenerate_excluded
            )
        )
        merged_excluded = combined_excluded
        if any(
            start < 0 or end > n_train or end <= start
            for start, end in merged_excluded
        ):
            raise AssertionError(
                "训练集清洗区间越出 train split："
                "内部错误，拒绝继续"
            )

        if (
            dedup_stats is not None
            or shared_chunk_stats is not None
            or near_duplicate_stats is not None
            or corrupt_stats is not None
            or degenerate_stats is not None
            or corrupt_byte_stats is not None
            or degenerate_run_stats is not None
        ):
            dropped_bytes = sum(
                end - start
                for start, end in merged_excluded
            )
            group_stats = [
                stats
                for stats in (
                    dedup_stats,
                    shared_chunk_stats,
                    near_duplicate_stats,
                    corrupt_stats,
                    degenerate_stats,
                )
                if stats is not None
            ]

            # 群组级统计的基座沿用第一种清洗的明细（例如
            # 去重的 dropped_duplicate_of、按原因拆分），
            # 再追加本次组合后的总量与字节级清洗。
            combined_stats: Dict[str, object] = (
                dict(group_stats[0]) if group_stats else {}
            )
            combined_stats.update({
                "enabled": True,
                "cleaning_kinds": [],
                "dropped_bytes": dropped_bytes,
                "post_clean_train_bytes": (
                    n_train - dropped_bytes
                ),
                # 清洗对照了哪些 split：test 出现在这里意味着
                # 训练集内容选择读取过测试集，违反默认尘封协议；
                # 只有显式开关才会出现。
                "cleaning_eval_splits": sorted(
                    cleaning_eval_ranges
                ),
                "test_used_for_cleaning": bool(
                    self.clean_train_against_test
                ),
            })

            if group_stats:
                total_groups = int(
                    group_stats[0]["groups_total"]
                )
                groups_dropped = sum(
                    int(stats["groups_dropped"])
                    for stats in group_stats
                )
                combined_stats["groups_total"] = total_groups
                combined_stats["groups_dropped"] = (
                    groups_dropped
                )
                combined_stats["groups_kept"] = (
                    total_groups - groups_dropped
                )

            if shared_chunk_stats is not None:
                combined_stats["shared_chunks"] = (
                    shared_chunk_stats
                )
            if near_duplicate_stats is not None:
                combined_stats["near_duplicates"] = (
                    near_duplicate_stats
                )
            if corrupt_stats is not None:
                combined_stats["corruption"] = corrupt_stats
            if corrupt_byte_stats is not None:
                combined_stats["corruption_bytes"] = (
                    corrupt_byte_stats
                )
            if degenerate_stats is not None:
                combined_stats["degenerate"] = degenerate_stats
            if degenerate_run_stats is not None:
                combined_stats["degenerate_runs"] = (
                    degenerate_run_stats
                )

            cleaning_kinds: List[str] = []
            if dedup_stats is not None:
                cleaning_kinds.append("duplicate")
            if shared_chunk_stats is not None:
                cleaning_kinds.append("shared_chunks")
            if near_duplicate_stats is not None:
                cleaning_kinds.append("near_duplicate")
            if corrupt_stats is not None:
                cleaning_kinds.append("corrupt")
            if degenerate_stats is not None:
                cleaning_kinds.append("degenerate")
            if corrupt_byte_stats is not None:
                cleaning_kinds.append("corrupt_bytes")
            if degenerate_run_stats is not None:
                cleaning_kinds.append("degenerate_runs")
            combined_stats["cleaning_kinds"] = cleaning_kinds

            policy_parts: List[str] = []
            if group_stats:
                policy_parts.append(
                    "drop train groups by kind(s): "
                    + ", ".join(
                        kind
                        for kind in cleaning_kinds
                        if kind != "corrupt_bytes"
                    )
                )
            if corrupt_byte_stats is not None:
                policy_parts.append(
                    "drop train bytes with invalid UTF-8 or NUL"
                )
            if degenerate_run_stats is not None:
                policy_parts.append(
                    "drop train byte runs of one value with "
                    "length >= "
                    f"{_AUDIT_DEGENERATE_RUN_MIN_BYTES}"
                )
            combined_stats["policy"] = (
                "; ".join(policy_parts)
                + ("; " if policy_parts else "")
                + "val/test untouched"
            )
            self.train_excluded_spans = merged_excluded
            self.train_cleaning = combined_stats

        self.train = tokens[:n_train]
        self.val = tokens[n_train:n_val_end]
        self.test = tokens[n_val_end:]
        self.seq_len = seq_len

        # 清洗的删除偏差随 train_cleaning 一起落盘：被删除与保留
        # 内容若分布不同，清洗后的训练分布就是选择性改变的，
        # 后续指标不能与未清洗运行直接比较。只在确有删除时计算，
        # 避免没有清洗的运行承担额外扫描成本。
        if (
            self.train_cleaning is not None
            and self.train_excluded_spans
        ):
            self.train_cleaning["deletion_bias"] = (
                _deletion_bias_record(
                    self._raw,
                    n_train,
                    self.train_excluded_spans,
                )
            )
            if self.train_cleaning["deletion_bias"] is None:
                # 删除区间非空但无法形成有效统计：显式记录，
                # 不能静默省略字段让读者以为没有删除偏差。
                self.train_cleaning["deletion_bias"] = {
                    "schema": "smelt-isr/deletion-bias/v1",
                    "dropped_bytes": sum(
                        end - start
                        for start, end in _merge_byte_intervals(
                            self.train_excluded_spans
                        )
                    ),
                    "kept_bytes": 0,
                    "train_bytes": int(n_train),
                    "byte_js": None,
                    "bigram_js": None,
                    "note": "没有可用于比较的保留内容",
                }

        # 清洗后的有效训练集指纹：resume/对比不能只看整体数据
        # 指纹与清洗开关，必须确认剔除区间及保留内容完全一致。
        self.effective_train_sha256 = (
            _effective_train_fingerprint(
                self._raw,
                n_train,
                self.train_excluded_spans,
            )
        )

        # 窗口暂存槽按调用方的 device 决定是否启用。
        self._stage_slots = None
        self._stage_index = 0

        # 每个 split 至少需要一个完整窗口，否则采样/验证
        # 没有合法起点（fixed_eval_batch 依赖 num_starts >= 1，
        # evaluate 依赖至少一个评估 token 作分母）。
        if len(self.train) < seq_len + 1:
            raise ValueError(
                "训练集长度不足（检查 val/test fraction 或语料大小）"
            )

        if len(self.val) < seq_len + 1:
            raise ValueError(
                "验证集长度不足（检查 val_fraction 或语料大小）"
            )

        if test_fraction > 0.0 and len(self.test) < seq_len + 1:
            raise ValueError(
                "测试集长度不足（检查 test_fraction 或语料大小）"
            )

        if self.train_excluded_spans:
            total_starts = len(self.train) - seq_len
            valid_intervals = _valid_window_start_intervals(
                total_starts,
                seq_len,
                self.train_excluded_spans,
            )
            if not valid_intervals:
                raise ValueError(
                    "训练集清洗后没有剩余任何合法训练窗口："
                    "清洗比例过高（几乎全部训练内容与 val/test "
                    "重复、损坏或退化），请检查语料/清洗开关，"
                    "而不是在清洗后继续训练"
                )

            self._train_start_intervals = valid_intervals
            lengths = [
                high - low + 1
                for low, high in valid_intervals
            ]
            self._train_interval_lows = torch.tensor(
                [low for low, _ in valid_intervals],
                dtype=torch.long,
            )
            self._train_interval_lengths = torch.tensor(
                lengths,
                dtype=torch.long,
            )
            self._train_interval_cumulative = torch.cumsum(
                self._train_interval_lengths,
                dim=0,
            )
            self.train_num_valid_starts = int(
                self._train_interval_cumulative[-1]
            )
            self.train_cleaning["valid_window_starts"] = (
                self.train_num_valid_starts
            )
            self.train_cleaning["total_window_starts"] = (
                total_starts
            )

        # unfold 产生 [num_windows, seq_len + 1] 的滑动窗口
        # 视图（stride 为 1），采样时按起点 index_select。
        # 窗口只在各自 split 内部滑动，不跨越 split 边界。
        self._windows = {
            "train": self.train.unfold(
                0,
                seq_len + 1,
                1,
            ),
            "val": self.val.unfold(
                0,
                seq_len + 1,
                1,
            ),
        }
        if len(self.test) >= seq_len + 1:
            self._windows["test"] = self.test.unfold(
                0,
                seq_len + 1,
                1,
            )

        # 固定评估起点按 split 分开保存。
        self._fixed_starts: Dict[str, Dict[str, object]] = {}

        # 群组（文档）起始位置缓存：评估不确定性的 cluster
        # bootstrap 需要把同一文档的 token 当成一个抽样单位，
        # 而不是把窗口当独立样本。只在支持 --group-separator
        # 的数据上可用；没有群组边界时保持 None，不伪造簇。
        self._split_group_starts: Dict[
            str, Optional[List[int]]
        ] = {}

        # 固定评估批的结果（设备侧）：键为
        # (split, batches, batch_size, batch_index, device)，
        # 值为 (x, y)；累计字节受 _EVAL_BATCH_CACHE_MAX_BYTES
        # 限制。
        self._fixed_batch_cache: Dict[
            tuple, Tuple[torch.Tensor, torch.Tensor]
        ] = {}
        self._fixed_batch_cache_bytes = 0

    @property
    def has_test(self) -> bool:
        """
        是否存在可用的测试 split（test_fraction > 0 且长度足够）。
        """
        return "test" in self._windows

    @property
    def split_fractions(self) -> Dict[str, float]:
        """
        各 split 的实际字节占比（吸附到群组边界后的真实值）。
        """
        total = max(1, self.num_bytes)
        return {
            split: (end - begin) / total
            for split, (begin, end) in self.split_bounds.items()
        }

    @property
    def effective_train_bytes(self) -> int:
        """
        实际参与训练统计的 train 字节数（扣除被清洗内容）。

        神经网络窗口采样已由 ``train_excluded_spans`` 屏蔽；任何
        在 train 上拟合统计量的基线也必须使用同一口径，否则
        被清洗的重复群组/损坏字节仍会进入 unigram / n-gram 计数。
        """
        excluded = sum(
            end - start
            for start, end in _merge_byte_intervals(
                self.train_excluded_spans
            )
        )
        return len(self.train) - excluded

    def effective_train_byte_counts(self) -> torch.Tensor:
        """
        统计实际参与训练的 train 字节频次（256 个字节类）。

        被 ``--deduplicate-train-groups`` 或
        ``--drop-train-corrupt-bytes`` 剔除的区间不计入；返回
        int64 张量，供 unigram 参考基线与数据审计的分布偏移
        统计使用，保证它们与神经网络看到的训练数据一致。
        """
        try:
            counts = torch.bincount(
                self.train,
                minlength=256,
            )
        except RuntimeError:
            counts = torch.bincount(
                self.train.to(torch.int64),
                minlength=256,
            )

        for start, end in _merge_byte_intervals(
            self.train_excluded_spans
        ):
            try:
                dropped = torch.bincount(
                    self.train[start:end],
                    minlength=256,
                )
            except RuntimeError:
                dropped = torch.bincount(
                    self.train[start:end].to(torch.int64),
                    minlength=256,
                )
            counts = counts - dropped

        if bool((counts < 0).any()):
            raise AssertionError(
                "训练集清洗区间统计为负：内部错误，拒绝继续"
            )

        return counts

    def _gather_windows(
        self,
        windows: torch.Tensor,
        starts: torch.Tensor,
        device: torch.device,
    ) -> torch.Tensor:
        """
        按窗口起点从 [num_windows, seq_len + 1] 的窗口视图收集字节，
        并搬运到目标设备（尚未转整数索引）。

        CUDA 下经暂存槽搬运，CPU 下走普通索引路径。
        """
        num_rows = starts.numel()

        if device.type != "cuda" or not torch.cuda.is_available():
            return torch.index_select(
                windows,
                0,
                starts,
            ).to(device)

        if self._stage_slots is None:
            # 每槽: [缓冲区或 None, 拷贝完成 Event 或 None]
            self._stage_slots = [[None, None], [None, None]]

        slot = self._stage_slots[self._stage_index]
        self._stage_index ^= 1

        # 使用槽位前确认上一次拷贝已完成。
        event = slot[1]
        if event is None:
            event = torch.cuda.Event()
            slot[1] = event
        else:
            event.synchronize()

        numel = num_rows * (self.seq_len + 1)
        buffer = slot[0]
        if buffer is None or buffer.numel() < numel:
            with torch.inference_mode(False):
                buffer = torch.empty(
                    numel,
                    dtype=torch.uint8,
                    pin_memory=True,
                )
            slot[0] = buffer

        staged = buffer[:numel].view(
            num_rows,
            self.seq_len + 1,
        )
        torch.index_select(windows, 0, starts, out=staged)

        chunks = staged.to(device, non_blocking=True)

        # 记录该槽位的完成时点。
        with torch.cuda.device(device):
            event.record()

        return chunks

    def _sample_train_starts(
        self,
        batch_size: int,
        generator: torch.Generator,
    ) -> torch.Tensor:
        """
        采样训练窗口起点；启用训练集群组清洗时只在合法起点
        区间内均匀采样，窗口不会触碰任何被剔除的群组内容。

        无清洗时走原路径（整个训练 split 均匀采样），保持
        随机流与历史运行逐位一致。
        """
        total_starts = len(self.train) - self.seq_len

        if self._train_start_intervals is None:
            return torch.randint(
                low=0,
                high=total_starts,
                size=(batch_size,),
                generator=generator,
            )

        assert self._train_interval_lows is not None
        assert self._train_interval_lengths is not None
        assert self._train_interval_cumulative is not None
        assert self.train_num_valid_starts is not None

        # 在每个合法区间内按区间长度均匀采样：先按累计长度
        # 抽全局序号，再映射回区间与区间内偏移。
        global_index = torch.randint(
            low=0,
            high=self.train_num_valid_starts,
            size=(batch_size,),
            generator=generator,
        )
        interval = torch.searchsorted(
            self._train_interval_cumulative,
            global_index,
            right=True,
        )
        offsets = global_index - (
            self._train_interval_cumulative[interval]
            - self._train_interval_lengths[interval]
        )
        return self._train_interval_lows[interval] + offsets

    def batch(
        self,
        split: str,
        batch_size: int,
        generator: torch.Generator,
        device: torch.device,
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        if split == "train":
            windows = self._windows["train"]
            data = self.train
        elif split == "val":
            windows = self._windows["val"]
            data = self.val
        elif split == "test":
            # 训练期间的随机批次绝不能碰测试集，
            # 否则测试集会在无感知的情况下被反复消费。
            raise ValueError(
                "测试集在最终评估前必须尘封，"
                "不能通过 batch() 访问"
            )
        else:
            raise ValueError(f"未知 split: {split}")

        if split == "train":
            starts = self._sample_train_starts(
                batch_size,
                generator,
            )
        else:
            max_start = len(data) - self.seq_len
            starts = torch.randint(
                low=0,
                high=max_start,
                size=(batch_size,),
                generator=generator,
            )

        # 窗口先以 uint8 搬运：输入 embedding 只接受 int32/int64，
        # 在目标设备上转 int32；目标 token 保持 uint8（cross_entropy
        # 直接支持 Byte 目标）。
        chunks = self._gather_windows(
            windows,
            starts,
            device,
        )

        x = chunks[:, :-1].to(torch.int32)
        y = chunks[:, 1:]

        return x, y

    def _eval_windows(
        self,
        split: str,
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        """
        取出指定评估 split 的窗口视图与底层 token 张量。

        batch() 只允许 train/val；test 只能经此处的固定窗口评估
        访问。
        """
        if split not in ("val", "test"):
            raise ValueError(f"未知评估 split: {split}")

        if split == "test" and not self.has_test:
            raise ValueError(
                "测试集不可用（test_fraction 为 0 或语料不足）"
            )

        windows = self._windows[split]
        data = self.val if split == "val" else self.test
        return windows, data

    def _ensure_fixed_starts(
        self,
        split: str,
        total_batches: int,
        num_starts: int,
    ) -> torch.Tensor:
        """生成（或复用）固定评估窗口起点。"""
        cache = self._fixed_starts.setdefault(
            split,
            {"total": None, "num_starts": None, "starts": None},
        )
        try:
            requested = int(total_batches)
        except (TypeError, ValueError, OverflowError):
            requested = 0
        try:
            available = int(num_starts)
        except (TypeError, ValueError, OverflowError):
            available = 0
        total_batches = max(0, min(requested, available))

        if (
            cache["total"] != total_batches
            or cache["num_starts"] != num_starts
        ):
            # 均匀覆盖整个评估流。total_batches <= num_starts，
            # linspace 的间距不小于 1，round 后不会重复。
            cache["starts"] = torch.linspace(
                0,
                num_starts - 1,
                steps=total_batches,
                dtype=torch.float64,
            ).round().long()
            cache["total"] = total_batches
            cache["num_starts"] = num_starts
        starts = cache["starts"]
        assert isinstance(starts, torch.Tensor)
        return starts

    def split_group_starts(
        self,
        split: str,
    ) -> Optional[List[int]]:
        """
        评估 split 内各群组（文档）的起始字节位置（相对 split
        起点）；没有 --group-separator 或 split 为空时返回 None。

        群组按 ``_iter_group_spans`` 的口径定义：分隔符之间的
        非空连续片段。分隔符本身不属于任何群组，但在下面的
        ``group_ids_for_starts`` 中并入前一个群组，保证每个
        目标 token 都能归属到一个文档簇；前导分隔符并入第一个
        群组。没有群组边界时不做任何近似（返回 None），避免
        把窗口当作文档簇写入报告。
        """
        if self.group_separator is None:
            return None
        if split not in self.split_bounds:
            raise ValueError(f"未知 split: {split}")
        if split in self._split_group_starts:
            return self._split_group_starts[split]

        begin, end = self.split_bounds[split]
        starts = sorted(
            {
                span_start - begin
                for span_start, _span_end in _iter_group_spans(
                    self._raw_buffer,
                    self.group_separator,
                    begin,
                    end,
                )
            }
        )
        result: Optional[List[int]]
        result = starts if starts else None
        self._split_group_starts[split] = result
        return result

    def group_assignment_fingerprint(self) -> Optional[str]:
        """群组定义指纹；没有群组分隔符时为 None。"""
        if self.group_separator is None:
            return None
        return hashlib.sha256(self.group_separator).hexdigest()

    def group_ids_for_starts(
        self,
        split: str,
        starts: torch.Tensor,
    ) -> Optional[torch.Tensor]:
        """
        固定评估窗口内每个**目标 token**（x 右移一位）所属的
        群组下标，形状 [n_windows, seq_len]，int64 CPU 张量。

        群组下标是 split 内部的 0 基序号，与
        ``split_group_starts`` 的顺序一致。位置 p 归属
        ``max{i: group_start_i <= p}``；因此分隔符与空群组
        并入前一个群组，前导分隔符并入第一个群组。没有群组
        边界时返回 None。
        """
        group_starts = self.split_group_starts(split)
        if group_starts is None:
            return None
        start_tensor = torch.tensor(
            group_starts,
            dtype=torch.long,
        )
        window_starts = torch.as_tensor(
            starts,
            dtype=torch.long,
        ).reshape(-1)
        if window_starts.numel() == 0:
            return torch.empty(
                (0, self.seq_len),
                dtype=torch.long,
            )
        offsets = torch.arange(
            1,
            self.seq_len + 1,
            dtype=torch.long,
        )
        positions = (
            window_starts.unsqueeze(1) + offsets.unsqueeze(0)
        )
        # right=True 让恰好落在群组起点的位置归入新群组；
        # clamp 处理前导分隔符（下标 -1）与空 split。
        ids = (
            torch.searchsorted(
                start_tensor,
                positions.reshape(-1),
                right=True,
            )
            - 1
        ).clamp_(min=0)
        return ids.view(positions.shape)

    def fixed_eval_group_ids(
        self,
        split: str,
        batches: int,
        batch_size: int,
    ) -> Optional[torch.Tensor]:
        """全部固定评估窗口的目标 token 群组下标；不可用时 None。"""
        windows, data = self._eval_windows(split)
        _ = windows
        num_starts = len(data) - self.seq_len
        try:
            requested = int(batches * batch_size)
        except (TypeError, ValueError, OverflowError):
            return None
        total_batches = max(0, min(requested, num_starts))
        starts = self._ensure_fixed_starts(
            split,
            total_batches,
            num_starts,
        )
        return self.group_ids_for_starts(split, starts)

    def fixed_eval_batch(
        self,
        split: str,
        batch_index: int,
        batches: int,
        batch_size: int,
        device: torch.device,
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        """
        返回跨指定评估 split（val/test）均匀分布的固定窗口。

        不用随机数，因此评估估计不随运行进程、CUDA 状态或
        eval_batches 的调用顺序而变化；不同实验看到的窗口集合
        完全相同。请求窗口多于合法起点时仅取一遍无重复起点。

        固定窗口在多次评估间逐位相同，结果张量在设备侧保存；
        总量受 _EVAL_BATCH_CACHE_MAX_BYTES 限制。所有调用方只读
        返回的 x/y。
        """
        windows, data = self._eval_windows(split)

        # 合法起点共 len(data) - seq_len 个。
        num_starts = len(data) - self.seq_len
        total_batches = min(
            batches * batch_size,
            num_starts,
        )

        starts_all = self._ensure_fixed_starts(
            split,
            total_batches,
            num_starts,
        )

        cache_key = (
            split,
            batches,
            batch_size,
            batch_index,
            str(device),
        )
        cached = self._fixed_batch_cache.get(cache_key)
        if cached is not None:
            return cached

        begin = batch_index * batch_size
        # starts 为 CPU 张量，窗口收集与搬运与训练批一致。
        starts = starts_all[begin:begin + batch_size]

        chunks = self._gather_windows(
            windows,
            starts,
            device,
        )

        x = chunks[:, :-1].to(torch.int32)
        y = chunks[:, 1:]

        batch_bytes = (
            x.numel() * x.element_size()
            + y.numel() * y.element_size()
        )
        if (
            self._fixed_batch_cache_bytes + batch_bytes
            <= _EVAL_BATCH_CACHE_MAX_BYTES
        ):
            self._fixed_batch_cache[cache_key] = (x, y)
            self._fixed_batch_cache_bytes += batch_bytes

        return x, y

    def clear_eval_batch_cache(self) -> None:
        """
        释放固定评估批的设备侧结果。

        评估协议结束后（最终/测试评估完成）显式清空；评估起点
        （_fixed_starts）只是 CPU 索引，保留。
        """
        self._fixed_batch_cache.clear()
        self._fixed_batch_cache_bytes = 0

    def fixed_val_batch(
        self,
        batch_index: int,
        batches: int,
        batch_size: int,
        device: torch.device,
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        """fixed_eval_batch("val", ...) 的兼容包装。"""
        return self.fixed_eval_batch(
            "val",
            batch_index,
            batches,
            batch_size,
            device,
        )


# ============================================================
# Pre-training data pipeline probe
# ============================================================

def _expected_window_pairs(
    data: torch.Tensor,
    starts: torch.Tensor,
    seq_len: int,
) -> Tuple[torch.Tensor, torch.Tensor]:
    """
    按窗口起点从原始 split 字节张量重建 (x, y)。

    x 是窗口去除最后一个字节的输入，y 是窗口去除第一个字节的
    目标（下一 token 监督位）。这是数据协议对 (x, y) 的定义，
    独立于 ByteDataset 的 unfold/index_select 实现，用于核对
    两者的逐位一致性。
    """
    positions = starts.to(torch.long).unsqueeze(1) + torch.arange(
        seq_len + 1,
        dtype=torch.long,
    )
    windows = data[positions]
    return windows[:, :-1].to(torch.int32), windows[:, 1:]


def probe_data_pipeline(
    dataset: ByteDataset,
    device: torch.device,
    *,
    batch_size: int = 4,
    batches: int = 2,
    seed: int = 20240607,
    include_test: bool = False,
) -> Dict[str, object]:
    """
    训练前的数据管线完整性质检（中间结果检查）。

    过拟合小批量只能证明「模型在本数据管线的输出上可以学到
    东西」：如果 x/y 错位、标签映射错误或切分越界，模型可以
    照样把固定小批次背下来，sanity check 无法发现。这里用
    独立重建的方式逐位核对数据协议：

    - 三段切分边界连续、长度与字节总数一致，train/val/test
      互不重叠（窗口不跨越 split 边界）；
    - 训练批的采样起点可复现，且 ``batch()`` 返回的 (x, y)
      与「从原始 train 字节按起点直接切片」逐位一致（覆盖
      群组去重后的合法起点区间路径）；
    - 验证固定窗口的起点可复现，且 ``fixed_eval_batch()``
      的 (x, y) 同样逐位一致；
    - 输入 token 落在 [0, vocab_size) 内、dtype 与形状符合
      约定（x 为 int32、y 为 uint8，监督位是后移一位的目标）。

    返回结构化报告；``failures`` 非空表示数据协议存在实质
    错误（错位、越界、不可复现），在训练前必须处理。
    """
    seq_len = dataset.seq_len
    failures: List[str] = []

    report: Dict[str, object] = {
        "ok": True,
        "failures": failures,
        "seq_len": seq_len,
        "train_checked": False,
        "val_fixed_checked": False,
        "test_fixed_checked": False,
        "split_bounds": {
            split: list(bounds)
            for split, bounds in dataset.split_bounds.items()
        },
    }

    bounds = dataset.split_bounds
    train_bounds = bounds["train"]
    val_bounds = bounds["val"]
    test_bounds = bounds["test"]

    if not (
        train_bounds[0] == 0
        and train_bounds[1] == val_bounds[0]
        and val_bounds[1] == test_bounds[0]
        and test_bounds[1] == dataset.num_bytes
    ):
        failures.append(
            "split 边界不连续（train/val/test 必须首尾相接且"
            "覆盖全部字节）"
        )

    split_lengths = (
        train_bounds[1] - train_bounds[0]
        + (val_bounds[1] - val_bounds[0])
        + (test_bounds[1] - test_bounds[0])
    )
    if split_lengths != dataset.num_bytes:
        failures.append(
            "split 长度之和与字节总数不一致"
        )

    if len(dataset.train) != train_bounds[1] - train_bounds[0]:
        failures.append("训练集长度与切分边界不一致")
    if len(dataset.val) != val_bounds[1] - val_bounds[0]:
        failures.append("验证集长度与切分边界不一致")
    if dataset.has_test and (
        len(dataset.test) != test_bounds[1] - test_bounds[0]
    ):
        failures.append("测试集长度与切分边界不一致")

    max_train_start = len(dataset.train) - seq_len
    if max_train_start < 1:
        failures.append("训练集没有合法窗口起点")

    # ---- 训练批：采样起点 + x/y 逐位对齐 ----
    try:
        probe_generator = torch.Generator().manual_seed(seed)
        starts = dataset._sample_train_starts(
            batch_size,
            probe_generator,
        )

        if int(starts.numel()) != batch_size:
            failures.append("训练批采样起点数量与 batch_size 不一致")

        if int(starts.min()) < 0 or int(starts.max()) > max_train_start - 1:
            failures.append(
                "训练批采样起点越界（窗口会跨越训练 split 边界）"
            )

        expected_x, expected_y = _expected_window_pairs(
            dataset.train,
            starts,
            seq_len,
        )

        batch_generator = torch.Generator().manual_seed(seed)
        x, y = dataset.batch(
            "train",
            batch_size,
            batch_generator,
            device,
        )

        report["train_checked"] = True

        if x.cpu().dtype != torch.int32:
            failures.append(
                f"训练批 x dtype 为 {x.dtype}，期望 int32"
            )
        if y.cpu().dtype != torch.uint8:
            failures.append(
                f"训练批 y dtype 为 {y.dtype}，期望 uint8"
            )

        if tuple(x.shape) != tuple(expected_x.shape):
            failures.append(
                f"训练批 x 形状 {tuple(x.shape)} 与期望 "
                f"{tuple(expected_x.shape)} 不一致"
            )
        elif not torch.equal(x.cpu(), expected_x):
            failures.append(
                "训练批 x 与原始字节切片不一致（输入窗口错位）"
            )

        if tuple(y.shape) != tuple(expected_y.shape):
            failures.append(
                f"训练批 y 形状 {tuple(y.shape)} 与期望 "
                f"{tuple(expected_y.shape)} 不一致"
            )
        elif not torch.equal(y.cpu(), expected_y):
            failures.append(
                "训练批 y 与原始字节切片不一致（下一 token "
                "标签错位）"
            )

        # 同一 seed 的第二次采样必须逐位一致：训练批采样
        # 不允许依赖生成器之外的任何隐式状态。
        repeat_x, repeat_y = dataset.batch(
            "train",
            batch_size,
            torch.Generator().manual_seed(seed),
            device,
        )
        if not (
            torch.equal(x.cpu(), repeat_x.cpu())
            and torch.equal(y.cpu(), repeat_y.cpu())
        ):
            failures.append(
                "训练批采样不可复现（同一 seed 两次采样结果"
                "不同）"
            )

        if x.numel() > 0 and (
            int(x.min()) < 0 or int(x.max()) >= 256
        ):
            failures.append(
                "训练批输入 token 超出 [0, 256) 字节范围"
            )

        if y.numel() > 0 and (
            int(y.min()) < 0 or int(y.max()) >= 256
        ):
            failures.append(
                "训练批标签 token 超出 [0, 256) 字节范围"
            )
    except (AssertionError, RuntimeError, ValueError) as error:
        failures.append(f"训练批检查抛出异常: {error}")

    # ---- 验证固定窗口：起点可复现 + x/y 逐位对齐 ----
    num_starts = len(dataset.val) - seq_len
    try:
        total_batches = min(batches * batch_size, num_starts)
        fixed_starts_all = torch.linspace(
            0,
            num_starts - 1,
            steps=total_batches,
            dtype=torch.float64,
        ).round().long()
        # batch_index=0 只返回前 batch_size 个固定起点。
        fixed_starts = fixed_starts_all[:batch_size]

        expected_x, expected_y = _expected_window_pairs(
            dataset.val,
            fixed_starts,
            seq_len,
        )

        dataset.clear_eval_batch_cache()
        x, y = dataset.fixed_eval_batch(
            "val",
            0,
            batches,
            batch_size,
            device,
        )

        report["val_fixed_checked"] = True

        if x.cpu().dtype != torch.int32:
            failures.append(
                f"验证固定窗口 x dtype 为 {x.dtype}，期望 int32"
            )
        if y.cpu().dtype != torch.uint8:
            failures.append(
                f"验证固定窗口 y dtype 为 {y.dtype}，期望 uint8"
            )

        if tuple(x.shape) != tuple(expected_x.shape):
            failures.append(
                f"验证固定窗口 x 形状 {tuple(x.shape)} 与期望 "
                f"{tuple(expected_x.shape)} 不一致"
            )
        elif not torch.equal(x.cpu(), expected_x):
            failures.append(
                "验证固定窗口 x 与原始字节切片不一致（固定评估"
                "窗口不可复现或输入错位）"
            )
        if tuple(y.shape) != tuple(expected_y.shape):
            failures.append(
                f"验证固定窗口 y 形状 {tuple(y.shape)} 与期望 "
                f"{tuple(expected_y.shape)} 不一致"
            )
        elif not torch.equal(y.cpu(), expected_y):
            failures.append(
                "验证固定窗口 y 与原始字节切片不一致（评估标签"
                "错位）"
            )

        if x.numel() > 0 and (
            int(x.min()) < 0 or int(x.max()) >= 256
        ):
            failures.append(
                "验证固定窗口输入 token 超出 [0, 256) 字节范围"
            )
        if y.numel() > 0 and (
            int(y.min()) < 0 or int(y.max()) >= 256
        ):
            failures.append(
                "验证固定窗口标签 token 超出 [0, 256) 字节范围"
            )

        # 清空结果后重建必须逐位一致：固定评估窗口跨进程/
        # 跨调用不依赖任何随机状态。
        dataset.clear_eval_batch_cache()
        repeat_x, repeat_y = dataset.fixed_eval_batch(
            "val",
            0,
            batches,
            batch_size,
            device,
        )
        if not (
            torch.equal(x.cpu(), repeat_x.cpu())
            and torch.equal(y.cpu(), repeat_y.cpu())
        ):
            failures.append(
                "验证固定窗口重复构建不可复现（结果依赖调用"
                "顺序或随机状态）"
            )
    except (AssertionError, RuntimeError, ValueError) as error:
        failures.append(f"验证固定窗口检查抛出异常: {error}")

    # ---- 测试固定窗口：只在最终解封时核对 ----
    if include_test and dataset.has_test:
        num_starts = len(dataset.test) - seq_len
        try:
            total_batches = min(
                batches * batch_size,
                num_starts,
            )
            fixed_starts_all = torch.linspace(
                0,
                num_starts - 1,
                steps=total_batches,
                dtype=torch.float64,
            ).round().long()
            fixed_starts = fixed_starts_all[:batch_size]

            expected_x, expected_y = _expected_window_pairs(
                dataset.test,
                fixed_starts,
                seq_len,
            )

            dataset.clear_eval_batch_cache()
            x, y = dataset.fixed_eval_batch(
                "test",
                0,
                batches,
                batch_size,
                device,
            )

            report["test_fixed_checked"] = True

            if x.cpu().dtype != torch.int32:
                failures.append(
                    f"测试固定窗口 x dtype 为 {x.dtype}，"
                    "期望 int32"
                )
            if y.cpu().dtype != torch.uint8:
                failures.append(
                    f"测试固定窗口 y dtype 为 {y.dtype}，"
                    "期望 uint8"
                )

            if tuple(x.shape) != tuple(expected_x.shape):
                failures.append(
                    "测试固定窗口 x 形状与期望不一致"
                )
            elif not torch.equal(x.cpu(), expected_x):
                failures.append(
                    "测试固定窗口 x 与原始测试字节不一致"
                    "（测试输入错位或窗口越界）"
                )

            if tuple(y.shape) != tuple(expected_y.shape):
                failures.append(
                    "测试固定窗口 y 形状与期望不一致"
                )
            elif not torch.equal(y.cpu(), expected_y):
                failures.append(
                    "测试固定窗口 y 与原始测试字节不一致"
                    "（测试标签错位）"
                )

            if x.numel() > 0 and (
                int(x.min()) < 0 or int(x.max()) >= 256
            ):
                failures.append(
                    "测试固定窗口输入 token 超出 [0, 256) "
                    "字节范围"
                )
            if y.numel() > 0 and (
                int(y.min()) < 0 or int(y.max()) >= 256
            ):
                failures.append(
                    "测试固定窗口标签 token 超出 [0, 256) "
                    "字节范围"
                )

            dataset.clear_eval_batch_cache()
            repeat_x, repeat_y = dataset.fixed_eval_batch(
                "test",
                0,
                batches,
                batch_size,
                device,
            )
            if not (
                torch.equal(x.cpu(), repeat_x.cpu())
                and torch.equal(y.cpu(), repeat_y.cpu())
            ):
                failures.append(
                    "测试固定窗口重复构建不可复现"
                )
        except (AssertionError, RuntimeError, ValueError) as error:
            failures.append(
                f"测试固定窗口检查抛出异常: {error}"
            )

    # ---- 群组边界：独立核对「任何群组不跨 split」----
    if dataset.group_separator is not None:
        report["group_boundaries_checked"] = True
        separator = dataset.group_separator

        for split, (begin, end) in bounds.items():
            # 空 split（如 test_fraction=0 时的 test）没有群组，
            # 其起点可能恰为文件末尾，不应要求末尾再有一个
            # 分组分隔符。
            if begin <= 0 or end <= begin:
                continue
            prefix = bytes(
                dataset._raw[
                    begin - len(separator):begin
                ]
            )
            if prefix != separator:
                failures.append(
                    f"{split} split 起点不在群组分隔符之后"
                    "（群组可能被拆到两侧）"
                )

        if dataset.groups_per_split is not None:
            recounted = dict(
                zip(
                    ("train", "val", "test"),
                    _count_groups(
                        dataset._raw_buffer,
                        separator,
                        [val_bounds[0], val_bounds[1]],
                    ),
                )
            )
            if recounted != dataset.groups_per_split:
                failures.append(
                    "群组计数与构造记录不一致（群组划分"
                    "可能被破坏）"
                )

    # ---- 训练集群组清洗：窗口不得触碰被剔除群组 ----
    if dataset.train_excluded_spans:
        report["train_cleaning_checked"] = True
        merged = _merge_byte_intervals(
            dataset.train_excluded_spans
        )

        if merged != list(dataset.train_excluded_spans):
            failures.append(
                "训练集清洗区间无序或重叠"
            )

        if any(
            start < 0 or end > len(dataset.train)
            for start, end in merged
        ):
            failures.append(
                "训练集清洗区间越出 train split"
            )

        cleaning = dataset.train_cleaning or {}
        dropped_bytes = sum(
            end - start for start, end in merged
        )
        if int(cleaning.get("dropped_bytes", -1)) != dropped_bytes:
            failures.append(
                "训练集清洗统计的 dropped_bytes 与"
                "实际排除区间不一致"
            )
        if int(
            cleaning.get("post_clean_train_bytes", -1)
        ) != len(dataset.train) - dropped_bytes:
            failures.append(
                "训练集清洗统计的剩余字节数不一致"
            )

        probe_starts = dataset._sample_train_starts(
            32,
            torch.Generator().manual_seed(seed + 1),
        )
        for start in probe_starts.tolist():
            window_end = start + seq_len
            if any(
                low <= window_end and high > start
                for low, high in merged
            ):
                failures.append(
                    "训练批采样窗口触碰被清洗内容"
                    "（清洗内容仍会进入训练）"
                )
                break

        if _valid_window_start_intervals(
            len(dataset.train) - seq_len,
            seq_len,
            merged,
        ) is None:
            failures.append(
                "训练集存在清洗区间但没有生成合法"
                "起点区间"
            )

    report["ok"] = not failures
    return report



# 重复窗口扫描的采样上限：窗口数超过该值时按等间距抽样。
_AUDIT_MAX_WINDOWS = 100000

# train/val(/test) 字节分布 JS 距离超过该值时报分布偏移警告。
_AUDIT_SHIFT_WARN = 0.1

# 字节二元组分布偏移的告警阈值：只看单字节频率会漏掉
# 「词表相同但上下文/顺序变了」的偏移，例如训练集是
# abab...、评估集是 baba...；二元组 JS 距离对这类偏移敏感。
_AUDIT_BIGRAM_SHIFT_WARN = 0.1

# 条件分布 P(next_byte | prev_byte) 的 JS 距离阈值：联合二元组
# 分布相同也可能存在「同一上下文接不同标签」的监督漂移。
_AUDIT_CONDITIONAL_SHIFT_WARN = 0.1

# eval 中未见过的 (上下文, 目标) 转移比例阈值：比例过高说明
# 训练集没有覆盖评估集的监督模式，泛化指标会包含大量外推。
_AUDIT_UNSEEN_TRANSITION_WARN = 0.5

# 时间边界分布漂移：全局直方图会把「train 尾部已经漂移、val
# 头部继续漂移」相互抵消。分别取 train 尾部与 val 头部（以及
# val 尾部与 test 头部）各一个块，比较字节分布的 JS 距离。
# 块大小取相邻 split 较小者的 10%，限制在 [4KiB, 1MiB]；
# split 太小时不做边界审计，避免把抽样噪声当漂移。
_AUDIT_BOUNDARY_BLOCK_FRACTION = 0.1
_AUDIT_BOUNDARY_MIN_BYTES = 4096
_AUDIT_BOUNDARY_MAX_BYTES = 1024 * 1024
_AUDIT_BOUNDARY_SHIFT_WARN = 0.1

# 单个字节占比超过该阈值时疑似填充/退化数据（异常值检查）。
_AUDIT_TOP_BYTE_WARN = 0.5

# UTF-8 解码失败（替换字符）占比超过该阈值时报语料损坏警告：
# 字节级语言模型直接以字节为标签，无法解码的字节就是
# 「标签噪声」的语料来源，必须先发现再决定是否清洗。
_AUDIT_UTF8_REPLACE_WARN = 1e-3

# NUL 字节占比超过该阈值时报二进制/填充污染警告
# （文本语料中 NUL 基本只来自错误编码或文件拼接损坏）。
_AUDIT_NUL_WARN = 1e-4

# 群组级异常值检查：长度至少为该值、且单一字节占比达到阈值的
# 群组视为低信息/退化群组（填充、重复字符、错误拼接的常见形态）。
# 只在 train 上统计；--drop-train-degenerate-groups 可整组清洗。
_AUDIT_DEGENERATE_GROUP_MIN_BYTES = 64
_AUDIT_DEGENERATE_GROUP_TOP_SHARE = 0.99

# 无群组连续字节流的异常值：长度至少为该值的同字节连续段
# 视为低信息/退化段（填充、错误拼接），可用
# --drop-train-degenerate-runs 只从 train 剔除。
_AUDIT_DEGENERATE_RUN_MIN_BYTES = 64

# 实际 split 比例相对名义值漂移超过该幅度（且绝对差
# 至少 _AUDIT_SPLIT_FRACTION_MIN_ABS）时告警：群组边界
# 吸附可能把验证/测试集缩小到名义比例的一小部分。
_AUDIT_SPLIT_FRACTION_DRIFT = 0.2
_AUDIT_SPLIT_FRACTION_MIN_ABS = 0.01

# 内容定义分块审计的最小/最大块长与边界概率掩码。分块边界
# 由块内局部内容的滚动哈希决定，而不是全局固定偏移，因此
# 同一段内容即使整体错位复制也会在后续块上重新对齐。最小
# 块长同时限制为至少 seq_len + 1：共享块足以覆盖一个完整
# 训练/评估窗口，才能作为跨 split 泄露证据。
_AUDIT_CHUNK_MIN_BYTES = 32
_AUDIT_CHUNK_MAX_BYTES = 512
_AUDIT_CHUNK_BOUNDARY_MASK = 0x3F
_AUDIT_CHUNK_GEAR_TABLE = tuple(
    int.from_bytes(
        hashlib.blake2b(
            bytes((value,)),
            digest_size=8,
        ).digest(),
        "little",
    )
    for value in range(256)
)
_AUDIT_CHUNK_UINT64_MASK = (1 << 64) - 1


# 训练集清洗的删除偏差审计：被删除内容与保留内容的字节/二元组
# 分布差异过大时，说明清洗不是随机删除，训练分布已被选择性改变。
# 这不是「清洗有 bug」，而是必须在报告里披露的干预效应：清洗后的
# 损失不能直接与未清洗运行比较，也不能把删除比例高当成数据更多。
_AUDIT_DELETION_BIAS_WARN = 0.10
_AUDIT_DELETION_DROP_WARN = 0.20

# 评估集标签覆盖：训练集从未出现过的字节类在评估 token 中占比
# 超过该阈值时告警。字节级 LM 无法通过上下文学习这些标签，
# 它们构成不可约的外推误差，不能全部归因于模型能力。
_AUDIT_UNSEEN_LABEL_WARN = 1e-4


def _byte_bigram_counts(
    tokens: torch.Tensor,
    excluded_spans: Optional[List[Tuple[int, int]]] = None,
) -> torch.Tensor:
    """
    统计 split 内相邻字节对的频次（256×256 展平）。

    排除区间两侧的字节不能组成跨越清洗内容的虚假二元组：
    只在每个连续有效内容区间内部计数，与训练窗口/统计基线
    的有效训练口径一致。
    """
    vocab_size = 256
    counts = torch.zeros(
        vocab_size * vocab_size,
        dtype=torch.int64,
    )

    intervals = _subtract_byte_intervals(
        0,
        int(tokens.numel()),
        list(excluded_spans or []),
    )

    for begin, end in intervals:
        if end - begin < 2:
            continue
        left = tokens[begin:end - 1].to(torch.int64)
        right = tokens[begin + 1:end].to(torch.int64)
        pairs = left * vocab_size + right
        counts += torch.bincount(
            pairs,
            minlength=vocab_size * vocab_size,
        )

    return counts


def _effective_edge_histogram(
    dataset: "ByteDataset",
    split: str,
    max_bytes: int,
    from_start: bool,
) -> Tuple[Optional[torch.Tensor], int]:
    """
    取 split 有效内容的头部或尾部连续字节，返回归一化字节分布
    与实际字节数。train 的清洗区间不参与边界漂移统计，避免把
    模型从未见过的字节当成训练尾部。
    """
    tokens = getattr(dataset, split)
    total = int(tokens.numel())
    if total <= 0 or max_bytes <= 0:
        return None, 0

    intervals = _subtract_byte_intervals(
        0,
        total,
        (
            dataset.train_excluded_spans
            if split == "train"
            else []
        ),
    )
    if not intervals:
        return None, 0

    ordered = intervals if from_start else list(reversed(intervals))
    remaining = max_bytes
    counts = torch.zeros(256, dtype=torch.float64)
    used = 0

    for begin, end in ordered:
        if remaining <= 0:
            break

        take = min(end - begin, remaining)
        if take <= 0:
            continue

        if from_start:
            chunk = tokens[begin:begin + take]
        else:
            chunk = tokens[end - take:end]

        counts += torch.bincount(
            chunk.to(torch.int64),
            minlength=256,
        ).to(torch.float64)
        used += take
        remaining -= take

    if used <= 0:
        return None, 0

    return counts / counts.sum(), used


def _temporal_boundary_shift_audit(
    dataset: "ByteDataset",
    split_names: List[str],
    warnings: List[str],
) -> Dict[str, object]:
    """
    时间边界分布漂移审计：全局直方图可能让「train 尾部已经
    漂移」和「val 头部继续漂移」相互抵消。分别取相邻 split
    的尾/头块做字节 JS 距离，专门检查切分边界附近是否存在
    全局统计看不到的分布突变。

    test 只在 include_test=True（解封评估）时参与，训练期间
    不会读取 test 内容。数据太少或清洗后有效内容不足时跳过，
    避免把小块抽样噪声当成漂移。
    """
    pairs: Dict[str, object] = {}

    for left, right in (
        ("train", "val"),
        ("val", "test"),
    ):
        if left not in split_names or right not in split_names:
            continue

        left_total = (
            int(dataset.effective_train_bytes)
            if left == "train"
            else int(
                dataset.split_bounds[left][1]
                - dataset.split_bounds[left][0]
            )
        )
        right_total = int(
            dataset.split_bounds[right][1]
            - dataset.split_bounds[right][0]
        )
        smaller = min(left_total, right_total)

        if smaller < 2 * _AUDIT_BOUNDARY_MIN_BYTES:
            continue

        block_bytes = int(
            smaller * _AUDIT_BOUNDARY_BLOCK_FRACTION
        )
        block_bytes = max(
            _AUDIT_BOUNDARY_MIN_BYTES,
            min(block_bytes, _AUDIT_BOUNDARY_MAX_BYTES),
        )

        left_hist, left_used = _effective_edge_histogram(
            dataset,
            left,
            block_bytes,
            from_start=False,
        )
        right_hist, right_used = _effective_edge_histogram(
            dataset,
            right,
            block_bytes,
            from_start=True,
        )
        if (
            left_hist is None
            or right_hist is None
            or left_used <= 0
            or right_used <= 0
        ):
            continue

        distance = _js_distance(left_hist, right_hist)
        key = f"{left}_tail_{right}_head"
        pairs[key] = {
            "js": round(distance, 6),
            "left_bytes": left_used,
            "right_bytes": right_used,
        }

        if distance > _AUDIT_BOUNDARY_SHIFT_WARN:
            warnings.append(
                f"{key}: 时间边界字节分布偏移较大"
                f"（JS 距离 {distance:.4f}，各取 "
                f"{left_used}/{right_used} 字节）；"
                "全局直方图可能掩盖切分边界附近的分布突变，"
                "需检查时间漂移或切分点"
            )

    return {
        "block_fraction": _AUDIT_BOUNDARY_BLOCK_FRACTION,
        "min_bytes": _AUDIT_BOUNDARY_MIN_BYTES,
        "max_bytes": _AUDIT_BOUNDARY_MAX_BYTES,
        "warn_js": _AUDIT_BOUNDARY_SHIFT_WARN,
        "pairs": pairs,
    }


def _js_distance(
    p: torch.Tensor,
    q: torch.Tensor,
) -> float:
    """
    两个离散分布之间的 Jensen-Shannon 距离
    （JS 散度开方，log 以 2 为底，取值 [0, 1]；0 表示分布相同）。
    """
    m = 0.5 * (p + q)

    def _kl(a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
        mask = a > 0
        # log2 才能让 JS 散度上界为 1 bit、距离落在 [0, 1]
        #（自然对数下上界是 ln 2，距离最大 sqrt(ln 2)≈0.83，
        # 与审计阈值按 [0, 1] 标定的口径不一致）。
        return (a[mask] * (a[mask] / b[mask]).log2()).sum()

    js = 0.5 * _kl(p, m) + 0.5 * _kl(q, m)
    return math.sqrt(max(0.0, float(js)))


def _conditional_bigram_shift(
    train_counts: torch.Tensor,
    eval_counts: torch.Tensor,
    vocab_size: int = 256,
) -> Dict[str, float]:
    """
    给定上下文后的标签分布偏移（P(next_byte | prev_byte)）。

    单字节/联合二元组分布可能掩盖条件分布变化：同样的二元组
    词表，若「同一上下文后面接什么」发生变化，监督信号已经
    漂移。这里逐上下文比较 train 与 eval 的条件分布：

    - ``conditional_js``：按 eval 中该上下文的出现次数加权的
      条件 JS 距离（只统计 train 中出现过的上下文；对每行做
      Laplace 平滑，避免零概率使距离失真）；
    - ``seen_context_share``：eval 二元组中，其上下文在 train
      至少出现过一次的比例；
    - ``unseen_transition_share``：eval 二元组中，该
      (上下文, 目标) 转移在 train 从未出现的比例。

    统计量只用于审计，不进入模型训练或选型。train 计数已经
    扣除清洗区间，与神经网络/统计基线看到的训练内容一致。
    """
    train = train_counts.view(
        vocab_size,
        vocab_size,
    ).to(torch.float64)
    evaluation = eval_counts.view(
        vocab_size,
        vocab_size,
    ).to(torch.float64)

    train_ctx = train.sum(dim=1)
    eval_ctx = evaluation.sum(dim=1)
    total_eval_pairs = float(eval_ctx.sum())

    if total_eval_pairs <= 0.0:
        return {
            "conditional_js": 0.0,
            "seen_context_share": 0.0,
            "unseen_transition_share": 0.0,
            "eval_pairs": 0.0,
        }

    supported = (eval_ctx > 0) & (train_ctx > 0)
    seen_pairs = float(eval_ctx[supported].sum())
    seen_context_share = seen_pairs / total_eval_pairs

    unseen_pairs = float(
        (evaluation * (train == 0)).sum()
    )
    unseen_transition_share = unseen_pairs / total_eval_pairs

    if seen_pairs <= 0.0:
        conditional_js = 1.0
    else:
        train_rows = train[supported] + 1.0
        eval_rows = evaluation[supported] + 1.0
        train_probs = train_rows / train_rows.sum(
            dim=1,
            keepdim=True,
        )
        eval_probs = eval_rows / eval_rows.sum(
            dim=1,
            keepdim=True,
        )
        mean_probs = 0.5 * (train_probs + eval_probs)

        def _kl_rows(
            left: torch.Tensor,
            right: torch.Tensor,
        ) -> torch.Tensor:
            return (
                left * (left / right).log2()
            ).sum(dim=1)

        js_rows = 0.5 * _kl_rows(
            train_probs,
            mean_probs,
        ) + 0.5 * _kl_rows(
            eval_probs,
            mean_probs,
        )
        distances = js_rows.clamp_min(0.0).sqrt()
        weights = eval_ctx[supported]
        conditional_js = float(
            (distances * weights).sum() / weights.sum()
        )

    return {
        "conditional_js": conditional_js,
        "seen_context_share": seen_context_share,
        "unseen_transition_share": unseen_transition_share,
        "eval_pairs": total_eval_pairs,
    }


def _subtract_byte_intervals(
    begin: int,
    end: int,
    excluded_spans: List[Tuple[int, int]],
) -> List[Tuple[int, int]]:
    """
    返回 [begin, end) 内扣除排除区间后的连续内容区间。
    """
    result: List[Tuple[int, int]] = []
    cursor = begin

    for excluded_start, excluded_end in _merge_byte_intervals(
        excluded_spans
    ):
        if excluded_end <= begin or excluded_start >= end:
            continue
        if cursor < excluded_start:
            result.append(
                (cursor, min(excluded_start, end))
            )
        cursor = max(cursor, excluded_end)
        if cursor >= end:
            break

    if cursor < end:
        result.append((cursor, end))

    return [
        (start, stop)
        for start, stop in result
        if stop > start
    ]


def _interval_byte_counts(
    raw: memoryview,
    intervals: List[Tuple[int, int]],
    chunk_bytes: int = 1 << 20,
) -> torch.Tensor:
    """
    统计若干连续区间内的字节频次（256 类，int64）。

    从原始缓冲区按块读取，避免把整个 split 复制成 Python bytes。
    与 ``_byte_bigram_counts`` 同一口径：只统计区间内部，不制造
    跨越被删除内容的虚假计数。
    """
    counts = torch.zeros(256, dtype=torch.int64)
    # 分块大小必须至少推进一个字节；0/负值会让 while 原地
    # 踏步而不是报错或返回。调用方可能传实验性小块做核对。
    step_bytes = max(1, int(chunk_bytes))

    for span_start, span_end in intervals:
        position = span_start
        while position < span_end:
            stop = min(position + step_bytes, span_end)
            block_view = raw[position:stop]
            # 只读 memoryview（如 memoryview(bytes)）不能安全传给
            # torch.frombuffer：PyTorch 会警告它无法阻止写入。
            block = torch.frombuffer(
                bytearray(block_view)
                if block_view.readonly
                else block_view,
                dtype=torch.uint8,
            )
            if block.numel() > 0:
                counts += torch.bincount(
                    block,
                    minlength=256,
                )
            position = stop

    return counts


def _interval_bigram_counts(
    raw: memoryview,
    intervals: List[Tuple[int, int]],
    chunk_bytes: int = 1 << 20,
) -> torch.Tensor:
    """
    统计若干连续区间内的相邻字节对频次（256*256 展平）。

    分块时保留一个字节的重叠，确保块边界上的
    (stop-1, stop) 转移不会被漏计；区间之间不连接，避免把
    「删除内容之后紧接保留内容」误算成一个训练二元组。
    """
    vocab_size = 256
    counts = torch.zeros(
        vocab_size * vocab_size,
        dtype=torch.int64,
    )
    # 二元组分块至少取 2 字节：chunk_bytes=1 时 stop-1 会把
    # position 推回原处，造成死循环；0/负值同理。
    step_bytes = max(2, int(chunk_bytes))

    for span_start, span_end in intervals:
        if span_end - span_start < 2:
            continue

        position = span_start
        while position < span_end - 1:
            stop = min(position + step_bytes, span_end)
            block_view = raw[position:stop]
            block = torch.frombuffer(
                bytearray(block_view)
                if block_view.readonly
                else block_view,
                dtype=torch.uint8,
            )
            left = block[:-1].to(torch.int64)
            right = block[1:].to(torch.int64)
            counts += torch.bincount(
                left * vocab_size + right,
                minlength=vocab_size * vocab_size,
            )
            if stop >= span_end:
                break
            # 下一块从上一块最后一个字节开始，保留边界转移。
            position = stop - 1

    return counts


def _interval_length_summary(
    intervals: List[Tuple[int, int]],
) -> Dict[str, object]:
    """返回区间长度（span 数、总字节、均值与分位数）。"""
    lengths = sorted(
        end - start
        for start, end in intervals
        if end > start
    )
    if not lengths:
        return {
            "spans": 0,
            "bytes": 0,
            "mean": None,
            "median": None,
            "p90": None,
            "max": None,
        }

    def _quantile(fraction: float) -> int:
        index = int(round(fraction * (len(lengths) - 1)))
        return lengths[max(0, min(index, len(lengths) - 1))]

    return {
        "spans": len(lengths),
        "bytes": sum(lengths),
        "mean": round(sum(lengths) / len(lengths), 3),
        "median": _quantile(0.5),
        "p90": _quantile(0.9),
        "max": lengths[-1],
    }


def _top_byte_summary(
    counts: torch.Tensor,
    top_k: int = 5,
) -> List[List[object]]:
    """把字节频次转成 [[byte, share], ...]（share 保留 6 位）。"""
    total = int(counts.sum())
    if total <= 0:
        return []
    k = min(top_k, int(counts.numel()))
    values, indices = torch.topk(counts, k=k)
    return [
        [int(byte), round(float(value) / total, 6)]
        for value, byte in zip(values.tolist(), indices.tolist())
    ]


def _deletion_bias_record(
    raw: memoryview,
    train_end: int,
    excluded_spans: List[Tuple[int, int]],
) -> Optional[Dict[str, object]]:
    """
    量化训练集清洗的「删除偏差」：被删除的 train 内容与保留内容
    在字节分布、二元组分布与连续段长度上是否不同。

    清洗不是随机缺失：去重会优先删除与 val/test 重复或更早出现
    的群组，损坏字节清洗会优先删除含非法 UTF-8/NUL 的片段。
    因此删除后的训练分布是**选择性**的，清洗前后的损失不可直接
    比较，也不能把「删掉重复后指标变差/变好」全部归因于模型。
    本记录只做诊断，不改变任何删除决策；返回 None 表示没有删除。
    """
    merged = _merge_byte_intervals(excluded_spans)
    if not merged or train_end <= 0:
        return None

    kept_intervals = _subtract_byte_intervals(
        0,
        train_end,
        merged,
    )
    dropped_bytes = sum(end - start for start, end in merged)
    kept_bytes = sum(
        end - start for start, end in kept_intervals
    )

    dropped_counts = _interval_byte_counts(raw, merged)
    kept_counts = _interval_byte_counts(raw, kept_intervals)
    dropped_total = int(dropped_counts.sum())
    kept_total = int(kept_counts.sum())

    byte_js: Optional[float] = None
    if dropped_total > 0 and kept_total > 0:
        byte_js = round(
            _js_distance(
                dropped_counts.to(torch.float64) / dropped_total,
                kept_counts.to(torch.float64) / kept_total,
            ),
            6,
        )

    dropped_bigram = _interval_bigram_counts(raw, merged)
    kept_bigram = _interval_bigram_counts(
        raw,
        kept_intervals,
    )
    bigram_js: Optional[float] = None
    dropped_bigram_total = int(dropped_bigram.sum())
    kept_bigram_total = int(kept_bigram.sum())
    if dropped_bigram_total > 0 and kept_bigram_total > 0:
        bigram_js = round(
            _js_distance(
                dropped_bigram.to(torch.float64)
                / dropped_bigram_total,
                kept_bigram.to(torch.float64)
                / kept_bigram_total,
            ),
            6,
        )

    train_bytes = max(1, int(train_end))
    return {
        "schema": "smelt-isr/deletion-bias/v1",
        "dropped_bytes": dropped_bytes,
        "kept_bytes": kept_bytes,
        "train_bytes": int(train_end),
        "drop_fraction": round(dropped_bytes / train_bytes, 6),
        "kept_fraction": round(kept_bytes / train_bytes, 6),
        "excluded_span_lengths": _interval_length_summary(
            merged
        ),
        "kept_span_lengths": _interval_length_summary(
            kept_intervals
        ),
        "dropped_top_bytes": _top_byte_summary(dropped_counts),
        "kept_top_bytes": _top_byte_summary(kept_counts),
        "byte_js": byte_js,
        "bigram_js": bigram_js,
        "warn_byte_js": _AUDIT_DELETION_BIAS_WARN,
        "warn_drop_fraction": _AUDIT_DELETION_DROP_WARN,
        "interpretation": (
            "删除由内容/群组规则触发，不是随机缺失；byte_js / "
            "bigram_js 越大、drop_fraction 越高，清洗后的训练"
            "分布与原始分布差异越大。比较清洗/未清洗运行的"
            "指标前必须先核对本记录，不能把选择性删除当成同一"
            "数据分布上的方法差异"
        ),
    }


def _content_defined_chunk_scan(
    raw: memoryview,
    intervals: List[Tuple[int, int]],
    min_chunk: int,
    max_chunk: int,
) -> Dict[str, object]:
    """
    对若干内容区间做 content-defined chunking 并返回块指纹。

    每个块的有效内容指纹与它出现的绝对位置无关；共享同一
    指纹即表示两个 split 含有相同的连续字节片段。分块只读取
    原始字节，不参与任何特征计算。
    """
    chunks: Dict[bytes, List[Tuple[int, int]]] = {}
    total_chunks = 0
    total_bytes = 0
    shortest: Optional[int] = None
    longest = 0

    if min_chunk <= 0 or max_chunk < min_chunk:
        raise ValueError(
            "内容定义分块要求 0 < min_chunk <= max_chunk"
        )

    for begin, end in intervals:
        chunk_start = begin
        rolling = 0

        for position in range(begin, end):
            rolling = (
                (rolling << 1)
                + _AUDIT_CHUNK_GEAR_TABLE[raw[position]]
            ) & _AUDIT_CHUNK_UINT64_MASK
            length = position - chunk_start + 1

            if length < min_chunk:
                continue

            if (
                length >= max_chunk
                or (
                    rolling
                    & _AUDIT_CHUNK_BOUNDARY_MASK
                ) == 0
            ):
                digest = hashlib.blake2b(
                    raw[chunk_start:position + 1],
                    digest_size=16,
                ).digest()
                chunks.setdefault(digest, []).append(
                    (chunk_start, position + 1)
                )
                total_chunks += 1
                total_bytes += length
                shortest = (
                    length
                    if shortest is None
                    else min(shortest, length)
                )
                longest = max(longest, length)
                chunk_start = position + 1
                rolling = 0

        tail_length = end - chunk_start
        if tail_length >= min_chunk:
            digest = hashlib.blake2b(
                raw[chunk_start:end],
                digest_size=16,
            ).digest()
            chunks.setdefault(digest, []).append(
                (chunk_start, end)
            )
            total_chunks += 1
            total_bytes += tail_length
            shortest = (
                tail_length
                if shortest is None
                else min(shortest, tail_length)
            )
            longest = max(longest, tail_length)

    return {
        "chunks": chunks,
        "total_chunks": total_chunks,
        "total_bytes": total_bytes,
        "unique_chunks": len(chunks),
        "within_duplicates": total_chunks - len(chunks),
        "min_chunk_bytes": shortest,
        "max_chunk_bytes": longest,
    }


def _content_chunk_duplicate_audit(
    dataset: ByteDataset,
    split_names: List[str],
) -> Dict[str, object]:
    """
    跨 split 内容定义分块重复审计。

    这是窗口签名扫描的独立补充：窗口扫描受采样步长限制，
    错位复制的长片段可能没有任何一个采样窗口完全相同；分块
    指纹由局部内容决定，错位后仍会重新对齐。群组分隔符本身
    是结构字节，分块只在群组内容上进行，避免把重复的分隔符
    误报为内容泄露。
    """
    min_chunk = max(
        _AUDIT_CHUNK_MIN_BYTES,
        dataset.seq_len + 1,
    )
    max_chunk = max(
        _AUDIT_CHUNK_MAX_BYTES,
        min_chunk * 4,
    )

    excluded = set(dataset.train_excluded_spans)
    indices: Dict[str, Dict[bytes, List[Tuple[int, int]]]] = {}
    per_split: Dict[str, Dict[str, object]] = {}

    for split in split_names:
        begin, end = dataset.split_bounds[split]
        if end <= begin:
            continue

        if dataset.group_separator is None:
            intervals = _subtract_byte_intervals(
                begin,
                end,
                (
                    dataset.train_excluded_spans
                    if split == "train"
                    else []
                ),
            )
        else:
            intervals = [
                (span_start, span_end)
                for span_start, span_end in _iter_group_spans(
                    dataset._raw_buffer,
                    dataset.group_separator,
                    begin,
                    end,
                )
                if not (
                    split == "train"
                    and (span_start, span_end) in excluded
                )
            ]

        scan = _content_defined_chunk_scan(
            dataset._raw,
            intervals,
            min_chunk,
            max_chunk,
        )
        indices[split] = scan["chunks"]
        per_split[split] = {
            "content_bytes": sum(
                stop - start for start, stop in intervals
            ),
            "chunks": scan["total_chunks"],
            "unique_chunks": scan["unique_chunks"],
            "within_split_duplicates": scan[
                "within_duplicates"
            ],
            "chunk_bytes": scan["total_bytes"],
        }

    cross_split: Dict[str, object] = {}

    for left, right in (
        ("train", "val"),
        ("train", "test"),
        ("val", "test"),
    ):
        if left not in indices or right not in indices:
            continue

        left_index = indices[left]
        right_index = indices[right]
        common = left_index.keys() & right_index.keys()

        shared_chunks = 0
        shared_bytes = 0
        examples = []

        # bytes 哈希随进程随机化；按摘要排序后再取示例，保证
        # 同一归档/审计报告在不同 PYTHONHASHSEED 下逐字一致。
        for digest in sorted(common):
            left_occurrences = left_index[digest]
            right_occurrences = right_index[digest]
            matched = min(
                len(left_occurrences),
                len(right_occurrences),
            )
            length = (
                left_occurrences[0][1]
                - left_occurrences[0][0]
            )
            shared_chunks += matched
            shared_bytes += matched * length
            if len(examples) < 3:
                examples.append([
                    left_occurrences[0][0],
                    right_occurrences[0][0],
                    length,
                ])

        cross_split[f"{left}_{right}"] = {
            "shared_chunks": shared_chunks,
            "shared_bytes": shared_bytes,
            "examples": examples,
        }

    return {
        "min_chunk_bytes": min_chunk,
        "max_chunk_bytes": max_chunk,
        "per_split": per_split,
        "cross_split": cross_split,
    }


def _window_signature_scan(
    raw: memoryview,
    offset: int,
    length: int,
    window_len: int,
    max_windows: int = _AUDIT_MAX_WINDOWS,
    exclude_spans: Optional[List[Tuple[int, int]]] = None,
) -> Dict[str, object]:
    """
    对 [offset, offset + length) 内的滑动窗口做有界签名扫描。

    对每个采样窗口取 blake2b-128 摘要，用于发现跨 split 的重复
    内容（数据泄露的常见来源）与 split 内部重复。窗口数超过
    max_windows 时等间距抽样，返回实际采样规模。该扫描只做
    数据审计，不参与特征计算或模型决策。

    exclude_spans 是绝对字节区间（如训练集清洗剔除的群组）；
    与这些区间重叠的窗口不参与签名统计，避免把已经不会进入
    训练的内容继续标记为泄露。
    """
    total = length - window_len + 1

    if total <= 0:
        return {
            "sampled": 0,
            "total": 0,
            "stride": 1,
            "within_duplicates": 0,
            "skipped_excluded": 0,
            "signatures": {},
        }

    stride = max(1, math.ceil(total / max_windows))
    excluded = _merge_byte_intervals(
        list(exclude_spans or [])
    )

    signatures: Dict[bytes, List[int]] = {}
    within_duplicates = 0
    sampled = 0
    skipped_excluded = 0
    excluded_index = 0

    for start in range(0, total, stride):
        absolute_start = offset + start

        while (
            excluded_index < len(excluded)
            and excluded[excluded_index][1] <= absolute_start
        ):
            excluded_index += 1

        if (
            excluded_index < len(excluded)
            and excluded[excluded_index][0]
            < absolute_start + window_len
        ):
            skipped_excluded += 1
            continue

        digest = hashlib.blake2b(
            raw[
                absolute_start:
                absolute_start + window_len
            ],
            digest_size=16,
        ).digest()
        sampled += 1

        bucket = signatures.get(digest)
        if bucket is None:
            signatures[digest] = [start]
        else:
            within_duplicates += 1
            if len(bucket) < 4:
                bucket.append(start)

    return {
        "sampled": sampled,
        "total": total,
        "stride": stride,
        "within_duplicates": within_duplicates,
        "skipped_excluded": skipped_excluded,
        "signatures": signatures,
    }


def _leakage_scan_coverage(
    scans: Dict[str, Dict[str, object]],
) -> Dict[str, object]:
    """
    汇总窗口签名扫描的覆盖情况，暴露「零发现」的证据强度。

    「未发现跨 split 重复窗口」只对被采样到的窗口成立：窗口
    总数超过 ``max_windows`` 时等间距抽样（stride>1），未采样
    窗口之间的重复完全不在证据范围内。把 coverage 写进审计，
    读者才能区分「穷尽扫描的零发现」与「抽样扫描的零发现」；
    内容定义分块审计按局部内容指纹穷尽扫描，是错位重复的
    兜底，但同样不能替代窗口级证据的口径披露。
    """
    per_split: Dict[str, Dict[str, object]] = {}
    exhaustive = True

    for split, scan in scans.items():
        total = int(scan["total"])
        sampled = int(scan["sampled"])
        stride = int(scan["stride"])
        per_split[split] = {
            "sampled": sampled,
            "total": total,
            "stride": stride,
            "coverage": (
                round(sampled / total, 6) if total > 0 else None
            ),
        }
        if total > 0 and stride > 1:
            exhaustive = False

    residual_risk: Optional[str] = None
    if not exhaustive:
        worst = max(
            (
                (int(info["stride"]), split)
                for split, info in per_split.items()
                if int(info["total"]) > 0
            ),
            default=(1, ""),
        )
        split_text = ", ".join(
            f"{split}:{info['sampled']}/{info['total']}"
            + (
                f"(stride={info['stride']})"
                if int(info["stride"]) > 1
                else ""
            )
            for split, info in per_split.items()
            if int(info["total"]) > 0
        )
        residual_risk = (
            f"窗口签名扫描未穷尽（最大 stride={worst[0]}；"
            f"{split_text}）：「未发现跨 split 重复窗口」"
            "只覆盖等间距采样的窗口，不等于「不存在重复」；"
            "内容定义分块审计为穷尽扫描，可兜底检出错位重复，"
            "但不能据此主张窗口级零泄露"
        )

    return {
        "exhaustive": exhaustive,
        "per_split": per_split,
        "residual_risk": residual_risk,
    }


def _scan_text_integrity(
    raw: memoryview,
    offset: int,
    length: int,
    chunk: int = 1 << 20,
    final: bool = False,
    warmup: bool = True,
) -> Dict[str, int]:
    """
    扫描一个 split 的文本完整性（数据清洗的标签噪声检查）。

    字节级语言模型的标签就是原始字节，损坏字节等价于标签
    噪声，必须在训练前可见：

    - utf8_replacements：无法按 UTF-8 解码的字节数。这里不用
      ``errors="replace"`` 统计 U+FFFD，因为语料本身可能合法地
      包含字面替换字符 U+FFFD；用 surrogateescape 把每个非法
      字节映射为 U+DC80..U+DCFF 代理码点，既能与
      ``_invalid_utf8_nul_spans`` 的清洗口径逐字节一致，也不会
      把合法文本误判为标签噪声；
    - nul_bytes：NUL（0x00）字节数量，文本语料中出现即疑似
      二进制污染或文件拼接错误。

    分块解码；只做诊断，不修改任何数据。

    切分边界处不制造假阳性：切分点之前最多 3 个字节先喂给
    解码器做状态预热（多字节 UTF-8 字符可以横跨 split 边界，
    文件整体仍然完全合法）；``final`` 只在扫描的是文件真正
    的末尾时为 True，否则末尾不完整的多字节序列留给下一个
    split 续接（其解码计数落在后续扫描里）。

    ``warmup=False`` 供逐群组扫描使用：每个群组按独立文本
    解码，不从前一段（分隔符）借状态。
    """
    decoder = codecs.getincrementaldecoder("utf-8")(
        errors="surrogateescape"
    )

    # 预热：把解码器带到「从 offset 前几个字节开始」的状态。
    # 预热输出（可能包含边界前的字符或无效序列）全部丢弃，
    # 不计入任何统计；但解码器可能缓冲着 offset 之前未完成的
    # 多字节序列。若后续字节把它判为非法，surrogateescape 会
    # 在第一个当前块里吐出属于 offset 之前的代理码点。必须跳过
    # 这些前缀代理码点，否则上一段末尾的坏字节会被记到本段
    #（测试集标签完整性门会因此拒绝一个字节干净的 test）。
    pre_offset_pending = 0
    if warmup and offset > 0:
        decoder.decode(
            bytes(raw[max(0, offset - 3):offset]),
            final=False,
        )
        pre_offset_pending = len(decoder.getstate()[0])

    replacements = 0
    nul_bytes = 0
    position = offset
    end = offset + length

    while position < end:
        stop = min(position + chunk, end)
        block = bytes(raw[position:stop])
        text = decoder.decode(
            block,
            final=final and stop >= end,
        )
        for character in text:
            codepoint = ord(character)
            if 0xDC80 <= codepoint <= 0xDCFF:
                # 前 pre_offset_pending 个代理码点对应 offset
                # 之前的未完成序列，不属于本段。一旦出现普通
                # 字符，说明之前的缓冲已被完整解码，后续代理
                # 码点都属于本段。
                if pre_offset_pending > 0:
                    pre_offset_pending -= 1
                    continue
                replacements += 1
            else:
                pre_offset_pending = 0
                if character == "\x00":
                    nul_bytes += 1
        position = stop

    return {
        "utf8_replacements": replacements,
        "nul_bytes": nul_bytes,
    }


def _invalid_utf8_nul_spans(
    raw: memoryview,
    offset: int,
    length: int,
    final: bool,
    chunk: int = 1 << 20,
) -> List[Tuple[int, int, str]]:
    """
    返回 [offset, offset+length) 内非法 UTF-8 字节与 NUL 字节的
    精确区间。

    使用 ``errors="surrogateescape"`` 的增量解码器：每个非法
    字节映射为一个 U+DC80..U+DCFF 代理码点，再把解码结果逐字符
    重新编码回字节，就能把码点位置映射回原始字节偏移。多字节
    合法字符跨分块时由解码器缓冲，偏移通过 ``pending_start``
    续接；``final=False`` 时末尾不完整的多字节序列留给下一个
    split，不会把合法字符的切分点误判为损坏。
    """
    decoder = codecs.getincrementaldecoder("utf-8")(
        errors="surrogateescape"
    )

    # 预热：offset 可能落在一个合法的多字节字符中间（split 边界
    # 不保证在字符边界上）。先把 offset 前最多 3 个字节喂给
    # 解码器，并记录它缓冲了多少「属于 offset 之前」的字节。
    # 之后解码出的第一个字符若消费了这些前缀字节，只能把其中
    # 落在 [offset, ...) 的实际字节数推进 cursor，不能把整个
    # 字符都算到本段（否则跨边界的合法字符会被误报为损坏）。
    pre_offset_pending = 0
    if offset > 0:
        decoder.decode(
            bytes(raw[max(0, offset - 3):offset]),
            final=False,
        )
        pre_offset_pending = len(decoder.getstate()[0])

    spans: List[Tuple[int, int, str]] = []
    position = offset
    end = offset + length
    cursor = offset
    skip_prefix = pre_offset_pending

    while position < end:
        stop = min(position + chunk, end)
        block = bytes(raw[position:stop])
        text = decoder.decode(
            block,
            final=final and stop >= end,
        )

        for character in text:
            encoded = character.encode(
                "utf-8",
                "surrogateescape",
            )
            size = len(encoded)
            codepoint = ord(character)

            if (
                size == 1
                and 0xDC80 <= codepoint <= 0xDCFF
            ):
                # 前缀遗留的非法字节可能先于本段被吐出；只跳过
                # 属于 offset 之前的那几个代理码点。
                if skip_prefix > 0:
                    skip_prefix -= 1
                    continue
                spans.append(
                    (cursor, cursor + 1, "invalid_utf8")
                )
            elif size > skip_prefix and skip_prefix > 0:
                # 合法的跨边界字符：只把 offset 之后的字节数
                # 推进 cursor，跳过整个字符的统计。
                cursor += size - skip_prefix
                skip_prefix = 0
                continue
            elif character == "\x00":
                spans.append((cursor, cursor + 1, "nul"))

            if skip_prefix > 0:
                # 理论上只有前缀遗留的非法字节会走到这里；安全
                # 起见不把尚未消费完的前缀算进本段。
                skip_prefix -= 1
                continue
            cursor += size

        position = stop

    return spans


def _plan_train_corruption_cleaning(
    raw: bytearray,
    separator: bytes,
    train_end: int,
    already_excluded: List[Tuple[int, int]],
) -> Tuple[List[Tuple[int, int]], Dict[str, object]]:
    """
    规划训练集标签噪声清洗：只从 train 中剔除「整组包含非法
    UTF-8 或 NUL 字节」的群组，绝不改动 val/test。

    字节级语言模型的监督位就是原始字节，无法解码的字节或 NUL
    就是标签噪声。这里整组剔除而不是修补字节：修补会凭空发明
    标签，整组剔除则能保证该群组不会以任何窗口形式进入训练。
    判定口径与 audit_data_splits 的文本完整性扫描一致（逐群组
    独立解码，不把用户配置的分隔符计入损坏）。已经被去重清洗
    剔除的群组不会重复扫描/统计。
    """
    excluded_set = set(already_excluded)
    excluded: List[Tuple[int, int]] = []
    stats: Dict[str, object] = {
        "enabled": True,
        "policy": (
            "drop train groups containing invalid UTF-8 or NUL "
            "bytes; val/test untouched"
        ),
        "groups_total": 0,
        "groups_scanned": 0,
        "groups_already_excluded": 0,
        "groups_dropped": 0,
        "dropped_bytes": 0,
        "groups_with_invalid_utf8": 0,
        "groups_with_nul": 0,
        "invalid_utf8_replacements": 0,
        "nul_bytes": 0,
        "examples": [],
    }

    for span_start, span_end in _iter_group_spans(
        raw,
        separator,
        0,
        train_end,
    ):
        stats["groups_total"] += 1

        if (span_start, span_end) in excluded_set:
            stats["groups_already_excluded"] += 1
            continue

        stats["groups_scanned"] += 1
        integrity = _scan_text_integrity(
            memoryview(raw),
            span_start,
            span_end - span_start,
            final=True,
            warmup=False,
        )

        if (
            integrity["utf8_replacements"] <= 0
            and integrity["nul_bytes"] <= 0
        ):
            continue

        if integrity["utf8_replacements"] > 0:
            stats["groups_with_invalid_utf8"] += 1
        if integrity["nul_bytes"] > 0:
            stats["groups_with_nul"] += 1

        stats["invalid_utf8_replacements"] += integrity[
            "utf8_replacements"
        ]
        stats["nul_bytes"] += integrity["nul_bytes"]
        stats["groups_dropped"] += 1
        stats["dropped_bytes"] += span_end - span_start
        excluded.append((span_start, span_end))
        if len(stats["examples"]) < 5:
            stats["examples"].append([
                span_start,
                span_end,
                integrity["utf8_replacements"],
                integrity["nul_bytes"],
            ])

    stats["post_clean_train_bytes"] = (
        train_end
        - sum(
            end - start
            for start, end in _merge_byte_intervals(
                list(already_excluded) + excluded
            )
        )
    )
    return excluded, stats


def _plan_train_corruption_cleaning_bytes(
    raw: bytearray,
    train_end: int,
) -> Tuple[List[Tuple[int, int]], Dict[str, object]]:
    """
    规划无群组连续字节流的训练集标签噪声清洗：只从 train 中
    剔除非法 UTF-8 字节与 NUL 字节本身，绝不修补字节，也绝不
    改动 val/test。

    与群组级清洗不同，这里不需要用户提供分隔符：损坏字节的
    位置由解码器直接定位。被剔除的字节不进入训练窗口、unigram/
    n-gram 计数或分布审计；仍保留的合法字节继续参与训练。
    """
    # 按整个文件解码，再把落在 train 内的坏字节归入清洗。只
    # 扫描到 train_end 且 final=False 会漏掉「train 末尾的非法
    # lead byte」：它需要后继 val/test 字节才能判定是否非法。
    # 全局扫描还能保留跨 split 的合法多字节字符，不会误删。
    tagged = [
        (start, end, kind)
        for start, end, kind in _invalid_utf8_nul_spans(
            memoryview(raw),
            0,
            len(raw),
            final=True,
        )
        if start < train_end
    ]

    invalid_bytes = sum(
        1
        for _, _, kind in tagged
        if kind == "invalid_utf8"
    )
    nul_bytes = sum(
        1
        for _, _, kind in tagged
        if kind == "nul"
    )
    excluded = _merge_byte_intervals(
        [(start, end) for start, end, _ in tagged]
    )

    stats: Dict[str, object] = {
        "enabled": True,
        "scope": "bytes",
        "policy": (
            "drop train bytes that are invalid UTF-8 or NUL; "
            "val/test untouched"
        ),
        "invalid_utf8_bytes": invalid_bytes,
        "nul_bytes": nul_bytes,
        "excluded_spans": len(excluded),
        "dropped_bytes": sum(
            end - start for start, end in excluded
        ),
        "examples": [
            [start, end]
            for start, end in excluded[:5]
        ],
    }
    stats["post_clean_train_bytes"] = (
        train_end - int(stats["dropped_bytes"])
    )
    return excluded, stats


def _group_top_byte_share(
    raw: memoryview,
    start: int,
    end: int,
) -> Tuple[int, float]:
    """返回群组内最高频字节及其占比（空群组返回 (0, 0.0)）。"""
    length = end - start
    if length <= 0:
        return 0, 0.0

    # ``torch.frombuffer`` 不能安全承载只读缓冲区：PyTorch 会
    # 发出 UserWarning（``-W error`` 下直接失败），因为它无法
    # 阻止写入。这里用可写的 bytearray 复制切片，代价与原来的
    # ``bytes(...)`` 复制相同。
    content = bytearray(raw[start:end])
    counts = torch.bincount(
        torch.frombuffer(content, dtype=torch.uint8),
        minlength=256,
    )
    top_count = int(counts.max())
    return int(counts.argmax()), top_count / length


def _plan_train_degenerate_cleaning(
    raw: bytearray,
    separator: bytes,
    train_end: int,
    already_excluded: List[Tuple[int, int]],
) -> Tuple[List[Tuple[int, int]], Dict[str, object]]:
    """
    规划训练集异常值清洗：只从 train 中整组剔除「长度达到
    阈值且单一字节占比极高」的低信息/退化群组，绝不改动
    val/test。

    判定只使用群组自身内容（没有跨 split 统计量），阈值固定
    并记录在审计中；已经被去重/标签噪声清洗剔除的群组不重复
    统计。
    """
    excluded_set = set(already_excluded)
    excluded: List[Tuple[int, int]] = []
    stats: Dict[str, object] = {
        "enabled": True,
        "policy": (
            "drop train groups with length >= "
            f"{_AUDIT_DEGENERATE_GROUP_MIN_BYTES} and top-byte "
            f"share >= {_AUDIT_DEGENERATE_GROUP_TOP_SHARE}; "
            "val/test untouched"
        ),
        "min_bytes": _AUDIT_DEGENERATE_GROUP_MIN_BYTES,
        "top_share_threshold": (
            _AUDIT_DEGENERATE_GROUP_TOP_SHARE
        ),
        "groups_total": 0,
        "groups_scanned": 0,
        "groups_already_excluded": 0,
        "groups_dropped": 0,
        "dropped_bytes": 0,
        "max_top_byte_share": 0.0,
        "examples": [],
    }

    for span_start, span_end in _iter_group_spans(
        raw,
        separator,
        0,
        train_end,
    ):
        stats["groups_total"] += 1

        if (span_start, span_end) in excluded_set:
            stats["groups_already_excluded"] += 1
            continue

        stats["groups_scanned"] += 1
        top_byte, top_share = _group_top_byte_share(
            memoryview(raw),
            span_start,
            span_end,
        )
        stats["max_top_byte_share"] = max(
            float(stats["max_top_byte_share"]),
            top_share,
        )

        if (
            span_end - span_start
            < _AUDIT_DEGENERATE_GROUP_MIN_BYTES
            or top_share < _AUDIT_DEGENERATE_GROUP_TOP_SHARE
        ):
            continue

        stats["groups_dropped"] += 1
        stats["dropped_bytes"] += span_end - span_start
        excluded.append((span_start, span_end))
        if len(stats["examples"]) < 5:
            stats["examples"].append([
                span_start,
                span_end,
                top_byte,
                round(top_share, 6),
            ])

    stats["post_clean_train_bytes"] = (
        train_end
        - sum(
            end - start
            for start, end in _merge_byte_intervals(
                list(already_excluded) + excluded
            )
        )
    )
    return excluded, stats


def _degenerate_run_spans(
    raw: memoryview,
    begin: int,
    end: int,
    min_bytes: int,
) -> List[Tuple[int, int, int]]:
    """返回 [begin, end) 内长度 >= min_bytes 的同字节连续段。"""
    spans: List[Tuple[int, int, int]] = []
    position = begin

    while position < end:
        value = raw[position]
        stop = position + 1
        while stop < end and raw[stop] == value:
            stop += 1
        if stop - position >= min_bytes:
            spans.append((position, stop, int(value)))
        position = stop

    return spans


def _plan_train_degenerate_run_cleaning(
    raw: bytearray,
    train_end: int,
    min_bytes: int,
    already_excluded: List[Tuple[int, int]],
) -> Tuple[List[Tuple[int, int]], Dict[str, object]]:
    """
    规划无群组连续字节流的训练集异常值清洗：只从 train 剔除
    长度达到阈值的单一字节连续段（填充、重复字符、错误拼接的
    常见形态），绝不修补字节，也绝不动 val/test。

    与群组版异常值清洗同一防御目标；连续流没有群组边界，
    只能按退化段本身剔除。与已经被其他清洗剔除的区间重叠的
    段不重复统计，避免组合清洗区间重叠。
    """
    merged_excluded = _merge_byte_intervals(
        list(already_excluded)
    )
    excluded: List[Tuple[int, int]] = []
    stats: Dict[str, object] = {
        "enabled": True,
        "scope": "bytes",
        "policy": (
            f"drop train byte runs of one value with length "
            f">= {min_bytes}; val/test untouched"
        ),
        "min_bytes": min_bytes,
        "runs_dropped": 0,
        "dropped_bytes": 0,
        "max_run_bytes": 0,
        "examples": [],
    }

    for start, end, value in _degenerate_run_spans(
        memoryview(raw),
        0,
        train_end,
        min_bytes,
    ):
        if any(
            start < excluded_end and end > excluded_start
            for excluded_start, excluded_end in merged_excluded
        ):
            continue

        stats["runs_dropped"] += 1
        stats["dropped_bytes"] += end - start
        stats["max_run_bytes"] = max(
            int(stats["max_run_bytes"]),
            end - start,
        )
        excluded.append((start, end))
        if len(stats["examples"]) < 5:
            stats["examples"].append([
                start,
                end,
                value,
            ])

    stats["post_clean_train_bytes"] = (
        train_end
        - sum(
            end - start
            for start, end in _merge_byte_intervals(
                list(already_excluded) + excluded
            )
        )
    )
    return excluded, stats


def _train_degenerate_run_audit(
    dataset: ByteDataset,
) -> Optional[Dict[str, object]]:
    """
    无群组连续字节流的训练集异常值审计：统计长度达到阈值的
    同字节连续段。只看 train，并跳过已被清洗剔除的区间；
    val/test 不参与统计。清洗需要显式
    --drop-train-degenerate-runs。
    """
    if dataset.group_separator is not None:
        return None

    begin, end = dataset.split_bounds["train"]
    intervals = _subtract_byte_intervals(
        begin,
        end,
        dataset.train_excluded_spans,
    )
    stats: Dict[str, object] = {
        "min_bytes": _AUDIT_DEGENERATE_RUN_MIN_BYTES,
        "runs": 0,
        "degenerate_bytes": 0,
        "max_run_bytes": 0,
        "examples": [],
    }

    for interval_begin, interval_end in intervals:
        for start, stop, value in _degenerate_run_spans(
            dataset._raw,
            interval_begin,
            interval_end,
            _AUDIT_DEGENERATE_RUN_MIN_BYTES,
        ):
            stats["runs"] += 1
            stats["degenerate_bytes"] += stop - start
            stats["max_run_bytes"] = max(
                int(stats["max_run_bytes"]),
                stop - start,
            )
            if len(stats["examples"]) < 5:
                stats["examples"].append([
                    start,
                    stop,
                    value,
                ])

    return stats


def _plan_train_shared_chunk_cleaning(
    raw: bytearray,
    separator: bytes,
    train_end: int,
    eval_ranges: Dict[str, Tuple[int, int]],
    min_chunk: int,
    max_chunk: int,
    already_excluded: List[Tuple[int, int]],
) -> Tuple[List[Tuple[int, int]], Dict[str, object]]:
    """
    规划训练集群组级「跨 split 近似重复」清洗：只从 train 中
    整组剔除包含与 val/test 共享的内容定义块的群组，绝不改动
    val/test。

    精确群组指纹只能抓内容完全相同的文档；同一段文字被包在
    更长的训练群组里（或整体错位复制）时指纹不同，但共享块
    仍会把评估内容泄露给训练。这里用与
    ``_content_chunk_duplicate_audit`` 完全相同的分块口径：
    只要训练群组内出现一个与 val/test 群组相同、长度至少为
    一个完整窗口的连续块，就整组剔除。整组剔除而不是删单个
    块，避免在连续字节流中制造新的跨群组邻接标签。
    """
    eval_chunks: set = set()
    eval_groups = 0

    for begin, end in eval_ranges.values():
        if end <= begin:
            continue
        for span_start, span_end in _iter_group_spans(
            raw,
            separator,
            begin,
            end,
        ):
            scan = _content_defined_chunk_scan(
                memoryview(raw),
                [(span_start, span_end)],
                min_chunk,
                max_chunk,
            )
            eval_chunks.update(scan["chunks"].keys())
            eval_groups += 1

    excluded_set = set(already_excluded)
    excluded: List[Tuple[int, int]] = []
    stats: Dict[str, object] = {
        "enabled": True,
        "policy": (
            "drop train groups sharing content-defined chunks "
            "with val/test; val/test untouched"
        ),
        "min_chunk_bytes": min_chunk,
        "max_chunk_bytes": max_chunk,
        "eval_groups": eval_groups,
        "eval_chunks": len(eval_chunks),
        "groups_total": 0,
        "groups_scanned": 0,
        "groups_already_excluded": 0,
        "groups_dropped": 0,
        "dropped_bytes": 0,
        "shared_chunks": 0,
        "examples": [],
    }

    for span_start, span_end in _iter_group_spans(
        raw,
        separator,
        0,
        train_end,
    ):
        stats["groups_total"] += 1

        if (span_start, span_end) in excluded_set:
            stats["groups_already_excluded"] += 1
            continue

        stats["groups_scanned"] += 1
        scan = _content_defined_chunk_scan(
            memoryview(raw),
            [(span_start, span_end)],
            min_chunk,
            max_chunk,
        )
        common = scan["chunks"].keys() & eval_chunks
        if not common:
            continue

        stats["groups_dropped"] += 1
        stats["dropped_bytes"] += span_end - span_start
        stats["shared_chunks"] += len(common)
        excluded.append((span_start, span_end))
        if len(stats["examples"]) < 5:
            stats["examples"].append([
                span_start,
                span_end,
                len(common),
            ])

    stats["post_clean_train_bytes"] = (
        train_end
        - sum(
            end - start
            for start, end in _merge_byte_intervals(
                list(already_excluded) + excluded
            )
        )
    )
    return excluded, stats


def _near_duplicate_shingle_hashes(
    raw,
    start: int,
    end: int,
    shingle_bytes: int,
):
    """
    逐个产出 [start, end) 内长度为 shingle_bytes 的字节 shingle
    的 64 位滚动多项式哈希。

    与逐 shingle 调用 blake2b 相比，滚动哈希把「提取全部 shingle」
    的成本降到线性；Jaccard 的精确复核仍在完整 shingle 哈希集合
    上做。64 位碰撞概率很低，但审计记录哈希口径，不把它说成
    逐字节完全相等。
    """
    length = end - start
    if length < shingle_bytes:
        return

    base = _NEAR_DUP_HASH_BASE
    mask = _NEAR_DUP_HASH_MASK
    # base^(shingle_bytes-1) mod 2^64：滚出最左字节时减去它的贡献。
    base_power = pow(base, shingle_bytes - 1, 1 << 64)

    value = 0
    for position in range(start, start + shingle_bytes):
        value = ((value * base) + raw[position]) & mask
    yield value

    for position in range(start + shingle_bytes, end):
        value = (
            (
                value
                - raw[position - shingle_bytes] * base_power
            )
            * base
            + raw[position]
        ) & mask
        yield value


def _near_duplicate_bottom_k(
    hashes,
    sketch_size: int,
) -> Tuple[int, ...]:
    """
    取 shingle 哈希的 bottom-k（最小的 k 个值），返回升序签名。

    bottom-k 是 Jaccard 的 MinHash 家族草图：两个高度重合的集合
    会共享大量最小哈希值，因此可把每个签名值当作倒排键生成候选。
    草图只用于候选生成，是否删除由完整 shingle 集合的精确 Jaccard
    决定。
    """
    heap: List[int] = []
    present: set = set()
    for value in hashes:
        # bottom-k 是 shingle **集合**的最小哈希，不是多重集：
        # 高度重复的内容（同一行重复很多次）会产生大量相同
        # shingle 哈希；若不去重，草图会被同一个值占满，丢掉
        # 真正参与 Jaccard 的其他值，近重复候选因此漏检。
        if value in present:
            continue
        if len(heap) < sketch_size:
            heapq.heappush(heap, -value)
            present.add(value)
        elif value < -heap[0]:
            removed = -heapq.heapreplace(heap, -value)
            present.discard(removed)
            present.add(value)
    return tuple(sorted(-item for item in heap))


def _near_duplicate_shingle_set(
    raw,
    start: int,
    end: int,
    shingle_bytes: int,
) -> set:
    """返回 [start, end) 的完整 shingle 哈希集合（精确复核用）。"""
    return set(
        _near_duplicate_shingle_hashes(
            raw,
            start,
            end,
            shingle_bytes,
        )
    )


def _near_duplicate_exact_values(
    raw,
    start: int,
    end: int,
    shingle_bytes: int,
) -> Tuple[object, int]:
    """
    返回 [start, end) 的完整 shingle 集合与近似内存占用。

    NumPy 可用时用去重后的 uint64 数组（8 字节/值）并配合
    ``intersect1d`` 做精确交集；没有 NumPy 时退回 Python set。
    与训练集近重复审计的精确复核口径一致，只是把缓存管理留给
    调用方。
    """
    count = max(0, end - start - shingle_bytes + 1)
    if np is not None:
        values = np.unique(
            np.fromiter(
                _near_duplicate_shingle_hashes(
                    raw,
                    start,
                    end,
                    shingle_bytes,
                ),
                dtype=np.uint64,
                count=count,
            )
        )
        return values, int(values.nbytes)

    values = _near_duplicate_shingle_set(
        raw,
        start,
        end,
        shingle_bytes,
    )
    # Python set 中每个 int 对象加哈希槽远大于 8 字节。
    return values, len(values) * 48 + max(1, end - start)


def _near_duplicate_threshold_or_default(
    value: object,
) -> float:
    """把存档/协议里的阈值转成有限 (0,1] 浮点，损坏值回退默认。"""
    try:
        number = float(value)
    except (TypeError, ValueError, OverflowError):
        return _NEAR_DUP_DEFAULT_THRESHOLD
    if not math.isfinite(number) or not 0.0 < number <= 1.0:
        return _NEAR_DUP_DEFAULT_THRESHOLD
    return number


def _near_duplicate_shingle_or_default(
    value: object,
) -> int:
    """把存档/协议里的 shingle 长度转成合法整数，损坏值回退默认。"""
    if (
        isinstance(value, int)
        and not isinstance(value, bool)
        and 1 <= value <= _NEAR_DUP_MAX_SHINGLE_BYTES
    ):
        return value
    return _NEAR_DUP_DEFAULT_SHINGLE_BYTES


def _plan_train_near_duplicate_cleaning(
    raw: bytearray,
    separator: bytes,
    train_end: int,
    eval_ranges: Dict[str, Tuple[int, int]],
    already_excluded: List[Tuple[int, int]],
    threshold: float = _NEAR_DUP_DEFAULT_THRESHOLD,
    shingle_bytes: int = _NEAR_DUP_DEFAULT_SHINGLE_BYTES,
    sketch_size: int = _NEAR_DUP_DEFAULT_SKETCH_SIZE,
    apply_cleaning: bool = True,
) -> Tuple[List[Tuple[int, int]], Dict[str, object]]:
    """
    扫描训练集群组的近重复（默认只对照 val，绝不改动 val/test）。

    流程：
    1. 对评估群组与训练群组分别计算字节 k-shingle 的 bottom-k 草图；
    2. 用草图哈希建倒排索引，为每个训练群组找候选；
    3. 对候选计算完整 shingle 集合的精确 Jaccard；
    4. 达到阈值时整组标记/删除（``apply_cleaning``）。

    ``apply_cleaning=False`` 是只读审计：不返回删除区间，但报告
    ``groups_flagged``、每个被标记群组的最佳匹配与 Jaccard。默认
    只对照 val；只有显式把 test 放进 ``eval_ranges`` 才会读取 test
    内容决定训练集删除，调用方负责把该事实写入清洗记录。

    近重复是内容级「相似」而不是逐字节相同：阈值是研究者事先声明
    的相似度门槛，报告同时给出实际 Jaccard 与匹配对象，避免把
    「被标记」当成确定泄露。群组过短（不足一个 shingle）或过大
    （完整集合内存不可控）时显式跳过并计数。
    """
    try:
        threshold = float(threshold)
    except (TypeError, ValueError, OverflowError) as error:
        raise ValueError("near-duplicate threshold 必须是数值") from error
    if not math.isfinite(threshold) or not 0.0 < threshold <= 1.0:
        raise ValueError(
            "near-duplicate threshold 必须落在 (0, 1]"
        )
    if (
        not isinstance(shingle_bytes, int)
        or isinstance(shingle_bytes, bool)
        or not 1 <= shingle_bytes <= _NEAR_DUP_MAX_SHINGLE_BYTES
    ):
        raise ValueError(
            "near-duplicate shingle_bytes 必须是 1.."
            f"{_NEAR_DUP_MAX_SHINGLE_BYTES} 的整数"
        )
    if (
        not isinstance(sketch_size, int)
        or isinstance(sketch_size, bool)
        or not 8 <= sketch_size <= _NEAR_DUP_MAX_SKETCH_SIZE
    ):
        raise ValueError(
            "near-duplicate sketch_size 必须是 8.."
            f"{_NEAR_DUP_MAX_SKETCH_SIZE} 的整数"
        )
    if separator is None or len(separator) == 0:
        raise ValueError(
            "near-duplicate 扫描需要非空群组分隔符"
        )

    excluded_set = set(
        (int(start), int(end))
        for start, end in already_excluded
    )
    eval_order = [
        split
        for split in ("val", "test")
        if split in eval_ranges
    ]
    eval_order.extend(
        sorted(
            split
            for split in eval_ranges
            if split not in ("val", "test")
        )
    )

    eval_groups: List[Tuple[str, int, int]] = []
    eval_index: Dict[int, List[int]] = {}
    eval_too_short = 0
    eval_too_large = 0

    for split in eval_order:
        begin, end = eval_ranges[split]
        if end <= begin:
            continue
        for span_start, span_end in _iter_group_spans(
            raw,
            separator,
            begin,
            end,
        ):
            length = span_end - span_start
            if length > _NEAR_DUP_MAX_GROUP_BYTES:
                eval_too_large += 1
                continue
            sketch = _near_duplicate_bottom_k(
                _near_duplicate_shingle_hashes(
                    raw,
                    span_start,
                    span_end,
                    shingle_bytes,
                ),
                sketch_size,
            )
            if not sketch:
                eval_too_short += 1
                continue

            group_index = len(eval_groups)
            eval_groups.append(
                (split, span_start, span_end)
            )
            for value in sketch:
                eval_index.setdefault(value, []).append(
                    group_index
                )

    # 精确复核缓存：按 (start, end) 复用完整 shingle 集合。
    # NumPy 可用时用 uint64 数组（每个 shingle 8 字节）并调用
    # intersect1d；没有 NumPy 时退回 Python set。缓存按近似
    # 占用限界，避免大语料把内存吃满。
    exact_cache: "OrderedDict[Tuple[int, int], Tuple[object, int]]" = (
        OrderedDict()
    )
    exact_cache_bytes = 0

    def _full_shingle_values(
        span: Tuple[int, int],
    ):
        nonlocal exact_cache_bytes
        cached = exact_cache.get(span)
        if cached is not None:
            exact_cache.move_to_end(span)
            return cached[0]

        count = max(
            0,
            span[1] - span[0] - shingle_bytes + 1,
        )
        if np is not None:
            values = np.unique(
                np.fromiter(
                    _near_duplicate_shingle_hashes(
                        raw,
                        span[0],
                        span[1],
                        shingle_bytes,
                    ),
                    dtype=np.uint64,
                    count=count,
                )
            )
            size = int(values.nbytes)
        else:
            value_set = _near_duplicate_shingle_set(
                raw,
                span[0],
                span[1],
                shingle_bytes,
            )
            values = value_set
            # Python set 中每个 int 对象加哈希槽远大于 8 字节。
            size = len(value_set) * 48 + (
                span[1] - span[0]
            )

        while (
            exact_cache
            and exact_cache_bytes + size
            > _NEAR_DUP_EXACT_CACHE_BYTES
        ):
            _, (_, old_size) = exact_cache.popitem(
                last=False
            )
            exact_cache_bytes -= old_size
        exact_cache[span] = (values, size)
        exact_cache_bytes += size
        return values

    def _jaccard(
        left: Tuple[int, int],
        right: Tuple[int, int],
    ) -> float:
        left_values = _full_shingle_values(left)
        right_values = _full_shingle_values(right)
        if np is not None:
            if left_values.size == 0 or right_values.size == 0:
                return 0.0
            intersection = int(
                np.intersect1d(
                    left_values,
                    right_values,
                    assume_unique=True,
                ).size
            )
            union = (
                int(left_values.size)
                + int(right_values.size)
                - intersection
            )
        else:
            if not left_values or not right_values:
                return 0.0
            intersection = len(
                left_values & right_values
            )
            union = (
                len(left_values)
                + len(right_values)
                - intersection
            )
        if union <= 0:
            return 0.0
        return intersection / union

    split_rank = {"val": 0, "test": 1, "train": 2}
    prior_spans: List[Tuple[int, int]] = []
    prior_index: Dict[int, List[int]] = {}

    stats: Dict[str, object] = {
        "enabled": True,
        "policy": (
            "drop train groups with shingle Jaccard >= threshold "
            "against val/test or earlier train; val/test untouched"
            if apply_cleaning
            else "audit train groups with shingle Jaccard >= threshold "
            "against val/test or earlier train; read-only"
        ),
        "mode": "clean" if apply_cleaning else "audit",
        "threshold": round(threshold, 6),
        "shingle_bytes": shingle_bytes,
        "sketch_size": sketch_size,
        "similarity": "jaccard_of_byte_shingle_sets",
        "shingle_hash": "rolling_polynomial_64bit",
        "exact_verification": True,
        "max_group_bytes": _NEAR_DUP_MAX_GROUP_BYTES,
        "eval_splits": list(eval_order),
        "eval_groups": len(eval_groups),
        "eval_groups_too_short": eval_too_short,
        "eval_groups_too_large": eval_too_large,
        "groups_total": 0,
        "groups_scanned": 0,
        "groups_already_excluded": 0,
        "groups_too_short": 0,
        "groups_too_large": 0,
        "groups_flagged": 0,
        "groups_dropped": 0,
        "flagged_bytes": 0,
        "dropped_bytes": 0,
        "flagged_duplicate_of": {
            "val": 0,
            "test": 0,
            "train": 0,
        },
        "candidate_pairs": 0,
        "examples": [],
    }

    flagged_spans: List[Tuple[int, int]] = []

    for span_start, span_end in _iter_group_spans(
        raw,
        separator,
        0,
        train_end,
    ):
        stats["groups_total"] += 1
        span = (span_start, span_end)

        if span in excluded_set:
            stats["groups_already_excluded"] += 1
            continue

        length = span_end - span_start
        if length > _NEAR_DUP_MAX_GROUP_BYTES:
            stats["groups_too_large"] += 1
            continue

        sketch = _near_duplicate_bottom_k(
            _near_duplicate_shingle_hashes(
                raw,
                span_start,
                span_end,
                shingle_bytes,
            ),
            sketch_size,
        )
        if not sketch:
            stats["groups_too_short"] += 1
            continue

        stats["groups_scanned"] += 1

        candidates = set()
        for value in sketch:
            for index in eval_index.get(value, ()):
                candidates.add(("eval", index))
            for index in prior_index.get(value, ()):
                candidates.add(("train", index))

        stats["candidate_pairs"] += len(candidates)

        best_key = None
        best_jaccard = 0.0
        best_reason: Optional[str] = None
        best_other: Optional[Tuple[int, int]] = None

        # 候选按来源与位置排序，保证同一数据/参数下报告与
        # 示例在不同 PYTHONHASHSEED 下完全一致。
        for origin, index in sorted(candidates):
            if origin == "eval":
                reason, other_start, other_end = eval_groups[
                    index
                ]
            else:
                reason = "train"
                other_start, other_end = prior_spans[index]
            other = (other_start, other_end)
            if other == span:
                continue

            jaccard = _jaccard(span, other)
            if jaccard + 1e-12 < threshold:
                continue

            key = (
                -jaccard,
                split_rank.get(reason, 3),
                other_start,
                other_end,
            )
            if best_key is None or key < best_key:
                best_key = key
                best_jaccard = jaccard
                best_reason = reason
                best_other = other

        if best_reason is not None:
            stats["groups_flagged"] += 1
            stats["flagged_bytes"] += length
            stats["flagged_duplicate_of"][best_reason] = (
                stats["flagged_duplicate_of"].get(best_reason, 0)
                + 1
            )
            flagged_spans.append(span)
            if len(stats["examples"]) < 5:
                stats["examples"].append([
                    span_start,
                    span_end,
                    best_reason,
                    round(best_jaccard, 6),
                    best_other[0],
                    best_other[1],
                ])

            if apply_cleaning:
                stats["groups_dropped"] += 1
                stats["dropped_bytes"] += length
            # 被标记的群组（无论删除还是只读审计）不能再作为
            # 后续群组的「更早 train」匹配对象：只保留第一个
            # 出现的群组，避免重复簇内产生 O(n^2) 候选。
            continue

        # 未标记的群组进入 prior 索引；只保留第一个出现的
        # 群组，避免重复簇内候选爆炸。
        prior_position = len(prior_spans)
        prior_spans.append(span)
        for value in sketch:
            prior_index.setdefault(value, []).append(
                prior_position
            )

    merged = _merge_byte_intervals(
        sorted(
            list(excluded_set)
            + (flagged_spans if apply_cleaning else [])
        )
    )
    projected = _merge_byte_intervals(
        sorted(list(excluded_set) + flagged_spans)
    )
    stats["groups_kept"] = (
        int(stats["groups_scanned"])
        - int(stats["groups_dropped"])
    )
    stats["groups_unflagged"] = (
        int(stats["groups_scanned"])
        - int(stats["groups_flagged"])
    )
    stats["post_clean_train_bytes"] = (
        train_end - sum(end - start for start, end in merged)
    )
    stats["projected_train_bytes_if_flagged_dropped"] = (
        train_end - sum(end - start for start, end in projected)
    )
    if apply_cleaning:
        return flagged_spans, stats
    return [], stats


def _eval_near_duplicate_audit(
    raw: bytearray,
    separator: bytes,
    ranges: Dict[str, Tuple[int, int]],
    threshold: float = _NEAR_DUP_DEFAULT_THRESHOLD,
    shingle_bytes: int = _NEAR_DUP_DEFAULT_SHINGLE_BYTES,
    sketch_size: int = _NEAR_DUP_DEFAULT_SKETCH_SIZE,
) -> Dict[str, object]:
    """
    评估集内部与 val↔test 之间的近重复群组只读审计。

    精确重复群组已由内容指纹门拦截，但同一文档的修订版/转载版
    仍可能以不同字节同时出现在 val 或 test：

    - split 内部近重复群组会把同一内容重复计入评估损失、
      固定窗口 bootstrap 与 checkpoint 选型，使有效样本量
      小于名义窗口/群组数，置信区间偏窄；
    - val↔test 近重复会让 val 选型通过近似内容间接看到 test，
      test 指标不再完全独立。

    本函数只读、只报告，不删除/修改任何字节。相似度仍是字节
    k-shingle 集合的精确 Jaccard，bottom-k 草图只用于生成候选。
    对每个 split 用并查集把达到阈值的近重复群组合并为簇，报告
    ``effective_groups``（簇数，即按「簇内全部冗余」计的独立
    内容单元保守下界）与 ``redundant_groups``（名义群组数 -
    簇数）。

    与训练集近重复审计的分工：训练集审计回答「train 是否把
    val/test 内容带进训练」，本函数回答「评估集自己是否把同一
    内容重复计数」。两者不能互相替代。
    """
    try:
        checked_threshold = float(threshold)
    except (TypeError, ValueError, OverflowError) as error:
        raise ValueError(
            "evaluation near-duplicate threshold 必须是数值"
        ) from error
    if (
        not math.isfinite(checked_threshold)
        or not 0.0 < checked_threshold <= 1.0
    ):
        raise ValueError(
            "evaluation near-duplicate threshold 必须落在 (0, 1]"
        )
    if (
        not isinstance(shingle_bytes, int)
        or isinstance(shingle_bytes, bool)
        or not 1 <= shingle_bytes <= _NEAR_DUP_MAX_SHINGLE_BYTES
    ):
        raise ValueError(
            "evaluation near-duplicate shingle_bytes 必须是 1.."
            f"{_NEAR_DUP_MAX_SHINGLE_BYTES} 的整数"
        )
    if (
        not isinstance(sketch_size, int)
        or isinstance(sketch_size, bool)
        or not 8 <= sketch_size <= _NEAR_DUP_MAX_SKETCH_SIZE
    ):
        raise ValueError(
            "evaluation near-duplicate sketch_size 必须是 8.."
            f"{_NEAR_DUP_MAX_SKETCH_SIZE} 的整数"
        )
    if separator is None or len(separator) == 0:
        raise ValueError(
            "evaluation near-duplicate 扫描需要非空群组分隔符"
        )

    split_order = [
        split
        for split in ("val", "test")
        if (
            split in ranges
            and int(ranges[split][1]) > int(ranges[split][0])
        )
    ]

    groups: List[Tuple[str, int, int]] = []
    split_group_indices: Dict[str, List[int]] = {
        split: [] for split in split_order
    }
    per_split: Dict[str, Dict[str, object]] = {}
    for split in split_order:
        per_split[split] = {
            "groups_total": 0,
            "groups_scanned": 0,
            "groups_too_short": 0,
            "groups_too_large": 0,
            "within_pairs": 0,
            "clusters": 0,
            "effective_groups": 0,
            "redundant_groups": 0,
            "effective_fraction": None,
            "largest_cluster_groups": 0,
        }

    candidate_pairs = 0
    exact_cache: "OrderedDict[Tuple[int, int], Tuple[object, int]]" = (
        OrderedDict()
    )
    exact_cache_bytes = 0

    def _full_shingle_set(
        span: Tuple[int, int],
    ) -> object:
        nonlocal exact_cache_bytes
        cached = exact_cache.get(span)
        if cached is not None:
            exact_cache.move_to_end(span)
            return cached[0]

        values, size = _near_duplicate_exact_values(
            raw,
            span[0],
            span[1],
            shingle_bytes,
        )
        while (
            exact_cache
            and exact_cache_bytes + size
            > _NEAR_DUP_EXACT_CACHE_BYTES
        ):
            _, (_, old_size) = exact_cache.popitem(
                last=False
            )
            exact_cache_bytes -= old_size
        exact_cache[span] = (values, size)
        exact_cache_bytes += size
        return values

    def _exact_jaccard(
        left: Tuple[int, int],
        right: Tuple[int, int],
    ) -> float:
        left_values = _full_shingle_set(left)
        right_values = _full_shingle_set(right)
        if np is not None:
            if (
                left_values.size == 0
                or right_values.size == 0
            ):
                return 0.0
            intersection = int(
                np.intersect1d(
                    left_values,
                    right_values,
                    assume_unique=True,
                ).size
            )
            union = (
                int(left_values.size)
                + int(right_values.size)
                - intersection
            )
        else:
            if not left_values or not right_values:
                return 0.0
            intersection = len(
                left_values & right_values
            )
            union = (
                len(left_values)
                + len(right_values)
                - intersection
            )
        if union <= 0:
            return 0.0
        return intersection / union

    # 只用 bottom-k 草图生成候选；是否近重复由完整 shingle
    # 集合的精确 Jaccard 决定。所有群组按 split 与位置顺序进入
    # 倒排索引，因此每对群组只比较一次，报告顺序确定。
    sketch_index: Dict[int, List[int]] = {}
    within_pairs: List[Tuple[int, int, float]] = []
    cross_pairs: List[Tuple[int, int, float]] = []

    for split in split_order:
        begin, end = (
            int(ranges[split][0]),
            int(ranges[split][1]),
        )
        for span_start, span_end in _iter_group_spans(
            raw,
            separator,
            begin,
            end,
        ):
            per_split[split]["groups_total"] += 1
            length = span_end - span_start
            if length > _NEAR_DUP_MAX_GROUP_BYTES:
                per_split[split]["groups_too_large"] += 1
                continue

            sketch = _near_duplicate_bottom_k(
                _near_duplicate_shingle_hashes(
                    raw,
                    span_start,
                    span_end,
                    shingle_bytes,
                ),
                sketch_size,
            )
            if not sketch:
                per_split[split]["groups_too_short"] += 1
                continue

            group_index = len(groups)
            groups.append((split, span_start, span_end))
            split_group_indices[split].append(group_index)
            per_split[split]["groups_scanned"] += 1

            candidates = set()
            for value in sketch:
                for other_index in sketch_index.get(
                    value, ()
                ):
                    candidates.add(other_index)

            span = (span_start, span_end)
            for other_index in sorted(candidates):
                candidate_pairs += 1
                other_split, other_start, other_end = groups[
                    other_index
                ]
                jaccard = _exact_jaccard(
                    span,
                    (other_start, other_end),
                )
                if jaccard + 1e-12 < checked_threshold:
                    continue
                if other_split == split:
                    within_pairs.append(
                        (group_index, other_index, jaccard)
                    )
                else:
                    cross_pairs.append(
                        (group_index, other_index, jaccard)
                    )

            for value in sketch:
                sketch_index.setdefault(value, []).append(
                    group_index
                )

    # 并查集只在 split 内部合并：同一近重复簇是一个「独立内容
    # 单元」，跨 split 的近似内容不计入 split 内部有效群组数。
    parent = list(range(len(groups)))
    rank = [0] * len(groups)

    def _find(index: int) -> int:
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def _union(left: int, right: int) -> None:
        left_root = _find(left)
        right_root = _find(right)
        if left_root == right_root:
            return
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    for left, right, _jaccard in within_pairs:
        _union(left, right)

    for split in split_order:
        info = per_split[split]
        indices = split_group_indices[split]
        root_sizes: Dict[int, int] = {}
        for index in indices:
            root = _find(index)
            root_sizes[root] = root_sizes.get(root, 0) + 1
        clusters = len(root_sizes)
        scanned = int(info["groups_scanned"])
        info["within_pairs"] = sum(
            1
            for left, right, _jaccard in within_pairs
            if groups[left][0] == split
        )
        info["clusters"] = clusters
        info["effective_groups"] = clusters
        info["redundant_groups"] = max(0, scanned - clusters)
        info["effective_fraction"] = (
            clusters / scanned if scanned > 0 else None
        )
        info["largest_cluster_groups"] = (
            max(root_sizes.values()) if root_sizes else 0
        )
        examples = []
        for left, right, jaccard in within_pairs:
            if groups[left][0] != split:
                continue
            if len(examples) >= 5:
                break
            # 先报告较晚出现的群组，再报告其更早的匹配对象，
            # 与训练集近重复审计的示例口径一致。
            examples.append([
                groups[left][1],
                groups[left][2],
                groups[right][1],
                groups[right][2],
                round(jaccard, 6),
            ])
        info["examples"] = examples

    cross_split: Dict[str, Dict[str, object]] = {}
    for left_index in range(len(split_order)):
        for right_index in range(left_index + 1, len(split_order)):
            left = split_order[left_index]
            right = split_order[right_index]
            key = f"{left}_{right}"
            entries = [
                (i, j, value)
                for i, j, value in cross_pairs
                if {
                    groups[i][0],
                    groups[j][0],
                } == {left, right}
            ]
            cross_split[key] = {
                "pairs": len(entries),
                "examples": [
                    [
                        groups[i][1],
                        groups[i][2],
                        groups[j][1],
                        groups[j][2],
                        round(value, 6),
                    ]
                    for i, j, value in entries[:5]
                ],
            }

    return {
        "schema": "smelt-isr/eval-near-duplicate/v1",
        "mode": "audit",
        "policy": (
            "read-only near-duplicate audit within val/test and "
            "across val/test; no bytes are removed"
        ),
        "threshold": round(checked_threshold, 6),
        "shingle_bytes": shingle_bytes,
        "sketch_size": sketch_size,
        "similarity": "jaccard_of_byte_shingle_sets",
        "shingle_hash": "rolling_polynomial_64bit",
        "exact_verification": True,
        "max_group_bytes": _NEAR_DUP_MAX_GROUP_BYTES,
        "splits": list(split_order),
        "test_content_used": "test" in split_order,
        "candidate_pairs": candidate_pairs,
        "per_split": per_split,
        "cross_split": cross_split,
        "note": (
            "effective_groups 是近重复簇数；按「簇内全部冗余」"
            "计这是独立样本量的保守下界，簇内群组仍可能包含"
            "不同内容"
        ),
    }


def _train_group_health_audit(
    dataset: ByteDataset,
) -> Optional[Dict[str, object]]:
    """
    训练集群组级异常值审计：统计「长度达到阈值且单一字节占比
    极高」的低信息/退化群组。

    只看 train，且跳过已被清洗剔除的群组；val/test 不参与统计。
    这是异常值检查，不会自动删除数据（需要显式
    --drop-train-degenerate-groups 才整组清洗）。
    """
    separator = dataset.group_separator
    if separator is None:
        return None

    excluded = set(dataset.train_excluded_spans)
    stats: Dict[str, object] = {
        "min_bytes": _AUDIT_DEGENERATE_GROUP_MIN_BYTES,
        "top_share_threshold": (
            _AUDIT_DEGENERATE_GROUP_TOP_SHARE
        ),
        "groups_checked": 0,
        "long_groups_checked": 0,
        "degenerate_groups": 0,
        "degenerate_bytes": 0,
        "max_top_byte_share": 0.0,
        "examples": [],
    }

    for span_start, span_end in _iter_group_spans(
        dataset._raw_buffer,
        separator,
        0,
        dataset.split_bounds["train"][1],
    ):
        if (span_start, span_end) in excluded:
            continue

        stats["groups_checked"] += 1
        length = span_end - span_start
        if length < _AUDIT_DEGENERATE_GROUP_MIN_BYTES:
            continue

        stats["long_groups_checked"] += 1
        top_byte, top_share = _group_top_byte_share(
            dataset._raw,
            span_start,
            span_end,
        )
        stats["max_top_byte_share"] = max(
            float(stats["max_top_byte_share"]),
            top_share,
        )

        if top_share < _AUDIT_DEGENERATE_GROUP_TOP_SHARE:
            continue

        stats["degenerate_groups"] += 1
        stats["degenerate_bytes"] += length
        if len(stats["examples"]) < 5:
            stats["examples"].append([
                span_start,
                span_end,
                top_byte,
                round(top_share, 6),
            ])

    return stats


def _group_content_duplicate_audit(
    dataset: ByteDataset,
    split_names: List[str],
) -> Optional[Dict[str, object]]:
    """
    群组级精确内容去重审计。

    窗口签名扫描是有界抽样的，可能漏掉短群组或错位重复；
    这里对每个群组的完整内容做 blake2b-128 指纹，逐 split
    核对完全相同的群组。跨 split 的重复群组是泄露级问题
    （同一文档/用户同时出现在训练与验证/测试两侧），必须
    进入 violations；split 内部的重复群组只作为重复样本/
    标签噪声提醒。

    训练集清洗（deduplicate_train_groups）剔除的群组不参与
    统计，因此清洗后的审计能反映「实际进入训练的内容」。
    """
    separator = dataset.group_separator
    if separator is None:
        return None

    excluded = set(dataset.train_excluded_spans)
    indices: Dict[str, Dict[bytes, List[int]]] = {}
    per_split: Dict[str, Dict[str, int]] = {}

    for split in split_names:
        begin, end = dataset.split_bounds[split]
        if end <= begin:
            continue

        index: Dict[bytes, List[int]] = {}
        groups = 0

        for span_start, span_end in _iter_group_spans(
            dataset._raw_buffer,
            separator,
            begin,
            end,
        ):
            if split == "train" and (
                (span_start, span_end) in excluded
            ):
                continue

            digest = _group_content_digest(
                dataset._raw,
                span_start,
                span_end,
            )
            index.setdefault(digest, []).append(span_start)
            groups += 1

        indices[split] = index
        per_split[split] = {
            "groups": groups,
            "unique_groups": len(index),
            "within_split_duplicates": (
                groups - len(index)
            ),
        }

    cross_split: Dict[str, object] = {}
    for left, right in (
        ("train", "val"),
        ("train", "test"),
        ("val", "test"),
    ):
        if left not in indices or right not in indices:
            continue

        left_index = indices[left]
        right_index = indices[right]
        common = left_index.keys() & right_index.keys()

        cross_split[f"{left}_{right}"] = {
            "shared_groups": len(common),
            "examples": [
                [
                    left_index[digest][0],
                    right_index[digest][0],
                ]
                for digest in sorted(common)[:3]
            ],
        }

    return {
        "per_split": per_split,
        "cross_split": cross_split,
    }


def audit_data_splits(
    dataset: ByteDataset,
    include_test: bool = False,
    max_windows: int = _AUDIT_MAX_WINDOWS,
    cache_scans: bool = False,
) -> Dict[str, object]:
    """
    数据审计：值域校验、文本完整性、分布偏移与重复窗口检测。

    - 校验每个 split 的 token 值域（字节管线为 0..255；整数
      token 中不存在 NaN/Inf，值域校验用于捕获上游 dtype 或
      编码错误）；
    - 扫描文本完整性（无法 UTF-8 解码的字节序列、NUL 字节），
      作为字节级标签噪声与语料损坏的清洗检查；
    - 统计每个 split 的字节直方图与字节二元组直方图，并计算
      train↔val（可选包含 train↔test、val↔test）之间的 JS
      距离：单字节频率发现词表/频率偏移，二元组发现「词表
      相同但上下文顺序改变」的偏移；
    - 对滑动窗口做有界签名扫描，检测跨 split 重复内容与 split
      内部重复；
    - 用内容定义分块指纹补齐窗口抽样漏掉的错位/近似重复：分块
      边界由局部内容决定，长片段整体偏移后仍会产生相同块指纹；
      跨 split 共享块是泄露级问题；
    - 群组划分（传入 group_separator 时）报告每个 split 的完整
      群组数与分隔符，供追踪「群组整体不跨界」的协议。

    ``leakage_scan_coverage`` 记录窗口签名扫描的覆盖（各 split
    采样窗口数/总窗口数与 stride）。stride>1 时窗口级「未发现
    跨 split 重复」只是抽样范围内的负结果，报告会显式写出残余
    风险，避免把抽样零发现读成「数据里没有泄露」。

    返回的 ``warnings`` 是全部提醒；``violations`` 是其中会
    被 ``--strict-data-audit`` 视为致命的问题（越界 token、
    跨 split 重复内容、任何 UTF-8/NUL 损坏）——这些问题直接
    对应数据泄露或标签噪声，严格模式下拒绝训练。
    ``leakage_violations`` 是 ``violations`` 中「跨 split 内容
    重复」这一类纯泄露问题：默认训练入口也会拒绝它们，除非
    显式传入 ``--allow-data-leakage``。损坏/标签噪声仍由
    ``--strict-data-audit`` 控制，避免把「数据脏」和「数据泄露」
    混为同一个开关。

    test 只在 include_test=True（最终评估解封时）才参与统计，
    训练期间默认只审计 train/val。审计只做诊断，不参与任何
    特征计算或模型决策。
    """
    split_names = ["train", "val"]
    if include_test and dataset.has_test:
        split_names.append("test")

    histograms: Dict[str, torch.Tensor] = {}
    scans: Dict[str, Dict[str, object]] = {}
    splits_report: Dict[str, object] = {}
    warnings: List[str] = []
    violations: List[str] = []
    leakage_violations: List[str] = []
    evaluation_violations: List[str] = []

    # 无群组语料：一次性按整个文件解码，得到每个非法/NUL 字节
    # 的绝对位置，再按 split 归属计数。逐 split 预热解码会把
    # 上一段末尾的未完成序列记到下一段（例如 val 末尾的坏字节
    # 让字节干净的 test 被标签完整性门拒绝）；全局定位既保留
    # 跨 split 合法多字节字符，又能把坏字节归到真正包含它的段。
    # 群组模式仍逐群组扫描，以排除用户声明的分隔符字节。
    global_integrity_spans: Optional[
        List[Tuple[int, int, str]]
    ] = None
    if dataset.group_separator is None:
        global_integrity_spans = _invalid_utf8_nul_spans(
            dataset._raw,
            0,
            dataset.num_bytes,
            final=True,
        )

    for split in split_names:
        tokens = getattr(dataset, split)

        # 字节管线固定为 uint8，直方图直接在原始 dtype 上
        # 统计（uint8 天然落在 0..255，越界恒为 0）。其他
        # dtype（若日后扩展管线）回退到 int64 校验路径，
        # 保持诊断语义不变。
        if split == "train" and dataset.train_excluded_spans:
            # 训练集群组清洗后的有效字节：被剔除的重复群组
            # 不会进入神经网络训练，也不应进入分布偏移统计，
            # 否则审计描述的是模型从未见过的数据。
            hist = dataset.effective_train_byte_counts().to(
                torch.float64
            )
            invalid = 0
        elif tokens.dtype == torch.uint8:
            try:
                hist = torch.bincount(
                    tokens,
                    minlength=256,
                )
            except RuntimeError:
                # 旧版本 bincount 仅接受 int64 输入，退回转换。
                hist = torch.bincount(
                    tokens.to(torch.int64),
                    minlength=256,
                )
            hist = hist.to(torch.float64)
            invalid = 0
        else:
            tokens_long = tokens.to(torch.int64)
            # 先统计越界，再对 clamp 后的值做直方图：
            # bincount 不接受负值，且 clamp 保证直方图长度
            # 恰为 256，跨 split 的 JS 距离形状一致。
            invalid = int(
                ((tokens_long < 0) | (tokens_long > 255)).sum()
            )
            hist = torch.bincount(
                tokens_long.clamp(0, 255),
                minlength=256,
            ).to(torch.float64)

        histograms[split] = hist / hist.sum()

        top_share, top_byte = torch.topk(
            histograms[split],
            k=5,
        )

        begin, end = dataset.split_bounds[split]
        # 训练前审计与解封测试集时的审计都会扫描 train/val；
        # 数据在运行期间不可变，按 (起点, 长度, 窗口, 上限)
        # 复用扫描结果。
        scan_cache = getattr(
            dataset, "_audit_scan_cache", None
        )
        scan_key = (
            begin,
            end - begin,
            dataset.seq_len + 1,
            max_windows,
        )
        scan = (
            scan_cache.get(scan_key)
            if scan_cache is not None
            else None
        )
        if scan is None:
            scan = _window_signature_scan(
                dataset._raw,
                begin,
                end - begin,
                dataset.seq_len + 1,
                max_windows,
                exclude_spans=(
                    dataset.train_excluded_spans
                    if split == "train"
                    else None
                ),
            )
            if cache_scans:
                if scan_cache is None:
                    scan_cache = {}
                    dataset._audit_scan_cache = scan_cache
                scan_cache[scan_key] = scan
        scans[split] = scan
        if dataset.group_separator is None:
            # 用全局字节位置归属到 split；train 的清洗区间不再
            # 计入（模型不会看到这些字节），val/test 不做清洗。
            integrity = {
                "utf8_replacements": 0,
                "nul_bytes": 0,
            }
            excluded = _merge_byte_intervals(
                dataset.train_excluded_spans
                if split == "train"
                else []
            )
            excluded_index = 0
            for span_start, _span_end, kind in (
                global_integrity_spans or []
            ):
                if span_start < begin:
                    continue
                if span_start >= end:
                    break
                while (
                    excluded_index < len(excluded)
                    and excluded[excluded_index][1]
                    <= span_start
                ):
                    excluded_index += 1
                if (
                    excluded_index < len(excluded)
                    and excluded[excluded_index][0]
                    <= span_start
                    < excluded[excluded_index][1]
                ):
                    continue
                if kind == "invalid_utf8":
                    integrity["utf8_replacements"] += 1
                elif kind == "nul":
                    integrity["nul_bytes"] += 1
        else:
            # 群组分隔符是用户显式声明的数据结构（可能含 NUL 或
            # 非 UTF-8 字节，如 --group-separator '\x00'），不能
            # 计入损坏统计，否则严格审计会把合法配置当成语料
            # 损坏而拒绝训练。逐群组扫描：每个群组按独立文本
            # 解码，组尾不完整的多字节序列计入该组。
            integrity = {
                "utf8_replacements": 0,
                "nul_bytes": 0,
            }
            train_excluded = (
                set(dataset.train_excluded_spans)
                if split == "train"
                else set()
            )
            for span_start, span_end in _iter_group_spans(
                dataset._raw_buffer,
                dataset.group_separator,
                begin,
                end,
            ):
                if (span_start, span_end) in train_excluded:
                    continue
                part = _scan_text_integrity(
                    dataset._raw,
                    span_start,
                    span_end - span_start,
                    final=True,
                    warmup=False,
                )
                integrity["utf8_replacements"] += part[
                    "utf8_replacements"
                ]
                integrity["nul_bytes"] += part["nul_bytes"]

        nominal_fraction = {
            "train": (
                1.0
                - dataset.val_fraction
                - dataset.test_fraction
            ),
            "val": dataset.val_fraction,
            "test": dataset.test_fraction,
        }[split]
        actual_fraction = dataset.split_fractions[split]

        splits_report[split] = {
            "bytes": end - begin,
            "effective_bytes": (
                dataset.effective_train_bytes
                if split == "train"
                else end - begin
            ),
            "fraction": actual_fraction,
            "nominal_fraction": nominal_fraction,
            "windows": scans[split]["total"],
            "effective_windows": (
                dataset.train_num_valid_starts
                if (
                    split == "train"
                    and dataset.train_excluded_spans
                )
                else scans[split]["total"]
            ),
            "invalid_tokens": invalid,
            "utf8_replacements": integrity["utf8_replacements"],
            "nul_bytes": integrity["nul_bytes"],
            "top_bytes": [
                [int(byte), round(float(share), 6)]
                for share, byte in zip(
                    top_share.tolist(),
                    top_byte.tolist(),
                )
            ],
        }

        if invalid > 0:
            message = f"{split}: 检测到 {invalid} 个越界 token"
            warnings.append(message)
            violations.append(message)

        split_bytes = max(1, end - begin)
        replacement_share = (
            integrity["utf8_replacements"] / split_bytes
        )
        if integrity["utf8_replacements"] > 0:
            message = (
                f"{split}: 检测到 "
                f"{integrity['utf8_replacements']} 处无法按"
                "UTF-8 解码的字节序列"
                f"（占比 {replacement_share:.4f}），"
                "疑似语料损坏（字节级标签噪声）"
            )
            # 严格模式对任何标签噪声都必须拒绝：低频损坏同样会
            # 污染监督位。默认模式只在占比超过告警阈值时打印
            # 警告，但严格判定不依赖该阈值。
            if replacement_share > _AUDIT_UTF8_REPLACE_WARN:
                warnings.append(message)
            violations.append(message)

        nul_share = integrity["nul_bytes"] / split_bytes
        if integrity["nul_bytes"] > 0:
            message = (
                f"{split}: 检测到 {integrity['nul_bytes']} 个"
                f"NUL 字节（占比 {nul_share:.4f}），"
                "疑似二进制/填充污染"
            )
            if nul_share > _AUDIT_NUL_WARN:
                warnings.append(message)
            violations.append(message)

        top_byte_share = float(top_share[0])
        if top_byte_share > _AUDIT_TOP_BYTE_WARN:
            warnings.append(
                f"{split}: 最高频字节占比 "
                f"{top_byte_share:.3f}，疑似填充/退化数据"
            )

        if nominal_fraction > 0.0 and abs(
            actual_fraction - nominal_fraction
        ) > max(
            _AUDIT_SPLIT_FRACTION_MIN_ABS,
            _AUDIT_SPLIT_FRACTION_DRIFT * nominal_fraction,
        ):
            warnings.append(
                f"{split}: 实际占比 {actual_fraction:.4f} "
                f"偏离名义值 {nominal_fraction:.4f}"
                "（群组边界吸附或语料大小导致），"
                "评估集规模/统计功效可能与预期不符"
            )

    # 评估集标签覆盖：训练集从未出现过的字节类在评估 token 中
    # 占比多少。字节级 LM 只能通过上下文降低已见标签的 NLL；
    # 未见标签的最优预测只能退到平滑/先验，属于不可约的外推
    # 误差。把它与分布偏移分开报告，避免把「模型没学会」和
    # 「训练数据根本没有这个标签」混为一谈。
    label_coverage: Dict[str, object] = {}
    train_hist = histograms.get("train")
    if train_hist is not None:
        train_present = train_hist > 0
        train_classes = int(train_present.sum())
        label_coverage["train"] = {
            "observed_byte_classes": train_classes,
        }
        for split in split_names:
            if split == "train":
                continue
            split_hist = histograms[split]
            unseen_mask = (split_hist > 0) & (~train_present)
            unseen_classes = int(unseen_mask.sum())
            unseen_share = float(
                split_hist[unseen_mask].sum()
            )
            info = {
                "observed_byte_classes": int(
                    (split_hist > 0).sum()
                ),
                "train_observed_byte_classes": train_classes,
                "unseen_label_classes": unseen_classes,
                "unseen_label_token_share": round(
                    unseen_share, 8
                ),
                "warn_token_share": (
                    _AUDIT_UNSEEN_LABEL_WARN
                ),
            }
            label_coverage[split] = info
            split_info = splits_report.get(split)
            if isinstance(split_info, dict):
                split_info["unseen_label_classes"] = (
                    unseen_classes
                )
                split_info["unseen_label_token_share"] = (
                    info["unseen_label_token_share"]
                )
            if unseen_share > _AUDIT_UNSEEN_LABEL_WARN:
                warnings.append(
                    f"{split}: 评估集有 {unseen_classes} 个"
                    "字节类在有效训练集中从未出现（占评估 "
                    f"token {unseen_share:.4%}）；这些标签的"
                    "NLL 无法通过训练降低，指标包含不可约的"
                    "外推误差，不能与训练集覆盖相同的运行"
                    "直接比较"
                )

    # 清洗的删除偏差：清洗按内容规则选择性删除，删除后的训练
    # 分布可能与原始分布不同。这里不重复打印所有统计，只在
    # 偏差达到告警阈值时提示；完整数值在
    # data.train_cleaning.deletion_bias。
    cleaning_record = dataset.train_cleaning
    if isinstance(cleaning_record, dict):
        bias = cleaning_record.get("deletion_bias")
        if isinstance(bias, dict):
            drop_fraction = bias.get("drop_fraction")
            if (
                isinstance(drop_fraction, (int, float))
                and drop_fraction > _AUDIT_DELETION_DROP_WARN
            ):
                warnings.append(
                    "train: 清洗删除了 "
                    f"{float(drop_fraction):.1%} 的训练字节"
                    f"（{bias.get('dropped_bytes')}B）；"
                    "删除由重复/损坏/退化规则触发，不是随机"
                    "缺失，清洗后的训练分布已被选择性改变。"
                    "清洗/未清洗运行的指标不能直接比较"
                )
            byte_js = bias.get("byte_js")
            if (
                isinstance(byte_js, (int, float))
                and byte_js > _AUDIT_DELETION_BIAS_WARN
            ):
                warnings.append(
                    "train: 被删除与保留内容的字节分布"
                    f"JS 距离 {float(byte_js):.4f} > "
                    f"{_AUDIT_DELETION_BIAS_WARN:.2f}；"
                    "清洗并非随机删除，训练分布发生了"
                    "选择性变化，见 "
                    "data.train_cleaning.deletion_bias"
                )
            bigram_js = bias.get("bigram_js")
            if (
                isinstance(bigram_js, (int, float))
                and bigram_js
                > _AUDIT_DELETION_BIAS_WARN
            ):
                warnings.append(
                    "train: 被删除与保留内容的二元组分布"
                    f"JS 距离 {float(bigram_js):.4f} > "
                    f"{_AUDIT_DELETION_BIAS_WARN:.2f}；"
                    "删除改变了上下文转移分布，不能把清洗后"
                    "的改善/退化全部归因于方法"
                )

    # 验证集标签噪声即使占比很低也必须显式提示：val 用于
    # checkpoint 选择、早停与超参/基线调参，少量损坏标签会
    # 系统性地改变选型结果，而不像 train 噪声那样只增加方差。
    # 这里只告警不拒绝（合法二进制语料仍可训练），严格模式
    # 或 --drop-train-* 清洗负责处理。
    val_info = splits_report.get("val")
    val_label_noise: Dict[str, object] = {
        "invalid_tokens": 0,
        "utf8_replacements": 0,
        "nul_bytes": 0,
        "has_label_noise": False,
        "used_for_selection": True,
    }
    if isinstance(val_info, dict):
        for key in (
            "invalid_tokens",
            "utf8_replacements",
            "nul_bytes",
        ):
            val_label_noise[key] = int(val_info.get(key, 0) or 0)
        val_label_noise["has_label_noise"] = any(
            int(val_label_noise[key]) > 0
            for key in (
                "invalid_tokens",
                "utf8_replacements",
                "nul_bytes",
            )
        )
        if val_label_noise["has_label_noise"]:
            warnings.append(
                "val: 验证集含标签噪声（越界 token "
                f"{val_label_noise['invalid_tokens']}、"
                "非法 UTF-8 "
                f"{val_label_noise['utf8_replacements']}、"
                f"NUL {val_label_noise['nul_bytes']}）；"
                "val 用于 checkpoint/早停选型，损坏标签会"
                "扭曲模型选择。默认仅告警；请用 "
                "--strict-data-audit 拒绝训练，或先清洗/"
                "重新切分数据"
            )

    # test 在训练期间保持尘封：这里只根据切分边界核对它的
    # 实际占比，不读取任何 test 内容。这样吸附导致的测试集
    # 缩水在训练前就能被发现。
    nominal_by_split = {
        "train": (
            1.0
            - dataset.val_fraction
            - dataset.test_fraction
        ),
        "val": dataset.val_fraction,
        "test": dataset.test_fraction,
    }
    for split, actual_fraction in (
        dataset.split_fractions.items()
    ):
        if split in splits_report:
            continue
        nominal_fraction = nominal_by_split[split]
        if nominal_fraction > 0.0 and abs(
            actual_fraction - nominal_fraction
        ) > max(
            _AUDIT_SPLIT_FRACTION_MIN_ABS,
            _AUDIT_SPLIT_FRACTION_DRIFT * nominal_fraction,
        ):
            warnings.append(
                f"{split}: 实际占比 {actual_fraction:.4f} "
                f"偏离名义值 {nominal_fraction:.4f}"
                "（群组边界吸附或语料大小导致；"
                "test 内容仍保持尘封）"
            )

    bigram_histograms: Dict[str, torch.Tensor] = {}
    bigram_counts: Dict[str, torch.Tensor] = {}

    for split in split_names:
        counts = _byte_bigram_counts(
            getattr(dataset, split),
            (
                dataset.train_excluded_spans
                if split == "train"
                else None
            ),
        )
        bigram_counts[split] = counts
        total = int(counts.sum())
        if total > 0:
            bigram_histograms[split] = (
                counts.to(torch.float64) / total
            )

    distribution_shift: Dict[str, float] = {}
    distribution_shift_bigram: Dict[str, float] = {}
    distribution_shift_conditional: Dict[str, float] = {}
    unseen_transition_share: Dict[str, float] = {}
    seen_context_share: Dict[str, float] = {}

    for left, right in (
        ("train", "val"),
        ("train", "test"),
        ("val", "test"),
    ):
        key = f"{left}_{right}"

        if left in histograms and right in histograms:
            distance = _js_distance(
                histograms[left],
                histograms[right],
            )
            distribution_shift[key] = round(distance, 6)

            if distance > _AUDIT_SHIFT_WARN:
                warnings.append(
                    f"{key}: 字节分布偏移较大"
                    f"（JS 距离 {distance:.4f}）"
                )

        if (
            left in bigram_histograms
            and right in bigram_histograms
        ):
            bigram_distance = _js_distance(
                bigram_histograms[left],
                bigram_histograms[right],
            )
            distribution_shift_bigram[key] = round(
                bigram_distance,
                6,
            )

            if bigram_distance > _AUDIT_BIGRAM_SHIFT_WARN:
                warnings.append(
                    f"{key}: 字节二元组分布偏移较大"
                    f"（JS 距离 {bigram_distance:.4f}）："
                    "单字节词表可能相同，但上下文/顺序分布"
                    "已发生变化"
                )

        if left in bigram_counts and right in bigram_counts:
            conditional = _conditional_bigram_shift(
                bigram_counts[left],
                bigram_counts[right],
            )
            distribution_shift_conditional[key] = round(
                conditional["conditional_js"],
                6,
            )
            unseen_transition_share[key] = round(
                conditional["unseen_transition_share"],
                6,
            )
            seen_context_share[key] = round(
                conditional["seen_context_share"],
                6,
            )

            if (
                conditional["conditional_js"]
                > _AUDIT_CONDITIONAL_SHIFT_WARN
            ):
                warnings.append(
                    f"{key}: 给定上下文后的标签分布偏移较大"
                    "（条件 JS 距离 "
                    f"{conditional['conditional_js']:.4f}）："
                    "同一上下文在 train 与评估 split 中"
                    "接不同标签，监督信号已漂移"
                )

            if (
                conditional["unseen_transition_share"]
                > _AUDIT_UNSEEN_TRANSITION_WARN
            ):
                warnings.append(
                    f"{key}: 评估集中 "
                    f"{conditional['unseen_transition_share']:.1%} "
                    "的 (上下文, 目标) 转移在 train 从未出现；"
                    "指标包含大量外推，需检查切分/分布偏移"
                )

    temporal_boundary_shift = _temporal_boundary_shift_audit(
        dataset,
        split_names,
        warnings,
    )

    duplicate_windows: Dict[str, object] = {}

    for split, scan in scans.items():
        duplicate_windows[split] = {
            "sampled": scan["sampled"],
            "total": scan["total"],
            "stride": scan["stride"],
            "within_duplicates": scan["within_duplicates"],
        }

        if scan["within_duplicates"] > 0:
            warnings.append(
                f"{split}: 采样窗口中有"
                f"{scan['within_duplicates']}个 split 内部重复"
                + (
                    "；固定窗口 bootstrap 会把重复窗口当作"
                    "独立抽样单位，评估区间可能偏窄"
                    if split in ("val", "test")
                    else ""
                )
            )

    for left, right in (
        ("train", "val"),
        ("train", "test"),
        ("val", "test"),
    ):
        if left not in scans or right not in scans:
            continue

        left_sigs = scans[left]["signatures"]
        right_sigs = scans[right]["signatures"]
        common = left_sigs.keys() & right_sigs.keys()

        duplicate_windows[f"{left}_{right}"] = {
            "shared_signatures": len(common),
            "examples": [
                [left_sigs[digest][0], right_sigs[digest][0]]
                for digest in sorted(common)[:3]
            ],
        }

        if common:
            message = (
                f"{left}_{right}: 检测到"
                f"{len(common)} 个重复窗口内容"
                "（跨 split 泄露风险）"
            )
            warnings.append(message)
            violations.append(message)
            leakage_violations.append(message)

    # 抽样扫描的零发现不能当成「无泄露」的证明：把覆盖情况与
    # 残余风险写进审计，读者才知道这条负结果的证据边界在哪。
    scan_coverage = _leakage_scan_coverage(scans)
    if scan_coverage["residual_risk"]:
        warnings.append(str(scan_coverage["residual_risk"]))

    groups_report: Optional[Dict[str, object]] = None

    if dataset.group_separator is not None:
        # 群组划分协议：分界点都是群组起始字节，因此每个群组
        # 整体落在一个 split 内；这里把群组规模写进审计，供
        # 事后核对（数据集构造时还做了防御性断言）。
        content_duplicates = _group_content_duplicate_audit(
            dataset,
            split_names,
        )
        content_health = _train_group_health_audit(dataset)

        groups_report = {
            "separator_hex": dataset.group_separator.hex(),
            "separator_length": len(dataset.group_separator),
            "cuts": dataset.group_cuts,
            "groups_per_split": dataset.groups_per_split,
            "groups_total": (
                sum(dataset.groups_per_split.values())
                if dataset.groups_per_split is not None
                else None
            ),
            "content_duplicates": content_duplicates,
            "content_health": content_health,
            "train_cleaning": dataset.train_cleaning,
        }

        if (
            isinstance(dataset.train_cleaning, dict)
            and dataset.train_cleaning.get(
                "test_used_for_cleaning"
            )
        ):
            message = (
                "train: 训练集清洗对照了 test 内容"
                "（显式开启 --clean-train-against-test）："
                "训练样本集合依赖测试集，最终 test 指标不再"
                "来自完全尘封的数据；该事实已写入 train_cleaning"
                "并参与跨运行协议核对"
            )
            warnings.append(message)
            violations.append(message)

        if (
            content_health is not None
            and content_health["degenerate_groups"] > 0
        ):
            warnings.append(
                "train: 检测到 "
                f"{content_health['degenerate_groups']} 个"
                "低信息/退化群组（长度 >= "
                f"{content_health['min_bytes']}B 且单一字节"
                "占比 >= "
                f"{content_health['top_share_threshold']}），"
                "疑似填充/重复字符污染（异常值）；可检查后用 "
                "--drop-train-degenerate-groups 清洗"
            )

        if content_duplicates is not None:
            for split, info in content_duplicates[
                "per_split"
            ].items():
                if info["within_split_duplicates"] > 0:
                    message = (
                        f"{split}: 检测到 "
                        f"{info['within_split_duplicates']} 个"
                        "完全重复的群组（重复样本/标签噪声）"
                    )
                    warnings.append(message)
                    if split in ("val", "test"):
                        evaluation_violations.append(message)

            for pair, info in content_duplicates[
                "cross_split"
            ].items():
                if info["shared_groups"] <= 0:
                    continue
                message = (
                    f"{pair}: 检测到 "
                    f"{info['shared_groups']} 个内容完全"
                    "相同的群组（跨 split 群组泄露风险）"
                )
                warnings.append(message)
                violations.append(message)
                leakage_violations.append(message)

    degenerate_runs = _train_degenerate_run_audit(dataset)

    if (
        degenerate_runs is not None
        and degenerate_runs["runs"] > 0
    ):
        warnings.append(
            "train: 检测到 "
            f"{degenerate_runs['runs']} 个低信息/退化连续段"
            "（长度 >= "
            f"{degenerate_runs['min_bytes']}B 的单一字节段，"
            f"共 {degenerate_runs['degenerate_bytes']} 字节，"
            "疑似填充/重复字符污染/异常值）；可检查后用 "
            "--drop-train-degenerate-runs 只清洗 train"
        )

    content_chunks = _content_chunk_duplicate_audit(
        dataset,
        split_names,
    )

    for pair, info in content_chunks["cross_split"].items():
        if info["shared_chunks"] <= 0:
            continue
        message = (
            f"{pair}: 内容定义分块检测到 "
            f"{info['shared_chunks']} 个相同的"
            f"连续字节块（共享 {info['shared_bytes']} 字节，"
            "错位/近似重复内容的跨 split 泄露风险）"
        )
        warnings.append(message)
        violations.append(message)
        leakage_violations.append(message)

    # 近重复只读审计：精确群组指纹与内容定义分块都要求内容
    # 完全相同/共享完整块；改写、转载、轻微编辑的群组仍可能
    # 把评估内容带进训练。这里按 shingle Jaccard 找近重复，
    # 默认只对照 val；只有解封测试集时才把 test 纳入。
    # 近重复是相似而非逐字节相同，默认只告警、不进入泄露硬门；
    # 清洗需显式 --drop-train-near-duplicate-groups。
    near_duplicates: Optional[Dict[str, object]] = None
    evaluation_near_duplicates: Optional[Dict[str, object]] = None
    if (
        dataset.group_separator is not None
        and getattr(dataset, "near_duplicate_audit", False)
    ):
        near_eval_ranges: Dict[str, Tuple[int, int]] = {
            "val": dataset.split_bounds["val"],
        }
        near_include_test = bool(
            include_test and dataset.has_test
        )
        if near_include_test:
            near_eval_ranges["test"] = (
                dataset.split_bounds["test"]
            )

        _, near_duplicates = (
            _plan_train_near_duplicate_cleaning(
                dataset._raw_buffer,
                dataset.group_separator,
                dataset.split_bounds["train"][1],
                near_eval_ranges,
                dataset.train_excluded_spans,
                threshold=getattr(
                    dataset,
                    "near_duplicate_threshold",
                    _NEAR_DUP_DEFAULT_THRESHOLD,
                ),
                shingle_bytes=getattr(
                    dataset,
                    "near_duplicate_shingle_bytes",
                    _NEAR_DUP_DEFAULT_SHINGLE_BYTES,
                ),
                apply_cleaning=False,
            )
        )
        near_duplicates["include_test"] = near_include_test
        near_duplicates["test_content_used"] = (
            near_include_test
        )

        flagged = int(near_duplicates["groups_flagged"])
        if flagged > 0:
            matched = ", ".join(
                f"{split}:{count}"
                for split, count in (
                    near_duplicates[
                        "flagged_duplicate_of"
                    ] or {}
                ).items()
                if int(count) > 0
            )
            warnings.append(
                "train: 近重复审计发现 "
                f"{flagged} 个训练群组与评估/更早训练群组"
                "的 shingle Jaccard 达到阈值 "
                f"{near_duplicates['threshold']}（{matched}；"
                f"shingle={near_duplicates['shingle_bytes']}B）；"
                "精确指纹/内容定义分块只能发现完全相同或"
                "共享完整块的重复，改写/转载可能仍把评估"
                "内容带入训练。检查 "
                "data_audit.near_duplicates.examples 后可用 "
                "--drop-train-near-duplicate-groups 整组清洗"
            )
        skipped = (
            int(near_duplicates["groups_too_short"])
            + int(near_duplicates["groups_too_large"])
            + int(near_duplicates["eval_groups_too_short"])
            + int(near_duplicates["eval_groups_too_large"])
        )
        if skipped > 0:
            warnings.append(
                "train/eval: 近重复审计跳过 "
                f"{skipped} 个群组（过短或超过 "
                f"{near_duplicates['max_group_bytes']}B）："
                "这些群组没有参与近重复判断，不能把"
                "「未标记」当成「不重复」"
            )

        # 评估集内部的近重复与 train→eval 是两类不同的问题：
        # 前者让同一内容在评估中被重复计数，后者才是训练污染。
        # 使用与训练集审计相同的阈值/shingle 口径；test 只在
        # 显式解封（include_test=True）时读取。
        evaluation_near_duplicates = _eval_near_duplicate_audit(
            dataset._raw_buffer,
            dataset.group_separator,
            near_eval_ranges,
            threshold=getattr(
                dataset,
                "near_duplicate_threshold",
                _NEAR_DUP_DEFAULT_THRESHOLD,
            ),
            shingle_bytes=getattr(
                dataset,
                "near_duplicate_shingle_bytes",
                _NEAR_DUP_DEFAULT_SHINGLE_BYTES,
            ),
        )

        for split, info in (
            evaluation_near_duplicates["per_split"] or {}
        ).items():
            if int(info["within_pairs"]) <= 0:
                continue
            consumers = (
                "固定窗口 bootstrap 与 checkpoint 选型"
                if split == "val"
                else "固定窗口 bootstrap"
            )
            warnings.append(
                f"{split}: 评估集内部检测到 "
                f"{info['within_pairs']} 对近重复群组"
                f"（{info['clusters']} 个独立簇 / 共 "
                f"{info['groups_scanned']} 个可比群组，"
                f"有效群组 {info['effective_groups']}，"
                "最大簇 "
                f"{info['largest_cluster_groups']} 个）；"
                f"{consumers}会把同源内容当作独立样本，"
                "评估区间可能偏窄，也不能把名义群组/窗口数"
                "当作独立样本量"
            )

        for pair, info in (
            evaluation_near_duplicates["cross_split"] or {}
        ).items():
            if int(info["pairs"]) <= 0:
                continue
            warnings.append(
                f"{pair}: 检测到 {info['pairs']} 对跨 split "
                "近重复评估群组（shingle Jaccard >= "
                f"{evaluation_near_duplicates['threshold']}）；"
                "val 选型可能通过近似内容间接看到 test，"
                "test 指标不再完全独立，需披露或重新划分"
            )

    return {
        "max_windows": max_windows,
        "splits": splits_report,
        "train_cleaning": dataset.train_cleaning,
        "split_fractions": {
            split: info["fraction"]
            for split, info in splits_report.items()
        },
        "dataset_split_fractions": dataset.split_fractions,
        "label_coverage": label_coverage,
        "distribution_shift": distribution_shift,
        "distribution_shift_bigram": distribution_shift_bigram,
        "distribution_shift_conditional": (
            distribution_shift_conditional
        ),
        "temporal_boundary_shift": temporal_boundary_shift,
        "unseen_transition_share": unseen_transition_share,
        "seen_context_share": seen_context_share,
        "duplicate_windows": duplicate_windows,
        "leakage_scan_coverage": scan_coverage,
        "content_chunks": content_chunks,
        "near_duplicates": near_duplicates,
        "evaluation_near_duplicates": (
            evaluation_near_duplicates
        ),
        "degenerate_runs": degenerate_runs,
        "val_label_noise": val_label_noise,
        "split_isolation": _split_isolation_record(
            dataset.split_bounds,
            dataset.num_bytes,
        ),
        "groups": groups_report,
        "warnings": warnings,
        "violations": violations,
        "leakage_violations": leakage_violations,
        "evaluation_violations": evaluation_violations,
    }


def enforce_data_leakage_gate(
    report: Dict[str, object],
    context: str = "",
) -> bool:
    """
    跨 split 泄露的默认硬门：只要审计发现内容重复（窗口级、
    群组级或内容定义分块级的跨 split 重复），就拒绝继续，
    而不是仅打印警告。

    与 ``enforce_strict_data_audit`` 的分工：
    - 本函数默认启用，只拦截「泄露」这一类问题；
    - 越界 token、UTF-8/NUL 损坏等标签噪声仍由
      ``--strict-data-audit`` 控制，避免默认行为因少量脏字节
      直接中断；
    - ``--allow-data-leakage`` 是显式豁免，用于确认重复内容
      在业务上不是泄露的场景；豁免会写入运行协议，跨运行
      对比时不会被静默忽略。

    返回 False 表示调用方必须拒绝训练/拒绝解封测试集。
    """
    leakage = report.get("leakage_violations") or []

    if not leakage:
        # 通过也必须交代证据边界：窗口签名扫描可能只是抽样，
        # 「没拦下泄露」不等于「数据里没有泄露」。
        coverage = report.get("leakage_scan_coverage") or {}
        residual = coverage.get("residual_risk")
        if residual:
            print(f"[data] 泄露门通过（未发现跨 split 重复）：{residual}")
        return True

    where = f"（{context}）" if context else ""
    print(f"[data] 跨 split 泄露检查未通过{where}：")
    for violation in leakage:
        print(f"[data]   泄露: {violation}")
    print(
        "[data] 默认拒绝在泄露数据上继续。请先去重/清洗数据；"
        "若已确认这些重复内容不构成泄露，可显式传 "
        "--allow-data-leakage（会被记录进配置）。"
    )

    return False


def enforce_evaluation_duplicate_gate(
    report: Dict[str, object],
    context: str = "",
) -> bool:
    """
    评估集重复样本硬门：val/test 内部完全重复的群组会虚增
    评估样本量，并让固定窗口 bootstrap 把同一条样本重复计入，
    从而低估评估不确定性；验证集重复还会让 checkpoint 选型在
    相同样本上过拟合。

    val/test 不参与清洗（清洗评估集会改变被评估的分布），
    因此默认拒绝继续，要求重新切分/去重或在确认重复是目标
    分布的一部分时显式传 ``--allow-eval-duplicates``。返回
    False 表示调用方必须拒绝训练/拒绝解封测试集。
    """
    duplicates = report.get("evaluation_violations") or []

    if not duplicates:
        return True

    where = f"（{context}）" if context else ""
    print(f"[data] 评估集重复样本检查未通过{where}：")
    for violation in duplicates:
        print(f"[data]   重复: {violation}")
    print(
        "[data] val/test 不参与清洗；重复评估样本会虚增有效样本"
        "并使区间偏窄。请先去重后重新切分，或在确认这些重复"
        "属于目标分布时显式传 --allow-eval-duplicates"
        "（会被记录进配置）。"
    )

    return False


def enforce_strict_data_audit(
    report: Dict[str, object],
    context: str = "",
) -> bool:
    """
    严格数据审计：报告中存在致命问题（数据泄露/标签噪声）时
    打印明细并返回 False，否则返回 True。

    调用方据此拒绝开始训练或拒绝解封测试集：宁可停在这一步，
    也不在已泄露的数据上产出「看起来有效」的结论。
    """
    violations = report.get("violations") or []

    if not violations:
        return True

    where = f"（{context}）" if context else ""
    print(f"[data] 严格数据审计未通过{where}：")
    for violation in violations:
        print(f"[data]   严重: {violation}")

    return False


def test_label_integrity_violations(
    report: Dict[str, object],
) -> List[str]:
    """
    返回测试集标签完整性问题的明细（越界 token、非法 UTF-8、
    NUL）。只看 ``splits["test"]``，train/val 的同类问题仍由
    ``--strict-data-audit`` 控制。

    测试集是最终结论的唯一证据，不能像训练集那样在事后清洗
    （清洗 test 会改变被评估的分布，也等于用测试数据做决策）。
    因此在解封前默认拒绝带标签噪声的测试集，而不是在损坏的
    标签上报告一个看似精确的最终指标。
    """
    test_info = (report.get("splits") or {}).get("test")
    if not isinstance(test_info, dict):
        return []

    violations: List[str] = []
    invalid = int(test_info.get("invalid_tokens", 0) or 0)
    if invalid > 0:
        violations.append(
            f"test: {invalid} 个越界 token（标签超出词表）"
        )
    replacements = int(
        test_info.get("utf8_replacements", 0) or 0
    )
    if replacements > 0:
        violations.append(
            f"test: {replacements} 个无法按 UTF-8 解码的"
            "字节（标签噪声）"
        )
    nul_bytes = int(test_info.get("nul_bytes", 0) or 0)
    if nul_bytes > 0:
        violations.append(
            f"test: {nul_bytes} 个 NUL 字节（二进制/填充污染）"
        )
    return violations


def enforce_test_label_integrity(
    report: Dict[str, object],
    context: str = "test",
) -> bool:
    """
    测试集标签完整性硬门：测试集永远不参与清洗，因此带标签
    噪声的测试集不能给出可信的最终指标。默认拒绝解封；只有
    显式 ``--allow-corrupt-test-labels`` 才放行，且豁免会写入
    运行记录。
    """
    violations = test_label_integrity_violations(report)
    if not violations:
        return True

    where = f"（{context}）" if context else ""
    print(f"[test] 测试集标签完整性检查未通过{where}：")
    for violation in violations:
        print(f"[test]   标签噪声: {violation}")
    print(
        "[test] 测试集不参与清洗，带标签噪声的最终指标不可信；"
        "默认拒绝解封。若这些字节确实是目标分布的一部分，"
        "可显式传 --allow-corrupt-test-labels（会被记录）。"
    )
    return False


def distribution_shift_violations(
    report: Dict[str, object],
    max_byte_js: Optional[float] = None,
    max_bigram_js: Optional[float] = None,
    max_conditional_js: Optional[float] = None,
) -> List[str]:
    """
    按显式阈值检查数据审计中的分布偏移指标。

    JS 距离越大表示两个 split 的分布差异越大；阈值只在该
    flag 被显式设置时生效，默认仍保留「警告但继续」的诊断
    模式。返回逐对 split 的超阈值说明。

    ``max_byte_js`` 同时约束时间边界块（相邻 split 的尾/头
    分布）：只检查全局直方图会让切分边界附近的突变漏过硬门。
    """
    checks = (
        ("distribution_shift", "字节分布 JS", max_byte_js),
        (
            "distribution_shift_bigram",
            "字节二元组分布 JS",
            max_bigram_js,
        ),
        (
            "distribution_shift_conditional",
            "条件标签分布 JS",
            max_conditional_js,
        ),
    )
    violations: List[str] = []

    for field, label, limit in checks:
        if limit is None:
            continue
        limit_value = _finite_float(limit)
        if limit_value is None:
            continue
        values = report.get(field) or {}
        if not isinstance(values, dict):
            continue
        for pair, value in values.items():
            distance = _finite_float(value)
            if distance is None:
                continue
            if distance > limit_value:
                violations.append(
                    f"{pair}: {label} = {distance:.4f} "
                    f"> 阈值 {limit_value:.4f}"
                )

    # 全局分布可能把边界两侧的漂移平均掉；显式设置单字节
    # 阈值时，边界块也必须受同一个硬门约束。
    if max_byte_js is not None:
        limit_value = _finite_float(max_byte_js)
        boundary = report.get("temporal_boundary_shift") or {}
        pairs = (
            boundary.get("pairs")
            if isinstance(boundary, dict)
            else None
        )
        if limit_value is not None and isinstance(pairs, dict):
            for pair, info in pairs.items():
                if not isinstance(info, dict):
                    continue
                distance = _finite_float(info.get("js"))
                if distance is None:
                    continue
                if distance > limit_value:
                    violations.append(
                        f"{pair}: 时间边界字节分布 JS = "
                        f"{distance:.4f} > 阈值 "
                        f"{limit_value:.4f}"
                    )

    return violations


def enforce_distribution_shift_gate(
    report: Dict[str, object],
    max_byte_js: Optional[float] = None,
    max_bigram_js: Optional[float] = None,
    max_conditional_js: Optional[float] = None,
    context: str = "",
) -> bool:
    """
    分布偏移硬门：显式设置阈值后，超阈值的 train/val（以及
    解封时的 test）偏移会拒绝继续，而不是只打印警告。

    分布偏移本身不等于数据泄露：它说明训练与评估数据来自
    不同分布，指标可能包含外推。拒绝继续是为了迫使先检查
    切分/时间顺序或调整评估口径，避免把外推误差当成方法
    收益。未设置任何阈值时返回 True。
    """
    violations = distribution_shift_violations(
        report,
        max_byte_js=max_byte_js,
        max_bigram_js=max_bigram_js,
        max_conditional_js=max_conditional_js,
    )
    if not violations:
        return True

    where = f"（{context}）" if context else ""
    print(f"[data] 分布偏移检查未通过{where}：")
    for violation in violations:
        print(f"[data]   偏移: {violation}")
    print(
        "[data] 默认拒绝在分布偏移超阈值的数据上继续；"
        "请检查切分/时间顺序与评估口径，或显式放宽/去掉 "
        "--max-byte-shift / --max-bigram-shift / "
        "--max-conditional-shift。"
    )
    return False


def print_data_audit(report: Dict[str, object]) -> None:
    """打印数据审计摘要与全部警告。"""
    splits = report.get("splits", {})
    parts = [
        (
            f"{name}={info['bytes']}B"
            + (
                f"(有效 {info['effective_bytes']}B)"
                if info.get("effective_bytes")
                != info.get("bytes")
                else ""
            )
        )
        for name, info in splits.items()
    ]
    print("[data] 数据审计: " + ", ".join(parts))

    isolation = report.get("split_isolation")
    if isinstance(isolation, dict):
        print(
            "[data]   时序隔离: "
            + " < ".join(isolation.get("split_order") or [])
            + "，bounds="
            + ", ".join(
                f"{name}={bounds[0]}..{bounds[1]}"
                for name, bounds in (
                    isolation.get("bounds") or {}
                ).items()
            )
            + (
                "，连续且无重叠"
                if isolation.get("contiguous")
                and int(isolation.get("overlap_bytes", 0)) == 0
                else "，边界异常"
            )
        )

    fractions = report.get("dataset_split_fractions") or {}
    if fractions:
        print(
            "[data]   实际 split 占比: "
            + ", ".join(
                f"{name}:{_format_finite(value)}"
                for name, value in fractions.items()
            )
        )

    groups = report.get("groups")
    if isinstance(groups, dict):
        per_split = groups.get("groups_per_split") or {}
        print(
            "[data]   群组划分: 分隔符长度 "
            f"{groups.get('separator_length')}B, "
            "groups="
            + ", ".join(
                f"{name}:{count}"
                for name, count in per_split.items()
            )
        )

    cleaning = report.get("train_cleaning")
    if isinstance(cleaning, dict):
        kinds = ", ".join(
            str(kind)
            for kind in (cleaning.get("cleaning_kinds") or [])
        )
        detail_parts: List[str] = []
        if cleaning.get("groups_total") is not None:
            detail_parts.append(
                f"drop={cleaning.get('groups_dropped')}"
                f"/{cleaning.get('groups_total')} 群组"
            )
        if cleaning.get("dropped_bytes") is not None:
            detail_parts.append(
                f"{cleaning.get('dropped_bytes')}B"
            )
        if cleaning.get("valid_window_starts") is not None:
            detail_parts.append(
                "valid_starts="
                f"{cleaning.get('valid_window_starts')}"
                f"/{cleaning.get('total_window_starts')}"
            )
        print(
            "[data]   训练集清洗"
            + (f"（{kinds}）" if kinds else "")
            + ": "
            + ", ".join(detail_parts)
        )

        bias = cleaning.get("deletion_bias")
        if isinstance(bias, dict):
            bias_parts = [
                f"drop_fraction={bias.get('drop_fraction')}",
                f"byte_js={bias.get('byte_js')}",
                f"bigram_js={bias.get('bigram_js')}",
            ]
            print(
                "[data]   清洗删除偏差: "
                + ", ".join(bias_parts)
                + (
                    "（删除非随机，清洗前后分布不可直接比较）"
                    if (
                        _finite_float(bias.get("drop_fraction"))
                        is not None
                        and _finite_float(bias.get("drop_fraction"))
                        > _AUDIT_DELETION_DROP_WARN
                    )
                    or (
                        _finite_float(bias.get("byte_js"))
                        is not None
                        and _finite_float(bias.get("byte_js"))
                        > _AUDIT_DELETION_BIAS_WARN
                    )
                    else ""
                )
            )

    label_coverage = report.get("label_coverage") or {}
    train_coverage = label_coverage.get("train")
    if isinstance(train_coverage, dict):
        print(
            "[data]   训练集标签覆盖: "
            f"{train_coverage.get('observed_byte_classes')}/256 "
            "个字节类"
        )
    for split, info in label_coverage.items():
        if split == "train" or not isinstance(info, dict):
            continue
        print(
            f"[data]   {split} 标签覆盖: 未见 "
            f"{info.get('unseen_label_classes')} 类，占评估 "
            "token "
            f"{_format_finite(info.get('unseen_label_token_share'), '.4%')}"
        )

    if isinstance(groups, dict):
        health = groups.get("content_health")
        if isinstance(health, dict):
            print(
                "[data]   训练群组异常值: "
                f"degenerate={health.get('degenerate_groups')}"
                f"/{health.get('long_groups_checked')} "
                "长群组（单一字节占比阈值 "
                f"{health.get('top_share_threshold')}），"
                "最大占比 "
                f"{_format_finite(health.get('max_top_byte_share'))}"
            )

        duplicates = groups.get("content_duplicates") or {}
        for pair, info in (
            duplicates.get("cross_split") or {}
        ).items():
            print(
                f"[data]   群组内容重复 {pair} = "
                f"{info.get('shared_groups')}"
            )

    for key, distance in report.get(
        "distribution_shift",
        {},
    ).items():
        print(
            f"[data]   {key} 字节分布 JS 距离 = "
            f"{_format_finite(distance)}"
        )

    for key, distance in report.get(
        "distribution_shift_bigram",
        {},
    ).items():
        print(
            f"[data]   {key} 字节二元组分布 JS 距离 = "
            f"{_format_finite(distance)}"
        )

    for key, distance in report.get(
        "distribution_shift_conditional",
        {},
    ).items():
        unseen_share = (
            report.get("unseen_transition_share", {}).get(key, 0.0)
        )
        print(
            f"[data]   {key} 条件标签分布 JS 距离 = "
            f"{_format_finite(distance)} "
            "(未见转移 "
            f"{_format_finite(unseen_share, '.1%')})"
        )

    for key, info in report.get(
        "duplicate_windows",
        {},
    ).items():
        if "shared_signatures" in info:
            print(
                f"[data]   {key} 共享窗口签名数 = "
                f"{info['shared_signatures']}"
            )

    coverage = report.get("leakage_scan_coverage") or {}
    per_split_coverage = coverage.get("per_split") or {}
    if per_split_coverage:
        print(
            "[data]   泄露窗口扫描覆盖: "
            + ", ".join(
                f"{name}:{info['sampled']}/{info['total']}"
                + (
                    f"(stride={info['stride']})"
                    if int(info["stride"]) > 1
                    else ""
                )
                for name, info in per_split_coverage.items()
                if int(info["total"]) > 0
            )
            + (
                "（穷尽扫描）"
                if coverage.get("exhaustive")
                else "（抽样扫描，零发现 ≠ 无泄露）"
            )
        )

    chunks = report.get("content_chunks") or {}
    for key, info in (
        chunks.get("cross_split") or {}
    ).items():
        if info.get("shared_chunks", 0) > 0:
            print(
                f"[data]   {key} 共享内容定义块 = "
                f"{info['shared_chunks']} "
                f"({info['shared_bytes']}B)"
            )

    near = report.get("near_duplicates")
    if isinstance(near, dict):
        print(
            "[data]   近重复审计: "
            f"flagged={near.get('groups_flagged')}"
            f"/{near.get('groups_scanned')} 群组, "
            f"Jaccard>={near.get('threshold')}, "
            f"shingle={near.get('shingle_bytes')}B, "
            f"candidates={near.get('candidate_pairs')}"
            + (
                "（含 test 内容）"
                if near.get("test_content_used")
                else "（仅 val）"
            )
        )
        for example in (near.get("examples") or [])[:3]:
            if not isinstance(example, (list, tuple)) or len(
                example
            ) < 6:
                continue
            print(
                "[data]     近重复示例: "
                f"[{example[0]},{example[1]}) ≈ "
                f"[{example[4]},{example[5]}) "
                f"reason={example[2]} J={example[3]}"
            )

    eval_near = report.get("evaluation_near_duplicates")
    if isinstance(eval_near, dict):
        print(
            "[data]   评估集近重复审计: "
            f"Jaccard>={eval_near.get('threshold')}, "
            f"shingle={eval_near.get('shingle_bytes')}B, "
            f"candidates={eval_near.get('candidate_pairs')}"
            + (
                "（含 test 内容）"
                if eval_near.get("test_content_used")
                else "（仅 val）"
            )
        )
        for split, info in (
            eval_near.get("per_split") or {}
        ).items():
            print(
                f"[data]     {split}: 可比群组 "
                f"{info.get('groups_scanned')}, "
                f"近重复对 {info.get('within_pairs')}, "
                f"有效群组 {info.get('effective_groups')}"
                f"/{info.get('groups_scanned')}, "
                "最大簇 "
                f"{info.get('largest_cluster_groups')}"
            )
        for pair, info in (
            eval_near.get("cross_split") or {}
        ).items():
            if int(info.get("pairs", 0)) <= 0:
                continue
            print(
                f"[data]     {pair} 跨 split 近重复对 = "
                f"{info.get('pairs')}"
            )

    violation_set = set(report.get("violations", []))

    for warning in report.get("warnings", []):
        # 致命问题在下面以「严重」单独打印，避免重复两遍。
        if warning not in violation_set:
            print(f"[data] 警告: {warning}")

    for violation in report.get("violations", []):
        print(f"[data] 严重: {violation}")


# ============================================================
# Class-imbalance-aware metrics
# ============================================================
#
# 指标口径说明（多分类、类别不平衡场景）：
# - 下一 token 预测是 256 类单标签多分类问题，字节分布天然
#   高度不平衡（空格/换行/常见字母 vs 罕见控制字节）；
# - token accuracy 单独看会被高频字节抬高，必须与
#   majority_accuracy（常数预测器参考）对照解读，并用
#   macro / weighted F1 补充逐类视角；
# - 单标签多分类下 micro-F1 数值恒等于 token accuracy，
#   两者都保留是为了让键名明确交代「micro」口径；
# - macro F1 只对评估 split 中出现过的类（support > 0）
#   求平均，避免给从未出现的字节类记 0 分拉低均值；
# - one-vs-rest 的 macro PR-AUC / ROC-AUC 只统计 support
#   不小于 _AUC_MIN_SUPPORT 的类。极度不平衡时优先看
#   PR-AUC：ROC-AUC 会因负样本基数巨大、FPR 增长缓慢而
#   给出过于乐观的分数。

# macro AUC 只纳入 support 达到该阈值的字节类。
_AUC_MIN_SUPPORT = 20

# AUC 计算最多保留的评估位置数。超出时不再截取评估序列
# 前缀（会让后段窗口系统性缺席），而是在全局评估位置上等距
# 抽样，并记录覆盖率与抽样方式。
_AUC_MAX_TOKENS = 100_000

# AUC 收集每次处理的最大行数；分块 softmax 与整批结果逐位一致。
_AUC_SOFTMAX_CHUNK_ROWS = 8192

# AUC 分块排序的块大小上限（纳入类数 × 评估位置数）。
_AUC_SORT_CHUNK_ELEMENTS = 1_600_000


def _auc_uniform_sample_positions(
    total_positions: int,
    capacity: int,
) -> Optional[torch.Tensor]:
    """
    在全部评估位置上等距抽取 capacity 个位置。

    ``total_positions <= capacity`` 时返回 None（无需抽样，直接
    全量收集）。否则用全局位置步长 floor(i·N/K) 抽样，保证前后
    段窗口都有代表，而不是只保留序列前缀。
    """
    if capacity <= 0 or total_positions <= capacity:
        return None
    if capacity == 1:
        return torch.tensor(
            [total_positions // 2],
            dtype=torch.int64,
        )
    step = float(total_positions - 1) / float(capacity - 1)
    positions = torch.round(
        torch.arange(capacity, dtype=torch.float64) * step
    ).to(torch.int64)
    positions.clamp_(0, total_positions - 1)
    return torch.unique(positions)


def confusion_matrix_metrics(
    confusion: torch.Tensor,
) -> Dict[str, float]:
    """
    从 [n_classes, n_classes] 混淆矩阵（行 = 目标类，
    列 = 预测类）计算 token accuracy 与 micro / macro /
    weighted F1 以及 macro / weighted precision、recall，
    还有多数类参考 accuracy。

    返回键全部不带 split 前缀，由调用方加上
    （val_ / test_），并保证口径在文档中显式说明：
    - ``token_accuracy`` / ``micro_f1``：micro 口径
      （单标签多分类下两者恒等；micro precision =
      micro recall = accuracy，故不单列）；
    - ``macro_f1`` / ``precision_macro`` / ``recall_macro``：
      对 support > 0 的类求算术平均（每类等权，少数类
      退化不会被高频类掩盖）；
    - ``weighted_f1`` / ``precision_weighted`` /
      ``recall_weighted``：按各类 support 加权平均；
    - ``majority_accuracy``：把所有位置都预测成评估集
      中最频繁字节时的 accuracy，是类别不平衡下
      解读 accuracy 的下界参考。

    precision / recall 让假设里「按研究目标选指标」（如
    「召回率不低于 90%」）真正可判定，而不是登记一个
    评估管线从不计算的指标。
    """
    confusion = confusion.double()
    total = confusion.sum()

    if float(total) <= 0.0:
        return {
            "token_accuracy": float("nan"),
            "micro_f1": float("nan"),
            "macro_f1": float("nan"),
            "weighted_f1": float("nan"),
            "precision_macro": float("nan"),
            "precision_weighted": float("nan"),
            "recall_macro": float("nan"),
            "recall_weighted": float("nan"),
            "majority_accuracy": float("nan"),
            "classes_present": 0.0,
        }

    support = confusion.sum(dim=1)
    predicted = confusion.sum(dim=0)
    true_positive = confusion.diagonal()

    precision = true_positive / predicted.clamp(min=1.0)
    recall = true_positive / support.clamp(min=1.0)

    denominator = precision + recall
    f1 = torch.zeros_like(true_positive)
    nonzero = denominator > 0.0
    f1[nonzero] = (
        2.0
        * precision[nonzero]
        * recall[nonzero]
        / denominator[nonzero]
    )

    present = support > 0.0

    return {
        "token_accuracy": float(
            true_positive.sum() / total
        ),
        "micro_f1": float(true_positive.sum() / total),
        "macro_f1": float(f1[present].mean()),
        "weighted_f1": float(
            (f1 * support).sum() / total
        ),
        "precision_macro": float(precision[present].mean()),
        "precision_weighted": float(
            (precision * support).sum() / total
        ),
        "recall_macro": float(recall[present].mean()),
        "recall_weighted": float(
            (recall * support).sum() / total
        ),
        "majority_accuracy": float(
            support.max() / total
        ),
        "classes_present": float(present.sum()),
    }


def class_balanced_loss_metrics(
    class_loss_sums: torch.Tensor,
    class_counts: torch.Tensor,
    vocab_size: int,
) -> Dict[str, float]:
    """
    类平衡（macro）似然口径：对评估集中出现的每个目标类等权
    平均每类 NLL。

    ``val_loss`` 是按 token 频率加权的平均：字节级语料里
    少数高频字节（空格、换行、常见标点）占绝大多数 token，
    稀有字节即使完全没学会，val_loss 也几乎不动——用频率
    加权的似然判定「学会了上下文」会系统性偏乐观。macro NLL
    先对每个类算它自己的平均 NLL，再对类等权平均，是似然
    口径下与 macro F1 对应的类平衡指标（不平衡场景下与
    macro F1 / PR-AUC 一起看才有意义）。

    随机水平参照 ``macro_nll_chance`` = log(vocab_size)：
    均匀预测器对每个类的 NLL 都恰为 log V，类平衡平均后不变，
    因此它是任何模型必须显著低于的绝对下限。

    ``macro_nll_min_support`` 披露被纳入的最小类 support：
    只有 1~2 个样本的稀有类会让 macro NLL 的方差被放大，
    解读时必须看到这一项（与 macro F1 同样的注意事项）。
    """
    counts = class_counts.to(torch.float64)
    sums = class_loss_sums.to(torch.float64)
    present = counts > 0.0

    chance = math.log(float(vocab_size))

    if not bool(present.any()):
        return {
            "macro_nll": float("nan"),
            "macro_nll_classes": 0.0,
            "macro_nll_chance": chance,
            "macro_nll_min_support": 0.0,
        }

    per_class = sums[present] / counts[present]
    return {
        "macro_nll": float(per_class.mean()),
        "macro_nll_classes": float(int(present.sum())),
        "macro_nll_chance": chance,
        "macro_nll_min_support": float(counts[present].min()),
    }


# 评估集不确定性：对固定评估窗口做有放回重采样。窗口是
# 评估协议的最小独立单位（同一窗口内 token 高度相关），
# 逐 token 重采样会低估不确定性。
_EVAL_BOOTSTRAP_CI_LEVEL = 0.95

# 评估窗口 lag-1 自相关达到该阈值时，把 bootstrap 区间按
# AR(1) 方差膨胀因子放宽（见 _bootstrap_eval_intervals）。
# 0.3 是「明显正自相关」的经验门槛：低于它时样本 ρ̂1 本身
# 的抽样噪声与调整量同量级，调整反而引入随机扰动；只放宽
# 不收窄，负相关不用于把区间做窄。
_EVAL_WINDOW_AUTOCORRELATION = 0.3

# 评估窗口 bootstrap 的重采样次数。该常量必须在使用它的
# 函数默认参数之前定义（模块导入时即求值），因此放在评估
# 不确定性工具区的开头。
_EVAL_WINDOW_BOOTSTRAP_REPLICATES = 2000

# 防御损坏/伪造报告里的超大重采样次数：再大既没有实际
# 统计收益，也无法在有限内存内完成。正常配置远低于该上限。
_MAX_BOOTSTRAP_REPLICATES = 10_000_000


def _eval_bootstrap_seed(
    data_sha256: str,
    split: str,
    batches: int,
    batch_size: int,
    seq_len: int,
) -> int:
    """
    由数据指纹与评估协议生成稳定的 bootstrap 随机种子。

    不使用全局 RNG：最终/测试评估的置信区间必须在同一
    运行内可复现，且不能扰动训练或数据采样轨迹。
    """
    material = (
        f"{data_sha256}|{split}|{batches}|{batch_size}|"
        f"{seq_len}|bootstrap-v1"
    ).encode("utf-8")
    return int.from_bytes(
        hashlib.blake2b(material, digest_size=8).digest(),
        "big",
    )


def _percentile_interval(
    values: torch.Tensor,
    ci_level: float,
) -> Tuple[float, float]:
    """返回 [lower, upper] 分位区间（线性插值）。"""
    lower = (1.0 - ci_level) / 2.0
    upper = 1.0 - lower
    quantiles = torch.quantile(
        values.to(torch.float64).reshape(-1),
        torch.tensor(
            [lower, upper],
            dtype=torch.float64,
        ),
    )
    return float(quantiles[0]), float(quantiles[1])


def _lag1_autocorrelation(
    values: torch.Tensor,
) -> Optional[float]:
    """
    序列的 lag-1 自相关 ρ̂1；样本不足或方差为 0 时返回 None。

    bootstrap 把窗口当 i.i.d. 抽样单位，但固定窗口沿评估序列
    排列，窗口指标常随数据顺序渐变（同一类块、主题相邻等）。
    正自相关会让区间偏窄；报告 ρ̂1 与 AR(1) 有效窗口数
    n·(1-ρ)/(1+ρ) 用于方差膨胀。ρ̂1 只依赖顺序与数值，与
    bootstrap 随机数无关。
    """
    numeric = values.to(torch.float64).reshape(-1)
    n = int(numeric.numel())
    if n < 4 or not bool(torch.isfinite(numeric).all()):
        return None
    # 合法的大数值（如 1e308）会让 ``head.mean()`` 与平方和溢出
    # 成 inf；此时 ``inf / inf`` 得到 NaN，后续 clamp 会把它变成
    # 伪造的 rho=1（常数序列也会被误判为强正自相关）。自相关对
    # 公共尺度不变，按最大绝对值归一化后再计算；正常量级保持
    # 原路径，避免改变历史结果的末位舍入。
    scale = float(numeric.abs().max().item())
    if scale > 1.0e150 or 0.0 < scale < 1.0e-150:
        numeric = numeric / scale
    head = numeric[:-1]
    tail = numeric[1:]
    head = head - head.mean()
    tail = tail - tail.mean()
    # 正常量级沿用「平方和相乘后开方」以保持历史末位；两个
    # 平方和各自可能合法但很小（如 1e-200），先相乘会在 1e-400
    # 量级下溢成 0，此时改用分别开方后相乘（数学等价）。
    head_square = float((head * head).sum())
    tail_square = float((tail * tail).sum())
    product = head_square * tail_square
    if product > 0.0 and math.isfinite(product):
        denominator = math.sqrt(product)
    else:
        denominator = math.sqrt(head_square) * math.sqrt(tail_square)
    if float(denominator) <= 0.0:
        return None
    raw_rho = float((head * tail).sum() / denominator)
    return max(-1.0, min(1.0, raw_rho))


def _ar1_effective_windows(
    n_windows: int,
    rho1: Optional[float],
) -> Tuple[float, float]:
    """
    由 ρ̂1 给出 AR(1) 有效窗口数与区间方差膨胀因子。

    负相关不用于缩窄区间（只放宽不收窄）：ρ→-1 时
    n·(1-ρ)/(1+ρ) 发散甚至除零（完全交替序列 ρ̂1 恰为 -1），
    此时直接取 n。ρ̂1 达到 _EVAL_WINDOW_AUTOCORRELATION 才
    启用膨胀，低于阈值时样本 ρ̂ 的噪声与调整量同量级。
    """
    if rho1 is None:
        return float(n_windows), 1.0
    if rho1 <= 0.0:
        effective = float(n_windows)
    elif rho1 >= 0.999:
        effective = 1.0
    else:
        effective = max(
            1.0,
            min(
                float(n_windows),
                float(n_windows)
                * (1.0 - rho1)
                / (1.0 + rho1),
            ),
        )
    inflation = 1.0
    if rho1 >= _EVAL_WINDOW_AUTOCORRELATION:
        inflation = math.sqrt(float(n_windows) / effective)
    return effective, inflation


def _ar1_adjusted_mean_test(
    values: List[float],
) -> Dict[str, object]:
    """
    对逐窗口配对差值的均值做 AR(1) 有效窗口数校正检验。

    普通配对 t 检验把沿评估序列排列的窗口当独立样本；固定
    窗口可能重叠或同属相邻主题块，正自相关会让标准误偏小。
    这里用 ρ̂1 推导有效窗口数 n_eff = n(1-ρ)/(1+ρ)，把标准误
    放大 sqrt(n/n_eff)，自由度取 n_eff-1。只放宽不收窄；ρ̂1
    低于阈值时不调整。n_eff<3 时不给 p 值（有效证据不足），
    避免用 1 个有效窗口伪造显著性。
    """
    n = len(values)
    if n < _MIN_SEEDS_FOR_STATS:
        return {
            "applied": False,
            "lag1_autocorrelation": None,
            "effective_windows": float(n),
            "ci_inflation": 1.0,
            "p_value": None,
            "df": None,
            "note": "insufficient_windows",
        }
    numeric = _finite_values(values)
    if numeric is None:
        return {
            "applied": False,
            "lag1_autocorrelation": None,
            "effective_windows": float(n),
            "ci_inflation": 1.0,
            "p_value": None,
            "df": None,
            "note": "non_finite_values",
        }
    values = numeric

    tensor = torch.tensor(values, dtype=torch.float64)
    rho1 = _lag1_autocorrelation(tensor)
    effective, inflation = _ar1_effective_windows(n, rho1)
    result: Dict[str, object] = {
        "applied": inflation > 1.0,
        "lag1_autocorrelation": rho1,
        "effective_windows": effective,
        "ci_inflation": inflation,
        "p_value": None,
        "df": None,
        "note": None,
    }
    if inflation <= 1.0:
        result["note"] = "autocorrelation_below_threshold"
        return result

    mean = _mean(values)
    std = _sample_std(values)
    if mean is None or std is None:
        result["note"] = "invalid_values"
        return result
    se = std / math.sqrt(n) * inflation
    if not math.isfinite(se):
        result["note"] = "invalid_values"
        return result
    if se == 0.0:
        if mean == 0.0:
            result["p_value"] = 1.0
            result["df"] = None
            result["note"] = "zero_variance"
        else:
            result["p_value"] = 0.0
            result["df"] = None
            result["note"] = "noise_free_separation"
        return result

    if effective < _MIN_SEEDS_FOR_STATS:
        result["note"] = "effective_windows_below_three"
        return result

    df = effective - 1.0
    t_value = mean / se
    result["t"] = t_value
    result["se"] = se
    result["df"] = df
    result["p_value"] = _two_sided_t_p_value(
        abs(t_value),
        df,
    )
    return result


# ============================================================
# 文档/群组 cluster bootstrap
# ============================================================

# 评估窗口不是天然的独立抽样单位：同一文档会被多个重叠窗口
# 覆盖，同一来源/主题的相邻文档也高度相关。窗口级 bootstrap
# 把同一文档的重复证据当成独立样本，会系统性低估评估不确定性。
# 有 --group-separator 时，把每个目标 token 归入其所属群组，
# 以群组为 resampling unit；没有群组边界时不伪造簇。
_GROUP_STATS_SCHEMA = "smelt-isr/eval-group-stats/v1"
_GROUP_ASSIGNMENT = (
    "split_group_starts_gaps_to_preceding_v1"
)


def _empty_group_stats_state(
    n_groups: int,
) -> Dict[str, torch.Tensor]:
    """逐群组充分统计量的累加缓冲（CPU float64）。"""
    return {
        "tokens": torch.zeros(n_groups, dtype=torch.float64),
        "loss_sum": torch.zeros(n_groups, dtype=torch.float64),
        "correct": torch.zeros(n_groups, dtype=torch.float64),
    }


def _finalize_group_stats(
    state: Dict[str, torch.Tensor],
    *,
    group_separator_sha256: Optional[str],
) -> Dict[str, object]:
    """
    把逐群组累加缓冲变成可落盘的记录。

    ``groups`` 只保留在固定评估窗口中出现过 token 的群组；
    每条记录是 ``[group_id, tokens, loss_sum, correct]``。
    群组 id 是 split 内部的 0 基序号，不含绝对字节位置，
    因此同一数据协议下的不同运行可以直接按 id 配对。
    """
    tokens = state["tokens"].to(torch.float64)
    loss_sum = state["loss_sum"].to(torch.float64)
    correct = state["correct"].to(torch.float64)
    observed = (
        torch.isfinite(tokens)
        & torch.isfinite(loss_sum)
        & torch.isfinite(correct)
        & (tokens > 0.0)
    )
    indices = torch.nonzero(observed, as_tuple=False).reshape(-1)
    records: List[List[object]] = []
    for index in indices.tolist():
        records.append([
            int(index),
            float(tokens[index].item()),
            float(loss_sum[index].item()),
            float(correct[index].item()),
        ])
    observed_tokens = float(
        sum(float(record[1]) for record in records)
    )
    return {
        "schema": _GROUP_STATS_SCHEMA,
        "assignment": _GROUP_ASSIGNMENT,
        "unit": "document_group",
        "group_separator_sha256": group_separator_sha256,
        "n_groups_total": int(tokens.numel()),
        "n_groups_observed": len(records),
        "tokens_observed": (
            observed_tokens
            if math.isfinite(observed_tokens)
            else None
        ),
        "groups": records,
        "note": (
            "group id 是 split 内部 0 基群组序号；分隔符与空群组"
            "并入前一个群组，前导分隔符并入第一个群组。"
            "cluster bootstrap 以群组为抽样单位；没有群组边界"
            "时不生成该记录"
        ),
    }


def _parse_group_stats(
    payload: object,
) -> Optional[Dict[str, object]]:
    """
    解析并校验 eval_windows.json 里的 ``group_stats``。

    损坏/缺字段/重复 id/非有限值一律返回 None：不能把无法
    核对的群组记录当成可用证据。
    """
    if not isinstance(payload, dict):
        return None
    stats = payload.get("group_stats")
    if not isinstance(stats, dict):
        return None
    if stats.get("schema") != _GROUP_STATS_SCHEMA:
        return None
    if stats.get("assignment") != _GROUP_ASSIGNMENT:
        return None
    records = stats.get("groups")
    if not isinstance(records, list) or not records:
        return None
    mapping: Dict[int, Tuple[float, float, float]] = {}
    for record in records:
        if not isinstance(record, (list, tuple)):
            return None
        if len(record) < 4:
            return None
        group_id = record[0]
        if (
            not isinstance(group_id, int)
            or isinstance(group_id, bool)
            or group_id < 0
        ):
            return None
        tokens = _finite_float(record[1])
        loss_sum = _finite_float(record[2])
        correct = _finite_float(record[3])
        if (
            tokens is None
            or loss_sum is None
            or correct is None
            or tokens <= 0.0
            or loss_sum < 0.0
            or correct < 0.0
            or correct > tokens + 1e-9
        ):
            return None
        if group_id in mapping:
            return None
        mapping[group_id] = (tokens, loss_sum, correct)
    separator = stats.get("group_separator_sha256")
    if separator is not None and not isinstance(separator, str):
        return None
    unit = stats.get("unit")
    if unit is not None and not isinstance(unit, str):
        return None
    return {
        "mapping": mapping,
        "group_separator_sha256": separator,
        "unit": unit,
    }


def _group_stats_bootstrap_ci(
    point_values: torch.Tensor,
    weights: torch.Tensor,
    replicates: int,
    generator: torch.Generator,
    ci_level: float = _EVAL_BOOTSTRAP_CI_LEVEL,
) -> Optional[Tuple[float, float]]:
    """按群组有放回重采样、再加权平均的分位区间。"""
    try:
        replicate_count = int(replicates)
    except (TypeError, ValueError, OverflowError):
        return None
    if (
        isinstance(ci_level, bool)
        or not isinstance(ci_level, (int, float))
    ):
        return None
    try:
        level = float(ci_level)
    except OverflowError:
        return None
    if not 0.0 < level < 1.0:
        return None
    n_groups = int(point_values.numel())
    if (
        n_groups < 2
        or replicate_count <= 1
        or replicate_count > _MAX_BOOTSTRAP_REPLICATES
    ):
        return None
    if (
        point_values.dim() != 1
        or weights.dim() != 1
        or int(weights.numel()) != n_groups
        or not bool(torch.isfinite(point_values).all())
        or not bool(torch.isfinite(weights).all())
        or bool((weights < 0.0).any())
    ):
        return None
    value_scale = float(point_values.abs().max().item())
    if value_scale > 1.0e150 or 0.0 < value_scale < 1.0e-150:
        point_values = point_values / value_scale
    else:
        value_scale = 1.0
    max_weight = float(weights.abs().max().item())
    if max_weight <= 0.0:
        return None
    if max_weight > 1.0e150 or max_weight < 1.0e-150:
        weights = weights / max_weight
    indices = torch.randint(
        low=0,
        high=n_groups,
        size=(replicate_count, n_groups),
        generator=generator,
    )
    sampled_weights = weights[indices].sum(dim=1)
    valid = sampled_weights > 0.0
    if not bool(valid.any()):
        return None
    sampled = (
        (point_values[indices] * weights[indices]).sum(dim=1)
        / sampled_weights
    )
    sampled = sampled[valid]
    if sampled.numel() == 0:
        return None
    low, high = _percentile_interval(sampled, level)
    low *= value_scale
    high *= value_scale
    if not (math.isfinite(low) and math.isfinite(high)):
        return None
    return low, high


def _group_cluster_eval_intervals(
    group_stats: Dict[str, object],
    replicates: int,
    seed: int,
    ci_level: float = _EVAL_BOOTSTRAP_CI_LEVEL,
) -> Dict[str, object]:
    """
    以文档/群组为单位的评估集 cluster bootstrap 区间。

    逐窗口 bootstrap 把同一文档上的重叠窗口当独立样本；本函数
    用 ``group_stats`` 的逐群组 loss 和/正确数直接重采样群组，
    给出 token 加权的 loss / ppl / token accuracy 区间。它不
    替代窗口级区间，而是回答「换一批同分布文档」时点估计有
    多不确定；没有群组记录时返回不可用。
    """
    parsed = _parse_group_stats({
        "group_stats": group_stats,
    })
    if parsed is None:
        return {
            "available": False,
            "reason": "missing_or_invalid_group_stats",
        }
    if isinstance(ci_level, bool) or not isinstance(
        ci_level, (int, float)
    ):
        return {
            "available": False,
            "reason": "invalid_ci_level",
            "ci_level": _finite_float(ci_level),
        }
    try:
        level = float(ci_level)
    except (TypeError, ValueError, OverflowError):
        return {
            "available": False,
            "reason": "invalid_ci_level",
            "ci_level": _finite_float(ci_level),
        }
    if not 0.0 < level < 1.0:
        return {
            "available": False,
            "reason": "invalid_ci_level",
            "ci_level": _finite_float(ci_level),
        }
    try:
        replicate_count = int(replicates)
    except (TypeError, ValueError, OverflowError):
        return {
            "available": False,
            "reason": "invalid_bootstrap_replicates",
            "replicates": _finite_float(replicates),
        }
    if replicate_count <= 1:
        return {
            "available": False,
            "reason": "insufficient_bootstrap_replicates",
            "replicates": replicate_count,
        }
    if replicate_count > _MAX_BOOTSTRAP_REPLICATES:
        return {
            "available": False,
            "reason": "invalid_bootstrap_replicates",
            "replicates": None,
        }
    if parsed["unit"] not in (None, "document_group"):
        return {
            "available": False,
            "reason": "unsupported_group_unit",
            "unit": parsed["unit"],
        }
    mapping = parsed["mapping"]
    assert isinstance(mapping, dict)
    group_ids = sorted(mapping)
    if len(group_ids) < 2:
        return {
            "available": False,
            "reason": "fewer_than_two_document_groups",
            "n_groups": len(group_ids),
        }
    tokens = torch.tensor(
        [mapping[group_id][0] for group_id in group_ids],
        dtype=torch.float64,
    )
    loss_sums = torch.tensor(
        [mapping[group_id][1] for group_id in group_ids],
        dtype=torch.float64,
    )
    correct = torch.tensor(
        [mapping[group_id][2] for group_id in group_ids],
        dtype=torch.float64,
    )
    loss_point = loss_sums / tokens
    scale = float(loss_point.abs().max().item())
    if scale > 1.0e150:
        loss_scaled = loss_point / scale
    elif 0.0 < scale < 1.0e-150:
        # 极小 loss 的加权和可能下溢；归一化后还原。
        loss_scaled = loss_point / scale
    else:
        scale = 1.0
        loss_scaled = loss_point
    accuracy_point = correct / tokens
    try:
        seed_value = int(seed) % (2 ** 64)
    except (TypeError, ValueError, OverflowError):
        return {
            "available": False,
            "reason": "invalid_bootstrap_seed",
        }
    generator = torch.Generator().manual_seed(seed_value)
    loss_interval = _group_stats_bootstrap_ci(
        loss_scaled,
        tokens,
        replicate_count,
        generator,
        level,
    )
    accuracy_interval = _group_stats_bootstrap_ci(
        accuracy_point,
        tokens,
        replicate_count,
        generator,
        level,
    )
    if loss_interval is None:
        return {
            "available": False,
            "reason": "bootstrap_unavailable",
            "n_groups": len(group_ids),
        }
    low = loss_interval[0] * scale
    high = loss_interval[1] * scale
    if not (math.isfinite(low) and math.isfinite(high)):
        return {
            "available": False,
            "reason": "unrepresentable_bounds",
            "n_groups": len(group_ids),
        }
    token_total = float(tokens.sum().item())
    result: Dict[str, object] = {
        "available": True,
        "n_groups": len(group_ids),
        "tokens": (
            token_total if math.isfinite(token_total) else None
        ),
        "bootstrap_replicates": replicate_count,
        "bootstrap_ci_level": level,
        "bootstrap_unit": "document_group",
        "loss_ci95_low": max(0.0, low),
        "loss_ci95_high": max(0.0, high),
        "ppl_ci95_low": math.exp(min(80.0, max(0.0, low))),
        "ppl_ci95_high": math.exp(min(80.0, max(0.0, high))),
        "method": "group_cluster_percentile_bootstrap",
        "note": (
            "以文档/群组为重采样单位的 token 加权区间；"
            "群组来自 --group-separator。它反映换一批同分布"
            "文档的评估不确定性，不替代训练种子级检验"
        ),
    }
    if accuracy_interval is not None:
        result["token_accuracy_ci95_low"] = min(
            1.0, max(0.0, accuracy_interval[0])
        )
        result["token_accuracy_ci95_high"] = min(
            1.0, max(0.0, accuracy_interval[1])
        )
    return result


def _group_cluster_paired_comparison(
    payload_a: Dict[str, object],
    payload_b: Dict[str, object],
    include_differences: bool = False,
) -> Optional[Dict[str, object]]:
    """
    两个运行在同一批固定评估窗口上的文档/群组级配对比较。

    两个运行的 ``group_stats`` 必须来自同一群组定义（分隔符
    指纹与 assignment 版本一致），且共同群组的 token 数逐项
    相同；否则不是同一批评估单位，直接返回不可用原因。差值 =
    b − a，按群组内 token 加权汇总；bootstrap 以群组为单位
    有放回重采样。

    该区间只覆盖「换一批同分布文档」的评估不确定性；训练
    随机性仍由种子级检验负责。群组数很少时百分位区间很粗，
    只作描述性证据。
    """
    parsed_a = _parse_group_stats(payload_a)
    parsed_b = _parse_group_stats(payload_b)
    if parsed_a is None and parsed_b is None:
        return None
    if parsed_a is None or parsed_b is None:
        return {
            "available": False,
            "reason": "group_stats_missing_in_one_run",
        }
    if parsed_a["unit"] != parsed_b["unit"]:
        return {
            "available": False,
            "reason": "group_unit_mismatch",
            "unit_a": parsed_a["unit"],
            "unit_b": parsed_b["unit"],
        }
    if parsed_a["unit"] not in (None, "document_group"):
        return {
            "available": False,
            "reason": "unsupported_group_unit",
            "unit": parsed_a["unit"],
        }
    if (
        parsed_a["group_separator_sha256"]
        != parsed_b["group_separator_sha256"]
    ):
        return {
            "available": False,
            "reason": "group_separator_mismatch",
        }
    mapping_a = parsed_a["mapping"]
    mapping_b = parsed_b["mapping"]
    assert isinstance(mapping_a, dict)
    assert isinstance(mapping_b, dict)
    common = sorted(set(mapping_a) & set(mapping_b))
    if len(common) < 2:
        return {
            "available": False,
            "reason": "fewer_than_two_common_groups",
            "n_common_groups": len(common),
        }
    tokens: List[float] = []
    loss_differences: List[float] = []
    accuracy_differences: List[float] = []
    for group_id in common:
        tokens_a, loss_a, correct_a = mapping_a[group_id]
        tokens_b, loss_b, correct_b = mapping_b[group_id]
        if not math.isclose(
            tokens_a,
            tokens_b,
            rel_tol=1e-12,
            abs_tol=0.0,
        ):
            return {
                "available": False,
                "reason": "group_token_count_mismatch",
                "group_id": group_id,
                "tokens_a": tokens_a,
                "tokens_b": tokens_b,
            }
        loss_differences.append(
            loss_b / tokens_b - loss_a / tokens_a
        )
        accuracy_differences.append(
            correct_b / tokens_b - correct_a / tokens_a
        )
        tokens.append(tokens_a)
    weight_tensor = torch.tensor(
        tokens,
        dtype=torch.float64,
    )
    difference_tensor = torch.tensor(
        loss_differences,
        dtype=torch.float64,
    )
    scale = float(difference_tensor.abs().max().item())
    if scale > 1.0e150 or 0.0 < scale < 1.0e-150:
        scaled_differences = difference_tensor / scale
    else:
        scale = 1.0
        scaled_differences = difference_tensor
    seed_values = loss_differences
    if all(math.isfinite(value) for value in loss_differences):
        seed_scale = max(
            abs(value) for value in loss_differences
        )
        if seed_scale > 0.0:
            seed_values = [
                float(f"{value / seed_scale:.12g}")
                for value in loss_differences
            ]
    generator = torch.Generator().manual_seed(
        _randomization_seed(seed_values)
    )
    interval = _group_stats_bootstrap_ci(
        scaled_differences,
        weight_tensor,
        _EVAL_WINDOW_BOOTSTRAP_REPLICATES,
        generator,
    )
    if interval is None:
        return {
            "available": False,
            "reason": "bootstrap_unavailable",
            "n_common_groups": len(common),
        }
    low = interval[0] * scale
    high = interval[1] * scale
    weight_scale = float(weight_tensor.abs().max().item())
    if (
        weight_scale > 1.0e150
        or 0.0 < weight_scale < 1.0e-150
    ):
        mean_weights = weight_tensor / weight_scale
    else:
        mean_weights = weight_tensor
    weighted_mean = float(
        (
            scaled_differences * mean_weights
        ).sum().item()
        / float(mean_weights.sum().item())
    ) * scale
    unweighted_mean = _mean(loss_differences)
    accuracy_weights = weight_tensor
    accuracy_tensor = torch.tensor(
        accuracy_differences,
        dtype=torch.float64,
    )
    accuracy_interval = _group_stats_bootstrap_ci(
        accuracy_tensor,
        accuracy_weights,
        _EVAL_WINDOW_BOOTSTRAP_REPLICATES,
        torch.Generator().manual_seed(
            _randomization_seed(accuracy_differences)
        ),
    )
    token_total = float(weight_tensor.sum().item())
    result: Dict[str, object] = {
        "available": True,
        "n_groups": len(common),
        "tokens": (
            token_total if math.isfinite(token_total) else None
        ),
        "group_separator_sha256": (
            parsed_a["group_separator_sha256"]
        ),
        "mean_loss_diff": weighted_mean,
        "unweighted_mean_loss_diff": unweighted_mean,
        "median_loss_diff": _median(loss_differences),
        "fraction_groups_better": (
            sum(
                1
                for value in loss_differences
                if value < 0.0
            )
            / len(loss_differences)
        ),
        "bootstrap_ci95": {
            "available": bool(
                math.isfinite(low) and math.isfinite(high)
            ),
            "low": low if math.isfinite(low) else None,
            "high": high if math.isfinite(high) else None,
            "replicates": _EVAL_WINDOW_BOOTSTRAP_REPLICATES,
            "method": "group_cluster_percentile_bootstrap",
        },
        "sign_test": _exact_sign_test(loss_differences),
        "method": "document_group_cluster_bootstrap",
        "note": (
            "以文档/群组为单位的配对评估证据；差值按群组内 "
            "token 加权。群组数少时区间很粗，且与种子级检验"
            "来自同一批运行，不是独立验证"
        ),
    }
    if accuracy_interval is not None:
        result["mean_accuracy_diff"] = (
            float(
                (
                    accuracy_tensor * mean_weights
                ).sum().item()
            )
            / float(mean_weights.sum().item())
        )
        result["accuracy_bootstrap_ci95"] = {
            "low": min(
                1.0, max(-1.0, accuracy_interval[0])
            ),
            "high": min(
                1.0, max(-1.0, accuracy_interval[1])
            ),
            "replicates": _EVAL_WINDOW_BOOTSTRAP_REPLICATES,
        }
    if include_differences:
        result["group_differences"] = [
            [
                int(group_id),
                float(difference),
                float(token),
            ]
            for group_id, difference, token in zip(
                common,
                loss_differences,
                tokens,
            )
        ]
    return result


def _hierarchical_group_bootstrap_ci(
    per_seed_group_differences: Dict[
        int, Dict[int, Tuple[float, float]]
    ],
    replicates: int = _EVAL_WINDOW_BOOTSTRAP_REPLICATES,
) -> Dict[str, object]:
    """
    种子 × 文档/群组交叉 design 的两层 cluster bootstrap。

    每个种子给出「群组 → (差值, token 数)」；只保留所有种子
    都有的群组，并核对 token 数一致。先有放回重采样种子，再
    对所有抽中的种子共用同一组群组下标做有放回重采样，最后
    对交叉重采样后的 token 加权差值取种子平均。区间反映
    「换一批训练种子 + 换一批同分布文档」的联合不确定性。
    """
    if not isinstance(per_seed_group_differences, dict):
        return {
            "available": False,
            "reason": "invalid_seed_group_differences",
        }
    try:
        replicate_count = int(replicates)
    except (TypeError, ValueError, OverflowError):
        return {
            "available": False,
            "reason": "invalid_bootstrap_replicates",
            "replicates": _finite_float(replicates),
        }
    if replicate_count <= 1:
        return {
            "available": False,
            "reason": "insufficient_bootstrap_replicates",
            "replicates": replicate_count,
        }
    if replicate_count > _MAX_BOOTSTRAP_REPLICATES:
        return {
            "available": False,
            "reason": "invalid_bootstrap_replicates",
            "replicates": None,
        }
    replicates = replicate_count
    cleaned: Dict[int, Dict[int, Tuple[float, float]]] = {}
    for seed, mapping in per_seed_group_differences.items():
        if (
            not isinstance(seed, int)
            or isinstance(seed, bool)
            or not isinstance(mapping, dict)
        ):
            continue
        entry: Dict[int, Tuple[float, float]] = {}
        for group_id, value in mapping.items():
            if (
                not isinstance(group_id, int)
                or isinstance(group_id, bool)
                or group_id < 0
                or not isinstance(value, (list, tuple))
                or len(value) < 2
            ):
                continue
            difference = _finite_float(value[0])
            tokens = _finite_float(value[1])
            if (
                difference is None
                or tokens is None
                or tokens <= 0.0
            ):
                continue
            entry[int(group_id)] = (difference, tokens)
        if entry:
            cleaned[int(seed)] = entry
    if len(cleaned) < 2:
        return {
            "available": False,
            "reason": "insufficient_seeds_or_groups",
            "n_seeds": len(cleaned),
        }
    seed_order = sorted(cleaned)
    common_groups = set(cleaned[seed_order[0]])
    for seed in seed_order[1:]:
        common_groups &= set(cleaned[seed])
    group_order = sorted(common_groups)
    if len(group_order) < 2:
        return {
            "available": False,
            "reason": "insufficient_seeds_or_groups",
            "n_seeds": len(seed_order),
            "n_groups": len(group_order),
        }
    reference_tokens = [
        cleaned[seed_order[0]][group_id][1]
        for group_id in group_order
    ]
    for seed in seed_order[1:]:
        tokens = [
            cleaned[seed][group_id][1]
            for group_id in group_order
        ]
        if any(
            not math.isclose(
                left,
                right,
                rel_tol=1e-12,
                abs_tol=0.0,
            )
            for left, right in zip(reference_tokens, tokens)
        ):
            return {
                "available": False,
                "reason": "group_token_count_mismatch",
                "n_seeds": len(seed_order),
                "n_groups": len(group_order),
            }
    seed_count = len(seed_order)
    group_count = len(group_order)
    values = torch.tensor(
        [
            [
                cleaned[seed][group_id][0]
                for group_id in group_order
            ]
            for seed in seed_order
        ],
        dtype=torch.float64,
    )
    tokens = torch.tensor(
        reference_tokens,
        dtype=torch.float64,
    )
    scale = float(values.abs().max().item())
    if scale > 1.0e150 or 0.0 < scale < 1.0e-150:
        values = values / scale
    else:
        scale = 1.0
    token_scale = max(reference_tokens)
    if token_scale > 1.0e150 or 0.0 < token_scale < 1.0e-150:
        token_weights = tokens / token_scale
    else:
        token_weights = tokens
    value_scale = float(values.abs().max().item())
    if math.isfinite(value_scale) and value_scale > 0.0:
        seed_values = [
            [
                float(f"{value:.12g}")
                for value in row
            ]
            for row in (values / value_scale).tolist()
        ]
    else:
        seed_values = values.tolist()
    token_seed_scale = max(
        abs(value) for value in reference_tokens
    )
    if math.isfinite(token_seed_scale) and token_seed_scale > 0.0:
        seed_tokens = [
            float(f"{value / token_seed_scale:.12g}")
            for value in reference_tokens
        ]
    else:
        seed_tokens = list(reference_tokens)
    generator = torch.Generator().manual_seed(
        _randomization_seed(
            [
                value
                for row in seed_values
                for value in row
            ]
            + seed_tokens
        )
    )
    seed_indices = torch.randint(
        low=0,
        high=seed_count,
        size=(replicate_count, seed_count),
        generator=generator,
    )
    group_indices = torch.randint(
        low=0,
        high=group_count,
        size=(replicate_count, group_count),
        generator=generator,
    )
    sampled_groups = group_indices
    sampled_tokens = token_weights[sampled_groups]
    sampled_total = sampled_tokens.sum(dim=1)
    usable_draws = (
        torch.isfinite(sampled_total) & (sampled_total > 0.0)
    )
    if not bool(usable_draws.any()):
        return {
            "available": False,
            "reason": "bootstrap_unavailable",
            "n_seeds": seed_count,
            "n_groups": group_count,
        }
    sampled_groups = sampled_groups[usable_draws]
    sampled_tokens = sampled_tokens[usable_draws]
    sampled_total = sampled_total[usable_draws]
    seed_indices = seed_indices[usable_draws]
    seed_means = torch.empty(
        (int(sampled_groups.size(0)), seed_count),
        dtype=torch.float64,
    )
    for column in range(seed_count):
        sampled_values = values[column][sampled_groups]
        seed_means[:, column] = (
            (sampled_values * sampled_tokens).sum(dim=1)
            / sampled_total
        )
    draws = (
        torch.gather(seed_means, 1, seed_indices).mean(dim=1)
        * scale
    )
    low = float(torch.quantile(draws, 0.025).item())
    high = float(torch.quantile(draws, 0.975).item())
    if not (math.isfinite(low) and math.isfinite(high)):
        return {
            "available": False,
            "reason": "unrepresentable_bounds",
            "n_seeds": seed_count,
            "n_groups": group_count,
        }
    return {
        "available": True,
        "low": low,
        "high": high,
        "replicates": int(replicates),
        "n_seeds": seed_count,
        "n_groups": group_count,
        "method": "crossed_seed_group_percentile_bootstrap",
        "resampling": "seeds_and_document_groups_with_replacement",
        "note": (
            "同时反映训练种子与文档/群组两层不确定性；"
            "群组按可交换单位重采样。种子或群组数很少时"
            "百分位区间很粗，只作描述性证据"
        ),
    }


def _bootstrap_window_indices(
    n_windows: int,
    replicates: int,
    generator: torch.Generator,
    block_size: int = 1,
) -> torch.Tensor:
    """窗口重采样下标：i.i.d. 或循环移动块。

    block_size>1 时先抽取 n_blocks=ceil(n/block_size) 个块起点，
    再拼接连续窗口（循环取模），最后截断到 n。它把相邻窗口
    成块重采样，部分吸收局部自相关；按文档/来源做 cluster
    bootstrap 仍然更合适，这里只是窗口级近似。
    """
    n = int(n_windows)
    reps = int(replicates)
    try:
        requested_block = int(block_size)
    except (TypeError, ValueError, OverflowError):
        requested_block = 1
    if requested_block <= 1:
        return torch.randint(
            low=0,
            high=n,
            size=(reps, n),
            generator=generator,
        )
    # 块长超过窗口数时，前 n 个循环偏移量本来就恰好是 0..n-1
    # 的一个排列；按 n 截断只改变中间分配大小，不改变抽样结果。
    # 不截断会让 --eval-bootstrap-block 的合法超大整数先分配
    # arange(block) 并耗尽内存。
    block = max(1, min(n, requested_block))
    n_blocks = int(math.ceil(n / block))
    starts = torch.randint(
        low=0,
        high=n,
        size=(reps, n_blocks),
        generator=generator,
    )
    offsets = torch.arange(block)
    indices = (
        starts.unsqueeze(-1) + offsets
    ) % n
    return indices.reshape(reps, -1)[:, :n]


def _bootstrap_eval_intervals(
    window_loss_sums: torch.Tensor,
    window_tokens: torch.Tensor,
    window_true_positive: torch.Tensor,
    window_predicted: torch.Tensor,
    window_support: torch.Tensor,
    replicates: int,
    seed: int,
    ci_level: float = _EVAL_BOOTSTRAP_CI_LEVEL,
    window_class_loss_sums: Optional[torch.Tensor] = None,
    block_size: int = 1,
) -> Dict[str, object]:
    """
    对固定评估窗口做有放回 bootstrap，给出评估集层面的
    95% 置信区间。

    覆盖的指标：
    - 似然口径：loss / ppl；以及传入逐窗口逐类损失时
      的 macro NLL（与点估计同口径，对出现类等权）；
    - 分类口径：token accuracy（micro）、macro / weighted
      F1、macro / weighted precision / recall。

    口径说明：
    - 重采样单位是完整评估窗口，不是 token：同一窗口内的
      token 由同一段上下文产生，逐 token 重采样会把相关样本
      当成独立样本，低估评估不确定性；
    - macro / weighted F1、precision、recall 的类别集合按
      每个重采样中实际出现的类确定（support>0），与点估计
      「只对评估集中出现过的类平均 / 按 support 加权」完全
      同口径。若固定为全量类别集合、把重采样缺席的稀有类按
      F1=0 计入，区间会系统性偏低，甚至不覆盖点估计；
    - macro NLL 同样只对本次重采样中出现过的类等权平均；
      逐窗口逐类损失足够统计量由评估循环与混淆统计共用同一次
      前向，不额外跑模型；
    - 重采样不进入训练、选型或超参数决策，只用于报告
      「测试集只评估一次」时点估计本身的抽样误差；
    - AR(1) 方差膨胀是一阶近似，膨胀后的区间会夹到指标的
      物理取值域（loss≥0、ppl≥1、比例类∈[0,1]）；
    - 只覆盖混淆矩阵/似然口径的指标；AUC 等排序指标未纳入。

    返回的键不带 split 前缀，由 ``evaluate`` 统一加前缀。
    """
    n_windows = int(window_tokens.numel())
    try:
        replicate_count = int(replicates)
    except (TypeError, ValueError, OverflowError):
        return {}
    try:
        requested_block = int(block_size)
    except (TypeError, ValueError, OverflowError):
        requested_block = 1
    if isinstance(ci_level, bool) or not isinstance(
        ci_level, (int, float)
    ):
        return {}
    try:
        level = float(ci_level)
    except (TypeError, ValueError, OverflowError):
        return {}
    try:
        seed_value = int(seed) % (2 ** 64)
    except (TypeError, ValueError, OverflowError):
        return {}
    if (
        replicate_count <= 1
        or replicate_count > _MAX_BOOTSTRAP_REPLICATES
        or n_windows <= 0
        or not math.isfinite(level)
        or not 0.0 < level < 1.0
    ):
        return {}
    block = max(1, min(n_windows, requested_block))

    generator = torch.Generator().manual_seed(seed_value)
    indices = _bootstrap_window_indices(
        n_windows,
        replicate_count,
        generator,
        block_size=block,
    )

    loss_sums = window_loss_sums.to(torch.float64)
    tokens = window_tokens.to(torch.float64)
    sampled_loss = (
        loss_sums[indices].sum(dim=1)
        / tokens[indices].sum(dim=1)
    )
    sampled_ppl = torch.exp(sampled_loss.clamp(max=80.0))

    true_positive = window_true_positive.to(torch.float64)
    predicted = window_predicted.to(torch.float64)
    support = window_support.to(torch.float64)

    sampled_tp = true_positive[indices].sum(dim=1)
    sampled_predicted = predicted[indices].sum(dim=1)
    sampled_support = support[indices].sum(dim=1)
    sampled_total_support = sampled_support.sum(dim=1)

    sampled_accuracy = (
        sampled_tp.sum(dim=1)
        / sampled_total_support.clamp_min(1.0)
    )

    precision = sampled_tp / sampled_predicted.clamp_min(1.0)
    recall = sampled_tp / sampled_support.clamp_min(1.0)
    denominator = precision + recall
    f1 = torch.zeros_like(sampled_tp)
    nonzero = denominator > 0.0
    f1[nonzero] = (
        2.0
        * precision[nonzero]
        * recall[nonzero]
        / denominator[nonzero]
    )
    # 每个重采样都有自己的类别集合：只对本次抽样中 support>0
    # 的类求平均。固定全量类别集合会把「本次抽样恰好没有该
    # 稀有类」当成 F1=0，使 bootstrap 分布整体下移。
    sampled_present = sampled_support > 0.0
    sampled_class_counts = sampled_present.sum(dim=1)
    sampled_macro_f1 = (
        (f1 * sampled_present).sum(dim=1)
        / sampled_class_counts.clamp_min(1.0)
    )
    sampled_precision_macro = (
        (precision * sampled_present).sum(dim=1)
        / sampled_class_counts.clamp_min(1.0)
    )
    sampled_recall_macro = (
        (recall * sampled_present).sum(dim=1)
        / sampled_class_counts.clamp_min(1.0)
    )
    sampled_weighted_f1 = (
        (f1 * sampled_support).sum(dim=1)
        / sampled_total_support.clamp_min(1.0)
    )
    sampled_precision_weighted = (
        (precision * sampled_support).sum(dim=1)
        / sampled_total_support.clamp_min(1.0)
    )
    sampled_recall_weighted = (
        (recall * sampled_support).sum(dim=1)
        / sampled_total_support.clamp_min(1.0)
    )
    degenerate_macro = sampled_class_counts == 0
    if bool(degenerate_macro.any()):
        for values in (
            sampled_macro_f1,
            sampled_precision_macro,
            sampled_recall_macro,
        ):
            values[degenerate_macro] = float("nan")

    # 类平衡似然的逐窗口逐类损失和：按同一组窗口索引重采样，
    # 再对本次重采样中出现过的类等权平均每类 NLL。
    sampled_macro_nll: Optional[torch.Tensor] = None
    if (
        window_class_loss_sums is not None
        and int(window_class_loss_sums.size(0)) == n_windows
    ):
        class_losses = window_class_loss_sums.to(torch.float64)
        sampled_class_loss = torch.empty(
            (int(replicates), int(class_losses.size(1))),
            dtype=torch.float64,
        )
        # 分块累加，避免 replicates × windows × vocab 的
        # 三维中间张量在较大评估集上占用过多内存。
        chunk = 64
        for begin in range(0, int(replicates), chunk):
            stop = min(begin + chunk, int(replicates))
            sampled_class_loss[begin:stop] = (
                class_losses[indices[begin:stop]].sum(dim=1)
            )
        per_class_nll = (
            sampled_class_loss
            / sampled_support.clamp_min(1.0)
        )
        sampled_macro_nll = (
            (per_class_nll * sampled_present).sum(dim=1)
            / sampled_class_counts.clamp_min(1.0)
        )
        sampled_macro_nll[degenerate_macro] = float("nan")

    # 窗口间 lag-1 自相关：bootstrap 把窗口当 i.i.d. 抽样单位，
    # 但固定窗口沿评估序列排列，窗口指标常随数据顺序渐变（同一
    # 类块、主题相邻等），正自相关会让区间偏窄。ρ̂1 达到阈值时
    # 按方差膨胀因子 √(n/n_eff) 放宽全部区间（以区间中点为中心
    # 等比放大，一阶近似；只放宽不收窄，负相关不用于缩窄）。
    per_window_loss = (
        window_loss_sums.to(torch.float64)
        / window_tokens.to(torch.float64).clamp_min(1.0)
    )
    rho1 = _lag1_autocorrelation(per_window_loss)
    effective_windows, inflation = _ar1_effective_windows(
        n_windows,
        rho1,
    )

    result: Dict[str, object] = {
        "bootstrap_replicates": int(replicates),
        "bootstrap_windows": n_windows,
        "bootstrap_ci_level": level,
        "window_lag1_autocorrelation": rho1,
        "window_effective_windows": effective_windows,
        "window_ci_inflation": inflation,
    }

    # 指标的物理取值域：AR(1) 膨胀是一阶近似，膨胀后可能
    # 把区间推到指标不可能出现的范围（如负准确率、loss<0）。
    # 写出报告前夹回域内，避免读者把不可能的边界当成有效
    # 估计；夹取只放宽到域边界，不会把区间缩窄到点估计之外。
    metric_bounds: Dict[str, Tuple[Optional[float], Optional[float]]] = {
        "loss": (0.0, None),
        "ppl": (1.0, None),
        "macro_nll": (0.0, None),
        "token_accuracy": (0.0, 1.0),
        "macro_f1": (0.0, 1.0),
        "weighted_f1": (0.0, 1.0),
        "precision_macro": (0.0, 1.0),
        "precision_weighted": (0.0, 1.0),
        "recall_macro": (0.0, 1.0),
        "recall_weighted": (0.0, 1.0),
    }

    metric_series = [
        ("loss", sampled_loss),
        ("ppl", sampled_ppl),
        ("token_accuracy", sampled_accuracy),
        ("macro_f1", sampled_macro_f1),
        ("weighted_f1", sampled_weighted_f1),
        ("precision_macro", sampled_precision_macro),
        ("precision_weighted", sampled_precision_weighted),
        ("recall_macro", sampled_recall_macro),
        ("recall_weighted", sampled_recall_weighted),
    ]
    if sampled_macro_nll is not None:
        metric_series.append(("macro_nll", sampled_macro_nll))

    for name, values in metric_series:
        finite = values[torch.isfinite(values)]
        if finite.numel() == 0:
            continue
        # 退化重采样（如 macro F1 抽到的窗口没有任何 support）
        # 会产生 NaN；直接对含 NaN 的张量取分位数会让整个区间
        # 变成 NaN。只用有限重采样估计区间，并显式记录退化数。
        degenerate = int(values.numel() - finite.numel())
        if degenerate > 0:
            result[f"{name}_bootstrap_degenerate"] = degenerate
        low, high = _percentile_interval(finite, level)
        if inflation > 1.0:
            # 所有纳入区间的指标都非负，用 low + (high - low)/2
            # 而不是 (low + high)/2：后者在端点都接近 float
            # 上限时会先溢出成 inf，把合法区间变成 ±inf。
            midpoint = low + (high - low) / 2.0
            half_width = (high - low) / 2.0 * inflation
            low = midpoint - half_width
            high = midpoint + half_width
            if not (
                math.isfinite(low) and math.isfinite(high)
            ):
                # 膨胀后的区间超出 float 可表示范围：不写出
                # inf/NaN 端点，保留点估计与诊断量。
                result[f"{name}_bootstrap_unavailable"] = (
                    "unrepresentable_bounds"
                )
                continue
        lower_bound, upper_bound = metric_bounds[name]
        if lower_bound is not None:
            low = max(low, lower_bound)
        if upper_bound is not None:
            high = min(high, upper_bound)
        result[f"{name}_ci95_low"] = low
        result[f"{name}_ci95_high"] = high

    result["bootstrap_unit"] = (
        "moving_block" if block > 1 else "window_iid"
    )
    result["bootstrap_block_size"] = int(block)
    result["bootstrap_note"] = (
        "窗口级重采样只近似评估不确定性；连续/重叠窗口应按"
        "文档/来源做 cluster bootstrap，块 bootstrap 仅部分"
        "吸收局部自相关"
    )
    return result


def macro_auc_metrics(
    probabilities: torch.Tensor,
    targets: torch.Tensor,
    vocab_size: int,
    min_support: int = _AUC_MIN_SUPPORT,
) -> Dict[str, object]:
    """
    one-vs-rest 的 macro PR-AUC 与 ROC-AUC。

    probabilities: [n_tokens, vocab] 的预测分布；
    targets: [n_tokens] 的目标类。只统计 support 达到
    min_support 的类，返回值同时记录纳入类数，保证
    「macro」的口径（对哪些类求平均）可追溯。

    ROC-AUC 的 TPR/FPR 都以真实类别为条件，其期望不随
    prevalence 变化；负样本更多只会让 FPR 估计更精确，不会
    把 AUC 本身抬高。真正的问题是：正类极稀有且分数区分度
    一般时，高 ROC-AUC 仍可能对应很低的 precision/recall，
    PR-AUC 的随机水平又等于 prevalence——因此排序指标要
    报告 PR-AUC 相对随机水平的 lift 与 precision@k，而不是
    把绝对 PR-AUC 当归一化准确率。

    同时返回 ``pr_auc_macro_chance``：macro PR-AUC 的随机
    水平（各纳入类 prevalence 的均值），以及
    ``pr_auc_macro_lift`` = ``pr_auc_macro - chance``。PR-AUC
    本身随正类比例缩放，脱离该水平看绝对值没有意义；
    1:1000 级别的不平衡下随机 PR-AUC 只有约 0.001，而随机
    ROC-AUC 仍是 0.5，两者的「及格线」完全不同。lift 的
    随机水平恒为 0，是不随 prevalence 缩放的一等指标，
    可直接用于预注册、跨运行对比与稻草人核对。

    每个类独立做 one-vs-rest：ROC-AUC 为并列分数取平均
    秩的 Mann-Whitney 统计量；PR-AUC 按相异分数阈值分步
    累计（与 sklearn average_precision_score 的阶梯式口径
    一致）。正类或负类为空的类按对应口径不计入 macro。

    实现按「类块 × 全部 token」分块：块内对各类分数一次
    批量排序后向量化统计，逐类结果与逐类单独排序的实现
    逐位一致——组秩与组边界均为整数运算（半整数秩以 2 倍
    整数累计，求和精确且与逐类求和同值），PR-AUC 分段
    求和的加数顺序也保持不变。
    """
    probabilities = probabilities.detach().cpu().float()
    targets = targets.detach().cpu()

    support = torch.bincount(
        targets,
        minlength=vocab_size,
    )
    eligible = torch.nonzero(
        support >= min_support
    ).squeeze(1)

    n_tokens = int(targets.numel())

    pr_aucs: List[float] = []
    roc_aucs: List[float] = []
    pr_prevalence_sum = 0.0

    if eligible.numel() > 0 and n_tokens > 0:
        # 块大小（类数 × 评估位置数）固定，块内中间量规模
        # 不随评估集增大而膨胀。
        chunk_size = max(
            1,
            _AUC_SORT_CHUNK_ELEMENTS // n_tokens,
        )
        index_i32 = torch.arange(n_tokens, dtype=torch.int32)
        invalid_i32 = torch.tensor(-1, dtype=torch.int32)
        n_i32 = torch.tensor(n_tokens, dtype=torch.int32)

        for begin in range(0, eligible.numel(), chunk_size):
            chunk = eligible[begin:begin + chunk_size]
            n_classes = int(chunk.numel())

            # 块内每个类一列：分数升序排序，ROC-AUC 与
            # PR-AUC 复用同一次排序结果。
            scores = probabilities[:, chunk].t().contiguous()
            labels = (
                targets.unsqueeze(0) == chunk.unsqueeze(1)
            )
            n_pos = labels.sum(dim=1)
            n_pos_list = n_pos.tolist()

            sorted_scores, order = torch.sort(
                scores, dim=1
            )
            sorted_labels = labels.gather(1, order)

            # 并列组：change 标记组起点；组内每个位置的
            # 1 基平均秩为 (start + end_excl + 1) / 2。
            change = torch.ones_like(
                sorted_scores, dtype=torch.bool
            )
            change[:, 1:] = (
                sorted_scores[:, 1:] != sorted_scores[:, :-1]
            )
            group_start = torch.cummax(
                torch.where(change, index_i32, invalid_i32),
                dim=1,
            ).values
            next_change = torch.flip(
                torch.cummin(
                    torch.flip(
                        torch.where(change, index_i32, n_i32),
                        dims=[1],
                    ),
                    dim=1,
                ).values,
                dims=[1],
            )
            group_end_excl = torch.cat(
                [
                    next_change[:, 1:],
                    n_i32.expand(n_classes, 1),
                ],
                dim=1,
            )

            # 平均秩恒为整数或半整数，以 2×秩 的整数和
            # 累计，除以 2 后与逐类实现的 fp64 秩和一致。
            rank_half = (
                (group_start << 1)
                + (group_end_excl - group_start)
                + 1
            )
            roc_rank_half_sums = (
                rank_half * sorted_labels
            ).sum(dim=1)

            # PR-AUC：降序排序下每个相异分数阈值组的
            # 结束位置（1 基秩）与累计真正例数。并列分数必须
            # 在整组结束时取累计命中数；若取组首会漏掉同组内
            # 后续正例，PR-AUC 系统性偏低。
            labels_desc = sorted_labels.flip(1)
            hits = torch.cumsum(labels_desc, dim=1)
            scores_desc = sorted_scores.flip(1)
            boundary = torch.ones_like(
                sorted_scores, dtype=torch.bool
            )
            boundary[:, :-1] = (
                scores_desc[:, :-1] != scores_desc[:, 1:]
            )
            boundary_counts = boundary.sum(dim=1)

            # 组边界按行主序压缩成一维：每类的边界连续，
            # split 分段即为逐类顺序。行内顺序与逐类实现
            # 的组枚举顺序相同。
            boundary_flat = (
                boundary.view(-1).nonzero().squeeze(1)
            )
            boundary_class = torch.div(
                boundary_flat,
                n_tokens,
                rounding_mode="floor",
            )
            boundary_hits = hits.view(-1).gather(
                0, boundary_flat
            )
            boundary_ranks_desc = (
                boundary_flat
                - boundary_class * n_tokens
            ).double() + 1.0

            recall = (
                boundary_hits.double()
                / n_pos.gather(
                    0, boundary_class
                ).double()
            )
            precision = (
                boundary_hits.double()
                / boundary_ranks_desc
            )

            # AP = Σ (R_i − R_{i−1}) × Precision_i；段首
            # 的 R_{i−1} 取 0，增益即该组 recall。
            recall_gain = recall.clone()
            if recall_gain.numel() > 1:
                recall_gain[1:] = recall[1:] - recall[:-1]
                boundary_start = torch.ones(
                    recall_gain.numel(), dtype=torch.bool
                )
                boundary_start[1:] = (
                    boundary_class[1:] != boundary_class[:-1]
                )
                recall_gain[boundary_start] = recall[
                    boundary_start
                ]
            ap_terms = recall_gain * precision
            ap_sums = torch.split(
                ap_terms, boundary_counts.tolist()
            )

            for class_offset in range(n_classes):
                n_pos_class = int(n_pos_list[class_offset])
                if n_pos_class > 0:
                    pr_aucs.append(
                        float(ap_sums[class_offset].sum())
                    )
                    pr_prevalence_sum += (
                        float(n_pos_class) / n_tokens
                    )
                if 0 < n_pos_class < n_tokens:
                    n_neg_class = n_tokens - n_pos_class
                    roc_aucs.append(
                        float(
                            (
                                roc_rank_half_sums[
                                    class_offset
                                ].double()
                                / 2.0
                                - n_pos_class
                                * (n_pos_class + 1)
                                / 2.0
                            )
                            / float(n_pos_class * n_neg_class)
                        )
                    )

    pr_auc_macro = (
        sum(pr_aucs) / len(pr_aucs)
        if pr_aucs
        else None
    )
    pr_auc_macro_chance = (
        pr_prevalence_sum / len(pr_aucs)
        if pr_aucs
        else None
    )
    return {
        "pr_auc_macro": pr_auc_macro,
        "pr_auc_macro_chance": pr_auc_macro_chance,
        # 相对随机水平的 lift 才是不随 prevalence 缩放的一等
        # 指标：PR-AUC 绝对值在 1:1000 不平衡下从 0.001 起步，
        # 跨数据集/不同类别构成不能直接比较；lift 的随机水平
        # 恒为 0，可直接预注册、对比与做稻草人核对。
        "pr_auc_macro_lift": (
            pr_auc_macro - pr_auc_macro_chance
            if pr_auc_macro is not None
            and pr_auc_macro_chance is not None
            else None
        ),
        "roc_auc_macro": (
            sum(roc_aucs) / len(roc_aucs)
            if roc_aucs
            else None
        ),
        # 三类计数分开记录：单类语料等退化情形下 PR 与 ROC 的
        # 可计算集合不同（全正类的 ROC 无定义），单一
        # auc_n_classes 无法同时描述两条 macro 曲线的口径。
        "auc_n_classes": len(eligible),
        "pr_auc_n_classes": len(pr_aucs),
        "roc_auc_n_classes": len(roc_aucs),
        "auc_min_support": min_support,
        "auc_tokens_evaluated": n_tokens,
    }


# ============================================================
# Evaluation
# ============================================================

# 评估张量不会回流到训练图，此处使用 inference_mode 是安全的。
@torch.inference_mode()
def evaluate(
    model: LanguageModel,
    dataset: ByteDataset,
    batch_size: int,
    batches: int,
    device: torch.device,
    amp_dtype: Optional[torch.dtype] = None,
    split: str = "val",
    compute_auc: bool = False,
    routing_probe: Optional["RoutingProbe"] = None,
    bad_case_collector: Optional["_BadCaseCollector"] = None,
    bootstrap_replicates: int = 0,
    window_sink: Optional[List[Dict[str, float]]] = None,
    bootstrap_block: int = 1,
) -> Dict[str, float]:
    """
    在指定评估 split 上计算加权平均语言模型损失与
    类别不平衡感知的分类指标。

    split 仅允许 val/test：val 用于训练期间的周期验证与选型，
    test 只在最终评估时调用一次；返回指标键带 split 前缀
    （val_loss/test_loss 等）。

    每次评估都基于同一批固定窗口累计混淆矩阵，并报告：

    - ``{split}_loss`` / ``{split}_ppl`` /
      ``{split}_bits_per_byte``：主指标（与 LM 研究目标
      对齐的似然口径）；
    - ``{split}_token_accuracy``（= micro 口径）与
      ``{split}_micro_f1``：单标签多分类下两者恒等；
    - ``{split}_macro_f1`` / ``{split}_weighted_f1``：
      必须注明平均口径，macro 只对评估集中出现过的类
      求平均；
    - ``{split}_precision_macro`` /
      ``{split}_precision_weighted`` /
      ``{split}_recall_macro`` /
      ``{split}_recall_weighted``：precision / recall 的
      macro（对出现过的类等权）与 weighted（按 support
      加权）口径；micro precision/recall 与 accuracy 恒等
      故不单列；
    - ``{split}_majority_accuracy``：常数预测器（永远
      猜最高频字节）的 accuracy，类别不平衡下解读
      accuracy 的参考下界。

    ``bootstrap_replicates > 0`` 时额外对固定评估窗口做
    有放回重采样，给出 loss / ppl / macro NLL / token accuracy /
    macro 与 weighted F1 / macro 与 weighted precision / recall
    的 95% 置信区间（``{split}_*_ci95_low/high``）。测试集
    只解封一次，点估计本身无法区分「方法差异」与「评估窗口
    抽样噪声」；置信区间是评估集层面的不确定性，与跨随机
    种子的训练方差互补，不参与训练或模型选择。假设以
    macro F1 / 召回率等分类指标判定时，区间与点估计同口径，
    不会只给 loss 不确定性而让分类结论裸奔。

    compute_auc=True 时（最终/测试评估）额外计算
    one-vs-rest 的 ``{split}_pr_auc_macro`` 与
    ``{split}_roc_auc_macro``，只纳入 support 达到
    _AUC_MIN_SUPPORT 的类；极度不平衡时优先看 PR-AUC，
    并与 ``{split}_pr_auc_macro_chance``（随机水平 =
    平均 prevalence）对照，而不是把 PR-AUC 绝对值当
    「准确率」解读。

    routing_probe 非 None 时，本次评估前向同时充当路由
    诊断的采样前向（探针在评估期间挂载、退出时卸载）：
    调用方在返回后用同一探针 build_report()；诊断只在
    val 上使用。

    window_sink 非 None 时，逐窗口记录（损失和、目标 token
    数、命中数）并追加到该列表：固定评估窗口在所有运行之间
    逐位相同，因此两个运行可以按窗口配对比较——这给出
    「在这批固定评估窗口上」的配对证据，与种子级检验
    （训练随机性）互补。
    """
    was_training = model.training
    model.eval()

    probe_attached = False
    if routing_probe is not None:
        routing_probe.attach(_unwrap_model(model))
        probe_attached = True

    use_amp = (
        amp_dtype is not None
        and device.type == "cuda"
    )

    # split 仅允许 val/test：val 用于训练期间的周期验证与选型，
    # test 只在最终评估时调用一次。

    vocab_size = _unwrap_model(model).cfg.vocab_size

    # 按目标 token 数加权累加。
    total = torch.zeros(
        (),
        device=device,
        dtype=torch.float32,
    )
    evaluated_tokens = 0

    # 混淆矩阵 [目标类, 预测类]，在评估设备上以 int64 累积，
    # 收尾时转 fp64。
    confusion = torch.zeros(
        (vocab_size, vocab_size),
        device=device,
        dtype=torch.int64,
    )

    # AUC 需要全部位置的预测概率；只在最终/测试评估时收集，
    # 并按 _AUC_MAX_TOKENS 限制。收集缓冲按固定窗口的实际
    # 位置数分配，逐批写入。
    auc_probs: Optional[torch.Tensor] = None
    auc_targets: Optional[torch.Tensor] = None
    auc_tokens = 0

    # 评估窗口级 bootstrap 的逐窗口充分统计量：窗口损失和、
    # token 数，以及每类 TP / 预测数 / support。只在最终与
    # 测试评估时收集，周期验证保持轻量。
    bootstrap_enabled = int(bootstrap_replicates) > 1
    window_loss_sums: List[torch.Tensor] = []
    window_tokens: List[torch.Tensor] = []
    window_true_positive: List[torch.Tensor] = []
    window_predicted: List[torch.Tensor] = []
    window_support: List[torch.Tensor] = []
    window_class_loss_sums: List[torch.Tensor] = []

    # 类平衡似然（macro NLL）的逐类充分统计量：按目标类累计
    # 损失和与 token 数。它与频率加权的 total 累加共用同一次
    # 前向的 logits，不额外跑模型。
    class_loss_sums = torch.zeros(
        vocab_size,
        device=device,
        dtype=torch.float64,
    )
    class_counts = torch.zeros(
        vocab_size,
        device=device,
        dtype=torch.float64,
    )

    # CUDA 路径在全部批次结束后统一同步；CPU 路径保持同步语义。
    auc_async = compute_auc and device.type == "cuda"

    auc_total_positions = 0
    auc_sample_positions: Optional[torch.Tensor] = None
    if compute_auc:
        _, eval_data = dataset._eval_windows(split)
        num_starts = len(eval_data) - dataset.seq_len
        auc_total_positions = (
            min(batches * batch_size, num_starts)
            * dataset.seq_len
        )
        auc_capacity = min(
            _AUC_MAX_TOKENS,
            auc_total_positions,
        )
        auc_sample_positions = _auc_uniform_sample_positions(
            auc_total_positions,
            auc_capacity,
        )
        auc_probs = torch.empty(
            auc_capacity,
            vocab_size,
            dtype=torch.float32,
            pin_memory=auc_async,
        )
        auc_targets = torch.empty(
            auc_capacity,
            dtype=torch.int64,
            pin_memory=auc_async,
        )
        auc_processed_positions = 0

    try:
        with torch.autocast(
            device_type="cuda",
            dtype=amp_dtype,
            enabled=use_amp,
        ):
            for batch_index in range(batches):
                x, y = dataset.fixed_eval_batch(
                    split,
                    batch_index,
                    batches,
                    batch_size,
                    device,
                )

                # 请求窗口超过验证集合法起点时，后继批次为空。
                if x.size(0) == 0:
                    break

                result = model(x, y)

                # argmax 直接取模型输出 dtype（bf16/fp16 -> fp32
                # 是精确升位，不改变数值与并列顺序）；AUC 的
                # softmax 仍在 fp32 下统计，避免半精度数值噪声
                # 影响逐类指标。
                raw_logits = result.pop("logits")

                # 坏案例收集复用同一次前向（仅最终评估传入）；
                # 不影响下面任何指标的计算与数值。
                if bad_case_collector is not None:
                    bad_case_collector.update(x, y, raw_logits)

                predicted = raw_logits.argmax(dim=-1)
                flat_target = y.reshape(-1).to(
                    torch.int64
                )
                flat_predicted = predicted.reshape(-1)

                # add(alpha=) 单次完成 target * vocab_size +
                # predicted（逐位等值）；flat_target 保持原值供
                # AUC 收集使用。
                confusion += torch.bincount(
                    torch.add(
                        flat_predicted,
                        flat_target,
                        alpha=vocab_size,
                    ),
                    minlength=vocab_size ** 2,
                ).view(
                    vocab_size,
                    vocab_size,
                )

                # 逐 token 损失：类平衡 NLL（macro_nll）与评估
                # 窗口 bootstrap 的逐窗口统计量共用它，不额外跑
                # 模型。logits 就是本批前向的输出，upcast 到
                # fp32 与 loss 计算口径一致。
                token_logits = raw_logits.reshape(
                    -1,
                    vocab_size,
                ).float()
                token_losses = F.cross_entropy(
                    token_logits,
                    flat_target,
                    reduction="none",
                )

                # 类平衡似然的逐类充分统计量：按目标类累计
                # 损失和与 token 数（fp64 累加，避免高频类的
                # 求和误差污染每类 NLL）。
                class_loss_sums.index_add_(
                    0,
                    flat_target,
                    token_losses.to(torch.float64),
                )
                class_counts.index_add_(
                    0,
                    flat_target,
                    torch.ones_like(
                        token_losses,
                        dtype=torch.float64,
                    ),
                )

                if window_sink is not None:
                    # 逐窗口统计：与整批口径同一份 logits 与
                    # 预测结果（不额外跑模型），供跨运行按窗口
                    # 配对比较使用。
                    window_losses = token_losses.view(
                        y.shape
                    ).sum(dim=1)
                    window_correct = (
                        predicted.to(torch.int64)
                        == flat_target.view(y.shape)
                    ).sum(dim=1)
                    loss_list = window_losses.detach().tolist()
                    correct_list = window_correct.detach().tolist()
                    window_token_count = int(y.size(1))
                    for row_index in range(y.size(0)):
                        window_sink.append({
                            "loss_sum": float(loss_list[row_index]),
                            "tokens": window_token_count,
                            "correct": int(correct_list[row_index]),
                        })

                if bootstrap_enabled:
                    # 逐窗口 loss 与混淆充分统计量：用与点估计
                    # 同一前向的 logits 计算，不额外跑模型。
                    window_loss_sums.append(
                        token_losses.view(y.shape)
                        .sum(dim=1)
                        .detach()
                        .to(torch.float64)
                        .cpu()
                    )
                    window_tokens.append(
                        torch.full(
                            (y.size(0),),
                            float(y.size(1)),
                            dtype=torch.float64,
                        )
                    )
                    for row in range(y.size(0)):
                        target_row = y[row].to(torch.int64)
                        predicted_row = predicted[row].to(
                            torch.int64
                        )
                        correct = target_row == predicted_row
                        window_true_positive.append(
                            torch.bincount(
                                target_row[correct],
                                minlength=vocab_size,
                            ).cpu()
                        )
                        window_predicted.append(
                            torch.bincount(
                                predicted_row,
                                minlength=vocab_size,
                            ).cpu()
                        )
                        row_support = torch.bincount(
                            target_row,
                            minlength=vocab_size,
                        )
                        window_support.append(row_support.cpu())
                        # 逐类损失和：供 macro NLL 的窗口级
                        # bootstrap 使用，与点估计共用同一批
                        # token 损失，不额外跑前向。
                        row_class_loss = torch.zeros(
                            vocab_size,
                            dtype=torch.float64,
                            device=device,
                        ).index_add_(
                            0,
                            target_row,
                            token_losses.view(y.shape)[
                                row
                            ].to(torch.float64),
                        )
                        window_class_loss_sums.append(
                            row_class_loss.cpu()
                        )

                if compute_auc:
                    flat_logits = raw_logits.reshape(
                        -1,
                        vocab_size,
                    )
                    if auc_sample_positions is None:
                        selected_logits = flat_logits
                        selected_targets = flat_target
                    else:
                        # 只对全局等距抽中的位置做 softmax：
                        # 两侧都按同一全局位置切分，避免把
                        # 后段评估窗口系统性排除。
                        start_position = (
                            auc_processed_positions
                        )
                        end_position = (
                            start_position
                            + flat_logits.size(0)
                        )
                        lower = int(
                            torch.searchsorted(
                                auc_sample_positions,
                                start_position,
                            )
                        )
                        upper = int(
                            torch.searchsorted(
                                auc_sample_positions,
                                end_position,
                            )
                        )
                        local_positions = (
                            auc_sample_positions[lower:upper]
                            - start_position
                        ).to(flat_logits.device)
                        selected_logits = flat_logits[
                            local_positions
                        ]
                        selected_targets = flat_target[
                            local_positions
                        ]
                    num_new = int(selected_logits.size(0))
                    # 按行分块：逐行 softmax 与整批等价。
                    for start in range(
                        0,
                        num_new,
                        _AUC_SOFTMAX_CHUNK_ROWS,
                    ):
                        stop = min(
                            start + _AUC_SOFTMAX_CHUNK_ROWS,
                            num_new,
                        )
                        probs = F.softmax(
                            selected_logits[
                                start:stop
                            ].float(),
                            dim=-1,
                        )
                        # 拷入 CPU 收集缓冲，循环结束统一同步。
                        auc_probs[
                            auc_tokens + start:
                            auc_tokens + stop
                        ].copy_(
                            probs,
                            non_blocking=auc_async,
                        )
                    auc_targets[
                        auc_tokens:auc_tokens + num_new
                    ].copy_(
                        selected_targets,
                        non_blocking=auc_async,
                    )
                    auc_tokens += num_new
                    auc_processed_positions += int(
                        flat_logits.size(0)
                    )

                # cross_entropy 返回批均值，乘回目标 token 数。
                # add_(alpha=) 完成「乘 token 数 + 累加」。
                total.add_(
                    result["lm_loss"].float(),
                    alpha=float(y.numel()),
                )
                evaluated_tokens += y.numel()
                del result, raw_logits, x, y
    finally:
        # 无论评估是否中途出错，都卸载探针并恢复原来的训练模式。
        if probe_attached:
            routing_probe.detach()
        model.train(was_training)

    # ByteDataset 保证至少有一个合法评估起点。
    loss = (total / evaluated_tokens).item()

    metrics = {
        f"{split}_loss": loss,
        f"{split}_ppl": math.exp(min(loss, 80.0)),
        f"{split}_bits_per_byte": loss / math.log(2.0),
    }

    class_metrics = confusion_matrix_metrics(confusion.double())

    for key, value in class_metrics.items():
        metrics[f"{split}_{key}"] = value

    # 类平衡似然口径：与频率加权的 {split}_loss 同单位（自然
    # 对数似然），但对评估集中出现的类等权，稀有字节不再被
    # 高频字节淹没。类别不平衡场景下它才是「有没有真的学会
    # 稀有字节」的似然口径。
    balanced_metrics = class_balanced_loss_metrics(
        class_loss_sums,
        class_counts,
        vocab_size,
    )
    for key, value in balanced_metrics.items():
        metrics[f"{split}_{key}"] = value

    if bootstrap_enabled and window_loss_sums:
        bootstrap_metrics = _bootstrap_eval_intervals(
            torch.cat(window_loss_sums),
            torch.cat(window_tokens),
            torch.stack(window_true_positive),
            torch.stack(window_predicted),
            torch.stack(window_support),
            int(bootstrap_replicates),
            _eval_bootstrap_seed(
                dataset.data_sha256,
                split,
                batches,
                batch_size,
                dataset.seq_len,
            ),
            window_class_loss_sums=torch.stack(
                window_class_loss_sums
            ),
            block_size=int(bootstrap_block),
        )
        for key, value in bootstrap_metrics.items():
            metrics[f"{split}_{key}"] = value

        # 评估窗口可能因 split 较短而重叠：重叠窗口不是独立
        # 抽样单位，bootstrap 区间会偏窄。把重叠比例随指标
        # 落盘，报告可据此判断区间是否被高估。
        starts = (
            dataset._fixed_starts.get(split, {}).get("starts")
        )
        if starts is not None and len(starts) > 1:
            gaps = starts[1:] - starts[:-1]
            overlap_count = int(
                (gaps < dataset.seq_len).sum().item()
            )
            metrics[f"{split}_eval_windows"] = int(len(starts))
            metrics[f"{split}_eval_window_overlap_fraction"] = (
                overlap_count / (len(starts) - 1)
            )

    if compute_auc:
        # 读取 CPU 收集缓冲前统一等待。
        if auc_async and auc_tokens > 0:
            torch.cuda.synchronize(device)

        metrics[f"{split}_auc_tokens_available"] = (
            auc_total_positions
        )
        metrics[f"{split}_auc_coverage_fraction"] = (
            auc_tokens / auc_total_positions
            if auc_total_positions > 0
            else 0.0
        )
        metrics[f"{split}_auc_sampling"] = (
            "uniform_stride"
            if auc_sample_positions is not None
            else "full"
        )

        if auc_tokens > 0:
            auc_metrics = macro_auc_metrics(
                auc_probs[:auc_tokens],
                auc_targets[:auc_tokens],
                vocab_size,
            )
            for key, value in auc_metrics.items():
                metrics[f"{split}_{key}"] = value
        else:
            # 空评估（理论上不可达）：显式记录而不是
            # 静默缺键。
            metrics[f"{split}_pr_auc_macro"] = None
            metrics[f"{split}_pr_auc_macro_chance"] = None
            metrics[f"{split}_pr_auc_macro_lift"] = None
            metrics[f"{split}_roc_auc_macro"] = None
            metrics[f"{split}_auc_n_classes"] = 0
            metrics[f"{split}_pr_auc_n_classes"] = 0
            metrics[f"{split}_roc_auc_n_classes"] = 0
            metrics[f"{split}_auc_min_support"] = (
                _AUC_MIN_SUPPORT
            )
            metrics[f"{split}_auc_tokens_evaluated"] = 0

    return metrics


# ============================================================
# Trivial reference baselines (uniform / unigram)
# ============================================================

@torch.inference_mode()
def compute_reference_baselines(
    dataset: ByteDataset,
    batch_size: int,
    batches: int,
    device: torch.device,
    split: str = "val",
) -> Dict[str, object]:
    """
    在与模型评估完全相同的固定窗口上计算两个「稻草人之下」
    的参考基线，作为解读指标的坐标系：

    - uniform：每个字节等概率 1/256，NLL = ln(256)，是
      任何模型必须显著低于的绝对下限；
    - unigram：只用 train split 的字节频率做无上下文预测
      （Laplace 平滑，统计量只在 train 上 fit），对应
      「类别不平衡下常数/多数类预测器」的视角——它的
      token accuracy 已经有相当份额，单看 accuracy 无法
      判断模型是否真的学到了上下文信息。

    返回 uniform / unigram 在指定 split 上的 loss、
    accuracy、macro/weighted F1、macro/weighted
    precision/recall 与多数类参考 accuracy，以及 AUC 类
    指标的常数预测器水平（PR-AUC 随机水平 = 纳入类平均
    prevalence，ROC-AUC = 0.5），随 config.json /
    metrics.jsonl 存档。训练曲线诊断把「是否学到东西」的
    欠拟合参照从 uniform 换成更强的 unigram，避免只战胜
    稻草人。
    """
    # 字节级管线的词表固定为 256。
    vocab_size = 256

    # unigram 统计量只在 train 上 fit，且与神经网络窗口采样
    # 使用同一「有效训练字节」口径：被群组去重或字节级标签噪声
    # 清洗掉的内容不能进入基线计数，否则基线会通过重复/损坏
    # 内容看到不同的训练分布，比较不再公平。
    train_counts = dataset.effective_train_byte_counts().double()
    train_total = float(train_counts.sum())
    raw_train_total = len(dataset.train)

    unigram_probs = (
        train_counts + 1.0
    ) / (train_total + vocab_size)
    uniform_probs = torch.full(
        (vocab_size,),
        1.0 / vocab_size,
        dtype=torch.float64,
    )

    unigram_prediction = int(train_counts.argmax())

    # log 概率预先算好（词表仅 256 项），循环内只做查表求和：
    # 与逐批对整批 token 求 log 的取值逐位一致。
    uniform_log_probs = uniform_probs.log()
    unigram_log_probs = unigram_probs.log()

    uniform_total = 0.0
    unigram_total = 0.0
    evaluated_tokens = 0

    confusion = torch.zeros(
        (vocab_size, vocab_size),
        dtype=torch.float64,
    )

    for batch_index in range(batches):
        x, y = dataset.fixed_eval_batch(
            split,
            batch_index,
            batches,
            batch_size,
            device,
        )

        if x.size(0) == 0:
            break

        flat_target = y.reshape(-1).to(torch.int64)

        uniform_total -= float(
            uniform_log_probs[flat_target].sum()
        )
        unigram_total -= float(
            unigram_log_probs[flat_target].sum()
        )
        evaluated_tokens += flat_target.numel()

        # unigram 预测器对所有位置输出同一个字节。
        predicted = torch.full_like(
            flat_target,
            unigram_prediction,
        )
        confusion += torch.bincount(
            flat_target * vocab_size + predicted,
            minlength=vocab_size ** 2,
        ).view(vocab_size, vocab_size).double()

    loss_uniform = uniform_total / evaluated_tokens
    loss_unigram = unigram_total / evaluated_tokens

    class_metrics = confusion_matrix_metrics(confusion)

    # PR-AUC / ROC-AUC 的常数预测器参考：unigram 对所有位置输出
    # 同一个（逐类不同的）分布，one-vs-rest 排序分数逐类恒定，
    # 因此
    # - PR-AUC 恰好等于该类在评估集上的 prevalence（平均精度
    #   在全部并列时 = 正类比例），macro 随机水平 = 纳入类
    #   （support >= _AUC_MIN_SUPPORT）prevalence 的均值；
    # - ROC-AUC 恒为 0.5（并列分数无排序信息）。
    # 只对有序指标的类（0 < support < 评估 token 数）定义
    # ROC 参考，与 macro_auc_metrics 的纳入口径一致。这样在
    # 按项目建议切换到 PR-AUC 对比时，稻草人核对不会静默失效。
    eval_support = confusion.sum(dim=1)
    eval_tokens = float(eval_support.sum())
    auc_eligible = eval_support >= _AUC_MIN_SUPPORT
    pr_auc_chance = None
    roc_auc_reference = None
    if eval_tokens > 0.0:
        if bool(auc_eligible.any()):
            pr_auc_chance = float(
                (eval_support[auc_eligible] / eval_tokens).mean()
            )
        roc_eligible = auc_eligible & (eval_support > 0.0) & (
            eval_support < eval_tokens
        )
        if bool(roc_eligible.any()):
            roc_auc_reference = 0.5

    # 类平衡（macro）NLL 参考：与 evaluate() 的 val_macro_nll
    # 同口径（对评估集中出现的类等权平均每类 NLL）。
    # - uniform：每类 NLL 恒为 log 256，类平衡平均后不变；
    # - unigram：预测器与上下文无关，每类 NLL 恒为 -log p(c)，
    #   类平衡平均即出现类上的平均 -log p(c)。
    # 这两个数是「类平衡似然」的稻草人下界：基线合理性检查在
    # val_macro_nll 上用它核对基线是否真的强于无上下文预测器。
    present_classes = eval_support > 0.0
    uniform_macro_nll = float(-uniform_log_probs.mean())
    if bool(present_classes.any()):
        unigram_macro_nll = float(
            (-unigram_log_probs[present_classes]).mean()
        )
    else:
        unigram_macro_nll = None

    return {
        "split": split,
        "tokens_evaluated": evaluated_tokens,
        "uniform_loss": loss_uniform,
        "unigram_loss": loss_unigram,
        "unigram_train_bytes": int(train_total),
        "unigram_train_bytes_raw": int(raw_train_total),
        "unigram_train_excluded_bytes": int(
            raw_train_total - train_total
        ),
        "majority_byte": unigram_prediction,
        "unigram_token_accuracy": class_metrics[
            "token_accuracy"
        ],
        "unigram_majority_accuracy": class_metrics[
            "majority_accuracy"
        ],
        "unigram_macro_f1": class_metrics["macro_f1"],
        "unigram_weighted_f1": class_metrics[
            "weighted_f1"
        ],
        # precision / recall：与 evaluate 同口径（macro 对
        # support > 0 的类等权、weighted 按 support 加权），
        # 供假设以「召回率/精确率」判定时核对基线是否强于
        # 无上下文预测器。
        "unigram_precision_macro": class_metrics[
            "precision_macro"
        ],
        "unigram_precision_weighted": class_metrics[
            "precision_weighted"
        ],
        "unigram_recall_macro": class_metrics[
            "recall_macro"
        ],
        "unigram_recall_weighted": class_metrics[
            "recall_weighted"
        ],
        # 序数指标（AUC）的常数预测器参考（见上方注释）。
        "unigram_pr_auc_macro_chance": pr_auc_chance,
        # 常数预测器的 PR-AUC lift = prevalence - prevalence = 0；
        # 显式落盘，基线守卫在 lift 口径上有同源参考。
        "unigram_pr_auc_macro_lift": 0.0,
        "unigram_roc_auc_macro": roc_auc_reference,
        # 类平衡似然参考（macro NLL）：与 val_macro_nll 同口径。
        "uniform_macro_nll": uniform_macro_nll,
        "unigram_macro_nll": unigram_macro_nll,
        "macro_nll_classes_present": float(
            int(present_classes.sum())
        ),
    }


# ============================================================
# N-gram statistical baseline (最简基线，先于任何神经模型)
# ============================================================
#
# 方法论要求：复杂模型必须显著战胜「精心调优过的简单基线」
# 才有说服力。本节实现字节级 n-gram 统计基线：
#
# - 计数只在 train split 上做（无泄露），评估用与神经模型
#   完全相同的固定窗口协议；
# - 插值平滑 P_o(c|ctx) =
#       (count(ctx,c) + α·P_{o-1}(c|ctx')) / (count(ctx) + α)，
#   一路回退到 uniform；阶数 o 与平滑系数 α 在 val 上
#   网格调优（简单基线同样要充分调优，而不是随便跑一档）；
# - test 只在显式 --evaluate-test 时用 val 上选出的
#   (o, α) 评估一次，绝不在 test 上调参。

# 上下文 + 目标按字节精确打包进 int64，7 个字节（56 bit）
# 是不越界的上限；更大的阶数需要哈希，超出即报错。
_NGRAM_MAX_ORDER = 7

# 每阶计数使用的最大训练窗口数；超过时按等距步长抽样
#（抽样是确定性的）。
_NGRAM_COUNT_CAP = 4_000_000


class NgramBaseline:
    """
    字节级插值 n-gram 基线（含 unigram）。

    每个阶 o 存三张有序表（torch.unique 保证升序）：
    - pair_keys / pair_counts：(ctx, c) 对的键
      （ctx*256 + c）与计数；
    - ctx_uniq / ctx_counts：ctx 键与出现次数。

    键按升序排列使得同一 ctx 的所有 (ctx, c) 对在
    pair_keys 中连续，查询用 searchsorted 完成。
    """

    def __init__(
        self,
        train_bytes: torch.Tensor,
        max_order: int,
        count_cap: int = _NGRAM_COUNT_CAP,
        exclude_spans: Optional[List[Tuple[int, int]]] = None,
    ):
        if not 1 <= max_order <= _NGRAM_MAX_ORDER:
            raise ValueError(
                "n-gram 阶数必须落在 "
                f"[1, {_NGRAM_MAX_ORDER}]（字节精确打包"
                "的 int64 上限）"
            )

        self.max_order = max_order
        self.vocab_size = 256
        self.exclude_spans = list(exclude_spans or [])

        data = train_bytes
        n_train = data.numel()

        self.levels: Dict[int, Dict[str, torch.Tensor]] = {}

        def _empty_level() -> Dict[str, torch.Tensor]:
            return {
                "pair_keys": torch.empty(
                    0,
                    dtype=torch.int64,
                ),
                "pair_counts": torch.empty(
                    0,
                    dtype=torch.int64,
                ),
                "ctx_uniq": torch.empty(
                    0,
                    dtype=torch.int64,
                ),
                "ctx_counts": torch.empty(
                    0,
                    dtype=torch.int64,
                ),
            }

        for order in range(1, max_order + 1):
            if n_train < order:
                # 语料比阶数还短：该阶没有可计数的窗口，
                # 查询时自然回退到低阶。
                self.levels[order] = _empty_level()
                continue

            num_windows = n_train - order + 1
            valid_intervals = _valid_window_start_intervals(
                num_windows,
                order - 1,
                self.exclude_spans,
            )

            if valid_intervals is None:
                stride = max(
                    1,
                    math.ceil(num_windows / count_cap),
                )

                # data.unfold(0, order, 1) 是
                # [num_windows, order] 的滑动窗口视图；
                # 按步长取行仍是视图，打包时才产生 int64
                # 张量。
                windows = data.unfold(0, order, 1)[::stride]
            elif not valid_intervals:
                self.levels[order] = _empty_level()
                continue
            else:
                # 与神经网络训练窗口同一口径：完全落在被
                # 清洗群组之外的窗口才参与计数，避免统计
                # 基线通过重复群组看到 val/test。
                lengths = torch.tensor(
                    [
                        high - low + 1
                        for low, high in valid_intervals
                    ],
                    dtype=torch.int64,
                )
                total_valid = int(lengths.sum())
                stride = max(
                    1,
                    math.ceil(total_valid / count_cap),
                )
                global_index = torch.arange(
                    0,
                    total_valid,
                    stride,
                    dtype=torch.int64,
                )
                cumulative = torch.cumsum(lengths, dim=0)
                interval = torch.searchsorted(
                    cumulative,
                    global_index,
                    right=True,
                )
                offsets = global_index - (
                    cumulative[interval] - lengths[interval]
                )
                lows = torch.tensor(
                    [low for low, _ in valid_intervals],
                    dtype=torch.int64,
                )
                starts = lows[interval] + offsets
                windows = data.unfold(0, order, 1)[starts]

            keys = windows[:, 0].to(torch.int64)
            for column in range(1, order):
                keys = keys * 256 + windows[
                    :, column
                ].to(torch.int64)

            pair_keys, pair_counts = torch.unique(
                keys,
                return_counts=True,
            )

            ctx_keys = pair_keys // 256

            ctx_uniq, inverse = torch.unique(
                ctx_keys,
                return_inverse=True,
            )
            ctx_counts = torch.zeros(
                ctx_uniq.numel(),
                dtype=torch.int64,
            ).scatter_add_(
                0,
                inverse,
                pair_counts,
            )

            self.levels[order] = {
                "pair_keys": pair_keys,
                "pair_counts": pair_counts,
                "ctx_uniq": ctx_uniq,
                "ctx_counts": ctx_counts,
            }

        # unigram 总计数（level 1 的 ctx 计数），用于
        # 参考/归一。
        first = self.levels[1]
        if first["ctx_uniq"].numel():
            self.train_total = int(
                first["ctx_counts"][0]
            )
        else:
            self.train_total = 0

    def _pack_context(
        self,
        context: torch.Tensor,
    ) -> torch.Tensor:
        """
        [n, ctx_len] 字节矩阵打包成 [n] 的 int64 键。
        """
        keys = context[:, 0].to(torch.int64)
        for column in range(1, context.size(1)):
            keys = keys * 256 + context[
                :, column
            ].to(torch.int64)
        return keys

    def _valid_contexts(
        self,
        windows: torch.Tensor,
        order: int,
    ) -> Tuple[
        torch.Tensor,
        torch.Tensor,
        int,
    ]:
        """
        返回给定阶数下每个有效位置的 (ctx 键, 扁平位置)。

        目标 y[t] = w[t+1]；长度 order-1 的上下文需要
        t+1-(order-1) >= 0，即 t >= order-2。
        """
        batch, total_len = windows.shape
        seq_len = total_len - 1
        n_positions = batch * seq_len

        if order == 1:
            return (
                torch.zeros(
                    n_positions,
                    dtype=torch.int64,
                ),
                # 位置索引只需覆盖 batch*seq_len（远小于 2^31），
                # 用 int32 存储。
                torch.arange(
                    n_positions,
                    dtype=torch.int32,
                ),
                n_positions,
            )

        context_len = order - 1

        if context_len > seq_len:
            # 阶数高于窗口可提供的最大上下文长度：没有任何
            # 有效位置，调用方将整阶回退到低阶模型；此处直接
            # 返回空结果。
            empty = torch.empty(0, dtype=torch.int64)
            return empty, empty, 0

        t_min = context_len - 1
        n_valid = seq_len - t_min

        # windows.unfold(1, ctx_len, 1) 的第 j 列是
        # w[:, j : j+ctx_len]；目标 t 对应 j = t+1-ctx_len，
        # j 取值范围 [0, seq_len - ctx_len] = [0, n_valid-1]。
        contexts = windows.unfold(
            1,
            context_len,
            1,
        )[:, :n_valid].reshape(-1, context_len)

        batch_index = torch.arange(
            batch,
            dtype=torch.int32,
        ).repeat_interleave(n_valid)
        offsets = (
            torch.arange(n_valid, dtype=torch.int32)
            + t_min
        ).repeat(batch)

        positions = batch_index * seq_len + offsets

        return (
            self._pack_context(contexts),
            positions,
            n_valid,
        )

    @staticmethod
    def _lookup(
        sorted_keys: torch.Tensor,
        values: torch.Tensor,
        queries: torch.Tensor,
    ) -> torch.Tensor:
        """
        在有序键值表中查询，未命中返回 0。
        """
        if sorted_keys.numel() == 0:
            return torch.zeros_like(queries)

        locations = torch.searchsorted(
            sorted_keys,
            queries,
        )
        locations = locations.clamp(
            max=sorted_keys.numel() - 1,
        )
        found = sorted_keys[locations] == queries
        return torch.where(
            found,
            values[locations],
            torch.zeros_like(values[locations]),
        )

    def _per_level_tables(
        self,
        windows: torch.Tensor,
    ) -> List[Optional[Dict[str, torch.Tensor]]]:
        """
        逐阶的 alpha 无关查表结果（ctx 计数与 (ctx, c) 对计数）。

        查表只依赖窗口与训练计数，与平滑系数 alpha 无关；
        positions 为空（窗口比阶还短）的阶记为 None，由插值
        阶段整阶保持低阶回退值。
        """
        targets = windows[
            :, 1:
        ].reshape(-1).to(torch.int64)

        tables: List[
            Optional[Dict[str, torch.Tensor]]
        ] = []

        for order in range(1, self.max_order + 1):
            level = self.levels[order]

            ctx_keys, positions, _ = (
                self._valid_contexts(windows, order)
            )

            if positions.numel() == 0:
                tables.append(None)
                continue

            n_ctx = self._lookup(
                level["ctx_uniq"],
                level["ctx_counts"],
                ctx_keys,
            ).double()

            pair_keys = ctx_keys * 256 + targets[
                positions
            ]
            count_pair = self._lookup(
                level["pair_keys"],
                level["pair_counts"],
                pair_keys,
            ).double()

            tables.append({
                "positions": positions,
                "n_ctx": n_ctx,
                "count_pair": count_pair,
            })

        return tables

    def _interpolate_log_probs(
        self,
        windows: torch.Tensor,
        tables: List[
            Optional[Dict[str, torch.Tensor]]
        ],
        alpha: float,
    ) -> torch.Tensor:
        """
        用 _per_level_tables 的查表结果按指定 alpha 计算逐阶
        目标 log 概率，语义与逐次查表版本完全一致。
        """
        batch, total_len = windows.shape
        seq_len = total_len - 1
        n_positions = batch * seq_len

        log_probs = torch.zeros(
            (self.max_order, n_positions),
            dtype=torch.float64,
        )

        # level 0 的目标概率：uniform。
        probability = torch.full(
            (n_positions,),
            1.0 / self.vocab_size,
            dtype=torch.float64,
        )

        for order in range(1, self.max_order + 1):
            table = tables[order - 1]

            row = log_probs[order - 1]

            if table is None:
                # 窗口比阶还短：整阶保持低阶回退值。
                if order > 1:
                    row.copy_(log_probs[order - 2])
                continue

            positions = table["positions"]

            if order > 1:
                # 上下文不足的位置保持低阶值：
                # 先整行复制，再覆写本阶的有效位置，
                # 与「按掩码只复制无效位置」结果一致。
                row.copy_(log_probs[order - 2])

            interpolated = (
                table["count_pair"]
                + alpha * probability[positions]
            ) / (table["n_ctx"] + alpha)

            row[positions] = interpolated.log()

            probability[positions] = interpolated

        return log_probs

    def target_log_probs_per_level(
        self,
        windows: torch.Tensor,
        alpha: float,
    ) -> torch.Tensor:
        """
        对一批窗口 [batch, seq_len + 1] 计算每个阶数
        （1..max_order）下目标字节的 log 概率。

        返回 [max_order, batch*seq_len]：第 o-1 行是
        「最高可用阶不超过 o」的回退模型在每个位置目标
        字节的 log 概率——上下文不足或从未见过的位置
        自动回退到低阶，供网格调优一次性拿到所有候选
        阶数的损失。
        """
        return self._interpolate_log_probs(
            windows,
            self._per_level_tables(windows),
            alpha,
        )

    def position_distributions(
        self,
        windows: torch.Tensor,
        alpha: float,
        order: int,
    ) -> torch.Tensor:
        """
        返回「最高可用阶不超过 order」的回退模型在每个
        位置的完整 [batch*seq_len, vocab] 概率分布，
        用于最终评估的 argmax / F1 / AUC 指标。
        """
        batch, total_len = windows.shape
        seq_len = total_len - 1
        n_positions = batch * seq_len

        probabilities = torch.full(
            (n_positions, self.vocab_size),
            1.0 / self.vocab_size,
            dtype=torch.float64,
        )

        for current in range(1, order + 1):
            level = self.levels[current]

            ctx_keys, positions, _ = (
                self._valid_contexts(
                    windows,
                    current,
                )
            )

            if positions.numel() == 0:
                continue

            n_ctx = self._lookup(
                level["ctx_uniq"],
                level["ctx_counts"],
                ctx_keys,
            ).double()

            if n_ctx.numel() and (
                level["pair_keys"].numel() == 0
            ):
                # 该阶没有任何计数：分布保持低阶回退。
                continue

            denominator = n_ctx + alpha

            updated = probabilities[
                positions
            ] * (alpha / denominator.unsqueeze(1))

            # 同一 ctx 的 (ctx, c) 对在升序 pair_keys 中
            # 连续：散射该 ctx 的全部非零计数行。
            starts = torch.searchsorted(
                level["pair_keys"],
                ctx_keys * 256,
            )
            ends = torch.searchsorted(
                level["pair_keys"],
                (ctx_keys + 1) * 256,
            )
            lengths = (ends - starts).clamp(min=0)

            total_nnz = int(lengths.sum())

            if total_nnz > 0:
                row_of = torch.repeat_interleave(
                    torch.arange(
                        positions.numel(),
                        dtype=torch.int64,
                    ),
                    lengths,
                )
                offsets = torch.cumsum(lengths, 0) - (
                    lengths
                )
                intra = torch.arange(total_nnz) - (
                    offsets[row_of]
                )
                flat_index = starts[row_of] + intra

                classes = level["pair_keys"][
                    flat_index
                ] % 256
                counts = level["pair_counts"][
                    flat_index
                ].double()

                updated.index_put_(
                    (row_of, classes),
                    counts
                    / denominator[row_of],
                    accumulate=True,
                )

            probabilities[positions] = updated

        return probabilities


def _ngram_eval_batches(
    dataset: ByteDataset,
    split: str,
    batch_size: int,
    batches: int,
) -> List[torch.Tensor]:
    """
    收集指定评估 split 的全部固定窗口（CPU uint8，
    [batch, seq_len + 1]）。
    """
    cpu = torch.device("cpu")
    windows: List[torch.Tensor] = []

    for batch_index in range(batches):
        x, y = dataset.fixed_eval_batch(
            split,
            batch_index,
            batches,
            batch_size,
            cpu,
        )

        if x.size(0) == 0:
            break

        windows.append(
            torch.cat(
                [
                    x[:, :1].to(torch.uint8),
                    y,
                ],
                dim=1,
            )
        )

    return windows


def _ngram_extended_metrics(
    model: NgramBaseline,
    windows: List[torch.Tensor],
    alpha: float,
    order: int,
    split: str,
    include_auc: bool = True,
    bootstrap_replicates: int = 0,
    bootstrap_seed: Optional[int] = None,
    bootstrap_block: int = 1,
    window_sink: Optional[List[Dict[str, object]]] = None,
    window_classification: bool = False,
) -> Dict[str, object]:
    """
    用调优好的 (order, alpha) 在固定窗口上计算与神经模型
    evaluate() 完全同口径的指标：loss / ppl / bits_per_byte、
    token accuracy（micro）、macro / weighted F1、多数类
    参考，以及 one-vs-rest 的 macro PR-AUC / ROC-AUC。

    ``include_auc=False`` 时跳过 AUC（网格调参只需要
    accuracy/F1 等分类指标时不收集整张概率矩阵，显著降低
    候选评估的 CPU/内存开销）；最终评估必须保持默认 True。

    ``window_classification=True`` 时每个窗口记录额外附带
    该窗口的 accuracy / micro、macro、weighted F1 与
    precision / recall（与全局指标同一 ``confusion_matrix_metrics``
    口径），供分类调参指标做逐窗口配对 one-SE 选择。默认
    False，避免把逐窗口分类明细写进 eval_windows.json。

    ``bootstrap_replicates > 1`` 时额外给出与神经模型同口径的
    逐窗口 bootstrap 置信区间（loss / ppl / macro NLL /
    token accuracy / macro 与 weighted F1 / macro 与 weighted
    precision / recall）。统计基线是确定性的，换 seed 重复运行
    不是独立重复；它的评估不确定性只能来自评估窗口抽样，因此
    这个区间是 ngram 对照唯一的误差线来源。``window_sink`` 非 None 时
    逐窗口记录损失和、token 数与命中数，供跨运行逐窗口配对
    比较使用（固定评估窗口对所有运行相同）。
    """
    vocab_size = model.vocab_size

    total_nll = 0.0
    evaluated_tokens = 0

    confusion = torch.zeros(
        (vocab_size, vocab_size),
        dtype=torch.float64,
    )

    # 类平衡（macro）NLL 的逐类充分统计量：与神经模型
    # evaluate() 同口径，保证统计基线与神经模型可以直接在
    # val_macro_nll 上对比（类平衡似然不能只给神经模型算）。
    class_loss_sums = torch.zeros(
        vocab_size,
        dtype=torch.float64,
    )
    class_counts = torch.zeros(
        vocab_size,
        dtype=torch.float64,
    )

    bootstrap_enabled = int(bootstrap_replicates) > 1
    window_loss_sums: List[float] = []
    window_tokens: List[float] = []
    window_true_positive: List[torch.Tensor] = []
    window_predicted: List[torch.Tensor] = []
    window_support: List[torch.Tensor] = []
    window_class_loss_sums: List[torch.Tensor] = []

    # 与神经模型评估同口径：按窗口总位置数分配收集缓冲
    # （不超过上限），逐窗口写入。不做 AUC 时不分配缓冲区。
    auc_capacity = 0
    auc_probs = None
    auc_targets = None
    auc_tokens = 0
    auc_total_positions = 0
    auc_sample_positions: Optional[torch.Tensor] = None
    auc_processed_positions = 0
    if include_auc:
        auc_total_positions = sum(
            int(window.size(0))
            * (int(window.size(1)) - 1)
            for window in windows
        )
        auc_capacity = min(
            _AUC_MAX_TOKENS,
            auc_total_positions,
        )
        auc_sample_positions = _auc_uniform_sample_positions(
            auc_total_positions,
            auc_capacity,
        )
        auc_probs = torch.empty(
            auc_capacity,
            vocab_size,
            dtype=torch.float32,
        )
        auc_targets = torch.empty(
            auc_capacity,
            dtype=torch.int64,
        )

    for window in windows:
        distributions = model.position_distributions(
            window,
            alpha,
            order,
        )

        targets = window[:, 1:].reshape(-1).to(
            torch.int64
        )
        probabilities = distributions

        target_probs = probabilities[
            torch.arange(targets.numel()),
            targets,
        ]

        token_nll = -target_probs.clamp_min(1e-300).log()

        total_nll += float(token_nll.sum())
        evaluated_tokens += targets.numel()

        class_loss_sums.index_add_(
            0,
            targets,
            token_nll.to(torch.float64),
        )
        class_counts.index_add_(
            0,
            targets,
            torch.ones_like(
                token_nll,
                dtype=torch.float64,
            ),
        )

        predicted = probabilities.argmax(dim=1)
        correct = targets == predicted

        # 逐窗口（batch 内每一行）统计，而不是把整个 batch
        # 当成一个窗口：神经模型的 evaluate() 以单个固定评估
        # 窗口为抽样单位，ngram 若按 batch 聚合，bootstrap 的
        # 重采样单位与窗口数都会与神经运行不一致，逐窗口配对
        # 比较也会因窗口数不同而直接失效。
        seq_len = int(window.size(1)) - 1
        row_losses = token_nll.view(int(window.size(0)), seq_len)
        row_correct = correct.view(int(window.size(0)), seq_len)
        row_targets = targets.view(int(window.size(0)), seq_len)
        row_predicted = predicted.view(int(window.size(0)), seq_len)

        for row in range(int(window.size(0))):
            row_loss_sum = float(row_losses[row].sum())
            row_target = row_targets[row]
            row_pred = row_predicted[row]
            row_hits = int(row_correct[row].sum())
            if window_sink is not None:
                window_record: Dict[str, object] = {
                    "loss_sum": row_loss_sum,
                    "tokens": seq_len,
                    "correct": row_hits,
                }
                if window_classification:
                    row_confusion = torch.bincount(
                        row_target * vocab_size + row_pred,
                        minlength=vocab_size ** 2,
                    ).view(vocab_size, vocab_size)
                    window_record["classification"] = (
                        confusion_matrix_metrics(
                            row_confusion.double()
                        )
                    )
                window_sink.append(window_record)

            if bootstrap_enabled:
                window_loss_sums.append(row_loss_sum)
                window_tokens.append(float(seq_len))
                window_true_positive.append(
                    torch.bincount(
                        row_target[row_correct[row]],
                        minlength=vocab_size,
                    )
                )
                window_predicted.append(
                    torch.bincount(
                        row_pred,
                        minlength=vocab_size,
                    )
                )
                row_support = torch.bincount(
                    row_target,
                    minlength=vocab_size,
                )
                window_support.append(row_support)
                window_class_loss_sums.append(
                    torch.zeros(
                        vocab_size,
                        dtype=torch.float64,
                    ).index_add_(
                        0,
                        row_target,
                        row_losses[row].to(torch.float64),
                    )
                )

        confusion += torch.bincount(
            targets * vocab_size + predicted,
            minlength=vocab_size ** 2,
        ).view(vocab_size, vocab_size).double()

        if (
            auc_probs is not None
            and auc_targets is not None
        ):
            if auc_sample_positions is None:
                selected_probabilities = probabilities
                selected_targets = targets
            else:
                start_position = auc_processed_positions
                end_position = (
                    start_position + targets.numel()
                )
                lower = int(
                    torch.searchsorted(
                        auc_sample_positions,
                        start_position,
                    )
                )
                upper = int(
                    torch.searchsorted(
                        auc_sample_positions,
                        end_position,
                    )
                )
                local_positions = (
                    auc_sample_positions[lower:upper]
                    - start_position
                )
                selected_probabilities = probabilities[
                    local_positions
                ]
                selected_targets = targets[local_positions]
            num_new = int(selected_targets.numel())
            auc_probs[
                auc_tokens:auc_tokens + num_new
            ].copy_(selected_probabilities)
            auc_targets[
                auc_tokens:auc_tokens + num_new
            ].copy_(selected_targets)
            auc_tokens += num_new
            auc_processed_positions += int(targets.numel())

    loss = total_nll / evaluated_tokens

    metrics: Dict[str, object] = {
        f"{split}_loss": loss,
        f"{split}_ppl": math.exp(min(loss, 80.0)),
        f"{split}_bits_per_byte": loss / math.log(2.0),
    }

    class_metrics = confusion_matrix_metrics(confusion)

    for key, value in class_metrics.items():
        metrics[f"{split}_{key}"] = value

    # 类平衡似然（macro NLL）：与神经模型同口径。
    balanced_metrics = class_balanced_loss_metrics(
        class_loss_sums,
        class_counts,
        vocab_size,
    )
    for key, value in balanced_metrics.items():
        metrics[f"{split}_{key}"] = value

    if include_auc:
        metrics[f"{split}_auc_tokens_available"] = (
            auc_total_positions
        )
        metrics[f"{split}_auc_coverage_fraction"] = (
            auc_tokens / auc_total_positions
            if auc_total_positions > 0
            else 0.0
        )
        metrics[f"{split}_auc_sampling"] = (
            "uniform_stride"
            if auc_sample_positions is not None
            else "full"
        )

    if (
        include_auc
        and auc_tokens > 0
        and auc_probs is not None
        and auc_targets is not None
    ):
        auc_metrics = macro_auc_metrics(
            auc_probs[:auc_tokens],
            auc_targets[:auc_tokens],
            vocab_size,
        )
        for key, value in auc_metrics.items():
            metrics[f"{split}_{key}"] = value

    if bootstrap_enabled and window_loss_sums:
        if bootstrap_seed is not None:
            seed_value = int(bootstrap_seed)
        else:
            # 调用方未给种子时由窗口内容派生：同一批固定窗口
            # 在重复评估中得到同一区间，不受全局 RNG 影响。
            material = b"|".join(
                window.numpy().tobytes() for window in windows
            )
            seed_value = int.from_bytes(
                hashlib.blake2b(
                    material,
                    digest_size=8,
                ).digest(),
                "big",
            )
        bootstrap_metrics = _bootstrap_eval_intervals(
            torch.tensor(window_loss_sums, dtype=torch.float64),
            torch.tensor(window_tokens, dtype=torch.float64),
            torch.stack(window_true_positive),
            torch.stack(window_predicted),
            torch.stack(window_support),
            int(bootstrap_replicates),
            seed_value,
            window_class_loss_sums=torch.stack(
                window_class_loss_sums
            ),
            block_size=int(bootstrap_block),
        )
        for key, value in bootstrap_metrics.items():
            metrics[f"{split}_{key}"] = value

    return metrics


def resolve_ngram_tuning_metric(
    args: argparse.Namespace,
) -> Tuple[str, str]:
    """
    决定 n-gram 基线选择 (order, alpha) 的目标指标。

    与简单神经基线同一纪律：预注册主指标优先于默认的
    val_loss；显式 --ngram-tuning-metric 优先于两者。主指标
    是路由诊断等 n-gram 无法计算的指标时回退到 val_loss 并
    说明原因，而不是静默换口径。
    """
    explicit = getattr(args, "ngram_tuning_metric", None)
    if explicit is not None:
        return str(explicit), "explicit"

    primary = getattr(args, "primary_metric", None)
    if primary is not None:
        if primary in _NGRAM_TUNING_METRIC_KEYS:
            return str(primary), "primary_metric"
        print(
            "[ngram] 预注册主指标 "
            f"{primary} 不是 n-gram 基线可计算的指标，"
            "回退到 val_loss 选择 (order, alpha)；"
            "如需按分类指标调参请显式传 "
            "--ngram-tuning-metric"
        )

    return "val_loss", "default_loss"


def _ngram_tuning_diagnostics(
    best: Dict[str, object],
    runner_up: Optional[Dict[str, object]],
    tuning_metric: str,
    alpha_grid: List[float],
    max_order: int,
    candidate_count: int,
    valid_candidate_count: int,
    selection: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """
    汇总 n-gram (order, alpha) 网格调参的选择不确定性。

    n-gram 的最终 val 指标是在同一批 val 窗口上从整个网格里
    选出的 winner，和神经模型的 checkpoint 选型一样存在乐观
    偏差；只看 winner 的分数无法判断它是否只是网格内的微小
    噪声优势。这里报告：

    - ``metric_gap`` / ``metric_gap_relative``：winner 与
      runner-up 在调参指标上的差距；差距为 0 表示并列，当前
      选择只是「更简单优先」的确定性 tie-break；
    - ``boundary_hits``：winner 落在 alpha / order 网格边界时
      提示网格可能没有覆盖更优区域；
    - ``selection_bias_note``：val 网格调参后的同一 val 指标
      带乐观偏差，test 全程尘封，评估不确定性应看窗口
      bootstrap 而不是重复 seed；
    - ``selection``：可选的 one-SE 选择记录；给出点估计最优、
      最终选择、并列候选与配对标准误，避免把微小噪声优势
      当成唯一最优。
    """
    best_value_float = _finite_float(best.get(tuning_metric))

    runner_value_float: Optional[float] = None
    if runner_up is not None:
        runner_value_float = _finite_float(
            runner_up.get(tuning_metric)
        )

    gap: Optional[float] = None
    gap_relative: Optional[float] = None
    if (
        best_value_float is not None
        and runner_value_float is not None
    ):
        gap = abs(best_value_float - runner_value_float)
        if abs(best_value_float) > 0.0:
            gap_relative = gap / abs(best_value_float)

    best_order = int(best["order"])
    best_alpha = float(best["alpha"])
    alpha_min = min(float(value) for value in alpha_grid)
    alpha_max = max(float(value) for value in alpha_grid)
    boundary_hits: List[str] = []
    if best_order >= int(max_order):
        boundary_hits.append("order=网格上界")
    if best_alpha <= alpha_min:
        boundary_hits.append("alpha=网格下界")
    if best_alpha >= alpha_max:
        boundary_hits.append("alpha=网格上界")

    advisories: List[str] = []
    if gap is not None:
        # 并列判定按指标尺度取相对容差；固定 1e-12 会把
        # 1e-13 量级的真实 gap 误报成并列。
        tolerance = 1e-12 * abs(best_value_float or 0.0)
        if gap <= tolerance and runner_up is not None:
            advisories.append(
                "winner 与 runner-up 在调参指标上并列：当前仅是"
                "按「更小 order / 更小 alpha」的确定性 tie-break，"
                "不能把选中配置的 val 指标当成唯一最优证据"
            )
    if boundary_hits:
        advisories.append(
            "winner 落在调参网格边界（"
            + ", ".join(boundary_hits)
            + "）：网格可能未覆盖更优区域，扩展候选后应重跑"
        )
    if selection and not selection.get(
        "selected_is_point_best", True
    ):
        advisories.append(
            "one-SE 规则未选择点估计最优配置："
            "与点估计 winner 的逐窗口配对差在 1 个标准误内，"
            "按更简单优先选择 order="
            f"{best_order}/alpha={best_alpha:g}，"
            "避免把网格内微小噪声优势当成稳定收益"
        )

    return {
        "tuning_metric": tuning_metric,
        "candidate_count": int(candidate_count),
        "valid_candidate_count": int(valid_candidate_count),
        "best": {
            "order": best_order,
            "alpha": best_alpha,
            "value": best_value_float,
        },
        "runner_up": (
            {
                "order": int(runner_up["order"]),
                "alpha": float(runner_up["alpha"]),
                "value": runner_value_float,
            }
            if runner_up is not None
            else None
        ),
        "metric_gap": gap,
        "metric_gap_relative": gap_relative,
        "boundary_hits": boundary_hits,
        "selection_bias_note": (
            "最终 val 指标是在同一批 val 窗口上从整个网格选出的 "
            "winner，和 checkpoint 选型一样带乐观偏差；test 全程"
            "尘封。评估不确定性应看 --eval-bootstrap 的窗口区间，"
            "不能用重复 seed 冒充独立重复"
        ),
        "selection": selection,
        "advisories": advisories,
    }


def _ngram_window_tuning_value(
    loss: float,
    tuning_metric: str,
) -> float:
    """把逐窗口 loss 变换到调参指标尺度（仅损失类指标）。"""
    if tuning_metric == "val_ppl":
        return math.exp(min(loss, 80.0))
    if tuning_metric == "val_bits_per_byte":
        return loss / math.log(2.0)
    return loss


def _select_ngram_candidate_one_se(
    point_best: Dict[str, object],
    candidates: List[Dict[str, object]],
    window_values: Dict[Tuple[int, float], List[float]],
    tuning_metric: str,
) -> Optional[Dict[str, object]]:
    """
    对 n-gram 网格用逐窗口配对 one-SE 规则做最终选择。

    点估计最优只说明「在这批 val 窗口上最小/最大」，网格里
    相邻配置的微小优势可能只是窗口抽样噪声。这里以点估计
    winner 为参照，对每个候选计算逐窗口配对差（候选 - 点估计
    winner）的均值与标准误；正自相关时按 AR(1) 有效窗口数
    放宽标准误。均值差不超过一个标准误的候选视为统计上
    不可分辨，再按「更小 order / 更小 alpha」选择更简单配置。

    损失类指标用逐窗口 loss 变换到调参指标尺度；accuracy /
    micro、macro、weighted F1 与 precision / recall 用
    ``_ngram_extended_metrics`` 记录的逐窗口同口径分类指标，
    并按同一规则配对（越高越好时方向取反）。AUC 需要整张
    概率矩阵且逐窗口类支持稀疏，逐窗口估计与原口径不一致，
    仍按点估计选择。
    """
    loss_like = tuning_metric in (
        "val_loss",
        "val_ppl",
        "val_bits_per_byte",
    )
    higher_is_better = metric_higher_is_better(tuning_metric)
    if (
        not loss_like
        and tuning_metric[len("val_"):]
        not in _NGRAM_PER_WINDOW_CLASSIFICATION_METRICS
    ):
        return None

    def _key(row: Dict[str, object]) -> Tuple[int, float]:
        return int(row["order"]), float(row["alpha"])

    def _values(raw: List[float]) -> Optional[List[float]]:
        values: List[float] = []
        for value in raw:
            try:
                number = float(value)
            except (TypeError, ValueError, OverflowError):
                return None
            if not math.isfinite(number):
                return None
            values.append(
                _ngram_window_tuning_value(
                    number, tuning_metric
                )
                if loss_like
                else number
            )
        return values

    point_key = _key(point_best)
    point_raw = window_values.get(point_key)
    if not point_raw or len(point_raw) < 3:
        return {
            "rule": "paired_one_se",
            "available": False,
            "reason": "insufficient_window_values",
        }
    point_values = _values(point_raw)
    if point_values is None:
        return {
            "rule": "paired_one_se",
            "available": False,
            "reason": "nonfinite_window_values",
        }

    n_windows = len(point_values)
    point_mean = _mean(point_values)
    if point_mean is None:
        return {
            "rule": "paired_one_se",
            "available": False,
            "reason": "nonfinite_point_mean",
        }
    # 容差必须相对于指标本身，而不是固定 1e-12：极小但非零的
    # loss 差异（如 1e-13）否则会被当成数值噪声而误判并列。
    tolerance = 1e-12 * abs(point_mean)

    tied: List[Dict[str, object]] = []
    for candidate in candidates:
        candidate_raw = window_values.get(_key(candidate))
        if (
            candidate_raw is None
            or len(candidate_raw) != n_windows
        ):
            continue
        candidate_values = _values(candidate_raw)
        if candidate_values is None:
            continue
        differences = [
            value - base
            for value, base in zip(
                candidate_values, point_values
            )
        ]
        mean_diff = _mean(differences)
        if mean_diff is None:
            continue
        std = _sample_std(differences)
        if std is None:
            continue
        se = std / math.sqrt(n_windows)
        rho1 = _lag1_autocorrelation(
            torch.tensor(differences, dtype=torch.float64)
        )
        _effective, inflation = _ar1_effective_windows(
            n_windows,
            rho1,
        )
        threshold = se * inflation
        within_one_se = (
            mean_diff >= -(threshold + tolerance)
            if higher_is_better
            else mean_diff <= threshold + tolerance
        )
        if within_one_se:
            value = candidate.get(tuning_metric)
            tied.append({
                "order": int(candidate["order"]),
                "alpha": float(candidate["alpha"]),
                "value": _finite_float(value),
                "paired_mean_diff": mean_diff,
                "paired_se": se,
                "ar1_inflation": inflation,
                "threshold": threshold,
            })

    if not tied:
        return {
            "rule": "paired_one_se",
            "available": False,
            "reason": "no_candidates_with_window_values",
        }

    selected = min(
        tied,
        key=lambda row: (row["order"], row["alpha"]),
    )
    selected_row = next(
        (
            candidate
            for candidate in candidates
            if _key(candidate)
            == (selected["order"], selected["alpha"])
        ),
        point_best,
    )
    selected_is_point_best = (
        _key(selected_row) == point_key
    )
    point_value = point_best.get(tuning_metric)
    return {
        "rule": "paired_one_se",
        "available": True,
        "n_windows": n_windows,
        "point_best": {
            "order": point_key[0],
            "alpha": point_key[1],
            "value": (
                float(point_value)
                if isinstance(point_value, (int, float))
                and not isinstance(point_value, bool)
                and math.isfinite(float(point_value))
                else None
            ),
        },
        "selected": {
            "order": int(selected_row["order"]),
            "alpha": float(selected_row["alpha"]),
        },
        "selected_is_point_best": selected_is_point_best,
        "tied": tied,
        "note": (
            "候选与点估计 winner 的逐窗口配对差不超过一个"
            "标准误时按更简单优先选择；正自相关按 AR(1) "
            "有效窗口数放宽标准误"
        ),
    }


def run_statistical_baseline(
    args: argparse.Namespace,
    dataset: ByteDataset,
    out_dir: Path,
    device: torch.device,
    data_audit: Optional[Dict[str, object]],
    data_protocol_check: Optional[Dict[str, object]] = None,
) -> None:
    """
    统计基线入口：计数（train）→ val 网格调优
    （阶数 × 平滑系数）→ 选出最优配置 → 与神经模型同口径
    的 val（及一次性 test）指标，写入与训练运行相同结构的
    config.json / metrics.jsonl，可直接进入 --compare。
    """
    del device  # n-gram 全部在 CPU 上完成。

    # 统计基线当前不消耗任何随机性（计数与固定窗口评估都是
    # 确定性的），但所有入口统一固定全部 RNG 种子：未来任何
    # 采样/初始化改动不会让本入口在无感知的情况下失去
    # 可复现性，config.json 里的种子也始终对应真实生效值。
    set_seed(
        args.seed,
        strict_determinism=args.strict_determinism,
    )

    # 在入口处捕获运行身份：final 记录使用真正的启动时间，
    # 而不是训练/计数结束后的时间。
    ngram_run_metadata = collect_run_metadata(
        torch.device("cpu")
    )

    alpha_grid: List[float] = list(args.ngram_alpha_grid)
    tuning_metric, tuning_metric_source = (
        resolve_ngram_tuning_metric(args)
    )

    excluded_bytes = (
        dataset.train.numel() - dataset.effective_train_bytes
    )
    print(
        "[ngram] 在 train split 上计数 "
        f"({dataset.effective_train_bytes:,} 有效字节"
        + (
            f", 已剔除 {excluded_bytes:,} 字节重复群组"
            if excluded_bytes > 0
            else ""
        )
        + f", max_order={args.ngram_max_order}, "
        f"count_cap={_NGRAM_COUNT_CAP:,})"
    )

    model = NgramBaseline(
        dataset.train,
        max_order=args.ngram_max_order,
        exclude_spans=dataset.train_excluded_spans,
    )

    val_windows = _ngram_eval_batches(
        dataset,
        "val",
        args.batch_size,
        args.eval_batches,
    )

    if not val_windows:
        raise SystemExit(
            "验证集固定窗口为空，无法调优统计基线"
        )

    # ---- 参考基线（uniform / unigram），与训练运行同款 ----
    reference = compute_reference_baselines(
        dataset,
        args.batch_size,
        args.eval_batches,
        torch.device("cpu"),
        split="val",
    )

    print(
        "[ngram] 参考基线: uniform_loss="
        f"{reference['uniform_loss']:.4f}, "
        "unigram_loss="
        f"{reference['unigram_loss']:.4f}"
    )

    metrics_path = out_dir / "metrics.jsonl"
    metrics_file = open(
        metrics_path,
        "w",
        encoding="utf-8",
    )

    def _write(record: Dict[str, object]) -> None:
        metrics_file.write(
            json.dumps(
                _json_safe(record),
                ensure_ascii=False,
            )
            + "\n"
        )
        metrics_file.flush()

    _write({
        "step": "reference_baselines",
        **tracking_header_fields(
            args,
            dataset,
            ngram_run_metadata,
        ),
        **reference,
    })

    # ---- 网格调优：α 每档一遍窗口，同时拿到所有阶数损失 ----
    # 逐阶查表只依赖窗口与训练计数，与 α 无关。
    val_tables = [
        model._per_level_tables(window)
        for window in val_windows
    ]

    candidates: List[Dict[str, object]] = []
    candidate_window_losses: Dict[
        Tuple[int, float], List[float]
    ] = {}
    # 分类调参指标（accuracy / F1 / precision / recall）的逐窗口
    # 同口径取值：供 one-SE 选择按窗口配对，而不是只看聚合后
    # 的微小差距。
    candidate_window_classification: Dict[
        Tuple[int, float], List[float]
    ] = {}
    loss_like_metrics = (
        "val_loss",
        "val_ppl",
        "val_bits_per_byte",
    )
    classification_metric_key = tuning_metric[
        len("val_"):
    ]
    classification_tunable = (
        tuning_metric not in loss_like_metrics
        and classification_metric_key
        in _NGRAM_PER_WINDOW_CLASSIFICATION_METRICS
    )
    higher_is_better = metric_higher_is_better(
        tuning_metric
    )
    print(
        "[ngram] (order, alpha) 的选择指标: "
        f"{tuning_metric}"
        f"（来源={tuning_metric_source}，"
        + (
            "越高越好"
            if higher_is_better
            else "越低越好"
        )
        + "；test 集不参与）"
    )

    for alpha in alpha_grid:
        # log_probs 是 float64（见 _interpolate_log_probs）；累加器
        # 必须同 dtype，否则 += 会把双精度的逐窗口损失静默降为
        # float32，val_loss 与 _ngram_extended_metrics 的 float64
        # 同口径值不一致，还可能改变 (order, alpha) 的选优结果。
        totals = torch.zeros(model.max_order, dtype=torch.float64)
        tokens = 0

        for window, tables in zip(
            val_windows,
            val_tables,
        ):
            log_probs = (
                model._interpolate_log_probs(
                    window,
                    tables,
                    alpha,
                )
            )
            totals += -log_probs.sum(dim=1)
            tokens += log_probs.size(1)
            if tuning_metric in loss_like_metrics:
                # 逐窗口损失用于 one-SE 选择：同一批窗口上
                # 候选与点估计 winner 可以按窗口配对，避免
                # 用聚合后的小差距把噪声当成稳定收益。
                seq_len = int(window.size(1)) - 1
                window_means = (
                    (-log_probs)
                    .reshape(
                        model.max_order,
                        int(window.size(0)),
                        seq_len,
                    )
                    .sum(dim=2)
                    / float(seq_len)
                )
                for order in range(
                    1, model.max_order + 1
                ):
                    candidate_window_losses.setdefault(
                        (order, alpha),
                        [],
                    ).extend(
                        window_means[order - 1].tolist()
                    )

        for order in range(1, model.max_order + 1):
            val_loss = float(
                totals[order - 1] / tokens
            )
            record = {
                "step": "baseline_sweep",
                "order": order,
                "alpha": alpha,
                "val_loss": val_loss,
                "val_ppl": math.exp(
                    min(val_loss, 80.0)
                ),
                "val_bits_per_byte": val_loss
                / math.log(2.0),
                "tokens_evaluated": tokens,
                "tuning_metric": tuning_metric,
            }

            if tuning_metric not in loss_like_metrics:
                # 分类/AUC 指标必须看完整的 argmax/概率分布：
                # 在 val_loss 上选出的 (order, alpha) 不能证明
                # 它在 macro F1 / PR-AUC 上也最优。
                class_window_records: List[
                    Dict[str, object]
                ] = []
                candidate_metrics = _ngram_extended_metrics(
                    model,
                    val_windows,
                    alpha,
                    order,
                    split="val",
                    include_auc=tuning_metric
                    in (
                        "val_pr_auc_macro",
                        "val_pr_auc_macro_lift",
                        "val_roc_auc_macro",
                    ),
                    window_sink=(
                        class_window_records
                        if classification_tunable
                        else None
                    ),
                    window_classification=(
                        classification_tunable
                    ),
                )
                if classification_tunable:
                    values: List[float] = []
                    usable = True
                    for window_record in class_window_records:
                        classification = window_record.get(
                            "classification"
                        )
                        if not isinstance(
                            classification, dict
                        ):
                            usable = False
                            break
                        number = _finite_float(
                            classification.get(
                                classification_metric_key
                            )
                        )
                        if number is None:
                            usable = False
                            break
                        values.append(number)
                    if usable and len(values) >= 3:
                        candidate_window_classification[
                            (order, alpha)
                        ] = values
                for key in (
                    "val_loss",
                    "val_ppl",
                    "val_bits_per_byte",
                ):
                    if key in candidate_metrics:
                        record[key] = candidate_metrics[key]
                number = _finite_float(
                    candidate_metrics.get(tuning_metric)
                )
                if number is not None:
                    record[tuning_metric] = number

            record["tuning_value"] = record.get(tuning_metric)
            _write(record)
            candidates.append(record)

        def _display_value(row: Dict[str, object]) -> str:
            value = _finite_float(row.get(tuning_metric))
            if value is None:
                return "NA"
            return f"{value:.4f}"

        print(
            "[ngram] alpha="
            f"{alpha:g}: "
            + ", ".join(
                f"order {row['order']}="
                + _display_value(row)
                for row in candidates[
                    -model.max_order:
                ]
            )
            + f" ({tuning_metric})"
        )

    # val 上选最优；并列时偏向更小的阶数与更小的 alpha
    # （简单优先，避免在验证集上过拟合出复杂配置）。
    def _candidate_rank(row: Dict[str, object]):
        value = _finite_float(row.get(tuning_metric))
        if value is None:
            return (1, 0.0, row["order"], row["alpha"])
        return (
            0,
            -value if higher_is_better else value,
            row["order"],
            row["alpha"],
        )

    valid_candidates = [
        row for row in candidates if _candidate_rank(row)[0] == 0
    ]
    if not valid_candidates:
        raise SystemExit(
            f"n-gram 调参没有任何候选提供可用的 {tuning_metric}："
            "无法按当前指标选出 (order, alpha)；请检查指标"
            "是否适用于该评估集，或显式改用 val_loss"
        )
    ranked_candidates = sorted(
        valid_candidates,
        key=_candidate_rank,
    )
    point_best = ranked_candidates[0]
    best = point_best
    runner_up = (
        ranked_candidates[1]
        if len(ranked_candidates) > 1
        else None
    )

    # 点估计最优可能只领先很小一截；损失类与分类指标都用
    # 逐窗口配对 one-SE 规则，把统计上不可分辨的候选按更简单
    # 优先收敛，降低网格调参的 winner's curse（AUC 除外，逐
    # 窗口类支持稀疏、与全局口径不一致）。
    selection = _select_ngram_candidate_one_se(
        point_best,
        valid_candidates,
        (
            candidate_window_classification
            if classification_tunable
            else candidate_window_losses
        ),
        tuning_metric,
    )
    if (
        selection is not None
        and selection.get("available")
        and not selection.get("selected_is_point_best")
    ):
        selected_order = int(selection["selected"]["order"])
        selected_alpha = float(selection["selected"]["alpha"])
        selected_candidate = next(
            (
                candidate
                for candidate in valid_candidates
                if int(candidate["order"]) == selected_order
                and abs(
                    float(candidate["alpha"]) - selected_alpha
                )
                <= 1e-15
            ),
            None,
        )
        if selected_candidate is not None:
            best = selected_candidate
            runner_up = point_best

    best_order = int(best["order"])
    best_alpha = float(best["alpha"])
    tuning_diagnostics = _ngram_tuning_diagnostics(
        best,
        runner_up,
        tuning_metric,
        alpha_grid,
        args.ngram_max_order,
        len(candidates),
        len(valid_candidates),
        selection=selection,
    )

    if (
        selection is not None
        and selection.get("available")
        and not selection.get("selected_is_point_best")
    ):
        selected_detail = next(
            (
                detail
                for detail in selection.get("tied", [])
                if int(detail["order"]) == best_order
                and abs(
                    float(detail["alpha"]) - best_alpha
                )
                <= 1e-15
            ),
            None,
        )
        if isinstance(selected_detail, dict):
            print(
                "[ngram] one-SE 选择更简单配置: "
                f"order={best_order}, alpha={best_alpha:g}；"
                "相对点估计最优的逐窗口配对差="
                f"{float(selected_detail['paired_mean_diff']):.6g}"
                "（阈值="
                f"{float(selected_detail['threshold']):.6g}）"
            )

    print(
        "[ngram] val 调优结果: order="
        f"{best_order}, alpha={best_alpha:g}, "
        f"{tuning_metric}="
        f"{float(best[tuning_metric]):.4f}, "
        f"val_loss={best['val_loss']:.4f}"
    )
    if tuning_diagnostics.get("metric_gap") is not None:
        print(
            "[ngram] winner 与 runner-up 的 "
            f"{tuning_metric} 差距="
            f"{float(tuning_diagnostics['metric_gap']):.6g}"
        )
    for advisory in tuning_diagnostics.get(
        "advisories", []
    ):
        print(f"[ngram][warn] {advisory}")

    # ---- 用调优好的配置算同口径完整指标 ----
    # 统计基线是确定性的：评估不确定性只能来自评估窗口抽样，
    # 因此与神经模型同口径给出逐窗口 bootstrap 区间，并落盘
    # 逐窗口记录供跨运行配对比较。
    bootstrap_replicates = int(
        getattr(args, "eval_bootstrap", 0)
    )
    bootstrap_block = int(
        getattr(args, "eval_bootstrap_block", 1)
    )
    val_window_records: List[Dict[str, float]] = []
    final_metrics = _ngram_extended_metrics(
        model,
        val_windows,
        best_alpha,
        best_order,
        split="val",
        bootstrap_replicates=bootstrap_replicates,
        bootstrap_seed=_eval_bootstrap_seed(
            dataset.data_sha256,
            "val",
            args.eval_batches,
            args.batch_size,
            dataset.seq_len,
        ),
        bootstrap_block=bootstrap_block,
        window_sink=val_window_records,
    )

    final_record = {
        "step": "final",
        "model": "ngram",
        "ngram_order": best_order,
        "ngram_alpha": best_alpha,
        "ngram_max_order": args.ngram_max_order,
        "ngram_tuning_metric": tuning_metric,
        "ngram_tuning_metric_source": tuning_metric_source,
        "ngram_tuning": tuning_diagnostics,
        # 统计基线同样自带实验追踪字段，便于 metrics.jsonl
        # 脱离 config.json 单独归档。
        "deterministic": True,
        "seed": args.seed,
        "data_sha256": dataset.data_sha256,
        "data_split_sha256": dict(dataset.split_sha256),
        "data_effective_train_sha256": (
            dataset.effective_train_sha256
        ),
        "script_sha256": ngram_run_metadata.get(
            "script_sha256"
        ),
        "git_commit": ngram_run_metadata.get("git_commit"),
        "git_dirty": ngram_run_metadata.get("git_dirty"),
        "run_started_utc": ngram_run_metadata.get(
            "timestamp_utc"
        ),
        "run_completed_utc": datetime.datetime.now(
            datetime.timezone.utc
        ).isoformat(),
        **final_metrics,
    }

    _write(final_record)
    print(
        json.dumps(
            _json_safe({"final": final_record}),
            ensure_ascii=False,
        )
    )

    if val_window_records:
        overlap_fraction: Optional[float] = None
        starts = dataset._fixed_starts.get(
            "val", {}
        ).get("starts")
        if starts is not None and len(starts) > 1:
            gaps = starts[1:] - starts[:-1]
            overlap_count = int(
                (gaps < dataset.seq_len).sum().item()
            )
            overlap_fraction = overlap_count / (
                len(starts) - 1
            )
        eval_windows_payload: Dict[str, object] = {
            "split": "val",
            "data_sha256": dataset.data_sha256,
            "split_sha256": dataset.split_sha256.get("val"),
            "seq_len": int(dataset.seq_len),
            "batch_size": int(args.batch_size),
            "batches": int(args.eval_batches),
            "n_windows": len(val_window_records),
            "overlap_fraction": overlap_fraction,
            "windows": val_window_records,
        }
        with open(
            out_dir / "eval_windows.json",
            "w",
            encoding="utf-8",
        ) as f:
            json.dump(
                _json_safe(eval_windows_payload),
                f,
                ensure_ascii=False,
            )

    # ---- 一次性 test 评估（沿用训练运行同一封存协议）----
    # 注意：本入口每次运行都会新建输出目录语义（metrics.jsonl
    # 截断重写），test 只在显式 --evaluate-test 时评估一次，
    # 且 (order, alpha) 完全沿用 val 上调优的结果，绝不在
    # test 上二次调参。
    if args.evaluate_test:
        if not dataset.has_test:
            raise SystemExit(
                "--evaluate-test 需要有效的测试集："
                "请设置正的 --test-fraction 且语料足够长"
            )

        if test_evaluation_sealed(
            out_dir,
            getattr(args, "test_ledger", None),
        ):
            raise SystemExit(
                "[test] 输出目录已有测试集评估记录/封条；"
                "统计基线也遵守唯一一次解封协议，请使用全新的 "
                "--out 目录"
            )

        test_audit = audit_data_splits(
            dataset,
            include_test=True,
        )
        print_data_audit(test_audit)

        leakage_blocked = (
            not args.allow_data_leakage
            and not enforce_data_leakage_gate(
                test_audit,
                "test",
            )
        )
        eval_duplicate_blocked = (
            not getattr(
                args, "allow_eval_duplicates", False
            )
            and not enforce_evaluation_duplicate_gate(
                test_audit,
                "test",
            )
        )
        strict_blocked = (
            args.strict_data_audit
            and not enforce_strict_data_audit(
                test_audit,
                "test",
            )
        )
        label_integrity_blocked = (
            not args.allow_corrupt_test_labels
            and not enforce_test_label_integrity(
                test_audit,
                "test",
            )
        )
        shift_blocked = (
            not enforce_distribution_shift_gate(
                test_audit,
                max_byte_js=args.max_byte_shift,
                max_bigram_js=args.max_bigram_shift,
                max_conditional_js=args.max_conditional_shift,
                context="test",
            )
        )
        if (
            leakage_blocked
            or eval_duplicate_blocked
            or strict_blocked
            or shift_blocked
            or label_integrity_blocked
        ):
            # 统计基线同样不能在泄露/损坏/分布偏移的测试集上
            # 报告指标；不写 test 记录，名额未消耗。
            print(
                "[test] 数据审计在测试集上发现泄露/损坏/"
                "标签噪声或分布偏移问题：拒绝解封测试集"
                "（不写入 test 记录）。请先清洗数据后重跑。"
            )
            test_windows = None
        else:
            test_protocol_check = probe_data_pipeline(
                dataset,
                torch.device("cpu"),
                include_test=True,
            )
            if not test_protocol_check["ok"]:
                print(
                    "[test] 测试集数据管线检查未通过，"
                    "拒绝解封（不写入 test 记录）："
                )
                for failure in test_protocol_check[
                    "failures"
                ]:
                    print(f"  - {failure}")
                test_windows = None
            else:
                # 研究级访问账本与神经路径同一协议：路径级封条
                # 挡不住「新建目录/换 seed 后再次访问同一测试
                # 集」。统计基线也是候选，必须进入同一账本，
                # 否则 --final-test-comparison 会漏报它的访问。
                ledger_path = (
                    Path(args.test_ledger)
                    if getattr(args, "test_ledger", None)
                    else out_dir / "test_access_ledger.jsonl"
                )
                if getattr(args, "test_ledger", None) is None:
                    print(
                        "[test] [warn] 未指定 --test-ledger：访问"
                        "账本只写在本次输出目录，无法阻止其它目录"
                        "重复解封同一测试集"
                    )
                access_key = _test_access_key(
                    dataset.data_sha256,
                    dataset.split_sha256,
                    dataset.test_fraction,
                )
                access_check = check_test_access_ledger(
                    ledger_path,
                    access_key,
                    out_dir,
                )
                if _test_access_repeat_blocked(
                    access_check
                ) and not getattr(
                    args,
                    "allow_repeat_test_access",
                    False,
                ):
                    raise SystemExit(
                        _repeat_test_access_error(access_check)
                    )
                append_test_access_ledger(
                    ledger_path,
                    {
                        **access_key,
                        "out_dir": str(out_dir),
                        "study_id": getattr(
                            args, "study_id", None
                        ),
                        "seed": args.seed,
                        "model": "ngram",
                        "ngram_order": best_order,
                        "ngram_alpha": best_alpha,
                        "script_sha256": ngram_run_metadata.get(
                            "script_sha256"
                        ),
                        "git_commit": ngram_run_metadata.get(
                            "git_commit"
                        ),
                        "hypothesis": getattr(
                            args, "hypothesis", None
                        ),
                        "primary_metric": getattr(
                            args, "primary_metric", None
                        ),
                        "allow_repeat_access": bool(
                            getattr(
                                args,
                                "allow_repeat_test_access",
                                False,
                            )
                        ),
                        "accessed_utc": datetime.datetime.now(
                            datetime.timezone.utc
                        ).isoformat(),
                        "note": (
                            "统计基线测试集访问账本；同一 "
                            "data/split 指纹的全部访问都应进入"
                            "最终报告"
                        ),
                    },
                )
                print(
                    "[test] 访问账本已记录: "
                    f"{ledger_path}（历史访问 "
                    f"{access_check['matching_accesses'] + 1} 次）"
                )

                # 与神经训练路径同一封存协议：先落
                # test_started 记录与持久封条，再访问测试
                # 窗口；评估中途崩溃也不能重复解封。
                _write({
                    "step": "test_started",
                    "split": "test",
                    "model": "ngram",
                })
                write_test_evaluation_seal(
                    out_dir,
                    {
                        "dataset_sha256": (
                            dataset.data_sha256
                        ),
                        "test_fraction": (
                            dataset.test_fraction
                        ),
                        "split_sha256": dict(
                            dataset.split_sha256
                        ),
                        "model": "ngram",
                    },
                )
                test_windows = _ngram_eval_batches(
                    dataset,
                    "test",
                    args.batch_size,
                    args.eval_batches,
                )

        if test_windows is not None:
            test_metrics = _ngram_extended_metrics(
                model,
                test_windows,
                best_alpha,
                best_order,
                split="test",
                bootstrap_replicates=bootstrap_replicates,
                bootstrap_seed=_eval_bootstrap_seed(
                    dataset.data_sha256,
                    "test",
                    args.eval_batches,
                    args.batch_size,
                    dataset.seq_len,
                ),
                bootstrap_block=bootstrap_block,
            )

            _write({
                "step": "test",
                "model": "ngram",
                "ngram_order": best_order,
                "ngram_alpha": best_alpha,
                "ngram_tuning_metric": tuning_metric,
                **test_metrics,
                "data_audit": test_audit,
                "data_protocol_check": test_protocol_check,
            })

            print(
                json.dumps(
                    _json_safe({"test": test_metrics}),
                    ensure_ascii=False,
                )
            )

    metrics_file.close()

    # ---- config.json：与训练运行相同结构，可直接 --compare ----
    payload = {
        # 与 write_run_config 使用同一配置 schema；统计基线也是
        # 独立实验单元，归档工具不应遇到两种结构。
        "config_schema": _ENVIRONMENT_CONFIG_SCHEMA,
        # 计数与固定窗口评估都不消耗随机性：显式标记，供
        # --compare 折叠多个 seed 的复制运行（不能当独立重复）。
        "deterministic": True,
        "config": {
            "mode": "ngram",
            "vocab_size": 256,
            "seq_len": dataset.seq_len,
            "ngram_max_order": args.ngram_max_order,
            "ngram_alpha_grid": alpha_grid,
            "ngram_order": best_order,
            "ngram_alpha": best_alpha,
            "ngram_tuning_metric": tuning_metric,
            "ngram_tuning_metric_source": (
                tuning_metric_source
            ),
            "ngram_tuning": tuning_diagnostics,
        },
        # 统计基线没有优化器与训练轮数；comparison_family 让
        # 受控变量检查只在神经网络运行之间进行。
        "comparison_protocol": {
            "comparison_family": "statistical",
            "optimizer": "none",
            "lr": None,
            "lr_schedule": "none",
            "warmup_steps": None,
            "total_steps": None,
            "weight_decay": None,
            "grad_clip": None,
            "batch_size": args.batch_size,
            "data_augmentation": "none",
            "seq_len": dataset.seq_len,
            "val_fraction": dataset.val_fraction,
            "test_fraction": dataset.test_fraction,
            "group_separator": getattr(args, "group_separator", None),
            "deduplicate_train_groups": bool(
                getattr(
                    args,
                    "deduplicate_train_groups",
                    False,
                )
            ),
            "drop_train_shared_chunks": bool(
                getattr(
                    args,
                    "drop_train_shared_chunks",
                    False,
                )
            ),
            "drop_train_near_duplicate_groups": bool(
                getattr(
                    args,
                    "drop_train_near_duplicate_groups",
                    False,
                )
            ),
            "near_duplicate_threshold": (
                _near_duplicate_threshold_or_default(
                    getattr(
                        args,
                        "near_duplicate_threshold",
                        _NEAR_DUP_DEFAULT_THRESHOLD,
                    )
                )
            ),
            "near_duplicate_shingle_bytes": (
                _near_duplicate_shingle_or_default(
                    getattr(
                        args,
                        "near_duplicate_shingle_bytes",
                        _NEAR_DUP_DEFAULT_SHINGLE_BYTES,
                    )
                )
            ),
            "clean_train_against_test": bool(
                getattr(
                    args,
                    "clean_train_against_test",
                    False,
                )
            ),
            "drop_train_corrupt_groups": bool(
                getattr(
                    args,
                    "drop_train_corrupt_groups",
                    False,
                )
            ),
            "drop_train_corrupt_bytes": bool(
                getattr(
                    args,
                    "drop_train_corrupt_bytes",
                    False,
                )
            ),
            "drop_train_degenerate_groups": bool(
                getattr(
                    args,
                    "drop_train_degenerate_groups",
                    False,
                )
            ),
            "drop_train_degenerate_runs": bool(
                getattr(
                    args,
                    "drop_train_degenerate_runs",
                    False,
                )
            ),
            "eval_content_access": (
                getattr(dataset, "eval_content_access", None)
                if dataset is not None
                else None
            ),
            "cleaning_domain_justification": getattr(
                args, "cleaning_domain_justification", None
            ),
            "split_policy": getattr(
                args, "split_policy", "contiguous"
            ),
            "time_order_evidence": getattr(
                args, "time_order_evidence", None
            ),
            "entity_audit": getattr(
                args, "data_entity_audit", None
            ),
            "allow_data_leakage": bool(
                getattr(args, "allow_data_leakage", False)
            ),
            "allow_corrupt_test_labels": bool(
                getattr(args, "allow_corrupt_test_labels", False)
            ),
            "allow_eval_duplicates": bool(
                getattr(args, "allow_eval_duplicates", False)
            ),
            "eval_interval": None,
            "eval_batches": args.eval_batches,
            "eval_bootstrap": args.eval_bootstrap,
            "eval_bootstrap_block": args.eval_bootstrap_block,
            "data_sha256": dataset.data_sha256,
            # 与神经运行相同：逐 split 内容指纹用于核对
            # ngram 与神经运行是否真的看到同一组 train/val/test
            # 字节段；只比整体文件指纹无法发现群组吸附/清洗/
            # 切分实现差异。
            "split_sha256": dict(dataset.split_sha256) or None,
            # 清洗后的有效训练集指纹：ngram 计数必须与神经
            # 窗口覆盖同一套训练字节。
            "effective_train_sha256": (
                dataset.effective_train_sha256
            ),
            "split_isolation": dict(
                dataset.split_isolation
            ),
        },
        "args": {
            key: value
            for key, value in vars(args).items()
            if key
            not in {
                "data_sha256",
                "data_bytes",
                "data_val_fraction",
                "data_test_fraction",
            }
        },
        "n_params": 0,
        "data": {
            "path": args.data,
            "sha256": dataset.data_sha256,
            "bytes": dataset.num_bytes,
            "val_fraction": dataset.val_fraction,
            "test_fraction": dataset.test_fraction,
            "group_separator": getattr(args, "group_separator", None),
            "deduplicate_train_groups": bool(
                getattr(args, "deduplicate_train_groups", False)
            ),
            "drop_train_shared_chunks": bool(
                getattr(args, "drop_train_shared_chunks", False)
            ),
            "drop_train_near_duplicate_groups": bool(
                getattr(
                    args,
                    "drop_train_near_duplicate_groups",
                    False,
                )
            ),
            "near_duplicate_audit": bool(
                getattr(args, "near_duplicate_audit", False)
            ),
            "near_duplicate_threshold": (
                _near_duplicate_threshold_or_default(
                    getattr(
                        args,
                        "near_duplicate_threshold",
                        _NEAR_DUP_DEFAULT_THRESHOLD,
                    )
                )
            ),
            "near_duplicate_shingle_bytes": (
                _near_duplicate_shingle_or_default(
                    getattr(
                        args,
                        "near_duplicate_shingle_bytes",
                        _NEAR_DUP_DEFAULT_SHINGLE_BYTES,
                    )
                )
            ),
            "split_bounds": {
                split: list(bounds)
                for split, bounds in dataset.split_bounds.items()
            },
            "split_isolation": dict(dataset.split_isolation),
            "split_fractions": dataset.split_fractions,
            "split_sha256": dict(dataset.split_sha256),
            "effective_train_bytes": (
                dataset.effective_train_bytes
            ),
            "effective_train_sha256": (
                dataset.effective_train_sha256
            ),
            "train_cleaning": dataset.train_cleaning,
            "group_cuts": (
                dict(dataset.group_cuts)
                if dataset.group_cuts is not None
                else None
            ),
            "groups_per_split": (
                dict(dataset.groups_per_split)
                if dataset.groups_per_split is not None
                else None
            ),
        },
        "data_audit": data_audit,
        "data_protocol_check": data_protocol_check,
        "reference_baselines": reference,
        "run_metadata": ngram_run_metadata,
        "sanity_check": None,
    }
    # 与神经训练入口一致：环境快照单独落一份 environment.json，
    # config.json 顶层只保留带文件哈希的摘要。统计基线也是独立
    # 实验单元，--check-environment 与归档清单必须能核对它产自
    # 哪套数值环境。
    environment_record = write_run_environment_record(
        out_dir,
        ngram_run_metadata,
    )
    if environment_record is not None:
        payload["environment"] = environment_record
    payload["comparison_protocol_sha256"] = _sha256_text(
        json.dumps(
            _json_safe(payload["comparison_protocol"]),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
    )

    # 与训练入口一样原子写 config.json：计数/评估结束后写盘失败
    # 不能留下半截 JSON，否则跟踪信息与归档清单都会失效。
    _atomic_write_json(out_dir / "config.json", payload)


# ============================================================
# Training-curve analysis
# ============================================================

# 曲线诊断最少需要的验证点数：少于该数量时只报告原始曲线，
# 不给出过拟合/欠拟合结论，避免用一两个点下判断。
_CURVE_MIN_EVAL_POINTS = 3

# 验证损失从最优点回升超过该比例、且训练损失仍在下降时
# 判定为过拟合。
_CURVE_OVERFIT_REGRESSION = 0.02

# 判定「训练损失仍在下降」的最小相对降幅。
_CURVE_TRAIN_STILL_DESCENDING = 0.02

# 最近一次验证间隔内训练/验证损失仍下降超过该比例时，
# 判定为尚未收敛（继续训练可能还有收益）。
_CURVE_STILL_DESCENDING = 0.05

# 整体相对下降小于该比例、且最终训练损失仍接近随机基线
# （baseline_loss）时判定为欠拟合/几乎没有学到东西。
_CURVE_NO_LEARN_DROP = 0.05
_CURVE_NO_LEARN_BASELINE = 0.9

# 过拟合的第二条证据：训练损失已不再下降（记忆化 regime 下
# 往往在低位走平），但最终训练损失比验证损失低出该相对比例
# 以上（泛化 gap 大）且验证损失回升达到阈值。只看「训练损失
# 仍在降」会把这类典型过拟合误报成 healthy。
_CURVE_GENERALIZATION_GAP = 0.1

# 泛化 gap 的早期预警：从首个验证点到最后一个验证点，泛化
# gap（相对验证损失的比例）扩大达到该幅度、且最终 gap 已不低
# 时，即使验证损失尚未明显回升（未触发 overfitting），也提示
# 「训练损失继续降但验证收益停滞」的过拟合前兆，建议提前准备
# 早停/加正则化。等待验证损失明显回升后再报警会偏晚。
_CURVE_GAP_WIDENING = 0.05

# 学习率已退火到峰值的该比例以下时，训练/验证双走平更像
# 调度末期的正常收敛平台，而不是学习率不当/数据管道问题
# （默认调度为 cosine 退火到峰值的 10%，留少量余量）。
_CURVE_LR_ANNEALED_FRACTION = 0.15

# 最近一次验证间隔内训练与验证损失同时相对上升达到该比例
# 时，判定为有限发散/训练不稳定（不是过拟合：过拟合要求训练
# 损失仍在下降）。这类曲线继续训练通常只会更糟，应优先降低
# 学习率、收紧梯度裁剪并从稳定检查点恢复。
_CURVE_DIVERGENCE_RISE = 0.10

# 梯度范数尖峰预警：近期窗口最大值达到此前中位数的该倍数时，
# 即使损失尚未变成 NaN，也提示梯度爆炸/学习率过大的前兆。
_CURVE_GRAD_SPIKE_RATIO = 5.0
_CURVE_GRAD_SPIKE_MIN_HISTORY = 20
_CURVE_GRAD_SPIKE_RECENT_FRACTION = 0.2
_CURVE_GRAD_SPIKE_MIN_RECENT = 5

_SPARK_BLOCKS = "▁▂▃▄▅▆▇█"


def _sparkline(values, width=48):
    """
    把一列数值渲染成等宽 Unicode 走势条，便于在终端快速扫
    训练曲线走势；数值越小时块越低（损失越小越靠下）。

    width<=0 返回空串；width=1 时只保留最后一个点（最近一次
    观测），避免降采样的端点插值除以 width-1。
    """
    # 记录里的数值可能来自 JSON（含超出 float 范围的整数）或
    # 已污染的曲线；无法得到有限浮点时返回空图，而不是让
    # float()/int(nan) 在展示路径抛异常。
    numeric: List[float] = []
    for value in values:
        try:
            number = float(value)
        except (TypeError, ValueError, OverflowError):
            return ""
        if not math.isfinite(number):
            return ""
        numeric.append(number)
    values = numeric

    if not values or width <= 0:
        return ""

    if len(values) > width:
        if width == 1:
            values = [values[-1]]
        else:
            # 采样必须覆盖两个端点：等距取整会让最后一个点落在
            # int((width-1)*stride) < len-1 上被丢掉，走势条看不到
            # 训练末段的收敛/发散，而末段恰恰是诊断最关心的部分。
            last = len(values) - 1
            values = [
                values[
                    min(
                        last,
                        int(round(index * last / (width - 1))),
                    )
                ]
                for index in range(width)
            ]

    # 合法但极大的有限值（如 -1e308 与 +1e308）会让 high-low
    # 溢出成 inf，进而 (value-low)/(high-low) 变成 inf/inf=NaN，
    # int(NaN) 在展示路径抛异常。归一化到 [-1,1] 后分块位置
    # 不变；正常量级不缩放，保持历史输出逐位一致。
    scale = max(abs(value) for value in values)
    if scale > 1.0e150:
        low = min(value / scale for value in values)
        high = max(value / scale for value in values)
        normalized = [value / scale for value in values]
    else:
        low = min(values)
        high = max(values)
        normalized = values

    if high - low <= 0.0:
        return _SPARK_BLOCKS[0] * len(values)

    return "".join(
        _SPARK_BLOCKS[
            min(
                len(_SPARK_BLOCKS) - 1,
                int(
                    (value - low)
                    / (high - low)
                    * (len(_SPARK_BLOCKS) - 1)
                    + 0.5
                ),
            )
        ]
        for value in normalized
    )


def _finite_gap(
    train_loss: Optional[float],
    val_loss: Optional[float],
) -> Optional[float]:
    """训练/验证损失之差；任一端缺失或差值溢出时返回 None。"""
    if train_loss is None or val_loss is None:
        return None
    difference = float(train_loss) - float(val_loss)
    if not math.isfinite(difference):
        return None
    return round(difference, 6)


def analyze_training_curve(
    records: List[Dict[str, object]],
    baseline_loss: Optional[float] = None,
) -> Dict[str, object]:
    """
    基于完整训练曲线（metrics.jsonl）而不是最终单个数值做诊断。

    对每个周期验证点，取「自上次验证以来训练损失的平均值」与
    val_loss 配对，按以下规则给出结论：

    - ``overfitting``：验证损失最优点早于最后一次验证、最终
      验证损失较最优值回升超过阈值，且训练损失仍在下降、
      或最终训练损失已显著低于验证损失（泛化 gap 大——
      记忆化 regime 下训练损失常在低位走平而不是继续下降）；
    - ``underfitting``：训练损失整体几乎不降，且最终仍接近随
      机基线（ln(vocab_size)）；
    - ``plateau``：训练与验证损失最近一个验证间隔内都没有
      有效下降（排除过拟合后，两者都不降指向欠拟合、学习率
      不当或数据管道问题；学习率已退火殆尽时则更像正常
      收敛平台，报告会结合记录中的 lr 曲线区分两种情形）；
    - ``not_converged``：最近一次间隔内训练与验证损失仍同步
      明显下降，说明训练步数/学习率还没到平台；
    - ``diverging``：最近一次间隔内训练与验证损失同时明显
      上升（有限发散/训练不稳定），需要降低学习率、收紧
      梯度裁剪并从稳定检查点恢复；
    - ``diverged``：最近一步损失非有限（NaN/Inf）；
    - ``healthy``：验证仍在改善（或训练验证同步缓降）且
      验证未回升；
    - ``insufficient_data``：验证点不足以做结论。

    除状态外还检查「尚未 NaN 的前兆」：近期梯度范数达到此前
    中位数的 ``_CURVE_GRAD_SPIKE_RATIO`` 倍时置
    ``grad_norm_spike_warning``，即使曲线仍被判为 healthy/
    plateau 也会在 warnings 中提示排查梯度爆炸/学习率过大。

    返回的诊断会追加为 ``{"step": "curve_analysis", ...}``
    记录，并打印对应建议（过拟合→正则化/增大数据/早停，
    欠拟合/双平台→查学习率、优化器与数据管道，有限发散→
    降学习率/收紧裁剪/从稳定检查点恢复）。
    """
    train_points: List[Tuple[int, float]] = []
    grad_points: List[Tuple[int, float]] = []
    nonfinite_steps: List[int] = []
    eval_points: List[Dict[str, object]] = []
    pending: List[float] = []
    peak_lr: Optional[float] = None
    last_lr: Optional[float] = None

    for record in records:
        step = record.get("step")

        if not isinstance(step, int):
            continue

        if "grad_norm" in record or "train_loss" in record:
            train_loss = record.get("train_loss")
            grad_norm = record.get("grad_norm")
            # 非有限事件既可能落在损失上（写盘为 null，在线记录
            # 保留 NaN/Inf），也可能只落在梯度上。判据必须覆盖
            # 原值非有限的情况，否则 NaN 会流进 _sparkline 的
            # int() 转换。
            # JSON 允许任意大整数（如 10**400）；float() 会溢出，
            # 必须与 NaN/Inf 一样按非有限事件处理，而不是让整份
            # 曲线诊断崩溃。
            train_value = _finite_float(train_loss)
            train_finite = train_value is not None
            grad_value = _finite_float(grad_norm)
            grad_nonfinite = (
                "grad_norm" in record and grad_value is None
            )
            nonfinite = not train_finite or grad_nonfinite
            if nonfinite:
                if (
                    not nonfinite_steps
                    or nonfinite_steps[-1] != step
                ):
                    nonfinite_steps.append(step)
            if train_finite:
                train_points.append((step, train_value))
                pending.append(train_value)

            # 有限梯度范数序列：用于在损失尚未变成 NaN 时发现
            # 梯度尖峰（爆炸/学习率过大的前兆）。
            if "grad_norm" in record and not grad_nonfinite:
                grad_points.append((step, grad_value))

            # 学习率曲线（每步记录）：用于区分「双平台」是调度
            # 末期的正常收敛，还是高学习率下的训练停滞。
            record_lr = _finite_float(record.get("lr"))
            if record_lr is not None:
                last_lr = record_lr
                if (
                    peak_lr is None
                    or record_lr > peak_lr
                ):
                    peak_lr = record_lr

        if "val_loss" not in record:
            continue

        # 盘上记录里的 NaN/Inf 会被 _json_safe 写成 null，在线
        # 记录保留原值；超出 float 范围的整数同样按非有限事件
        # 处理，避免 NaN/溢出值流入 _sparkline 的 int() 转换。
        val_loss = _finite_float(record.get("val_loss"))
        if val_loss is None:
            if (
                not nonfinite_steps
                or nonfinite_steps[-1] != step
            ):
                nonfinite_steps.append(step)
            eval_points.append({
                "step": step,
                "val_loss": None,
                "train_loss": None,
            })
            pending = []
            continue

        # 用带缩放的均值而不是直接 sum：两个各自有限的大损失
        # （如 1e308）相加会溢出成 inf，让 eval 点的 train_loss
        # 以及由它派生的 gap/发散判据全部失真。正常量级下
        # _mean 仍走原来的直接求和路径，历史数值不变。
        train_at_eval = (
            _mean(pending)
            if pending
            else (train_points[-1][1] if train_points else None)
        )

        eval_points.append({
            "step": step,
            "val_loss": val_loss,
            "train_loss": train_at_eval,
        })
        pending = []

    finite_evals = [
        point
        for point in eval_points
        if point["val_loss"] is not None
    ]

    # 「最近仍是非有限」才判定发散；早先出现过 NaN 但后续恢复
    # 的运行保留警告但不直接判发散。
    recent_nonfinite = bool(nonfinite_steps) and (
        not train_points
        or nonfinite_steps[-1] >= train_points[-1][0]
    )
    last_eval_nonfinite = bool(
        eval_points and eval_points[-1]["val_loss"] is None
    )

    warnings: List[str] = []

    # 梯度尖峰：与「此前中位数」比较而不是与绝对阈值比较，
    # 不同模型/模式的正常梯度量级差异很大。只把近期窗口纳入
    # 判断，早期 warmup 的高梯度不应让最终报告永久报警。
    grad_spike = False
    grad_spike_ratio: Optional[float] = None
    grad_spike_recent_max: Optional[float] = None
    grad_prior_median: Optional[float] = None
    if len(grad_points) >= _CURVE_GRAD_SPIKE_MIN_HISTORY:
        grad_values = [value for _, value in grad_points]
        recent_count = max(
            _CURVE_GRAD_SPIKE_MIN_RECENT,
            int(
                len(grad_values)
                * _CURVE_GRAD_SPIKE_RECENT_FRACTION
            ),
        )
        recent_count = min(recent_count, len(grad_values) - 1)
        prior_values = sorted(grad_values[:-recent_count])
        grad_spike_recent_max = max(
            grad_values[-recent_count:]
        )
        grad_prior_median = _median(prior_values)
        if grad_prior_median > 0.0:
            ratio = (
                grad_spike_recent_max / grad_prior_median
            )
            if math.isfinite(ratio):
                grad_spike_ratio = ratio
                grad_spike = (
                    ratio >= _CURVE_GRAD_SPIKE_RATIO
                )
            else:
                # 中位数极小、近期最大值极大时比值会溢出成 inf；
                # 尖峰仍然真实存在，但报告字段必须是有限数或
                # None，不能把 inf 写进 metrics/config。
                grad_spike = True

    analysis: Dict[str, object] = {
        "n_train_steps": len(train_points),
        "n_eval_points": len(finite_evals),
        "n_nonfinite_events": len(nonfinite_steps),
        "recent_grad_norm_max": (
            round(grad_spike_recent_max, 6)
            if grad_spike_recent_max is not None
            else None
        ),
        "prior_grad_norm_median": (
            round(grad_prior_median, 6)
            if grad_prior_median is not None
            else None
        ),
        "grad_norm_spike_ratio": (
            round(grad_spike_ratio, 6)
            if grad_spike_ratio is not None
            else None
        ),
        "grad_norm_spike_warning": bool(grad_spike),
        "nonfinite_steps": nonfinite_steps[-10:],
        "peak_lr": peak_lr,
        "last_lr": last_lr,
        "last_lr_over_peak": (
            _safe_ratio(last_lr, peak_lr)
            if peak_lr is not None
            and peak_lr > 0.0
            and last_lr is not None
            else None
        ),
        "warnings": warnings,
        "status": "insufficient_data",
        "recommendation": (
            "验证点不足，继续训练后再看曲线；"
            "至少需要 3 个周期验证点。"
        ),
    }

    if nonfinite_steps:
        warnings.append(
            f"训练/验证损失出现 {len(nonfinite_steps)} 次非有限"
            "（NaN/Inf）记录；按排查路径逐项检查：数据是否含 "
            "NaN/Inf → log(0)/除零/softmax 溢出 → fp16 混合"
            "精度溢出 → 梯度爆炸/学习率过大（见 "
            "diagnose_non_finite 输出的 nan_diagnosis 记录）。"
        )

    if grad_spike:
        ratio_text = (
            f"{grad_spike_ratio:.1f} 倍"
            if grad_spike_ratio is not None
            else "超出可表示的倍数范围"
        )
        warnings.append(
            "近期梯度范数最大值 "
            f"{grad_spike_recent_max:.4g} 是此前中位数 "
            f"{grad_prior_median:.4g} 的 "
            f"{ratio_text}：即使损失尚未变成 "
            "NaN，也可能是梯度爆炸/学习率过大的前兆。"
            "建议降低学习率、收紧 --grad-clip，并检查是否"
            "已出现参数/优化器状态污染。"
        )

    # 警告签名用布尔类别而不是完整文本：文本包含计数/百分比，
    # 每次验证都会变化，在线监控会退化成每点重复打印。
    analysis["warning_flags"] = {
        "nonfinite": bool(nonfinite_steps),
        "gap_widening": False,
        "diverging": False,
        "grad_spike": bool(grad_spike),
    }

    if (recent_nonfinite or last_eval_nonfinite) and (
        eval_points or train_points
    ):
        analysis["status"] = "diverged"
        analysis["recommendation"] = (
            "损失已发散为 NaN/Inf，不要继续加载该检查点训练；"
            "先按 diagnose_non_finite 的四步路径排查，"
            "再考虑降低学习率/开启梯度裁剪后重跑。"
        )
        analysis["curve_sparkline_train"] = _sparkline(
            [value for _, value in train_points]
        )
        return analysis

    if len(finite_evals) < _CURVE_MIN_EVAL_POINTS:
        analysis["curve_sparkline_train"] = _sparkline(
            [value for _, value in train_points]
        )
        analysis["curve_sparkline_val"] = _sparkline(
            [point["val_loss"] for point in finite_evals]
        )
        return analysis

    first = finite_evals[0]
    last = finite_evals[-1]
    previous = finite_evals[-2]

    best_index = min(
        range(len(finite_evals)),
        key=lambda index: finite_evals[index]["val_loss"],
    )
    best = finite_evals[best_index]

    regression = (
        (last["val_loss"] - best["val_loss"])
        / max(float(best["val_loss"]), 1e-12)
    )
    # 两端损失各自有限，但差值/相对值仍可能越过 float 上限；
    # 无法表示时按缺失处理，不能让 inf 进入状态判定与报告。
    if not math.isfinite(regression):
        regression = None

    def _relative_drop(newer, older):
        if older is None or newer is None:
            return None
        older = float(older)
        newer = float(newer)
        if older <= 0.0:
            return None
        try:
            value = (older - newer) / older
        except OverflowError:
            return None
        return value if math.isfinite(value) else None

    train_drop_total = _relative_drop(
        last["train_loss"],
        first["train_loss"],
    )
    train_still_down = (
        best_index < len(finite_evals) - 1
        and last["train_loss"] is not None
        and best["train_loss"] is not None
        and float(last["train_loss"])
        < float(best["train_loss"])
        * (1.0 - _CURVE_TRAIN_STILL_DESCENDING)
    )
    recent_train_drop = _relative_drop(
        last["train_loss"],
        previous["train_loss"],
    )
    recent_val_drop = _relative_drop(
        last["val_loss"],
        previous["val_loss"],
    )
    recent_train_rise = (
        None
        if recent_train_drop is None
        else -recent_train_drop
    )
    recent_val_rise = (
        None
        if recent_val_drop is None
        else -recent_val_drop
    )

    # 有限发散：最近一个验证间隔内训练与验证损失同时明显
    # 上升。它不是过拟合（过拟合要求训练损失仍在下降），也不是
    # 普通平台；继续训练通常只会更糟，必须先处理数值/优化
    # 稳定性。
    finite_diverging = (
        recent_train_drop is not None
        and recent_val_drop is not None
        and recent_train_drop <= -_CURVE_DIVERGENCE_RISE
        and recent_val_drop <= -_CURVE_DIVERGENCE_RISE
    )

    # 泛化 gap：最终训练损失比验证损失低出的相对比例。记忆化
    # regime 下训练损失常在低位走平而不再「仍在下降」，但
    # 大 gap + 验证回升同样是典型过拟合证据。
    def _gap_ratio(point):
        if (
            point["train_loss"] is None
            or float(point["val_loss"]) <= 0.0
        ):
            return None
        try:
            value = (
                float(point["val_loss"])
                - float(point["train_loss"])
            ) / float(point["val_loss"])
        except OverflowError:
            return None
        return value if math.isfinite(value) else None

    generalization_gap_ratio = _gap_ratio(last)
    generalization_gap_ratio_first = _gap_ratio(first)
    generalization_gap_trend = (
        generalization_gap_ratio - generalization_gap_ratio_first
        if generalization_gap_ratio is not None
        and generalization_gap_ratio_first is not None
        else None
    )
    if (
        generalization_gap_trend is not None
        and not math.isfinite(generalization_gap_trend)
    ):
        generalization_gap_trend = None
    train_below_val = (
        generalization_gap_ratio is not None
        and generalization_gap_ratio >= _CURVE_GENERALIZATION_GAP
    )

    analysis.update({
        "first_train_loss": first["train_loss"],
        "last_train_loss": last["train_loss"],
        "first_val_loss": first["val_loss"],
        "last_val_loss": last["val_loss"],
        "best_val_loss": best["val_loss"],
        "best_val_step": best["step"],
        "val_regression_from_best": (
            round(regression, 6)
            if regression is not None
            else None
        ),
        "train_val_gap_first": _finite_gap(
            first["train_loss"], first["val_loss"]
        ),
        "train_val_gap_last": _finite_gap(
            last["train_loss"], last["val_loss"]
        ),
        "generalization_gap_ratio_last": (
            None
            if generalization_gap_ratio is None
            else round(generalization_gap_ratio, 6)
        ),
        "generalization_gap_ratio_first": (
            None
            if generalization_gap_ratio_first is None
            else round(generalization_gap_ratio_first, 6)
        ),
        "generalization_gap_trend": (
            None
            if generalization_gap_trend is None
            else round(generalization_gap_trend, 6)
        ),
        "curve_sparkline_train": _sparkline(
            [value for _, value in train_points]
        ),
        "curve_sparkline_val": _sparkline(
            [point["val_loss"] for point in finite_evals]
        ),
    })

    # 过拟合前兆：验证损失尚未明显回升（未触发 overfitting），
    # 但泛化 gap 从首个验证点起持续扩大且已不低。此时训练损失
    # 仍在降而验证收益停滞，继续训练大概率只会加深过拟合；
    # 在状态判定后统一追加警告，不改变既有 status 语义。
    gap_widening = (
        generalization_gap_trend is not None
        and generalization_gap_ratio is not None
        and generalization_gap_trend >= _CURVE_GAP_WIDENING
        and generalization_gap_ratio >= _CURVE_GENERALIZATION_GAP
    )
    analysis["gap_widening_warning"] = bool(gap_widening)
    analysis["warning_flags"]["gap_widening"] = bool(
        gap_widening
    )
    analysis["recent_train_rise"] = (
        None
        if recent_train_rise is None
        else round(recent_train_rise, 6)
    )
    analysis["recent_val_rise"] = (
        None
        if recent_val_rise is None
        else round(recent_val_rise, 6)
    )
    analysis["finite_diverging"] = bool(finite_diverging)
    analysis["warning_flags"]["diverging"] = bool(
        finite_diverging
    )
    if gap_widening:
        warnings.append(
            "泛化 gap 相对首个验证点扩大 "
            f"{generalization_gap_trend * 100:.1f} 个百分点"
            "（最终 gap "
            f"{generalization_gap_ratio * 100:.1f}%）："
            "训练损失继续下降但验证收益停滞，是过拟合前兆。"
        )

    if finite_diverging:
        analysis["status"] = "diverging"
        analysis["divergence_signal"] = "both_losses_rising"
        analysis["recommendation"] = (
            "最近一次验证间隔内训练损失上升 "
            f"{recent_train_rise * 100:.1f}%、验证损失上升 "
            f"{recent_val_rise * 100:.1f}%：这不是过拟合"
            "（过拟合时训练损失仍在下降），而是训练不稳定/"
            "有限发散的信号。继续训练通常只会更糟。建议："
            "降低学习率、收紧 --grad-clip、检查最近的梯度"
            "范数尖峰与数据批次，并从发散前的最优检查点恢复；"
            "若发生在 warmup 阶段，先确认 warmup 步数与峰值"
            "学习率是否匹配。"
        )
    elif (
        best_index <= len(finite_evals) - 2
        and regression is not None
        and regression >= _CURVE_OVERFIT_REGRESSION
        and (train_still_down or train_below_val)
    ):
        analysis["status"] = "overfitting"
        if train_still_down:
            analysis["overfit_signal"] = "train_still_descending"
            evidence_text = "训练损失仍在下降"
        else:
            analysis["overfit_signal"] = "generalization_gap"
            evidence_text = (
                "训练损失已不再下降但比验证损失低 "
                f"{generalization_gap_ratio * 100:.1f}%"
                "（泛化 gap 大，记忆化特征）"
            )
        analysis["recommendation"] = (
            f"验证损失在第 {best['step']} 步达到最优 "
            f"{float(best['val_loss']):.4f} 后回升 "
            f"{regression * 100:.1f}%，{evidence_text}："
            "典型过拟合。建议按序尝试：加正则化"
            "（调大 --weight-decay / 适度增大 balance_coef）、"
            "增大训练数据、用 --early-stop-patience 早停"
            "（不要把验证损失回升后的步数计入结论）。"
        )
    elif (
        train_drop_total is not None
        and train_drop_total < _CURVE_NO_LEARN_DROP
        and (
            baseline_loss is None
            or (
                last["train_loss"] is not None
                and float(last["train_loss"])
                > _CURVE_NO_LEARN_BASELINE * baseline_loss
            )
        )
    ):
        analysis["status"] = "underfitting"
        analysis["recommendation"] = (
            f"训练损失整体仅下降 "
            f"{max(0.0, train_drop_total) * 100:.1f}%，"
            "接近随机基线，训练与验证都没有有效下降："
            "欠拟合或学习率/数据管道有问题。建议检查："
            "学习率是否过小或过大、优化器配置、标签与输入是否"
            "对齐（可先跑 --sanity-only 小批量过拟合检查）、"
            "模型容量与训练步数是否足够。"
        )
    elif (
        recent_train_drop is not None
        and recent_val_drop is not None
        and recent_train_drop < _CURVE_STILL_DESCENDING
        and recent_val_drop < _CURVE_STILL_DESCENDING
    ):
        # 两者都不降：学习率已退火殆尽时是正常的末期收敛平台；
        # 学习率仍高时则指向欠拟合（容量不足）、学习率不当或
        # 数据管道问题。
        analysis["status"] = "plateau"
        lr_annealed = (
            peak_lr is not None
            and peak_lr > 0.0
            and last_lr is not None
            and last_lr
            < _CURVE_LR_ANNEALED_FRACTION * peak_lr
        )
        drops_text = (
            f"训练 {max(0.0, recent_train_drop) * 100:.1f}% / "
            f"验证 {max(0.0, recent_val_drop) * 100:.1f}%"
        )
        if lr_annealed:
            analysis["plateau_kind"] = "schedule_end"
            analysis["recommendation"] = (
                f"最近一次验证间隔内训练与验证损失都没有有效下降"
                f"（{drops_text}），且学习率已退火至峰值的 "
                f"{analysis['last_lr_over_peak'] * 100:.0f}%："
                "更像调度末期的正常收敛平台。若结果已够用可就此"
                "结束；仍需改善时应调整学习率调度/模型容量后重跑，"
                "而不是在已退火的学习率下继续加步数。"
            )
        else:
            analysis["plateau_kind"] = "stalled"
            lr_text = (
                f"（当前 lr={last_lr:.3e}，峰值 {peak_lr:.3e}）"
                if last_lr is not None and peak_lr is not None
                else ""
            )
            analysis["recommendation"] = (
                f"最近一次验证间隔内训练与验证损失都没有有效下降"
                f"（{drops_text}），且已排除过拟合：两者都不降"
                f"通常指向欠拟合（模型容量不足）、学习率不当"
                f"{lr_text}或数据管道本身有问题。建议检查："
                "学习率是否过小或过大、模型容量"
                "（--d-model / --n-layers）是否足够，并用 "
                "--sanity-only 的小批量过拟合检查排除数据管道"
                "问题（标签错位、输入输出不对齐）；定位原因前"
                "不要盲目增加步数。"
            )
    elif (
        recent_train_drop is not None
        and recent_val_drop is not None
        and recent_train_drop > _CURVE_STILL_DESCENDING
        and recent_val_drop > _CURVE_STILL_DESCENDING
    ):
        analysis["status"] = "not_converged"
        analysis["recommendation"] = (
            "最近一次验证间隔内训练与验证损失仍在同步明显下降，"
            "尚未收敛。建议增大 --steps（或调大学习率后重跑），"
            "并参考 learning-rate 曲线确认退火是否太慢。"
        )
    else:
        analysis["status"] = "healthy"
        analysis["recommendation"] = (
            "训练与验证损失同步下降、验证未回升或仅轻微波动，"
            "曲线健康；如需进一步改善，可关注仍未收敛时的"
            "更多步数与模型容量。"
        )

    # 过拟合前兆的行动建议：状态仍判 healthy/not_converged（验证
    # 尚未回升），但必须提示现在就设置早停/加强正则化，而不是等
    # 验证损失回升后才行动。
    if gap_widening and analysis["status"] in (
        "healthy",
        "not_converged",
    ):
        analysis["recommendation"] = (
            str(analysis["recommendation"])
            + " 注意泛化 gap 正在扩大（训练损失下降、验证收益"
            "停滞）：建议立即设定或收紧早停"
            "（--early-stop-patience），并加强正则化/增大数据，"
            "避免验证损失回升后才被动止损。"
        )

    analysis["recent_train_drop"] = (
        None
        if recent_train_drop is None
        else round(recent_train_drop, 6)
    )
    analysis["recent_val_drop"] = (
        None
        if recent_val_drop is None
        else round(recent_val_drop, 6)
    )
    analysis["train_still_down"] = train_still_down

    return analysis


def print_curve_analysis(analysis: Dict[str, object]) -> None:
    """打印训练曲线诊断摘要、走势条与建议。"""
    print(
        "[curve] 状态: "
        f"{analysis.get('status')} | "
        f"验证点 {analysis.get('n_eval_points')} 个 | "
        f"非有限事件 {analysis.get('n_nonfinite_events')} 次"
    )

    if analysis.get("best_val_loss") is not None:
        # 最后一个验证点之前可能一个有限训练损失都没有（早期
        # NaN/Inf 后恢复的运行），此时 last_train_loss 为 None，
        # 与其它字段一致按缺失值打印。
        last_train_loss = analysis.get("last_train_loss")
        last_train_text = (
            _format_finite(last_train_loss)
            if last_train_loss is not None
            else "-"
        )
        regression = analysis.get("val_regression_from_best")
        if regression is None:
            regression = 0.0
        print(
            "[curve] 最优验证损失 "
            f"{_format_finite(analysis.get('best_val_loss'))} @ step "
            f"{analysis.get('best_val_step')}，"
            "最终验证损失 "
            f"{_format_finite(analysis.get('last_val_loss'))}"
            "（相对最优回升 "
            f"{_format_finite(regression, '.1f', 100.0)}%），"
            "最终训练损失 "
            f"{last_train_text}"
        )

    if analysis.get("curve_sparkline_train"):
        print(
            "[curve] train " + str(analysis["curve_sparkline_train"])
        )

    if analysis.get("curve_sparkline_val"):
        print(
            "[curve] val   " + str(analysis["curve_sparkline_val"])
        )

    for warning in analysis.get("warnings", []):
        print(f"[curve] 警告: {warning}")

    print(f"[curve] 建议: {analysis.get('recommendation')}")


def monitor_training_curve(
    records: List[Dict[str, object]],
    baseline_loss: Optional[float],
    previous_status: Optional[str],
    previous_warning_flags: Optional[Dict[str, bool]] = None,
) -> Tuple[Dict[str, object], Optional[str]]:
    """
    训练期间的在线曲线监控：每个周期验证点复用
    analyze_training_curve 的判定，在状态迁移或警告前兆出现时
    报告。

    返回 ``(analysis, new_status)``；状态与上一次相同且警告
    签名没有新增时 ``new_status`` 为 None，表示不需要重复记录/
    打印。只比较状态会漏掉「状态仍为 healthy、但泛化 gap 已
    快速扩大」这类前兆——那正是最值得在训练中途介入的时刻，
    因此 warning_flags 的新增 True 也触发一次报告
    （``analysis["monitor_trigger"]`` 标为 warning_change）。
    验证点不足以判断（``insufficient_data``）时不触发。
    """
    analysis = analyze_training_curve(
        records,
        baseline_loss=baseline_loss,
    )
    status = str(analysis.get("status"))

    if status == "insufficient_data":
        return analysis, None

    warning_flags = analysis.get("warning_flags")
    if not isinstance(warning_flags, dict):
        warning_flags = {}
    analysis["warning_flags"] = {
        str(key): bool(value)
        for key, value in warning_flags.items()
    }

    if status != previous_status:
        analysis["monitor_trigger"] = "status_change"
        return analysis, status

    # 调用方未提供上一次签名时（旧记录/旧调用）不推断新增
    # 警告，保持「仅状态迁移」的兼容语义。
    if previous_warning_flags is None:
        return analysis, None

    previous_flags = previous_warning_flags
    appeared = [
        key
        for key, value in analysis["warning_flags"].items()
        if value and not bool(previous_flags.get(key, False))
    ]
    if appeared:
        analysis["monitor_trigger"] = "warning_change"
        analysis["new_warning_flags"] = appeared
        return analysis, status

    return analysis, None


def selection_improved(
    value: float,
    best: Optional[float],
    higher_is_better: bool,
    min_delta: float,
) -> bool:
    """
    判断一次验证观测是否刷新了选型指标的最优值。

    与早停共用同一口径：``min_delta`` 是必须超过的改善幅度，
    方向由指标本身决定（loss/ppl 越低越好，F1/accuracy 越高
    越好）。非有限值一律不算改善。
    """
    value = _finite_float(value)
    if value is None:
        return False
    best_value = _finite_float(best) if best is not None else None
    # 损坏的 CLI/旧记录可能把 min_delta 写成 None/字符串/NaN；
    # 不可用时按 0 处理（不额外要求改善幅度），而不是让 resume
    # 在减法处崩溃。
    delta = _finite_float(min_delta)
    if delta is None:
        delta = 0.0
    if best_value is None:
        return True
    if higher_is_better:
        return value > best_value + delta
    return value < best_value - delta


def early_stop_state_from_records(
    records: List[Dict[str, object]],
    min_delta: float,
    metric: str = "val_loss",
) -> Tuple[Optional[float], Optional[int], int]:
    """
    从已有 metrics.jsonl 记录恢复早停状态（最优选型指标、最优
    步数、连续未改善次数），保证 resume 后早停判定与原运行一致。

    ``metric`` 必须与本次运行的 ``--selection-metric`` 一致；
    方向由 ``metric_higher_is_better`` 决定（分类指标越高越好，
    loss/ppl 越低越好）。旧记录缺少该指标时跳过，不把「没算」
    当成「变差」。
    """
    best_value: Optional[float] = None
    best_step: Optional[int] = None
    evals_without_improvement = 0
    higher_is_better = metric_higher_is_better(metric)

    for record in records:
        step = record.get("step")
        if not isinstance(step, int):
            continue
        if metric not in record:
            continue

        # 非有限值不算「改善」也不触发「未改善」计数，
        # 与在线训练循环的判定保持一致；否则 NaN 会把 best
        # 永久污染成 NaN，resume 后的选型与早停全部失准。
        # 记录来自 JSON，超范围整数同样按不可用值跳过，
        # 不能让它以 OverflowError 中断 resume。
        value = _finite_float(record.get(metric))
        if value is None:
            continue

        if selection_improved(
            value,
            best_value,
            higher_is_better,
            min_delta,
        ):
            best_value = value
            best_step = step
            evals_without_improvement = 0
        else:
            evals_without_improvement += 1

    return best_value, best_step, evals_without_improvement


# ============================================================
# Bad-case analysis
# ============================================================

# top1 概率与目标 token 概率之差小于该值时视为「样本模糊」：
# 正确答案与模型首选几乎并列，不是明确的模型错误。
_BAD_CASE_AMBIGUOUS_MARGIN = 0.1

# 模型以该置信度以上的概率给出错误答案时，优先怀疑模型盲区
# 或标注噪声。
_BAD_CASE_CONFIDENT = 0.9

# 目标字节在评估 split 中的占比低于该值且模型高置信度答错时，
# 提示标注本身可能有误（需人工复核）。
_BAD_CASE_RARE_TARGET_SHARE = 0.005

# 同一 (target, predicted) 混淆对在错误列表中出现该次数以上时，
# 视为系统性混淆（模型盲区），而不是孤立个例。
_BAD_CASE_SYSTEMATIC_COUNT = 3

# 置信度校准：ECE 的分箱数与「高置信度错误」的阈值。ECE 衡量
# 模型自报概率与真实正确率之间的平均差距；只看 accuracy 会把
# 「自信地答错」与「不确定地答错」混为一谈。
_BAD_CASE_CALIBRATION_BINS = 10
_BAD_CASE_OVERCONFIDENT_THRESHOLD = 0.9

# 标签噪声核验：在训练集里用「目标字节前 K 个字节」作为上下文
# 查找同一上下文的后续字节。只有训练集中同一上下文反复出现、
# 且评估目标不是该上下文的主流后续字节时，才有证据把错误标为
# 疑似标注错误；否则「稀有目标 + 高置信度」更可能是模型盲区
# 或评估抽样波动，不能仅凭此归因于标注。
_BAD_CASE_LABEL_CONTEXT = 8
_BAD_CASE_LABEL_MIN_SUPPORT = 2
_BAD_CASE_LABEL_TARGET_MAX_SHARE = 0.1
# 「训练上下文的主流后续字节」必须有实质优势，否则同一上下文
# 本来就多峰（如空格后的多个合法词首），把「非主流」当标注
# 错误会把正常歧义样本误报为标签噪声。只有主流占比达到该
# 阈值时，评估标签与之矛盾才算可核验的标注可疑。
_BAD_CASE_LABEL_MAJORITY_MIN_SHARE = 0.5

# top-N 案例多样性：最差 token 可能集中在同一窗口的不同位置，
# 此时它们不是 N 个独立证据。至少要有若干案例、且单一窗口
# 占比达到阈值时才提示，避免短报告误报。
_BAD_CASE_WINDOW_CONCENTRATION = 0.6
_BAD_CASE_WINDOW_MIN_CASES = 3

# 全量错误归因与 top-N 案例归因共用同一组类别（顺序即编码）。
_BAD_CASE_CATEGORIES: Tuple[str, ...] = (
    "ambiguous",
    "systematic_confusion",
    "label_noise_suspect",
    "uncertain",
)

# 逐 token 错误率的上下文位置分层：自回归模型在序列开头的
# 有效上下文最短，错误率若显著高于后段，改进方向应是位置/
# 前缀建模而不是继续堆参数。区间为 [lower, upper)。
_BAD_CASE_POSITION_BUCKETS: Tuple[
    Tuple[str, int, Optional[int]], ...
] = (
    ("position_0", 0, 1),
    ("position_1_3", 1, 4),
    ("position_4_7", 4, 8),
    ("position_8_15", 8, 16),
    ("position_16_31", 16, 32),
    ("position_32_plus", 32, None),
)

# 按目标字节在训练集中的频率分层：稀有目标的错误占比高，
# 说明问题在数据不平衡/覆盖不足；高频目标错误率高则更像
# 模型盲区。区间为 [lower, upper)，share 是训练集中该字节
# 的 token 占比。
_BAD_CASE_FREQUENCY_BUCKETS: Tuple[
    Tuple[str, float, Optional[float]], ...
] = (
    ("train_share_lt_0.1pct", 0.0, 0.001),
    ("train_share_0.1pct_to_1pct", 0.001, 0.01),
    ("train_share_1pct_to_5pct", 0.01, 0.05),
    ("train_share_ge_5pct", 0.05, None),
)


def _stratified_error_rows(
    values: torch.Tensor,
    wrong_mask: torch.Tensor,
    buckets: Sequence[Tuple[str, object, Optional[object]]],
    total_wrong: int,
) -> List[Dict[str, object]]:
    """
    按一维分组变量统计 token 数、错误数与错误率。

    ``values`` 与 ``wrong_mask`` 逐 token 对齐；只返回实际出现
    过的分组（空分组不写入报告），避免短序列下大量零计数桶
    淹没信息。``share_of_errors`` 是该组错误占全部错误的比例，
    用于回答「错误主要集中在哪一类 token」。
    """
    rows: List[Dict[str, object]] = []
    for name, lower, upper in buckets:
        mask = values >= lower
        if upper is not None:
            mask = mask & (values < upper)
        tokens = int(mask.sum().item())
        if tokens <= 0:
            continue
        wrong = int((mask & wrong_mask).sum().item())
        rows.append({
            "name": name,
            "tokens": tokens,
            "wrong": wrong,
            "error_rate": round(wrong / tokens, 6),
            "share_of_errors": (
                round(wrong / total_wrong, 6)
                if total_wrong > 0
                else None
            ),
        })
    return rows


def _render_byte(value: int) -> str:
    """把单个字节渲染为可打印文本（不可打印字节用 \\xNN）。"""
    value = int(value)
    if 32 <= value < 127:
        return chr(value)
    return f"\\x{value:02x}"


def _render_bytes(values) -> str:
    """把字节序列渲染为可打印文本。"""
    return "".join(_render_byte(value) for value in values)


def _calibration_report(
    confidence: torch.Tensor,
    correct: torch.Tensor,
    num_bins: int = _BAD_CASE_CALIBRATION_BINS,
) -> Dict[str, object]:
    """
    计算 top1 置信度的可靠性（ECE）与过度自信程度。

    ``confidence`` 是每 token 的 top1 概率，``correct`` 是
    top1 是否命中目标。ECE = Σ (n_bin / N) · |acc_bin − conf_bin|，
    按等宽概率分箱；它直接回答「模型说 90% 时是否真的对 90%」，
    这是 accuracy/loss 都看不出来的性质。
    """
    confidence = confidence.float().reshape(-1).clamp(0.0, 1.0)
    correct = correct.float().reshape(-1)
    total = int(confidence.numel())

    if total == 0:
        return {
            "ece": None,
            "mean_confidence": None,
            "accuracy": None,
            "overconfidence": None,
            "bins": [],
            "note": "没有可校准的 token。",
        }

    ece = 0.0
    bins = []
    for index in range(num_bins):
        lower = index / num_bins
        upper = (index + 1) / num_bins
        if index == num_bins - 1:
            mask = (confidence >= lower) & (
                confidence <= upper
            )
        else:
            mask = (confidence >= lower) & (
                confidence < upper
            )
        count = int(mask.sum().item())
        if count == 0:
            bins.append({
                "lower": round(lower, 6),
                "upper": round(upper, 6),
                "count": 0,
                "mean_confidence": None,
                "accuracy": None,
                "gap": None,
            })
            continue
        mean_confidence = float(
            confidence[mask].mean().item()
        )
        accuracy = float(correct[mask].mean().item())
        gap = accuracy - mean_confidence
        ece += (count / total) * abs(gap)
        bins.append({
            "lower": round(lower, 6),
            "upper": round(upper, 6),
            "count": count,
            "mean_confidence": round(mean_confidence, 6),
            "accuracy": round(accuracy, 6),
            "gap": round(gap, 6),
        })

    mean_confidence = float(confidence.mean().item())
    accuracy = float(correct.mean().item())
    return {
        "ece": round(ece, 6),
        "mean_confidence": round(mean_confidence, 6),
        "accuracy": round(accuracy, 6),
        # 正值 = 过度自信（自报概率高于实际正确率）。
        "overconfidence": round(
            mean_confidence - accuracy,
            6,
        ),
        "bins": bins,
        "note": (
            "ECE 为 0 表示置信度与正确率完全一致；"
            "ECE 越大，模型自报概率越不可用于阈值决策。"
        ),
    }


def _train_next_byte_evidence(
    dataset: "ByteDataset",
    contexts: List[bytes],
) -> Dict[bytes, Dict[str, object]]:
    """
    在训练集中查找每个上下文之后实际出现的字节分布。

    只扫描训练段（绝不读取 val/test），并返回支持数、主流后续
    字节及其占比。用于核验「评估标签与训练监督是否矛盾」：
    相同上下文在训练中反复以另一个字节为目标，才构成标注
    可疑的证据；上下文未在训练中出现时只能记为无法核验。
    """
    evidence: Dict[bytes, Dict[str, object]] = {}
    unique_contexts = sorted(set(contexts))

    if not unique_contexts:
        return evidence

    train_end = dataset.split_bounds["train"][1]
    train_bytes = bytes(dataset._raw_buffer[:train_end])
    # 被清洗的群组区间不参与窗口采样，其字节不构成训练监督：
    # 与 train_excluded_spans 相交的命中必须跳过，否则清洗掉的
    # 重复内容会冒充「训练里见过同一上下文」的核验证据（与
    # effective_train_byte_counts / 数据审计同一口径）。
    excluded_spans = _merge_byte_intervals(
        dataset.train_excluded_spans
    )

    for context in unique_contexts:
        counts: Dict[int, int] = {}
        support = 0
        start = 0
        while True:
            position = train_bytes.find(context, start)
            if position < 0:
                break
            next_position = position + len(context)
            if next_position < len(train_bytes):
                # 命中区间为 [position, next_position]（上下文加
                # 目标字节，闭区间），半开化后与排除区间求交。
                if excluded_spans and any(
                    low <= next_position and high > position
                    for low, high in excluded_spans
                ):
                    start = position + 1
                    continue
                next_byte = train_bytes[next_position]
                counts[next_byte] = (
                    counts.get(next_byte, 0) + 1
                )
                support += 1
            start = position + 1

        if support == 0:
            evidence[context] = {
                "support": 0,
                "majority_byte": None,
                "majority_share": None,
                "counts": {},
            }
            continue

        majority_byte, majority_count = max(
            counts.items(),
            key=lambda item: item[1],
        )
        evidence[context] = {
            "support": support,
            "majority_byte": int(majority_byte),
            "majority_share": round(
                majority_count / support,
                6,
            ),
            "counts": {
                int(byte): int(count)
                for byte, count in sorted(
                    counts.items(),
                    key=lambda item: (-item[1], item[0]),
                )
            },
        }

    return evidence


def _label_noise_context_verdict(
    evidence: Optional[Dict[str, object]],
    target: int,
) -> Tuple[bool, Optional[float]]:
    """
    由训练上下文证据判断评估标签是否「可核验地可疑」。

    返回 ``(verified, target_share)``。只要求「多数类不等于
    目标」不够：多数类占比可能只有 11%，其余是大量合法分支，
    这更像上下文歧义而不是标注错误。只有支持数足够、目标占比
    低、且主流后续字节有实质优势时，才把它当作标注噪声证据。
    """
    if not isinstance(evidence, dict):
        return False, None
    support = int(evidence.get("support") or 0)
    counts = evidence.get("counts")
    if support <= 0 or not isinstance(counts, dict):
        return False, None
    target_share = float(counts.get(target, 0)) / support
    majority_share = evidence.get("majority_share")
    if majority_share is None:
        return False, target_share
    majority_byte = evidence.get("majority_byte")
    verified = bool(
        support >= _BAD_CASE_LABEL_MIN_SUPPORT
        and target_share <= _BAD_CASE_LABEL_TARGET_MAX_SHARE
        and float(majority_share)
        >= _BAD_CASE_LABEL_MAJORITY_MIN_SHARE
        and majority_byte is not None
        and int(majority_byte) != int(target)
    )
    return verified, target_share


def _empty_bad_case_report(
    split: str,
    note: str = "评估窗口为空，未生成坏案例。",
) -> Dict[str, object]:
    """
    空评估集的坏案例报告骨架。

    即使没有可评估 token，报告也必须保留与正常路径相同的
    键集合：调用方会无条件读取 wrong_tokens / 类别计数等
    字段，缺键会让「评估集为空」从可解释的空结果变成
    KeyError 崩溃。
    """
    return {
        "split": split,
        "tokens_evaluated": 0,
        "token_accuracy": None,
        "wrong_tokens": 0,
        "top_cases": [],
        "top_cases_unique_windows": 0,
        "top_cases_window_concentration": None,
        "top_cases_concentration_warning": False,
        "top_confusions": [],
        "error_rate_by_target": [],
        "error_rate_by_position": [],
        "error_rate_by_train_frequency": [],
        "error_frequency_basis": None,
        "category_counts": {},
        "error_category_counts": {
            name: 0 for name in _BAD_CASE_CATEGORIES
        },
        "error_category_shares": {
            name: None for name in _BAD_CASE_CATEGORIES
        },
        "calibration": {
            "ece": None,
            "mean_confidence": None,
            "accuracy": None,
            "overconfidence": None,
            "bins": [],
            "note": "没有可校准的 token。",
        },
        "label_noise_verification": {
            "context_length": _BAD_CASE_LABEL_CONTEXT,
            "min_train_support": _BAD_CASE_LABEL_MIN_SUPPORT,
            "max_target_share_in_context": (
                _BAD_CASE_LABEL_TARGET_MAX_SHARE
            ),
            "min_majority_share_in_context": (
                _BAD_CASE_LABEL_MAJORITY_MIN_SHARE
            ),
            "candidates": 0,
            "verified": 0,
            "unverified": 0,
            "unverifiable_no_train_context": 0,
            "note": note,
        },
        "summary": note,
    }


def _bad_case_report_from_buffers(
    loss_buffer: torch.Tensor,
    target_buffer: torch.Tensor,
    predicted_buffer: torch.Tensor,
    confidence_buffer: torch.Tensor,
    margin_buffer: torch.Tensor,
    written: int,
    top_candidates: List[
        Tuple[float, int, torch.Tensor, int, int, int, float, float]
    ],
    split: str,
    top_n: int,
    context_before: int,
    context_after: int,
    vocab_size: int,
    dataset: Optional["ByteDataset"] = None,
) -> Dict[str, object]:
    """由紧凑逐 token 缓冲生成坏案例报告（供流式收集器复用）。"""
    loss_all = loss_buffer[:written]
    target_all = target_buffer[:written].to(torch.int64)
    predicted_all = predicted_buffer[:written].to(torch.int64)
    confidence_all = confidence_buffer[:written].float()
    margin_all = margin_buffer[:written].float()

    num_tokens = loss_all.numel()

    wrong_mask = target_all != predicted_all
    token_accuracy = float(
        (1.0 - wrong_mask.float().mean()).item()
    )

    # 逐目标字节在评估 split 中的占比，用于标注噪声提示。
    target_counts = torch.bincount(
        target_all,
        minlength=vocab_size,
    ).to(torch.float64)
    target_share = target_counts / max(1.0, float(num_tokens))

    # 训练集目标分布：评估 split 中稀少的目标若在训练中很常见，
    # 更可能是评估抽样波动/上下文特异，而不是标注错误。
    # 与 unigram 基线同口径：被清洗群组不进入监督，也不进入该
    # 分布（见 effective_train_byte_counts 的约定），否则
    # train_rare 会把模型从未见过的字节当成「训练中常见」。
    train_target_counts: Optional[torch.Tensor] = None
    train_target_share: Optional[torch.Tensor] = None
    if dataset is not None:
        train_tokens = int(dataset.effective_train_bytes)
        if train_tokens > 0:
            train_target_counts = (
                dataset.effective_train_byte_counts().to(
                    torch.float64
                )
            )
            train_target_share = (
                train_target_counts / float(train_tokens)
            )

    # 错误归因的两个关键分层：位置与目标频率。它们把
    # 「模型错在哪些 token」从个例提升为可行动的分布结论：
    # 开头位置错误率高指向前缀/位置建模，稀有目标错误占比高
    # 指向数据覆盖或重采样，高频目标错误率高才更像模型盲区。
    total_wrong = int(wrong_mask.sum().item())
    error_rate_by_position: List[Dict[str, object]] = []
    if dataset is not None and int(dataset.seq_len) > 1:
        positions = (
            torch.arange(num_tokens)
            % int(dataset.seq_len)
        )
        error_rate_by_position = _stratified_error_rows(
            positions,
            wrong_mask,
            _BAD_CASE_POSITION_BUCKETS,
            total_wrong,
        )

    if train_target_share is not None:
        frequency_values = train_target_share[target_all]
        frequency_basis = "train_target_share"
    else:
        frequency_values = target_share[target_all]
        frequency_basis = "eval_target_share"
    error_rate_by_frequency = _stratified_error_rows(
        frequency_values,
        wrong_mask,
        _BAD_CASE_FREQUENCY_BUCKETS,
        total_wrong,
    )

    # 标签噪声核验：只对 top-N 候选做训练集上下文查找，避免为
    # 全量错误 token 建索引；这些候选正是报告里被人工复核的
    # 样本，核验结果直接决定 label_noise_suspect 归类。
    context_evidence: Dict[bytes, Dict[str, object]] = {}
    if dataset is not None and top_candidates:
        candidate_contexts = []
        for entry in top_candidates:
            window_row = entry[2]
            position = int(entry[3])
            target_position = position + 1
            begin = max(
                0,
                target_position - _BAD_CASE_LABEL_CONTEXT,
            )
            candidate_contexts.append(
                bytes(
                    window_row[begin:target_position].tolist()
                )
            )
        context_evidence = _train_next_byte_evidence(
            dataset,
            candidate_contexts,
        )

    # 高频混淆对：target * vocab + predicted。
    confusion_index = (
        target_all * vocab_size + predicted_all
    )
    confusion_counts = torch.bincount(
        confusion_index[wrong_mask],
        minlength=vocab_size * vocab_size,
    )
    confusion_count_by_token = confusion_counts[
        confusion_index
    ]

    top_confusion_values, top_confusion_indices = torch.topk(
        confusion_counts,
        k=min(10, int((confusion_counts > 0).sum().item()) or 1),
    )

    top_confusions = []
    for count, index in zip(
        top_confusion_values.tolist(),
        top_confusion_indices.tolist(),
    ):
        if count <= 0:
            break
        top_confusions.append([
            int(index) // vocab_size,
            int(index) % vocab_size,
            int(count),
        ])

    # 逐目标字节错误率（只保留出现过的目标字节，按错误率排序）。
    error_counts = torch.bincount(
        target_all[wrong_mask],
        minlength=vocab_size,
    )
    error_rate = torch.where(
        target_counts > 0,
        error_counts.to(torch.float64)
        / target_counts.clamp(min=1),
        torch.zeros(vocab_size, dtype=torch.float64),
    )
    seen = target_counts > 0
    seen_indices = torch.nonzero(seen).reshape(-1)
    seen_rates = error_rate[seen_indices]
    order = torch.argsort(seen_rates, descending=True)
    error_rate_by_target = []
    for index in order[:10].tolist():
        byte = int(seen_indices[index])
        error_rate_by_target.append([
            byte,
            round(float(seen_rates[index]), 6),
            int(target_counts[byte]),
        ])

    # 污染最严重的 top_n token：候选在流式循环中以「每批
    # top-N + 跨批截断」精确维护（全局 top-N 必在各批
    # top-N 内），这里只做最终排序与上下文渲染。
    top_candidates.sort(
        key=lambda entry: (-entry[0], entry[1])
    )

    top_cases = []
    for rank, entry in enumerate(top_candidates):
        (
            entry_loss,
            _entry_order,
            window_row,
            position,
            target,
            predicted,
            confidence,
            margin,
        ) = entry

        pair_count = int(
            confusion_counts[
                target * vocab_size + predicted
            ]
        )

        # 窗口 = [x[0]] + y，目标 token 是窗口的第
        # position+1 个元素（候选构建时已知）。
        target_position = position + 1

        context_begin = max(
            0,
            target_position - _BAD_CASE_LABEL_CONTEXT,
        )
        context_key = bytes(
            window_row[
                context_begin:target_position
            ].tolist()
        )
        evidence = context_evidence.get(context_key)
        label_noise_verified, train_context_target_share = (
            _label_noise_context_verdict(evidence, target)
        )

        train_rare = bool(
            train_target_share is None
            or float(train_target_share[target])
            < _BAD_CASE_RARE_TARGET_SHARE
        )

        if margin < _BAD_CASE_AMBIGUOUS_MARGIN:
            category = "ambiguous"
        elif (
            pair_count >= _BAD_CASE_SYSTEMATIC_COUNT
            and confidence >= 0.5
        ):
            category = "systematic_confusion"
        elif (
            confidence >= _BAD_CASE_CONFIDENT
            and train_rare
            and float(target_share[target])
            < _BAD_CASE_RARE_TARGET_SHARE
            and label_noise_verified
        ):
            # 「稀有目标 + 高置信度」本身不是标注错误：还必须
            # 在训练集中找到同一上下文，且训练监督的主流后续
            # 字节与评估标签不同。
            category = "label_noise_suspect"
        else:
            category = "uncertain"

        begin = max(0, target_position - context_before)
        end = min(
            window_row.numel(),
            target_position + 1 + context_after,
        )
        fragment = window_row[begin:end].tolist()
        marker = target_position - begin

        context = (
            _render_bytes(fragment[:marker])
            + "["
            + _render_byte(target)
            + "]"
            + _render_bytes(fragment[marker + 1:])
        )

        top_cases.append({
            "rank": rank + 1,
            "position": target_position,
            "target": target,
            "target_text": _render_byte(target),
            "predicted": predicted,
            "predicted_text": _render_byte(predicted),
            "loss": round(float(entry_loss), 6),
            "confidence": round(confidence, 6),
            "margin": round(margin, 6),
            "category": category,
            "confusion_count": pair_count,
            # 标签噪声核验证据：训练集同一上下文的支持数、
            # 主流后续字节及其占比、评估目标在该上下文中的
            # 占比。support=0 表示无法核验，不等于标注正确。
            "label_noise_verified": label_noise_verified,
            "train_context_support": (
                int(evidence["support"])
                if evidence is not None
                else 0
            ),
            "train_context_majority_byte": (
                int(evidence["majority_byte"])
                if evidence is not None
                and evidence.get("majority_byte") is not None
                else None
            ),
            "train_context_majority_share": (
                float(evidence["majority_share"])
                if evidence is not None
                and evidence.get("majority_share") is not None
                else None
            ),
            "train_context_target_share": (
                round(train_context_target_share, 6)
                if train_context_target_share is not None
                else None
            ),
            "train_target_share": (
                round(float(train_target_share[target]), 6)
                if train_target_share is not None
                else None
            ),
            "context": context,
            "window_text": _render_bytes(
                window_row.tolist()
            ),
        })

    category_counts: Dict[str, int] = {}
    for case in top_cases:
        key = str(case["category"])
        category_counts[key] = (
            category_counts.get(key, 0) + 1
        )

    # top-N 案例的来源窗口是否重复：同一窗口的多个位置都被
    # 选中时，案例数会被高估为独立证据；保留重复计数并在
    # 报告层提示，避免把「一个坏窗口」读成「N 种失败模式」。
    window_counts: Dict[str, int] = {}
    for case in top_cases:
        window_key = str(case["window_text"])
        window_counts[window_key] = (
            window_counts.get(window_key, 0) + 1
        )
    for case in top_cases:
        case["window_repeat_count"] = window_counts[
            str(case["window_text"])
        ]
    top_cases_window_concentration = (
        max(window_counts.values()) / len(top_cases)
        if top_cases
        else None
    )
    top_cases_concentration_warning = bool(
        top_cases
        and len(top_cases) >= _BAD_CASE_WINDOW_MIN_CASES
        and top_cases_window_concentration is not None
        and top_cases_window_concentration
        >= _BAD_CASE_WINDOW_CONCENTRATION
    )

    # 全量错误 token 的类别归因（不只是 top_n 个最差样本）：
    # 错误原因分布是提出新改进思路的最重要证据，必须按整个
    # 评估 split 统计，避免「最高损失的几个样本正好都是同一
    # 类」把结论带偏。分类规则与逐案例完全一致，优先级为
    # ambiguous > systematic_confusion > label_noise_suspect
    # > uncertain。
    train_rare_all = (
        torch.ones_like(target_all, dtype=torch.bool)
        if train_target_share is None
        else (
            train_target_share[target_all]
            < _BAD_CASE_RARE_TARGET_SHARE
        )
    )
    wrong_category_code = torch.full_like(target_all, 3)
    wrong_category_code = torch.where(
        (
            (confidence_all >= _BAD_CASE_CONFIDENT)
            & (
                target_share[target_all]
                < _BAD_CASE_RARE_TARGET_SHARE
            )
            # 全量归因无法逐 token 做上下文查找（成本过高），
            # 但至少要求目标在训练集同样稀少；否则「评估稀有」
            # 只是抽样波动，不能归因于标注。
            & train_rare_all
        ),
        torch.full_like(wrong_category_code, 2),
        wrong_category_code,
    )
    wrong_category_code = torch.where(
        (
            (confusion_count_by_token >= _BAD_CASE_SYSTEMATIC_COUNT)
            & (confidence_all >= 0.5)
        ),
        torch.full_like(wrong_category_code, 1),
        wrong_category_code,
    )
    wrong_category_code = torch.where(
        margin_all < _BAD_CASE_AMBIGUOUS_MARGIN,
        torch.full_like(wrong_category_code, 0),
        wrong_category_code,
    )
    wrong_category_code = wrong_category_code[wrong_mask]

    category_names = _BAD_CASE_CATEGORIES
    wrong_tokens = int(wrong_mask.sum())
    error_category_counts = {
        name: int((wrong_category_code == code).sum())
        for code, name in enumerate(category_names)
    }
    error_category_shares = {
        name: (
            round(count / wrong_tokens, 6)
            if wrong_tokens > 0
            else None
        )
        for name, count in error_category_counts.items()
    }

    calibration = _calibration_report(
        confidence_all,
        ~wrong_mask,
    )
    high_confidence_errors = int(
        (
            wrong_mask
            & (
                confidence_all
                >= _BAD_CASE_OVERCONFIDENT_THRESHOLD
            )
        ).sum().item()
    )
    if wrong_tokens > 0:
        calibration["high_confidence_error_count"] = (
            high_confidence_errors
        )
        calibration["high_confidence_error_share"] = round(
            high_confidence_errors / wrong_tokens,
            6,
        )

    verified_label_noise = sum(
        1
        for case in top_cases
        if case.get("label_noise_verified")
    )
    unverifiable_label_noise = sum(
        1
        for case in top_cases
        if int(case.get("train_context_support") or 0) == 0
    )
    label_noise_verification = {
        "context_length": _BAD_CASE_LABEL_CONTEXT,
        "min_train_support": _BAD_CASE_LABEL_MIN_SUPPORT,
        "max_target_share_in_context": (
            _BAD_CASE_LABEL_TARGET_MAX_SHARE
        ),
        "min_majority_share_in_context": (
            _BAD_CASE_LABEL_MAJORITY_MIN_SHARE
        ),
        "candidates": len(top_cases),
        "verified": verified_label_noise,
        "unverified": len(top_cases)
        - verified_label_noise,
        "unverifiable_no_train_context": (
            unverifiable_label_noise
        ),
        "note": (
            "只有训练集中同一上下文有足够支持、评估目标占比低、"
            "且主流后续字节有实质优势（≥50%）时，top-N 案例才"
            "标记为 label_noise_suspect；多数类优势不足说明"
            "上下文本身歧义。support=0 表示无法核验，不能据此"
            "断定标注正确。全量错误归因只做训练/评估目标稀有度"
            "交叉核对。"
        ),
    }

    top1 = top_cases[0] if top_cases else None
    dominant_category = (
        max(
            error_category_counts,
            key=lambda name: error_category_counts[name],
        )
        if wrong_tokens > 0
        else None
    )
    summary = (
        f"评估 {num_tokens} 个 token，token 准确率 "
        f"{token_accuracy:.4f}（{wrong_tokens} 个错误）；"
        + (
            "全量错误归因以 "
            f"{dominant_category}"
            f"（{error_category_shares[dominant_category] * 100:.1f}%）"
            "为主；最差样本 "
            if dominant_category is not None
            else "无错误 token；最差样本 "
        )
        + (
            "target="
            f"'{_render_byte(int(top1['target']))}', "
            "predicted="
            f"'{_render_byte(int(top1['predicted']))}', "
            f"loss={float(top1['loss']):.4f}, "
            f"category={top1['category']}。"
            if top1 is not None
            else "无。"
        )
    )

    report: Dict[str, object] = {
        "split": split,
        "tokens_evaluated": int(num_tokens),
        "token_accuracy": round(token_accuracy, 6),
        "wrong_tokens": wrong_tokens,
        "top_cases": top_cases,
        "top_cases_unique_windows": len(window_counts),
        "top_cases_window_concentration": (
            round(top_cases_window_concentration, 6)
            if top_cases_window_concentration is not None
            else None
        ),
        "top_cases_concentration_warning": (
            top_cases_concentration_warning
        ),
        "top_confusions": top_confusions,
        "error_rate_by_target": error_rate_by_target,
        "error_rate_by_position": error_rate_by_position,
        "error_rate_by_train_frequency": (
            error_rate_by_frequency
        ),
        "error_frequency_basis": frequency_basis,
        "category_counts": category_counts,
        "error_category_counts": error_category_counts,
        "error_category_shares": error_category_shares,
        "calibration": calibration,
        "label_noise_verification": (
            label_noise_verification
        ),
        "summary": summary,
    }

    return report


class _BadCaseCollector:
    """
    在评估前向中流式收集坏案例所需的全量紧凑统计。

    ``evaluate`` 与 ``analyze_bad_cases`` 使用完全相同的固定
    窗口与预测口径；最终评估时把收集器传入 ``evaluate``，即可
    得到同样的前向统计。收集器只保留逐 token 标量与 top-N 窗口。
    """

    def __init__(
        self,
        dataset: ByteDataset,
        split: str,
        batch_size: int,
        batches: int,
        top_n: int,
        context_before: int = 16,
        context_after: int = 8,
        device: Optional[torch.device] = None,
    ):
        self.dataset = dataset
        self.split = split
        self.top_n = top_n
        self.context_before = context_before
        self.context_after = context_after
        self.device = device
        self.sequence_length = dataset.seq_len

        _, eval_data = dataset._eval_windows(split)
        num_starts = len(eval_data) - self.sequence_length
        capacity = (
            min(batches * batch_size, num_starts)
            * self.sequence_length
        )

        self.async_copy = (
            device is not None and device.type == "cuda"
        )
        pin = self.async_copy
        self.loss_buffer = torch.empty(
            capacity, dtype=torch.float32, pin_memory=pin
        )
        self.target_buffer = torch.empty(
            capacity, dtype=torch.uint8, pin_memory=pin
        )
        self.predicted_buffer = torch.empty(
            capacity, dtype=torch.int16, pin_memory=pin
        )
        self.confidence_buffer = torch.empty(
            capacity, dtype=torch.float16, pin_memory=pin
        )
        self.margin_buffer = torch.empty(
            capacity, dtype=torch.float16, pin_memory=pin
        )

        self.top_candidates: List[
            Tuple[
                float,
                int,
                torch.Tensor,
                int,
                int,
                int,
                float,
                float,
            ]
        ] = []
        self.pending_candidates: List[
            Dict[str, torch.Tensor]
        ] = []
        self._candidates_materialized = False
        self.written = 0

    def update(
        self,
        x: torch.Tensor,
        y: torch.Tensor,
        logits: torch.Tensor,
    ) -> None:
        """处理一个评估批（与 analyze_bad_cases 的单批逻辑一致）。"""
        logits = logits.float()

        log_normalizer = torch.logsumexp(logits, dim=-1)
        target_logits = logits.gather(
            -1,
            y.unsqueeze(-1).to(torch.int64),
        ).squeeze(-1)
        loss_tokens = log_normalizer - target_logits

        top_values, predicted = logits.max(dim=-1)
        confidence = (top_values - log_normalizer).exp()
        target_probability = (
            target_logits - log_normalizer
        ).exp()

        window = torch.cat(
            [x[:, :1].to(torch.uint8), y],
            dim=1,
        )

        batch_loss = loss_tokens.reshape(-1)
        batch_target = y.reshape(-1)
        batch_predicted = predicted.reshape(-1)
        batch_confidence = confidence.reshape(-1)
        batch_margin = (
            confidence - target_probability
        ).reshape(-1)

        batch_rows = batch_loss.numel()
        batch_end = self.written + batch_rows
        self.loss_buffer[
            self.written:batch_end
        ].copy_(
            batch_loss, non_blocking=self.async_copy
        )
        self.target_buffer[
            self.written:batch_end
        ].copy_(
            batch_target.to(torch.uint8),
            non_blocking=self.async_copy,
        )
        self.predicted_buffer[
            self.written:batch_end
        ].copy_(
            batch_predicted.to(torch.int16),
            non_blocking=self.async_copy,
        )
        self.confidence_buffer[
            self.written:batch_end
        ].copy_(
            batch_confidence.to(torch.float16),
            non_blocking=self.async_copy,
        )
        self.margin_buffer[
            self.written:batch_end
        ].copy_(
            batch_margin.to(torch.float16),
            non_blocking=self.async_copy,
        )
        self.written = batch_end

        if self.top_n > 0 and batch_loss.numel() > 0:
            batch_k = min(self.top_n, batch_loss.numel())
            batch_top_losses, batch_top_indices = (
                torch.topk(batch_loss, k=batch_k)
            )
            batch_top_indices = (
                batch_top_indices.reshape(-1)
            )
            rows = torch.div(
                batch_top_indices,
                self.sequence_length,
                rounding_mode="floor",
            )
            # 候选数据先在设备上暂存，报告阶段一次取回：
            # 每批 top-N 已经保证全局 top-N 必在并集中，
            # 最终按 (loss, 插入序号) 排序截断即可。
            self.pending_candidates.append({
                "losses": batch_top_losses,
                "indices": batch_top_indices,
                "windows": window.index_select(0, rows),
                "targets": batch_target.index_select(
                    0, batch_top_indices
                ),
                "predicted": batch_predicted.index_select(
                    0, batch_top_indices
                ),
                "confidence": batch_confidence.index_select(
                    0, batch_top_indices
                ),
                "margin": batch_margin.index_select(
                    0, batch_top_indices
                ),
            })

    def _materialize_candidates(self) -> None:
        """一次性取回流式暂存的 top-N 候选并重建全局列表。"""
        if self._candidates_materialized:
            return
        self._candidates_materialized = True

        if not self.pending_candidates:
            return

        losses = torch.cat(
            [item["losses"] for item in self.pending_candidates]
        ).cpu().tolist()
        indices = torch.cat(
            [item["indices"] for item in self.pending_candidates]
        ).cpu().tolist()
        windows = torch.cat(
            [item["windows"] for item in self.pending_candidates]
        ).cpu()
        targets = torch.cat(
            [item["targets"] for item in self.pending_candidates]
        ).cpu().tolist()
        predicted = torch.cat(
            [item["predicted"] for item in self.pending_candidates]
        ).cpu().tolist()
        confidence = torch.cat(
            [item["confidence"] for item in self.pending_candidates]
        ).cpu().tolist()
        margin = torch.cat(
            [item["margin"] for item in self.pending_candidates]
        ).cpu().tolist()

        offset = 0
        counter = 0
        for item in self.pending_candidates:
            count = int(item["losses"].numel())
            for slot in range(offset, offset + count):
                self.top_candidates.append((
                    float(losses[slot]),
                    counter,
                    windows[slot],
                    int(indices[slot])
                    % self.sequence_length,
                    int(targets[slot]),
                    int(predicted[slot]),
                    float(confidence[slot]),
                    float(margin[slot]),
                ))
                counter += 1
            offset += count

        self.pending_candidates.clear()
        self.top_candidates.sort(
            key=lambda entry: (-entry[0], entry[1])
        )
        del self.top_candidates[self.top_n:]

    def report(self, vocab_size: int) -> Dict[str, object]:
        """生成与独立分析路径逐位一致的坏案例报告。"""
        if self.async_copy and self.written > 0:
            torch.cuda.synchronize(self.device)

        self._materialize_candidates()

        if self.written == 0:
            return _empty_bad_case_report(self.split)

        return _bad_case_report_from_buffers(
            self.loss_buffer,
            self.target_buffer,
            self.predicted_buffer,
            self.confidence_buffer,
            self.margin_buffer,
            self.written,
            self.top_candidates,
            self.split,
            self.top_n,
            self.context_before,
            self.context_after,
            vocab_size,
            dataset=self.dataset,
        )


@torch.inference_mode()
def analyze_bad_cases(
    model: LanguageModel,
    dataset: ByteDataset,
    batch_size: int,
    batches: int,
    device: torch.device,
    amp_dtype: Optional[torch.dtype] = None,
    split: str = "val",
    top_n: int = 10,
    context_before: int = 16,
    context_after: int = 8,
    collector: Optional["_BadCaseCollector"] = None,
) -> Dict[str, object]:
    """
    坏案例分析：把预测错误的样本打印出来并归类错误原因。

    使用与周期验证完全相同的固定窗口（protocol 口径一致），
    对每个目标 token 计算：

    - loss / 置信度（top1 概率）/ margin（top1 概率 − 目标概率）；
    - 污染最严重的 top_n 个 token，附上下文文本、目标与预测
      字节、错误类别；
    - 高频混淆对（target→predicted）与逐目标字节错误率；
    - 错误类别统计：ambiguous（样本极其模糊）、
      systematic_confusion（同类混淆反复出现，模型盲区）、
      label_noise_suspect（目标在训练/评估中都稀少、模型高
      置信度答错，且训练集同一上下文的主流后续字节与评估
      标签矛盾）、uncertain（其余）；
    - 置信度校准：ECE、平均置信度、实际准确率、过度自信
      幅度与可靠性分箱，回答「模型说 90% 时是否真的对 90%」；
    - 标签噪声核验：只对 top_n 候选查找训练集同上下文支持，
      报告 support / 主流后续字节 / 目标占比，无法核验时明确
      标记而不是默认相信。

    统计口径与实现：在固定窗口上流式处理全部目标 token，
    token 准确率、混淆对、逐目标错误率与错误类别归因都基于
    全量评估 token（与 evaluate 同一窗口集合、同一预测口径），
    不对评估集做随机下采样；top_n 最差样本通过「每批 top-N +
    跨批截断」精确维护（全局 top-N 必然出现在各自批次的
    top-N 内），窗口只为入选样本保留。相同数据与模型下报告
    逐位可复现。

    仅访问 val（或显式解封后的 test），绝不接触训练期间尘封的
    测试集；输出既打印，也写回 metrics.jsonl 的
    ``{"step": "bad_cases", ...}`` 记录，完整报告另存
    bad_cases.json，作为提出新改进思路的证据来源。

    ``collector`` 非 None 时直接使用最终 ``evaluate`` 已完成的
    同窗口前向统计。
    """
    if collector is not None:
        return collector.report(
            _unwrap_model(model).cfg.vocab_size
        )

    was_training = model.training
    model.eval()

    use_amp = (
        amp_dtype is not None
        and device.type == "cuda"
    )

    vocab_size = _unwrap_model(model).cfg.vocab_size

    # fixed_eval_batch 的每个窗口行含 seq_len+1 个 token，
    # 输入 x 与目标 y 各 seq_len 个位置。
    sequence_length = dataset.seq_len

    # 全量统计缓冲：每个 token 保留 loss fp32、target uint8、
    # predicted int16、confidence/margin fp16；统计口径与 evaluate
    # 的固定窗口评估完全一致。缓冲按固定窗口的实际位置数分配、
    # 逐批写入。
    _, eval_data = dataset._eval_windows(split)
    num_starts = len(eval_data) - sequence_length
    capacity = min(batches * batch_size, num_starts) * sequence_length
    # CUDA 路径在全部批次结束后统一同步。CPU 路径保持同步语义。
    async_copy = device.type == "cuda"
    loss_buffer = torch.empty(
        capacity, dtype=torch.float32, pin_memory=async_copy
    )
    target_buffer = torch.empty(
        capacity, dtype=torch.uint8, pin_memory=async_copy
    )
    predicted_buffer = torch.empty(
        capacity, dtype=torch.int16, pin_memory=async_copy
    )
    confidence_buffer = torch.empty(
        capacity, dtype=torch.float16, pin_memory=async_copy
    )
    margin_buffer = torch.empty(
        capacity, dtype=torch.float16, pin_memory=async_copy
    )
    written = 0

    # 全局 top-N 最差 token：每批先取本批 top-N 候选再跨批截断
    #（全局 top-N 必然在各自批次的 top-N 内），窗口只为入选
    # 样本保留。
    # 插入序号保证并列损失下的排序确定（报告可复现）。
    # 候选项：(loss, 插入序号, 窗口行, 目标位置, target,
    # predicted, confidence, margin)。
    top_candidates: List[
        Tuple[float, int, torch.Tensor, int, int, int, float, float]
    ] = []
    top_insert_counter = 0

    try:
        with torch.autocast(
            device_type="cuda",
            dtype=amp_dtype,
            enabled=use_amp,
        ):
            for batch_index in range(batches):
                x, y = dataset.fixed_eval_batch(
                    split,
                    batch_index,
                    batches,
                    batch_size,
                    device,
                )

                if x.size(0) == 0:
                    break

                result = model(x)

                # 坏案例统计只在 fp32 下做，避免半精度下
                # softmax/gather 的数值误差影响错误归因。
                logits = result["logits"].float()
                del result

                log_normalizer = torch.logsumexp(logits, dim=-1)
                target_logits = logits.gather(
                    -1,
                    y.unsqueeze(-1).to(torch.int64),
                ).squeeze(-1)
                loss_tokens = log_normalizer - target_logits

                # 预测与置信度只取 top1，与 evaluate 的
                # argmax 口径一致。
                top_values, predicted = logits.max(dim=-1)
                confidence = (
                    top_values - log_normalizer
                ).exp()
                target_probability = (
                    target_logits - log_normalizer
                ).exp()

                # 还原完整窗口：x = tokens[:-1]，y = tokens[1:]。
                window = torch.cat(
                    [x[:, :1].to(torch.uint8), y],
                    dim=1,
                )

                batch_loss = loss_tokens.reshape(-1)
                batch_target = y.reshape(-1)
                batch_predicted = predicted.reshape(-1)
                batch_confidence = confidence.reshape(-1)
                batch_margin = (
                    confidence - target_probability
                ).reshape(-1)

                batch_rows = batch_loss.numel()
                batch_end = written + batch_rows
                loss_buffer[written:batch_end].copy_(
                    batch_loss, non_blocking=async_copy
                )
                target_buffer[written:batch_end].copy_(
                    batch_target.to(torch.uint8),
                    non_blocking=async_copy,
                )
                predicted_buffer[written:batch_end].copy_(
                    batch_predicted.to(torch.int16),
                    non_blocking=async_copy,
                )
                confidence_buffer[written:batch_end].copy_(
                    batch_confidence.to(torch.float16),
                    non_blocking=async_copy,
                )
                margin_buffer[written:batch_end].copy_(
                    batch_margin.to(torch.float16),
                    non_blocking=async_copy,
                )
                written = batch_end

                # 本批的 top-N 候选（全局 top-N 必在其中）。
                if top_n > 0 and batch_loss.numel() > 0:
                    batch_k = min(top_n, batch_loss.numel())
                    batch_top_losses, batch_top_indices = (
                        torch.topk(batch_loss, k=batch_k)
                    )
                    # 取回本批候选损失，随后按索引取回候选标量
                    # 与窗口行。
                    batch_top_losses = (
                        batch_top_losses.cpu().tolist()
                    )
                    batch_top_indices = (
                        batch_top_indices.reshape(-1)
                    )
                    rows = torch.div(
                        batch_top_indices,
                        sequence_length,
                        rounding_mode="floor",
                    )
                    candidate_target = (
                        batch_target.index_select(
                            0, batch_top_indices
                        ).cpu().tolist()
                    )
                    candidate_predicted = (
                        batch_predicted.index_select(
                            0, batch_top_indices
                        ).cpu().tolist()
                    )
                    candidate_confidence = (
                        batch_confidence.index_select(
                            0, batch_top_indices
                        ).cpu().tolist()
                    )
                    candidate_margin = (
                        batch_margin.index_select(
                            0, batch_top_indices
                        ).cpu().tolist()
                    )
                    window_cpu = window.index_select(0, rows).cpu()
                    for candidate_slot, (
                        local_loss,
                        local_index,
                    ) in enumerate(zip(
                        batch_top_losses,
                        batch_top_indices.tolist(),
                    )):
                        position = local_index % sequence_length
                        top_candidates.append((
                            float(local_loss),
                            top_insert_counter,
                            window_cpu[candidate_slot],
                            position,
                            int(candidate_target[candidate_slot]),
                            int(candidate_predicted[candidate_slot]),
                            float(
                                candidate_confidence[candidate_slot]
                            ),
                            float(candidate_margin[candidate_slot]),
                        ))
                        top_insert_counter += 1

                    if len(top_candidates) > top_n:
                        top_candidates.sort(
                            key=lambda entry: (-entry[0], entry[1])
                        )
                        del top_candidates[top_n:]

        # 读取 CPU 缓冲前统一等待。
        if async_copy and written > 0:
            torch.cuda.synchronize(device)

        if written == 0:
            return _empty_bad_case_report(split)

        return _bad_case_report_from_buffers(
            loss_buffer,
            target_buffer,
            predicted_buffer,
            confidence_buffer,
            margin_buffer,
            written,
            top_candidates,
            split,
            top_n,
            context_before,
            context_after,
            vocab_size,
            dataset=dataset,
        )
    finally:
        model.train(was_training)


def print_bad_cases(report: Dict[str, object]) -> None:
    """打印坏案例报告：最差样本、混淆对与错误分类统计。"""
    split = report.get("split")
    print(
        f"[bad-case] split={split} tokens="
        f"{report.get('tokens_evaluated')} "
        f"token_acc={report.get('token_accuracy')}"
    )

    for case in report.get("top_cases", []):
        print(
            f"[bad-case]   #{case['rank']} "
            f"loss={_format_finite(case.get('loss'), '.4f')} "
            f"conf={_format_finite(case.get('confidence'), '.3f')} "
            f"margin={_format_finite(case.get('margin'), '.3f')} "
            f"target='{case['target_text']}' "
            f"pred='{case['predicted_text']}' "
            f"category={case['category']} | "
            f"{case['context']}"
        )

    if report.get("top_cases_concentration_warning"):
        print(
            "[bad-case] top-N 案例集中在少数窗口："
            f"唯一窗口 {report.get('top_cases_unique_windows')} 个，"
            "单一窗口最高占比 "
            f"{_format_finite(report.get('top_cases_window_concentration'), '.1f', 100.0)}%"
            "；这些案例不是彼此独立的失败模式"
        )

    if report.get("top_confusions"):
        pairs = " ".join(
            f"'{_render_byte(target)}'→"
            f"'{_render_byte(predicted)}'({count})"
            for target, predicted, count in report[
                "top_confusions"
            ][:5]
        )
        print(f"[bad-case] 高频混淆对: {pairs}")

    def _stratified_text(rows) -> str:
        return " ".join(
            f"{row['name']}="
            f"{_format_finite(row.get('error_rate'), '.1f', 100.0)}%"
            f"({row.get('wrong')}/{row.get('tokens')})"
            for row in rows
        )

    position_rows = report.get("error_rate_by_position")
    if position_rows:
        print(
            "[bad-case] 按序列位置错误率: "
            + _stratified_text(position_rows)
        )

    frequency_rows = report.get(
        "error_rate_by_train_frequency"
    )
    if frequency_rows:
        basis = report.get("error_frequency_basis")
        basis_text = (
            "训练集目标占比"
            if basis == "train_target_share"
            else "评估集目标占比"
        )
        print(
            f"[bad-case] 按目标频率错误率（{basis_text}）: "
            + _stratified_text(frequency_rows)
        )

    if report.get("category_counts"):
        print(
            "[bad-case] top-N 错误类别统计: "
            + json.dumps(
                report["category_counts"],
                ensure_ascii=False,
            )
        )

    calibration = report.get("calibration")
    if isinstance(calibration, dict) and calibration.get(
        "ece"
    ) is not None:
        print(
            "[bad-case] 置信度校准: "
            f"ECE={_format_finite(calibration.get('ece'))} "
            "平均置信度="
            f"{_format_finite(calibration.get('mean_confidence'))} "
            "实际准确率="
            f"{_format_finite(calibration.get('accuracy'))} "
            "过度自信="
            f"{_format_finite(calibration.get('overconfidence'), '+.4f')} "
            "（高置信度错误 "
            f"{calibration.get('high_confidence_error_count', 0)}"
            " 个）"
        )

    verification = report.get(
        "label_noise_verification"
    )
    if isinstance(verification, dict):
        print(
            "[bad-case] 标签噪声核验: "
            f"top-N 候选 {verification['candidates']} 个，"
            f"训练上下文支持后确认 "
            f"{verification['verified']} 个，"
            f"未确认 {verification['unverified']} 个"
            "（其中 "
            f"{verification['unverifiable_no_train_context']}"
            " 个无训练上下文可核验）"
        )

    if report.get("error_category_counts"):
        shares = report.get("error_category_shares") or {}
        detail = ", ".join(
            f"{name}={count}"
            + (
                f"({_format_finite(shares.get(name), '.1f', 100.0)}%)"
                if shares.get(name) is not None
                else ""
            )
            for name, count in report[
                "error_category_counts"
            ].items()
        )
        print(
            "[bad-case] 全量错误归因"
            f"（共 {report.get('wrong_tokens')} 个错误 token）: "
            f"{detail}"
        )

    print(f"[bad-case] 小结: {report.get('summary')}")


# ============================================================
# Routing diagnostics (RQ3 / RQ4)
# ============================================================
#
# 研究问题 RQ3/RQ4 需要的不只是最终指标，而是训练后模型内部的
# 路由行为证据：第二轮是否选中与第一轮不同的专家（专家重合度 /
# Jaccard 相似度），以及专家负载分布与路由熵（专家专门化）。
# 本节的诊断在验证集的同一批固定窗口上、在验证集选定模型上做
# 一次无梯度前向，按 (Block, 轮次) 记录每次 route() 的 top-k
# 专家下标、门控权重与完整路由分布，汇总为结构化报告。
#
# 口径（随报告落盘，避免事后各自解释）：
# - 轮次 = 同一 Block 内 route() 的调用序号：第 1 次为第一轮，
#   第 2 次为第二轮。smelt 的两次中间循环、A/local_base 的
#   两阶段、B 的分支创建 + 第二轮完整中间区域都满足该顺序。
# - 专家重合度在「同一 token、同一 Block」的两轮路由之间比较；
#   分支结构（A/B）另外报告逐分支与 token 级（跨分支并集）口径。
# - 只使用验证集固定窗口；测试集保持尘封，不参与路由诊断。
# - 路由诊断只描述模型的内部行为，不参与模型选择、早停或任何
#   指标优化，避免把诊断本身变成调参信号。


def _routing_set_bool(
    indices: torch.Tensor,
    n_experts: int,
) -> torch.Tensor:
    """把 [N, k] 的专家下标转成 [N, n_experts] 的集合指示位。"""
    # 不能用原地 clamp_：.to(int64) 对已经是 int64 的输入返回
    # 同一张量，会改写调用方数据；对 expand 出来的 stride-0
    # 视图则直接抛「multiple elements refer to single memory」。
    indices = indices.to(torch.int64).clamp(
        min=0,
        max=n_experts - 1,
    )
    out = torch.zeros(
        indices.size(0),
        n_experts,
        dtype=torch.bool,
    )
    out.scatter_(1, indices, True)
    return out


def _routing_set_metrics_bool(
    a_bool: torch.Tensor,
    b_bool: torch.Tensor,
) -> Optional[Dict[str, float]]:
    """
    两组 [N, E] 专家集合指示位的逐 token 重合指标。

    - jaccard：|A∩B| / |A∪B|；
    - exact_match：两轮集合完全相同的 token 占比；
    - first_recall：|A∩B| / |A|，第一轮专家在第二轮复现的比例；
    - second_unique_reuse：|A∩B| / |B|，第二轮独特专家来自
      第一轮的比例。

    Jaccard 不能直接跨 $k_1/k_2$、专家数与负载集中度比较：
    均匀随机选择时两个 k 元集合的期望交集是 k1*k2/E。因此
    同时给出两个机会水平（chance level）：

    - ``jaccard_chance_uniform``：每个 token 按 |A|、|B| 与
      E 计算期望交集的均匀随机基线；
    - ``jaccard_chance_marginal``：第二轮的专家边际负载保持
      不变（P(e∈B)=第二轮负载份额），只随机化组合；这对应
      「保持负载分布、打乱路由」的置换基线。

    ``*_lift`` 为观测 Jaccard 相对机会水平的倍数，``*_adjusted``
    为 (obs − chance)/(1 − chance)。低重合本身不证明路由更
    有效，必须结合干预实验（见 analyze_routing_interventions）。
    """
    if a_bool.numel() == 0 or b_bool.numel() == 0:
        return None
    if a_bool.size(0) != b_bool.size(0):
        return None

    intersection = (a_bool & b_bool).sum(dim=-1).float()
    union = (a_bool | b_bool).sum(dim=-1).float()
    r1_size = a_bool.sum(dim=-1).float()
    r2_size = b_bool.sum(dim=-1).float()
    n_experts = int(a_bool.size(-1))

    jaccard = intersection / union.clamp_min(1e-12)
    jaccard_mean = float(jaccard.mean())

    # 均匀随机基线：E|A∩B| = |A|·|B|/E。
    expected_uniform = (
        r1_size * r2_size / max(1, n_experts)
    )
    union_uniform = (
        r1_size + r2_size - expected_uniform
    ).clamp_min(1e-12)
    chance_uniform = float(
        (expected_uniform / union_uniform).mean()
    )

    # 边际负载保持基线：P(e∈B) 取第二轮的经验负载份额，
    # 对每个 token 的 A 集合求和得到期望交集。该口径保留
    # 「某些专家本来就更常被选中」带来的重合，避免把负载
    # 集中误读成路由机制。
    b_load = b_bool.float().mean(dim=0)
    expected_marginal = (
        a_bool.float() * b_load.unsqueeze(0)
    ).sum(dim=-1)
    union_marginal = (
        r1_size + r2_size - expected_marginal
    ).clamp_min(1e-12)
    chance_marginal = float(
        (expected_marginal / union_marginal).mean()
    )

    def _adjusted(chance: float) -> Optional[float]:
        if chance >= 1.0:
            return None
        return (jaccard_mean - chance) / (1.0 - chance)

    def _lift(chance: float) -> Optional[float]:
        if chance <= 0.0:
            return None
        return jaccard_mean / chance

    return {
        "units": int(a_bool.size(0)),
        "second_round_jaccard_mean": jaccard_mean,
        "second_round_exact_match_share": float(
            (intersection == union).float().mean()
        ),
        "first_round_recall_mean": float(
            (intersection / r1_size.clamp_min(1e-12)).mean()
        ),
        "second_round_unique_reuse_mean": float(
            (intersection / r2_size.clamp_min(1e-12)).mean()
        ),
        "expected_intersection_uniform": float(
            expected_uniform.mean()
        ),
        "jaccard_chance_uniform": chance_uniform,
        "jaccard_chance_marginal": chance_marginal,
        "jaccard_lift_over_uniform": _lift(chance_uniform),
        "jaccard_lift_over_marginal": _lift(chance_marginal),
        "jaccard_adjusted_uniform": _adjusted(chance_uniform),
        "jaccard_adjusted_marginal": _adjusted(chance_marginal),
        "chance_note": (
            "uniform = 均匀随机集合（E|A∩B|=k1*k2/E）；"
            "marginal = 保持第二轮专家负载份额、随机化组合。"
            "低 Jaccard 必须先减去机会水平才可与其它 k1/k2 "
            "或负载分布比较"
        ),
    }


def _routing_set_metrics(
    a: torch.Tensor,
    b: torch.Tensor,
    n_experts: int,
) -> Optional[Dict[str, float]]:
    """[N, ka] / [N, kb] 专家下标对的集合重合指标（含 slot 口径）。"""
    if a.numel() == 0 or b.numel() == 0:
        return None
    if a.size(0) != b.size(0):
        return None

    a_bool = _routing_set_bool(a, n_experts)
    b_bool = _routing_set_bool(b, n_experts)
    metrics = _routing_set_metrics_bool(a_bool, b_bool)
    if metrics is None:
        return None

    # slot 口径：第二轮每个 assignment 的专家是否落在第一轮集合中
    # （重复专家按 slot 各计一次，反映实际计算里的复用比例）。
    b_slots = b.to(torch.int64).clamp(
        min=0, max=n_experts - 1
    )
    metrics["second_round_slot_reuse_mean"] = float(
        a_bool.float().gather(1, b_slots).mean()
    )
    return metrics


class RoutingProbe:
    """
    RQ3/RQ4 的路由探针：在分析前向中按调用顺序记录每次 route()。

    只由 analyze_routing 挂载/卸载；探针为 None 时 route()
    不记录。
    """

    def __init__(self, cfg: Config, batch_size: int):
        self.cfg = cfg
        self.batch_size = max(1, int(batch_size))
        self.events: List[Dict[str, object]] = []
        self._modules: List[SparseMoE] = []
        self._block_index: Dict[int, int] = {}
        self._call_counts: Dict[int, int] = {}
        self._wrapped_model: Optional[nn.Module] = None
        self._original_forward = None

    def attach(self, model: nn.Module) -> None:
        core = _unwrap_model(model)

        # 轮次计数必须在每次前向开始时清零：第 1 次调用是
        # 第一轮、第 2 次是第二轮。包装 model.forward（nn.Module
        # 的 __call__ 会在实例上查找 forward），分析循环只通过
        # core(x) 调用前向，因此每次前向都从干净计数开始。
        self._wrapped_model = core
        self._original_forward = core.forward
        probe = self

        def _forward_with_probe_reset(*args, **kwargs):
            probe._call_counts.clear()
            return probe._original_forward(*args, **kwargs)

        core.forward = _forward_with_probe_reset

        for index, block in enumerate(getattr(core, "blocks", [])):
            moe = getattr(block, "moe", None)
            if not isinstance(moe, SparseMoE):
                continue
            self._block_index[id(moe)] = index
            self._modules.append(moe)
            moe._routing_probe = self

    def detach(self) -> None:
        for moe in self._modules:
            moe._routing_probe = None
        self._modules.clear()
        if self._wrapped_model is not None:
            self._wrapped_model.forward = self._original_forward
            self._wrapped_model = None
            self._original_forward = None
        self._call_counts.clear()

    def _branch_cosine_stats(
        self,
        x: torch.Tensor,
        branch_dim: int,
    ) -> Tuple[
        Optional[torch.Tensor],
        Optional[torch.Tensor],
    ]:
        """
        分支表示的两两余弦相似度（mean 与最小 pair）。

        余弦接近 1 说明分支轨迹几乎重合（延迟合并没有带来
        独立计算）；明显小于 1 说明分支确实在分化。逐 pair
        统计先在设备上堆叠；均值/最小值保持为设备标量，由
        build_report 与其他路由统计一起一次性取回。
        """
        branches = int(x.size(branch_dim))
        if branches < 2:
            return None, None

        base = x.detach().float()
        base = base / base.norm(
            dim=-1,
            keepdim=True,
        ).clamp_min(1e-6)
        moved = base.movedim(branch_dim, 0).reshape(
            branches,
            -1,
            base.size(-1),
        )

        pair_tensors: List[torch.Tensor] = []
        for i in range(branches):
            for j in range(i + 1, branches):
                cosine = (moved[i] * moved[j]).sum(dim=-1)
                pair_tensors.append(cosine.mean())

        pair_means = torch.stack(pair_tensors)

        # 保持为 0 维设备张量，由 build_report 取回。
        return pair_means.mean(), pair_means.min()

    def record(
        self,
        module: SparseMoE,
        x: torch.Tensor,
        top_indices: torch.Tensor,
        top_weights: torch.Tensor,
        router_logits: torch.Tensor,
    ) -> None:
        block = self._block_index.get(id(module))
        if block is None:
            return

        key = id(module)
        call = self._call_counts.get(key, 0) + 1
        self._call_counts[key] = call

        with torch.no_grad():
            indices = top_indices.detach().reshape(
                -1,
                top_indices.size(-1),
            )
            if indices.numel() == 0:
                return

            n_experts = int(module.n_experts)
            flat_indices = indices.to(torch.int64).clamp(
                min=0,
                max=n_experts - 1,
            ).reshape(-1)
            weights = top_weights.detach().float().reshape(-1)

            usage = torch.bincount(
                flat_indices,
                minlength=n_experts,
            )
            usage_share = usage.float() / usage.sum().clamp_min(1)

            gate_mass = torch.zeros(
                n_experts,
                dtype=torch.float32,
                device=flat_indices.device,
            )
            gate_mass.scatter_add_(0, flat_indices, weights)

            probs = router_logits.detach().float().softmax(dim=-1)
            log_e = (
                math.log(n_experts)
                if n_experts > 1
                else 0.0
            )

            if log_e > 0.0:
                router_entropy = (
                    -(
                        probs.clamp_min(1e-12).log()
                        * probs
                    ).sum(-1).mean()
                    / log_e
                )
                nonzero = usage_share[usage_share > 0]
                load_entropy = (
                    -(nonzero * nonzero.log()).sum() / log_e
                )
            else:
                router_entropy = probs.new_zeros(())
                load_entropy = probs.new_zeros(())

            branch_mean: Optional[torch.Tensor] = None
            branch_min: Optional[torch.Tensor] = None
            cfg = self.cfg
            shape = x.shape
            is_middle = cfg.middle_start <= block < cfg.middle_end
            branch_dim: Optional[int] = None

            if cfg.mode == "A" and len(shape) == 4:
                branch_dim = 2
            elif (
                cfg.mode in ("B", "B_early")
                and is_middle
                and cfg.k1 >= 2
                and len(shape) == 3
                and not (
                    block == cfg.middle_start and call == 1
                )
                and shape[0] % cfg.k1 == 0
            ):
                rows = int(shape[0])
                batch = rows // cfg.k1
                if 0 < batch <= self.batch_size:
                    x = x.reshape(
                        batch,
                        cfg.k1,
                        shape[1],
                        shape[2],
                    )
                    branch_dim = 1

            if branch_dim is not None:
                branch_mean, branch_min = (
                    self._branch_cosine_stats(x, branch_dim)
                )

            # 统计量留在设备上，由 build_report 取回。
            scalar_values = [
                router_entropy.to(torch.float64),
                load_entropy.to(torch.float64),
                usage_share.max().to(torch.float64),
                (usage == 0).sum().to(torch.float64),
                probs.max(-1).values.mean().to(torch.float64),
            ]
            if branch_mean is None:
                nan = router_entropy.new_tensor(
                    float("nan")
                ).to(torch.float64)
                scalar_values.extend([nan, nan])
            else:
                scalar_values.extend([
                    branch_mean.to(torch.float64),
                    branch_min.to(torch.float64),
                ])
            scalars = torch.stack(scalar_values)

            self.events.append({
                "block": block,
                "round": call,
                "top_k": int(indices.size(-1)),
                "rows": int(indices.size(0)),
                "input_shape": [int(size) for size in shape],
                "usage": usage.to(torch.int64),
                "gate_mass": gate_mass,
                "scalars": scalars,
                # int16 在 n_experts>32767 时会静默溢出成负下标，
                # 后续集合指标会从错误的专家上计算；int32 足够
                # 覆盖任何可实际分配的路由表规模。
                "indices": indices.to(torch.int32),
            })

    @staticmethod
    def _accumulate(
        accumulator: Dict[str, object],
        metrics: Optional[Dict[str, float]],
    ) -> None:
        if not metrics:
            return
        for name, value in metrics.items():
            if name == "units":
                accumulator[name] = (
                    int(accumulator.get(name, 0)) + int(value)
                )
            elif isinstance(value, (int, float)) and not isinstance(
                value, bool
            ):
                accumulator.setdefault(name, []).append(float(value))
            # 非数值字段（如 chance_note 说明文字）不参与均值
            # 聚合，直接忽略而不是 float() 崩溃。

    @staticmethod
    def _finalize(
        accumulator: Dict[str, object],
    ) -> Dict[str, object]:
        result: Dict[str, object] = {}
        for name, value in accumulator.items():
            if name == "units":
                result[name] = int(value)
            else:
                values = [float(v) for v in value]
                result[name] = (
                    sum(values) / len(values)
                    if values
                    else None
                )
        return result

    def _round_summary(
        self,
        events: List[Dict[str, object]],
        n_experts: int,
    ) -> Optional[Dict[str, object]]:
        if not events:
            return None

        usage = [0] * n_experts
        gate = [0.0] * n_experts
        token_count = 0
        for event in events:
            token_count += int(event["rows"])
            for index, count in enumerate(event["usage"]):
                usage[index] += int(count)
            for index, mass in enumerate(event["gate_mass"]):
                gate[index] += float(mass)

        # usage 是 assignment 计数（token × top_k），token 数单独
        # 记录，避免 token 量与 assignment 量混淆。
        total = sum(usage)
        usage_share = (
            [count / total for count in usage]
            if total > 0
            else [0.0] * n_experts
        )
        gate_total = sum(gate)
        gate_share = (
            [mass / gate_total for mass in gate]
            if gate_total > 0
            else [0.0] * n_experts
        )

        shares = torch.tensor(usage_share, dtype=torch.float64)
        log_e = (
            math.log(n_experts)
            if n_experts > 1
            else 0.0
        )
        if log_e > 0.0 and total > 0:
            nonzero = shares[shares > 0]
            load_entropy = float(
                -(nonzero * nonzero.log()).sum() / log_e
            )
        else:
            load_entropy = 0.0

        mean_share = (
            sum(usage_share) / n_experts
            if n_experts > 0
            else 0.0
        )
        if mean_share > 0:
            variance = sum(
                (share - mean_share) ** 2
                for share in usage_share
            ) / n_experts
            load_cv = math.sqrt(variance) / mean_share
        else:
            load_cv = 0.0

        def _mean_events(field: str) -> Optional[float]:
            values = [
                float(event[field])
                for event in events
                if event.get(field) is not None
            ]
            return sum(values) / len(values) if values else None

        return {
            "events": len(events),
            "tokens": token_count,
            "assignments": total,
            "expert_usage_share": [
                round(share, 6) for share in usage_share
            ],
            "expert_gate_mass_share": [
                round(share, 6) for share in gate_share
            ],
            "load_entropy": load_entropy,
            "load_max_share": max(usage_share) if usage_share else 0.0,
            "load_cv": load_cv,
            "dead_experts": sum(1 for count in usage if count == 0),
            "router_entropy_mean": _mean_events("router_entropy"),
            "router_max_prob_mean": _mean_events("router_max_prob"),
        }

    def _pair_overlap(
        self,
        first: Dict[str, object],
        second: Dict[str, object],
        block: int,
    ) -> Dict[str, object]:
        """
        一对（第一轮、第二轮）route 记录的重合指标。

        返回 branch_level（逐分支对齐）与 token_level（跨分支
        并集）两种口径；smelt/local_base 无分支结构，两者相同。
        """
        cfg = self.cfg
        n_experts = cfg.n_experts
        k1 = cfg.k1
        k2 = cfg.k2

        a = first["indices"].to(torch.int64)
        b = second["indices"].to(torch.int64)
        shape_first = list(first["input_shape"])
        shape_second = list(second["input_shape"])

        result: Dict[str, object] = {
            "branch_level": None,
            "token_level": None,
            "branch_self_reuse_share": None,
        }

        if cfg.mode in ("base", "smelt", "local_base", "local_base_k2"):
            metrics = _routing_set_metrics(a, b, n_experts)
            result["branch_level"] = metrics
            result["token_level"] = (
                dict(metrics) if metrics is not None else None
            )
            return result

        if cfg.mode == "A":
            # 第一轮 [B*T, k1]；第二轮 [B*T*k1, k2]，
            # 行序为 (batch, time, branch)。
            if len(shape_second) != 4 or a.size(0) * k1 != b.size(0):
                return result
            rows = a.size(0)
            b_branch = b.reshape(rows, k1, k2)
            a_expanded = a.repeat_interleave(k1, dim=0)
            result["branch_level"] = _routing_set_metrics(
                a_expanded,
                b_branch.reshape(-1, k2).contiguous(),
                n_experts,
            )
            a_bool = _routing_set_bool(a, n_experts)
            b_bool = _routing_set_bool(
                b,
                n_experts,
            ).reshape(rows, k1, n_experts).any(dim=1)
            result["token_level"] = _routing_set_metrics_bool(
                a_bool,
                b_bool,
            )
            b_branch_bool = _routing_set_bool(
                b,
                n_experts,
            ).reshape(rows, k1, n_experts)
            own = b_branch_bool.gather(
                2,
                a.unsqueeze(2),
            ).float()
            result["branch_self_reuse_share"] = float(own.mean())
            return result

        if cfg.mode in ("B", "B_early") and block == cfg.middle_start:
            # 分支创建：[B, T, k1]（第 j 个分支的专家）；第二轮
            # 经 run_independent_blocks 把分支维并入批维后为
            # [B*k1*T, k2]，行序为 (batch, branch, time)。
            batch = int(shape_first[0])
            time_steps = int(shape_first[1])
            if batch * time_steps != a.size(0):
                return result
            if batch * k1 * time_steps != b.size(0):
                return result
            a_tokens = a.reshape(batch, time_steps, k1)
            b_branch = b.reshape(
                batch,
                k1,
                time_steps,
                k2,
            )
            # 分支 j 的第二轮只应和「该分支携带的第一轮专家」
            # 比较，而不是和父 token 的整个 top-k 集合比较：
            # a_tokens[..., j] 才是分支 j 的起点。行序必须与
            # b_branch 的 (batch, branch, time) 一致。
            a_expanded = (
                a_tokens.permute(0, 2, 1)
                .unsqueeze(-1)
                .reshape(-1, 1)
            )
            result["branch_level"] = _routing_set_metrics(
                a_expanded,
                b_branch.reshape(-1, k2).contiguous(),
                n_experts,
            )
            b_bool = _routing_set_bool(
                b_branch.reshape(-1, k2),
                n_experts,
            ).reshape(batch, k1, time_steps, n_experts).any(dim=1)
            result["token_level"] = _routing_set_metrics_bool(
                _routing_set_bool(
                    a_tokens.reshape(batch * time_steps, k1),
                    n_experts,
                ),
                b_bool.reshape(batch * time_steps, n_experts),
            )
            own = _routing_set_bool(
                b_branch.reshape(-1, k2),
                n_experts,
            ).reshape(
                batch,
                k1,
                time_steps,
                n_experts,
            ).gather(
                3,
                a_tokens.permute(0, 2, 1).unsqueeze(-1),
            ).float()
            result["branch_self_reuse_share"] = float(own.mean())
            return result

        if cfg.mode in ("B", "B_early"):
            # 第一轮其余 Block 与第二轮：x 为 [B*k1, T, D]，
            # 行序为 (batch, branch)；两轮逐分支对齐。
            time_steps = int(shape_first[1])
            if time_steps <= 0:
                return result
            rows = a.size(0)
            if rows % (k1 * time_steps) != 0:
                return result
            batch = rows // (k1 * time_steps)
            if b.size(0) != rows:
                return result
            a_branch = a.reshape(batch, k1, time_steps, k1)
            b_branch = b.reshape(batch, k1, time_steps, k2)
            result["branch_level"] = _routing_set_metrics(
                a_branch.reshape(-1, k1),
                b_branch.reshape(-1, k2).contiguous(),
                n_experts,
            )
            a_bool = _routing_set_bool(
                a_branch.reshape(-1, k1),
                n_experts,
            ).reshape(
                batch,
                k1,
                time_steps,
                n_experts,
            ).any(dim=1)
            b_bool = _routing_set_bool(
                b_branch.reshape(-1, k2),
                n_experts,
            ).reshape(
                batch,
                k1,
                time_steps,
                n_experts,
            ).any(dim=1)
            result["token_level"] = _routing_set_metrics_bool(
                a_bool.reshape(batch * time_steps, n_experts),
                b_bool.reshape(batch * time_steps, n_experts),
            )
            return result

        return result

    def _materialize_events(self) -> None:
        """
        把 record 阶段留在设备上的小张量取回并写回事件。

        重复调用是幂等的。
        """
        if not self.events:
            return
        if isinstance(self.events[0].get("usage"), list):
            return

        scalars = torch.stack(
            [event["scalars"] for event in self.events]
        ).cpu()
        usages = torch.stack(
            [event["usage"] for event in self.events]
        ).cpu()
        gate_masses = torch.stack(
            [event["gate_mass"] for event in self.events]
        ).cpu()
        flat_indices = torch.cat(
            [
                event["indices"].reshape(-1)
                for event in self.events
            ]
        ).cpu()

        offset = 0
        for position, event in enumerate(self.events):
            values = scalars[position].tolist()
            event["router_entropy"] = values[0]
            event["load_entropy"] = values[1]
            event["load_max_share"] = values[2]
            event["dead_experts"] = int(values[3])
            event["router_max_prob"] = values[4]
            event["branch_cosine_mean"] = (
                None
                if math.isnan(values[5])
                else values[5]
            )
            event["branch_cosine_min_pair"] = (
                None
                if math.isnan(values[6])
                else values[6]
            )
            event["usage"] = usages[position].to(
                torch.int64
            ).tolist()
            event["gate_mass"] = gate_masses[
                position
            ].tolist()

            shape = event["indices"].shape
            count = event["indices"].numel()
            event["indices"] = flat_indices[
                offset:offset + count
            ].view(shape)
            offset += count
            del event["scalars"]

    def build_report(self, split: str = "val") -> Dict[str, object]:
        cfg = self.cfg
        report: Dict[str, object] = {
            "mode": cfg.mode,
            "split": split,
            "top_k": cfg.top_k,
            "k1": cfg.k1,
            "k2": cfg.k2,
            "n_experts": cfg.n_experts,
            "events": len(self.events),
            "round_semantics": (
                "round = 同一 Block 内 route() 的调用序号："
                "1=第一轮，2=第二轮"
            ),
            "branch_semantics": (
                "B 的分支是「按第一轮路由排名（slot）组成的序列"
                "分支」：同一 slot 在不同位置可以对应不同专家。"
                "分支间的前向状态彼此隔离（各自做 Attention），"
                "但全部专家/router/embedding 参数共享，梯度通过"
                "共享参数耦合；它们不是参数独立的专家轨迹，也"
                "不保证统计独立。'独立'只在「前向状态不混合」"
                "这一意义上成立"
            ),
            "notes": [
                "诊断只使用验证集固定窗口，测试集不参与。",
                "路由诊断不参与模型选择、早停或指标优化。",
                "重合度在同一 token、同一 Block 的两轮路由之间"
                "比较；A/B 的分支结构另有逐分支与 token 级"
                "（跨分支并集）口径。",
                "Jaccard 必须与 jaccard_chance_uniform / "
                "jaccard_chance_marginal 及 lift 一起读；低重合"
                "本身不证明路由更有效，需要干预实验验证。",
            ],
        }

        if cfg.mode == "dense":
            report["skipped"] = (
                "dense 基线没有 MoE 路由，无 RQ3/RQ4 诊断"
            )
            return report

        if not self.events:
            report["skipped"] = (
                "分析前向未记录到任何 route 调用"
            )
            return report

        self._materialize_events()

        grouped: Dict[int, Dict[int, List[Dict[str, object]]]] = {}
        for event in self.events:
            grouped.setdefault(event["block"], {}).setdefault(
                event["round"],
                [],
            ).append(event)

        middle_blocks = list(
            range(cfg.middle_start, cfg.middle_end)
        )

        per_block: Dict[str, object] = {}
        rq3_summary_values: Dict[str, List[float]] = {}
        rq4_round_values: Dict[str, Dict[str, List[float]]] = {
            "round1": {},
            "round2": {},
        }
        divergence_values: List[float] = []
        tokens_total = 0

        for block in middle_blocks:
            rounds = grouped.get(block, {})
            round1 = rounds.get(1, [])
            round2 = rounds.get(2, [])

            round1_summary = self._round_summary(
                round1,
                cfg.n_experts,
            )
            round2_summary = self._round_summary(
                round2,
                cfg.n_experts,
            )
            if round1_summary is not None:
                tokens_total += int(round1_summary["tokens"])

            overlap_accumulators: Dict[str, Dict[str, object]] = {
                "branch_level": {},
                "token_level": {},
            }
            self_reuse_values: List[float] = []
            cosine_values: List[float] = []
            cosine_min_values: List[float] = []

            for first, second in zip(round1, round2):
                overlap = self._pair_overlap(
                    first,
                    second,
                    block,
                )
                self._accumulate(
                    overlap_accumulators["branch_level"],
                    overlap.get("branch_level"),
                )
                self._accumulate(
                    overlap_accumulators["token_level"],
                    overlap.get("token_level"),
                )
                if overlap.get("branch_self_reuse_share") is not None:
                    self_reuse_values.append(
                        float(overlap["branch_self_reuse_share"])
                    )

            for event in round1 + round2:
                if event.get("branch_cosine_mean") is not None:
                    cosine_values.append(
                        float(event["branch_cosine_mean"])
                    )
                if event.get("branch_cosine_min_pair") is not None:
                    cosine_min_values.append(
                        float(event["branch_cosine_min_pair"])
                    )

            branch_metrics = self._finalize(
                overlap_accumulators["branch_level"]
            )
            token_metrics = self._finalize(
                overlap_accumulators["token_level"]
            )

            block_report: Dict[str, object] = {
                "round1": round1_summary,
                "round2": round2_summary,
                "expert_overlap_branch_level": (
                    branch_metrics or None
                ),
                "expert_overlap_token_level": (
                    token_metrics or None
                ),
                "branch_self_reuse_share": (
                    sum(self_reuse_values) / len(self_reuse_values)
                    if self_reuse_values
                    else None
                ),
                "branch_cosine_mean": (
                    sum(cosine_values) / len(cosine_values)
                    if cosine_values
                    else None
                ),
                "branch_cosine_min_pair": (
                    sum(cosine_min_values) / len(cosine_min_values)
                    if cosine_min_values
                    else None
                ),
            }
            per_block[str(block)] = block_report

            for name in (
                "second_round_jaccard_mean",
                "second_round_exact_match_share",
                "second_round_slot_reuse_mean",
                "first_round_recall_mean",
                "second_round_unique_reuse_mean",
                "expected_intersection_uniform",
                "jaccard_chance_uniform",
                "jaccard_chance_marginal",
                "jaccard_lift_over_uniform",
                "jaccard_lift_over_marginal",
                "jaccard_adjusted_uniform",
                "jaccard_adjusted_marginal",
            ):
                value = branch_metrics.get(name)
                if isinstance(value, (int, float)):
                    rq3_summary_values.setdefault(
                        name,
                        [],
                    ).append(float(value))
                token_value = token_metrics.get(name)
                if isinstance(token_value, (int, float)):
                    rq3_summary_values.setdefault(
                        f"token_{name}",
                        [],
                    ).append(float(token_value))
            if self_reuse_values:
                rq3_summary_values.setdefault(
                    "branch_self_reuse_share",
                    [],
                ).append(
                    sum(self_reuse_values) / len(self_reuse_values)
                )

            for round_name, summary in (
                ("round1", round1_summary),
                ("round2", round2_summary),
            ):
                if summary is None:
                    continue
                for field in (
                    "load_entropy",
                    "load_max_share",
                    "dead_experts",
                    "router_entropy_mean",
                    "router_max_prob_mean",
                ):
                    value = summary.get(field)
                    if isinstance(value, (int, float)):
                        rq4_round_values[round_name].setdefault(
                            field,
                            [],
                        ).append(float(value))

            if cosine_values:
                divergence_values.append(
                    sum(cosine_values) / len(cosine_values)
                )

        rq3_summary = {
            name: sum(values) / len(values)
            for name, values in rq3_summary_values.items()
            if values
        }

        rq4_summary = {}
        for round_name, field_values in rq4_round_values.items():
            rq4_summary[round_name] = {
                field: sum(values) / len(values)
                for field, values in field_values.items()
                if values
            }

        report.update({
            "tokens_evaluated": tokens_total,
            "middle_blocks": middle_blocks,
            "per_block": per_block,
            "rq3_expert_overlap": {
                "definition": (
                    "第二轮相对第一轮的专家集合重合：jaccard = "
                    "|A∩B|/|A∪B|；chance_uniform = 均匀随机集合"
                    "的期望 Jaccard（E|A∩B|=k1*k2/E）；"
                    "chance_marginal = 保持第二轮专家边际负载、"
                    "随机化组合的期望 Jaccard；lift = 观测/chance；"
                    "adjusted = (obs−chance)/(1−chance)。"
                    "slot_reuse = 第二轮每个 assignment 的专家落在"
                    "第一轮集合中的比例；branch 级 = 同一分支两轮"
                    "对齐，token 级 = 第二轮跨分支并集对第一轮集合"
                ),
                "summary": rq3_summary,
            },
            "rq4_load_and_entropy": {
                "definition": (
                    "专家负载分布与路由熵：load_entropy 为逐专家"
                    "使用率香农熵（按 ln(n_experts) 归一，1=完全"
                    "均匀）；router_entropy_mean 为路由 softmax "
                    "分布熵；dead_experts 为无 assignment 的专家数"
                ),
                "summary": rq4_summary,
            },
            "branch_divergence": {
                "definition": (
                    "A/B 分支表示的跨分支平均余弦相似度：接近 1 "
                    "说明分支轨迹几乎重合（延迟合并未产生独立"
                    "计算），明显小于 1 说明分支在分化"
                ),
                "summary": {
                    "branch_cosine_mean": (
                        sum(divergence_values)
                        / len(divergence_values)
                        if divergence_values
                        else None
                    ),
                    "blocks_with_branches": len(divergence_values),
                },
            },
        })
        return report


def analyze_routing(
    model: nn.Module,
    dataset: ByteDataset,
    batch_size: int,
    batches: int,
    device: torch.device,
    amp_dtype: Optional[torch.dtype] = None,
    split: str = "val",
) -> Dict[str, object]:
    """
    在固定评估窗口上做一次无梯度前向，汇总 RQ3/RQ4 路由诊断。

    split 只允许 val/test；调用方（训练入口）只传 val——路由
    诊断不接触尘封的测试集。返回结构化报告，供 metrics.jsonl、
    config.json 与 routing.json 落盘。
    """
    was_training = model.training
    model.eval()

    core = _unwrap_model(model)
    cfg = core.cfg
    probe = RoutingProbe(cfg, batch_size)
    probe.attach(core)

    use_amp = (
        amp_dtype is not None
        and device.type == "cuda"
    )

    try:
        with torch.autocast(
            device_type="cuda",
            dtype=amp_dtype,
            enabled=use_amp,
        ):
            with torch.no_grad():
                for batch_index in range(batches):
                    x, _ = dataset.fixed_eval_batch(
                        split,
                        batch_index,
                        batches,
                        batch_size,
                        device,
                    )
                    if x.size(0) == 0:
                        break
                    core(x)
    finally:
        probe.detach()
        model.train(was_training)

    report = probe.build_report(split=split)
    report["batches_requested"] = batches
    report["batch_size"] = batch_size
    return report


def print_routing_analysis(report: Dict[str, object]) -> None:
    """打印 RQ3/RQ4 路由诊断摘要。"""
    mode = report.get("mode")
    if "skipped" in report:
        print(
            f"[routing] mode={mode} 跳过路由诊断: "
            f"{report.get('skipped')}"
        )
        return

    print(
        f"[routing] mode={mode} split={report.get('split')} "
        f"tokens={report.get('tokens_evaluated')} "
        f"blocks={report.get('middle_blocks')}"
    )

    rq4 = report.get("rq4_load_and_entropy") or {}
    for round_name in ("round1", "round2"):
        summary = (rq4.get("summary") or {}).get(round_name) or {}
        if not summary:
            continue
        print(
            f"[routing] {round_name} 专家负载: "
            "load_entropy="
            f"{_format_finite(summary.get('load_entropy'))} "
            "max_share="
            f"{_format_finite(summary.get('load_max_share'))} "
            f"dead={summary.get('dead_experts')} "
            "router_entropy="
            f"{_format_finite(summary.get('router_entropy_mean'))}"
        )

    rq3 = (report.get("rq3_expert_overlap") or {}).get(
        "summary"
    ) or {}
    if rq3:
        def _show(name: str) -> str:
            value = rq3.get(name)
            if value is None:
                return "n/a"
            return _format_finite(value)

        print(
            "[routing] RQ3 两轮专家重合（branch 级）："
            f"jaccard={_show('second_round_jaccard_mean')} "
            f"exact_match="
            f"{_show('second_round_exact_match_share')} "
            f"slot_reuse="
            f"{_show('second_round_slot_reuse_mean')} | "
            "token 级："
            f"jaccard={_show('token_second_round_jaccard_mean')} "
            f"exact_match="
            f"{_show('token_second_round_exact_match_share')}"
        )
        if rq3.get("branch_self_reuse_share") is not None:
            print(
                "[routing] 分支自身专家在第二轮复现比例（A/B）: "
                f"{_format_finite(rq3.get('branch_self_reuse_share'))}"
            )
        # 机会水平校正：不同 k1/k2 与负载分布下 Jaccard 的
        # 零点不同，必须并列展示。
        print(
            "[routing] RQ3 机会水平："
            f"uniform={_show('jaccard_chance_uniform')} "
            f"marginal={_show('jaccard_chance_marginal')} "
            f"lift_uniform={_show('jaccard_lift_over_uniform')} "
            f"lift_marginal={_show('jaccard_lift_over_marginal')} "
            f"adjusted_marginal="
            f"{_show('jaccard_adjusted_marginal')}"
        )

    divergence = (report.get("branch_divergence") or {}).get(
        "summary"
    ) or {}
    if divergence.get("branch_cosine_mean") is not None:
        print(
            "[routing] 跨分支表示平均余弦相似度: "
            f"{_format_finite(divergence.get('branch_cosine_mean'))}"
            f"（blocks_with_branches="
            f"{divergence.get('blocks_with_branches')}）"
        )


def _routing_shuffle_seed(
    seed: int,
    module_index: int,
) -> int:
    """
    路由打乱干预的稳定子种子。

    只用 (运行 seed, MoE 在模型中的固定序号) 派生，绝不使用
    ``id(module)`` 或对象地址：后者随进程、内存分配和模型
    构造顺序变化，会让同一 ``--seed`` 的 RQ4 干预在不同运行
    中消费不同的随机路由，功能证据不可复现。
    """
    material = (
        f"routing_shuffle_v1|{int(seed)}|{int(module_index)}"
    ).encode("utf-8")
    return int.from_bytes(
        hashlib.blake2b(material, digest_size=8).digest(),
        "big",
    )


def _intervention_eval(
    model: nn.Module,
    dataset: ByteDataset,
    batch_size: int,
    batches: int,
    device: torch.device,
    amp_dtype: Optional[torch.dtype],
) -> Dict[str, float]:
    """在固定验证窗口上做一次前向，返回损失与 token 准确率。"""
    core = _unwrap_model(model)
    was_training = core.training
    core.eval()
    use_amp = amp_dtype is not None and device.type == "cuda"
    total_loss = 0.0
    total_tokens = 0
    correct = 0
    try:
        with torch.autocast(
            device_type="cuda",
            dtype=amp_dtype,
            enabled=use_amp,
        ):
            with torch.no_grad():
                for batch_index in range(batches):
                    x, y = dataset.fixed_eval_batch(
                        "val",
                        batch_index,
                        batches,
                        batch_size,
                        device,
                    )
                    if x.size(0) == 0:
                        break
                    logits = core(x)["logits"].float()
                    loss = F.cross_entropy(
                        logits.reshape(-1, logits.size(-1)),
                        y.reshape(-1),
                        reduction="sum",
                    )
                    total_loss += float(loss)
                    total_tokens += int(y.numel())
                    correct += int(
                        (logits.argmax(dim=-1) == y).sum()
                    )
    finally:
        core.train(was_training)
    if total_tokens <= 0:
        return {
            "loss": float("nan"),
            "token_accuracy": float("nan"),
            "tokens": 0,
        }
    return {
        "loss": total_loss / total_tokens,
        "token_accuracy": correct / total_tokens,
        "tokens": total_tokens,
    }


def _routing_shuffle_indices(
    n_experts: int,
    shape: torch.Size,
    generator: torch.Generator,
) -> torch.Tensor:
    """为每个 token 无放回抽取 top-k 个随机专家。

    原来的 `torch.randint` 有放回抽样会把同一专家分配给一个
    token 的多个 slot（E=4、k=2 时约 1/4 的行），模型随后把
    重复 slot 合并成单专家满权重，随机路由的分布已经偏离
    「均匀随机 top-k」。这里对每行随机打分再取前 k 个不同的
    专家，保持 assignment 数与均匀权重口径。
    """
    rows = int(shape[0]) if len(shape) > 0 else 0
    slots = int(shape[-1]) if len(shape) > 0 else 0
    if rows <= 0 or slots <= 0:
        return torch.empty(shape, dtype=torch.int64)
    if slots > n_experts:
        raise ValueError(
            "routing_shuffle 的 top-k 不能超过专家数"
        )
    scores = torch.rand(
        (rows, int(n_experts)),
        generator=generator,
    )
    selected = torch.topk(
        scores,
        k=slots,
        dim=-1,
    ).indices
    return selected.reshape(shape)


def analyze_routing_interventions(
    model: nn.Module,
    dataset: ByteDataset,
    batch_size: int,
    batches: int,
    device: torch.device,
    amp_dtype: Optional[torch.dtype] = None,
    seed: int = 0,
) -> Dict[str, object]:
    """
    RQ4 的干预验证：负载均匀/熵高本身不能证明专家专门化。

    三类反事实只用验证集固定窗口，不参与选型：

    1. ``routing_shuffle``：把每个 token 的顶层路由替换为均匀
       随机专家（保留 k 个 assignment，权重均匀）。若专家存在
       可区分的功能，随机化路由应显著抬高损失；
    2. ``expert_drop``：逐个把某专家的输出置零（路由/门控保持
       不变），记录损失上升。若专家专门化，不同专家的 drop
       损失上升应有明显差异，而不是所有专家都差不多；
    3. ``baseline``：同一批窗口、同一模型的原损失。

    报告给出损失差、准确率差、专家重要性分布与「最重/最轻
    专家」的比值，并把路由分布诊断降级为「利用率描述」。
    代价是 E+2 次验证前向，默认不启用（``--routing-interventions``）。
    """
    core = _unwrap_model(model)
    cfg = core.cfg
    moe_modules = [
        block.moe
        for block in core.blocks
        if isinstance(getattr(block, "moe", None), SparseMoE)
    ]
    report: Dict[str, object] = {
        "mode": cfg.mode,
        "split": "val",
        "batches_requested": batches,
        "batch_size": batch_size,
        "n_experts": cfg.n_experts,
        "baseline": _intervention_eval(
            core,
            dataset,
            batch_size,
            batches,
            device,
            amp_dtype,
        ),
        "interventions": {
            "routing_shuffle": {},
            "expert_drop": {},
        },
        "notes": [
            "只使用验证集固定窗口；测试集不参与。",
            "routing_shuffle 保持 assignment 数与均匀权重，仅把"
            "专家身份随机化；expert_drop 保持路由与门控，仅把"
            "被屏蔽专家的输出置零。",
            "这是功能干预证据；负载熵/死专家数只是利用率描述，"
            "均匀随机路由也能得到高熵，不能单独证明专门化。",
            "代价：E+2 次验证前向，大 E 时开销明显。",
        ],
    }

    baseline_loss = float(report["baseline"]["loss"])
    baseline_acc = float(report["baseline"]["token_accuracy"])

    # 路由打乱：每个 MoE 用独立、固定的随机流；保留原 k。
    # 种子必须由「运行 seed + 模型内 MoE 序号」派生，不能用
    # id(module)：对象地址随进程/分配顺序变化，同一 --seed 的
    # 干预实验会跨进程得到不同路由，RQ4 的功能证据不可复现。
    def _make_override(module: SparseMoE, module_index: int):
        generator = torch.Generator(device="cpu")
        # 只在创建 override 时播种一次，让随机流在后续每次
        # route 调用（两轮、多个 batch）之间自然推进。原先在
        # 闭包里每调用一次就 manual_seed，所有同形状调用拿到
        # 完全相同的 assignment，round1/round2 与不同 batch 被
        # 人为绑定，随机化失去意义。
        generator.manual_seed(
            _routing_shuffle_seed(seed, module_index)
        )

        def _override(indices, weights, logits):
            new_indices = _routing_shuffle_indices(
                int(module.n_experts),
                indices.shape,
                generator,
            ).to(indices.device)
            new_weights = torch.full_like(
                weights,
                1.0 / max(1, indices.size(-1)),
            )
            return new_indices, new_weights

        return _override

    overrides = {}
    for module_index, module in enumerate(moe_modules):
        overrides[id(module)] = _make_override(
            module,
            module_index,
        )
        module._routing_override = overrides[id(module)]
    try:
        shuffled = _intervention_eval(
            core,
            dataset,
            batch_size,
            batches,
            device,
            amp_dtype,
        )
    finally:
        for module in moe_modules:
            module._routing_override = None
    report["interventions"]["routing_shuffle"] = {
        **shuffled,
        "loss_delta": float(shuffled["loss"]) - baseline_loss,
        "loss_ratio": (
            float(shuffled["loss"]) / baseline_loss
            if baseline_loss > 0
            else None
        ),
        "accuracy_delta": float(shuffled["token_accuracy"]) - baseline_acc,
    }

    # 专家屏蔽：逐个专家置零。E 较大时也只在 val 固定窗口上
    # 做一次前向/专家，成本可控但会明显变慢。
    drop_rows: Dict[str, object] = {}
    drop_deltas: List[float] = []
    for expert_index in range(cfg.n_experts):
        for module in moe_modules:
            module._expert_drop_index = expert_index
        try:
            dropped = _intervention_eval(
                core,
                dataset,
                batch_size,
                batches,
                device,
                amp_dtype,
            )
        finally:
            for module in moe_modules:
                module._expert_drop_index = None
        delta = float(dropped["loss"]) - baseline_loss
        drop_deltas.append(delta)
        drop_rows[str(expert_index)] = {
            **dropped,
            "loss_delta": delta,
        }
    finite_deltas = [
        value for value in drop_deltas if math.isfinite(value)
    ]
    if finite_deltas:
        mean_delta = sum(finite_deltas) / len(finite_deltas)
        variance = sum(
            (value - mean_delta) ** 2 for value in finite_deltas
        ) / len(finite_deltas)
        max_index = max(
            range(len(drop_deltas)),
            key=lambda index: drop_deltas[index],
        )
        min_index = min(
            range(len(drop_deltas)),
            key=lambda index: drop_deltas[index],
        )
        max_delta = drop_deltas[max_index]
        min_delta = drop_deltas[min_index]
        report["interventions"]["expert_drop"] = {
            "per_expert": drop_rows,
            "mean_loss_delta": mean_delta,
            "std_loss_delta": math.sqrt(variance),
            "max_loss_delta": max_delta,
            "max_expert": max_index,
            "min_loss_delta": min_delta,
            "min_expert": min_index,
            "max_over_min_abs_ratio": (
                abs(max_delta) / abs(min_delta)
                if abs(min_delta) > 1e-12
                else None
            ),
            "importance_cv": (
                math.sqrt(variance) / abs(mean_delta)
                if abs(mean_delta) > 1e-12
                else None
            ),
        }
    else:
        report["interventions"]["expert_drop"] = {
            "per_expert": drop_rows,
            "error": "所有专家屏蔽后的损失都不是有限值",
        }
    return report


def print_routing_interventions(report: Dict[str, object]) -> None:
    """打印 RQ4 干预实验摘要。"""
    baseline = report.get("baseline") or {}
    if not baseline or "loss" not in baseline:
        return
    print(
        "[routing-intervention] mode="
        f"{report.get('mode')} baseline_loss="
        f"{_format_finite(baseline.get('loss'), '.6f')}"
    )
    shuffle = (report.get("interventions") or {}).get(
        "routing_shuffle"
    ) or {}
    if shuffle.get("loss_delta") is not None:
        print(
            "[routing-intervention] 路由打乱："
            "Δloss="
            f"{_format_finite(shuffle.get('loss_delta'), '+.6f')} "
            f"ratio={shuffle.get('loss_ratio')} "
            "Δacc="
            f"{_format_finite(shuffle.get('accuracy_delta'), '+.4f')}"
        )
    drop = (report.get("interventions") or {}).get(
        "expert_drop"
    ) or {}
    if drop.get("max_expert") is not None:
        print(
            "[routing-intervention] 专家屏蔽："
            f"max_expert={drop.get('max_expert')} "
            "Δloss="
            f"{_format_finite(drop.get('max_loss_delta'), '+.6f')}；"
            f"min_expert={drop.get('min_expert')} "
            "Δloss="
            f"{_format_finite(drop.get('min_loss_delta'), '+.6f')}；"
            "mean="
            f"{_format_finite(drop.get('mean_loss_delta'), '+.6f')}"
            f"±{_format_finite(drop.get('std_loss_delta'), '.6f')} "
            f"CV={drop.get('importance_cv')}"
        )


# ============================================================
# Non-finite (NaN/Inf) diagnosis
# ============================================================

# 非有限损失/梯度的系统排查路径（顺序固定，先查证据更简单
# 的环节，再查混合精度与优化环节）。
# 诊断时保留的近期有限梯度范数窗口：用失败步之前的梯度水平
# 判断「梯度爆炸/学习率过大」是否有证据。
_NAN_GRAD_TREND_WINDOW = 50

# 失败步梯度范数达到近期中位数的该倍数时，判定为梯度放大明显。
_NAN_GRAD_EXPLOSION_RATIO = 5.0

_NONFINITE_CHECKLIST = [
    "1) 数据：批次内是否存在 NaN/Inf 或越界 token"
    "（字节管线的整数 token 天然无 NaN，越界/负值可能来自"
    "上游 dtype 或编码错误；扩展到连续值特征后必须查 NaN/Inf）。",
    "2) 前向数值：logits 是否非有限、绝对值是否接近低精度"
    "上限；有限 logits + 非有限损失通常是 log(0)/除零/目标"
    "越界等损失侧问题。",
    "3) 混合精度：fp16 autocast 下 matmul/softmax 溢出会先"
    "出现大绝对值再变 NaN；梯度下溢则表现为小梯度被 flush 成"
    "0、更新丢失（grad_scale 被持续上调、梯度范数异常小、"
    "训练停滞但不发散）。可对比关闭 AMP（--device cpu 或"
    "换 bf16）判断。",
    "4) 梯度与优化：逐参数梯度是否爆炸/非有限、参数与优化器"
    "状态是否已被污染；若是则降低学习率、开启/收紧梯度裁剪"
    "（--grad-clip）并从污染前的检查点恢复。",
]


def _check_batch_integrity(
    x: torch.Tensor,
    y: torch.Tensor,
    vocab_size: int,
) -> Dict[str, object]:
    """检查一个训练批次的值域与非有限元素。"""
    info: Dict[str, object] = {
        "x_dtype": str(x.dtype),
        "y_dtype": str(y.dtype),
        "x_min": None,
        "x_max": None,
        "y_min": None,
        "y_max": None,
        "nonfinite_elements": 0,
        "out_of_range_elements": 0,
        "ok": True,
    }

    for name, tensor in (("x", x), ("y", y)):
        if tensor.numel() == 0:
            continue

        if tensor.is_floating_point():
            finite_mask = torch.isfinite(tensor)
            info["nonfinite_elements"] = int(
                info["nonfinite_elements"]
            ) + int((~finite_mask).sum())
            finite_values = tensor[finite_mask]
            if finite_values.numel() > 0:
                info[f"{name}_min"] = float(
                    finite_values.min()
                )
                info[f"{name}_max"] = float(
                    finite_values.max()
                )
            # NaN/Inf 已在上面单独计数；值域检查只看有限元素。
            comparison = finite_values.to(torch.int64)
        else:
            info[f"{name}_min"] = int(tensor.min())
            info[f"{name}_max"] = int(tensor.max())
            # 值域比较前统一提升到 int64。
            comparison = tensor.to(torch.int64)

        info["out_of_range_elements"] = int(
            info["out_of_range_elements"]
        ) + int(
            ((comparison < 0) | (comparison >= vocab_size)).sum()
        )

    info["ok"] = (
        int(info["nonfinite_elements"]) == 0
        and int(info["out_of_range_elements"]) == 0
    )
    return info


def diagnose_non_finite(
    model: nn.Module,
    optimizer: torch.optim.Optimizer,
    x: torch.Tensor,
    y: torch.Tensor,
    result: Dict[str, torch.Tensor],
    grad_norm: torch.Tensor,
    *,
    step: int,
    lr: float,
    amp_dtype: Optional[torch.dtype] = None,
    scaler: Optional[object] = None,
    amp_scale_before_step: Optional[float] = None,
    vocab_size: int = 256,
    recent_grad_norms: Optional[List[Tuple[int, float]]] = None,
) -> Dict[str, object]:
    """
    非有限损失/梯度出现时的系统排查。

    按固定路径收集证据：数据值域与非有限元素 → logits/损失
    数值（log(0)、除零、softmax 溢出）→ 低精度上限 → 逐参数
    梯度、参数与优化器状态污染 → 学习率/梯度缩放状态；并用
    失败步之前的有限梯度范数（``recent_grad_norms``）判断
    「梯度爆炸/学习率过大」是否有证据，还是更像前向/损失侧
    问题。返回的报告会附加到触发该步的 metrics 记录
    （nan_diagnosis 字段）并打印，之后按报告中的 next_steps
    逐项排除。
    """
    findings: List[str] = []
    checks: Dict[str, object] = {}

    report: Dict[str, object] = {
        "step": step,
        "lr": lr,
        "checks": checks,
        "findings": findings,
        "next_steps": list(_NONFINITE_CHECKLIST),
    }

    # ---- 1) 数据 ----
    data_check = _check_batch_integrity(x, y, vocab_size)
    checks["data"] = data_check
    if not data_check["ok"]:
        findings.append(
            "数据批次包含非有限或越界元素"
            f"（nonfinite={data_check['nonfinite_elements']}, "
            f"out_of_range={data_check['out_of_range_elements']}）"
        )

    # ---- 2) 前向数值 ----
    logits = result.get("logits")
    loss = result.get("loss")
    lm_loss = result.get("lm_loss")
    aux_loss = result.get("aux_loss")

    # 训练循环在反向之前就释放了 logits；诊断时补跑一次前向。
    # 只在确认出错后执行一次。
    probe_source = "training result"
    # torch.compile 返回的 OptimizedModule 不是 LanguageModel 的
    # isinstance，必须解包后再判断，否则 --compile 运行时前向
    # 证据（logits 有限性/量级）永远缺失。
    if logits is None and isinstance(
        _unwrap_model(model),
        LanguageModel,
    ):
        was_training = model.training
        try:
            model.eval()
            probe_use_amp = (
                amp_dtype is not None
                and x.is_cuda
            )
            with torch.no_grad():
                with torch.autocast(
                    device_type="cuda",
                    dtype=amp_dtype,
                    enabled=probe_use_amp,
                ):
                    probe = model(x)
            probe_logits = probe.get("logits")
            if probe_logits is not None:
                logits = probe_logits
                probe_source = "diagnostic forward probe"
        except Exception:
            pass
        finally:
            model.train(was_training)

    def _finite(value) -> Optional[bool]:
        if value is None or not torch.is_tensor(value):
            return None
        return bool(torch.isfinite(value).all())

    logits_absmax = None
    logits_dtype = None
    if logits is not None and torch.is_tensor(logits):
        logits_dtype = str(logits.dtype)
        if logits.numel() > 0:
            logits_absmax = float(
                logits.detach().abs().max()
            )

    # 用同一份 logits 在 fp32 下重算逐 token LM 损失：这是
    # 区分「前向 logits 已坏」与「损失侧 log(0)/除零/低精度
    # 归约」的直接证据，也能量化目标概率下溢为 0 的 token 数。
    recomputed_loss: Dict[str, object] = {
        "available": False,
        "lm_loss": None,
        "finite": None,
        "nonfinite_tokens": None,
        "log_zero_probability_tokens": None,
        "target_range_ok": None,
    }
    if (
        logits is not None
        and torch.is_tensor(logits)
        and y is not None
        and torch.is_tensor(y)
        and logits.size(-1) > 0
    ):
        try:
            flat_logits = logits.detach().reshape(
                -1, int(logits.size(-1))
            ).float()
            flat_targets = y.reshape(-1).to(torch.int64)
            if flat_logits.size(0) == flat_targets.numel():
                target_range_ok = bool(
                    (
                        (flat_targets >= 0)
                        & (flat_targets < logits.size(-1))
                    ).all()
                )
                recomputed_loss["available"] = True
                recomputed_loss["target_range_ok"] = (
                    target_range_ok
                )
                if target_range_ok:
                    with torch.no_grad():
                        token_losses = F.cross_entropy(
                            flat_logits,
                            flat_targets,
                            reduction="none",
                        )
                    finite_tokens = torch.isfinite(
                        token_losses
                    )
                    recomputed_loss["finite"] = bool(
                        finite_tokens.all()
                    )
                    recomputed_loss["nonfinite_tokens"] = int(
                        (~finite_tokens).sum().item()
                    )
                    recomputed_loss["log_zero_probability_tokens"] = int(
                        torch.isinf(token_losses).sum().item()
                    )
                    finite_values = token_losses[
                        finite_tokens
                    ]
                    if finite_values.numel() > 0:
                        recomputed_loss["lm_loss"] = float(
                            finite_values.mean().item()
                        )
        except Exception as exc:
            recomputed_loss["error"] = str(exc)[:200]

    overflow_limit = None
    if amp_dtype == torch.float16:
        overflow_limit = 65504.0
    elif amp_dtype == torch.bfloat16:
        overflow_limit = float(
            torch.finfo(torch.bfloat16).max
        )

    checks["forward"] = {
        "logits_source": probe_source,
        "logits_dtype": logits_dtype,
        "logits_finite": _finite(logits),
        "logits_absmax": logits_absmax,
        "lm_loss_finite": _finite(lm_loss),
        "aux_loss_finite": _finite(aux_loss),
        "total_loss_finite": _finite(loss),
        "amp_dtype": (
            str(amp_dtype) if amp_dtype is not None else None
        ),
        "low_precision_overflow_limit": overflow_limit,
        "recompute_loss_fp32": recomputed_loss,
    }

    if _finite(logits) is False:
        findings.append(
            "logits 已含 NaN/Inf：优先怀疑低精度 matmul/softmax "
            "溢出或模型内部数值爆炸"
        )
    if recomputed_loss["available"]:
        if recomputed_loss["target_range_ok"] is False:
            findings.append(
                "目标 token 越界：损失侧 gather/cross_entropy 会"
                "产生非有限值或未定义行为，先修复数据/标签对齐"
            )
        elif (
            recomputed_loss["finite"] is False
            and _finite(logits) is True
        ):
            findings.append(
                "logits 有限，但用同一 logits 在 fp32 重算仍有 "
                f"{recomputed_loss['nonfinite_tokens']} 个 token "
                "损失非有限：优先查目标概率下溢为 0（log(0)）"
                "与低精度 logits 的动态范围，而不是梯度侧"
            )
        if (
            recomputed_loss["log_zero_probability_tokens"]
            or 0
        ) > 0:
            findings.append(
                "重算发现 "
                f"{recomputed_loss['log_zero_probability_tokens']}"
                " 个 token 的目标概率为 0（对数发散）：这是"
                "log(0)/softmax 下溢的直接证据"
            )
    if _finite(aux_loss) is False:
        findings.append(
            "辅助负载均衡损失非有限：检查路由计数归一化的"
            "除零（空 token/batch）、softmax 溢出与 "
            "balance_coef 数值范围"
        )
    if (
        logits_absmax is not None
        and overflow_limit is not None
        and logits_absmax > overflow_limit / 2.0
    ):
        findings.append(
            f"logits 绝对值 {logits_absmax:.3e} 已接近 "
            f"{amp_dtype} 上限 {overflow_limit:.3e}，"
            "低精度溢出风险高"
        )
    if (
        _finite(logits) is True
        and _finite(loss) is False
    ):
        findings.append(
            "logits 有限但总损失非有限：检查损失侧（目标越界、"
            "log(0)、除零、混合精度下的归约）"
        )

    # ---- 3) 逐参数梯度 ----
    nonfinite_grad_params: List[str] = []
    gradient_absmax: List[Tuple[float, str]] = []

    for name, parameter in model.named_parameters():
        if parameter.grad is None:
            continue
        gradient = parameter.grad.detach()
        if bool(torch.isfinite(gradient).all()):
            gradient_absmax.append(
                (float(gradient.abs().max()), name)
            )
        else:
            nonfinite_grad_params.append(name)

    gradient_absmax.sort(reverse=True)

    grad_norm_value = None
    if torch.is_tensor(grad_norm) and bool(
        torch.isfinite(grad_norm)
    ):
        grad_norm_value = float(grad_norm)

    checks["gradients"] = {
        "grad_norm": grad_norm_value,
        "nonfinite_grad_params": nonfinite_grad_params[:5],
        "n_nonfinite_grad_params": len(nonfinite_grad_params),
        "largest_grad_absmax": [
            [round(value, 6), name]
            for value, name in gradient_absmax[:5]
        ],
    }

    if nonfinite_grad_params:
        findings.append(
            f"{len(nonfinite_grad_params)} 个参数的梯度非有限"
            "（梯度爆炸/损失侧 NaN 反传）"
        )
    elif grad_norm_value is None and torch.is_tensor(grad_norm):
        findings.append(
            "梯度总体范数非有限但逐参数梯度均为有限："
            "可能是裁剪/缩放链路上的数值问题"
        )

    # ---- 4) 参数与优化器状态污染 ----
    nonfinite_params = [
        name
        for name, parameter in model.named_parameters()
        if not bool(
            torch.isfinite(parameter.detach()).all()
        )
    ]
    checks["parameters_nonfinite"] = nonfinite_params[:5]
    if nonfinite_params:
        findings.append(
            f"{len(nonfinite_params)} 个参数已含 NaN/Inf："
            "参数已被污染，应从污染前的检查点恢复"
        )

    nonfinite_state_keys = []
    for state in optimizer.state.values():
        for key, value in state.items():
            if torch.is_tensor(value) and not bool(
                torch.isfinite(value).all()
            ):
                nonfinite_state_keys.append(key)
    nonfinite_state_keys = sorted(set(nonfinite_state_keys))
    checks["optimizer_state_nonfinite_keys"] = (
        nonfinite_state_keys[:5]
    )
    if nonfinite_state_keys:
        findings.append(
            "优化器状态（"
            + ", ".join(nonfinite_state_keys)
            + "）已含 NaN/Inf：状态已被污染，需要从检查点恢复"
        )

    # ---- 5) 学习率、梯度缩放与梯度趋势 ----
    checks["lr"] = lr
    amp_state: Dict[str, object] = {
        "grad_scale_before_step": None,
        "grad_scale_at_diagnosis": None,
        "scale_reduced_on_failure": False,
    }
    if scaler is not None:
        try:
            scale_at_diagnosis = float(scaler.get_scale())
        except Exception:
            scale_at_diagnosis = None
        checks["grad_scale"] = scale_at_diagnosis
        amp_state["grad_scale_at_diagnosis"] = (
            scale_at_diagnosis
        )
        if (
            amp_scale_before_step is not None
            and math.isfinite(float(amp_scale_before_step))
            and float(amp_scale_before_step) > 0.0
        ):
            before = float(amp_scale_before_step)
            amp_state["grad_scale_before_step"] = before
            if scale_at_diagnosis is not None:
                amp_state["scale_ratio_to_before"] = round(
                    scale_at_diagnosis / before,
                    6,
                )
                # GradScaler 在 unscale 时发现 inf/nan 梯度会
                # 立即回退 scale（默认 ×0.5）；失败步出现回退
                # 是混合精度反传溢出的直接证据，比让用户
                # 「去查 AMP」更可行动。
                reduced = (
                    scale_at_diagnosis < before * 0.999
                )
                amp_state["scale_reduced_on_failure"] = reduced
                if reduced:
                    findings.append(
                        "AMP GradScaler 在失败步把 grad scale "
                        f"从 {before:.4g} 回退到 "
                        f"{scale_at_diagnosis:.4g}："
                        "反传梯度发生 fp16/bf16 溢出（inf/nan），"
                        "这是混合精度数值问题的直接证据。"
                        "优先检查 logits/损失量级、开启梯度裁剪、"
                        "降低学习率，或改用 bf16/fp32 复现确认。"
                    )
    checks["amp"] = amp_state

    # 用失败步之前的有限梯度范数做对照：非有限通常是「梯度爆炸/
    # 学习率过大」的特征；梯度水平正常则更像前向/损失侧问题，
    # 避免把两类根因混在一起排查。
    gradient_trend: Dict[str, object] = {}
    history_values = [
        float(value)
        for _, value in (recent_grad_norms or [])
        if math.isfinite(float(value))
    ]
    if history_values:
        ordered = sorted(history_values)
        median = float(_median(ordered))
        gradient_trend = {
            "window": len(ordered),
            "recent_median": round(median, 6),
            "recent_max": round(ordered[-1], 6),
            "fail_step_grad_norm": grad_norm_value,
        }
        if grad_norm_value is None:
            findings.append(
                f"失败步梯度范数非有限，而此前 {len(ordered)} 步"
                f"梯度范数均为有限（中位 {median:.4g}）："
                "符合梯度爆炸/学习率过大的特征，优先降低学习率、"
                "收紧 --grad-clip 并从污染前的检查点恢复"
            )
        elif (
            median > 0.0
            and grad_norm_value
            >= median * _NAN_GRAD_EXPLOSION_RATIO
        ):
            findings.append(
                f"失败步梯度范数 {grad_norm_value:.4g} 约为近期"
                f"中位数 {median:.4g} 的 "
                f"{grad_norm_value / median:.1f} 倍：梯度放大明显，"
                "符合梯度爆炸/学习率过大特征"
            )
        elif _finite(loss) is False:
            findings.append(
                "失败步梯度范数与近期水平相当：更像前向/损失侧"
                "（数据、log(0)/除零或低精度溢出）问题，"
                "而非梯度爆炸"
            )
    checks["gradient_trend"] = gradient_trend

    if not findings:
        findings.append(
            "本轮检查未定位到单一根因：按 next_steps 顺序逐项"
            "复现排查（数据→损失→混合精度→梯度/学习率）"
        )

    return report


def print_non_finite_report(report: Dict[str, object]) -> None:
    """打印非有限值的系统排查报告。"""
    print(
        f"[nan] step {report.get('step')} 检测到非有限损失/梯度，"
        f"lr={report.get('lr')}"
    )
    for finding in report.get("findings", []):
        print(f"[nan] 发现: {finding}")
    for line in report.get("next_steps", []):
        print(f"[nan] 排查: {line}")


# ============================================================
# Efficiency measurement
# ============================================================

def _unwrap_model(model: nn.Module) -> nn.Module:
    """取出 torch.compile 包装前的原始模型。"""
    return getattr(model, "_orig_mod", model)


def _count_non_embedding_params(model: LanguageModel) -> int:
    """统计不含 token/position embedding 的参数量。"""
    excluded = {
        id(model.token_embedding.weight),
        id(model.position_embedding.weight),
    }
    return sum(
        parameter.numel()
        for parameter in model.parameters()
        if id(parameter) not in excluded
    )


def _count_forward_flops(
    model: LanguageModel,
    x: torch.Tensor,
    y: torch.Tensor,
) -> Dict[str, Optional[int]]:
    """
    统计一次前向的理论计算量。

    - 线性层（mm/addmm，含专家与路由）用
      torch.utils.flop_counter.FlopCounterMode 测量；
    - SDPA 内部的注意力矩阵乘不计入 FlopCounter，测量期间
      包装每个 Block 的 attention_step 按 4·B·T²·D 补上
      （乘加各计 1 次浮点运算）。

    返回的是一次前向的总 FLOPs，用于跨模式比较计算量。
    """
    flops: Dict[str, Optional[int]] = {
        "linear_flops": None,
        "attention_flops": None,
        "total_flops_per_forward": None,
        "flops_note": (
            "linear(mm/addmm) 测量 + attention(4·B·T²·D) 估计"
        ),
    }

    try:
        from torch.utils.flop_counter import FlopCounterMode
    except Exception:
        return flops

    attention_flops = [0]

    # 训练路径会直接调用 first_branch_step / local_two_stage 等
    # Block 方法而不经过 __call__，模块级 hook 会漏计；所有路径
    # 最终都要走 attention_step，因此在测量期间按实例包装它。
    wrapped_modules: List[TransformerBlock] = []
    for module in model.modules():
        if not isinstance(module, TransformerBlock):
            continue
        original_attention_step = module.attention_step

        def _wrapped_attention_step(
            inputs: torch.Tensor,
            *args,
            _original=original_attention_step,
            **kwargs,
        ) -> torch.Tensor:
            if inputs.dim() == 3:
                # numel = B·T·D，乘 4·T 即 4·B·T²·D。
                attention_flops[0] += (
                    4 * int(inputs.size(-2)) * int(inputs.numel())
                )
            # scale 等区域参数必须原样透传，否则测量前向会走
            # 默认全局残差口径、与被测模型的实际计算图不一致。
            return _original(inputs, *args, **kwargs)

        module.attention_step = _wrapped_attention_step
        wrapped_modules.append(module)

    try:
        try:
            counter_context = FlopCounterMode(display=False)
        except TypeError:
            counter_context = FlopCounterMode()

        with torch.no_grad():
            with counter_context as counter:
                model(x, y)

        linear_flops = int(counter.get_total_flops())
    except Exception:
        return flops
    finally:
        for module in wrapped_modules:
            del module.attention_step

    flops["linear_flops"] = linear_flops
    flops["attention_flops"] = int(attention_flops[0])
    flops["total_flops_per_forward"] = (
        linear_flops + int(attention_flops[0])
    )
    return flops


def _process_peak_rss_mb() -> Optional[float]:
    """
    进程峰值常驻内存（MB）：Linux 读 /proc/self/status 的
    VmHWM，其他平台退回 resource.getrusage。
    """
    try:
        with open("/proc/self/status", encoding="utf-8") as f:
            for line in f:
                if line.startswith("VmHWM:"):
                    return round(
                        int(line.split()[1]) / 1024.0,
                        3,
                    )
    except (OSError, ValueError, IndexError):
        pass

    try:
        import resource

        peak_kb = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss
        if sys.platform == "darwin":
            return round(peak_kb / (1024.0 * 1024.0), 3)
        return round(peak_kb / 1024.0, 3)
    except Exception:
        return None


def _percentile(
    sorted_values: List[float],
    fraction: float,
) -> Optional[float]:
    """线性插值分位数；空列表返回 None。"""
    if not sorted_values:
        return None
    try:
        if len(sorted_values) == 1:
            return float(sorted_values[0])
        position = (len(sorted_values) - 1) * fraction
        lower = int(math.floor(position))
        upper = int(math.ceil(position))
        if lower == upper:
            return float(sorted_values[lower])
        weight = position - lower
        lower_value = float(sorted_values[lower])
        upper_value = float(sorted_values[upper])
    except (IndexError, OverflowError, TypeError, ValueError):
        return None
    return (
        lower_value * (1.0 - weight)
        + upper_value * weight
    )


def _safe_ratio(
    numerator: Optional[float],
    denominator: Optional[float],
) -> Optional[float]:
    """两个有限数的比值；缺失、除零或结果不可表示时返回 None。"""
    if numerator is None or denominator is None:
        return None
    if (
        isinstance(numerator, int)
        and not isinstance(numerator, bool)
        and isinstance(denominator, int)
        and not isinstance(denominator, bool)
    ):
        if denominator == 0:
            return None
        try:
            # 两个超大但同量级的整数计数可以直接相除；
            # 先各自转 float 会无谓地丢掉可表示的倍率。
            ratio = numerator / denominator
        except (OverflowError, ValueError):
            return None
    else:
        try:
            left = float(numerator)
            right = float(denominator)
        except (TypeError, ValueError, OverflowError):
            return None
        if (
            not math.isfinite(left)
            or not math.isfinite(right)
            or right == 0.0
        ):
            return None
        try:
            ratio = left / right
        except OverflowError:
            return None
    if not math.isfinite(ratio):
        return None
    return round(ratio, 6)


def _safe_cv(std: float, mean: float) -> Optional[float]:
    """变异系数；均值非正或比值超出 float 范围时返回 None。"""
    if mean <= 0.0 or not math.isfinite(mean):
        return None
    try:
        ratio = std / mean
    except OverflowError:
        return None
    if not math.isfinite(ratio):
        return None
    return round(ratio, 6)


def _timing_summary(
    timings: List[float],
    unit_scale: float = 1e3,
) -> Dict[str, object]:
    """
    计时分布摘要：中位数之外还报告 p95/p99、标准差与变异
    系数。只报单次中位数会把「偶发长尾」隐藏掉——对部署而言
    p99 延迟和均值稳定性往往比中位数更重要，跨运行的成本
    倍率也需要离散度才能判断是否只是计时噪声。
    """
    if not timings:
        return {
            "n": 0,
            "mean": None,
            "median": None,
            "p95": None,
            "p99": None,
            "min": None,
            "max": None,
            "std": None,
            "coefficient_of_variation": None,
        }

    # 记录来自 JSON 时可能是 10**400 这类合法但超出 float 范围
    # 的整数；直接 float() 会让整份计时摘要崩溃。按不可用值
    # 处理，保留 n 并让各统计量为 None。
    numeric = _finite_values(list(timings))
    count = len(timings)
    if numeric is None:
        return {
            "n": count,
            "mean": None,
            "median": None,
            "p95": None,
            "p99": None,
            "min": None,
            "max": None,
            "std": None,
            "coefficient_of_variation": None,
        }
    ordered = sorted(numeric)
    mean = _mean(ordered)
    if mean is None:
        return {
            "n": count,
            "mean": None,
            "median": None,
            "p95": None,
            "p99": None,
            "min": None,
            "max": None,
            "std": None,
            "coefficient_of_variation": None,
        }
    std = _sample_std(ordered)
    if std is None:
        std = 0.0

    def scaled(value: Optional[float]) -> Optional[float]:
        """换算单位并取整；结果超出 float 范围时返回 None。"""
        if value is None:
            return None
        result = value * unit_scale
        if not math.isfinite(result):
            return None
        return round(result, 6)

    return {
        "n": count,
        "mean": scaled(mean),
        "median": scaled(_percentile(ordered, 0.5)),
        "p95": scaled(_percentile(ordered, 0.95)),
        "p99": scaled(_percentile(ordered, 0.99)),
        "min": scaled(ordered[0]),
        "max": scaled(ordered[-1]),
        "std": scaled(std),
        "coefficient_of_variation": _safe_cv(std, mean),
    }


def measure_efficiency(
    model: nn.Module,
    dataset: ByteDataset,
    device: torch.device,
    batch_size: int,
    amp_dtype: Optional[torch.dtype] = None,
    warmup: int = 2,
    iters: int = 5,
) -> Dict[str, object]:
    """
    效率测量：参数量、前向 FLOPs 等模型规模指标。

    计时同时报告中位数与 p95/p99、标准差、变异系数及原始
    样本，避免用单次中位数掩盖长尾或把计时噪声当成方法差异。

    本测量在训练结束时对当前模型测一次，与精度指标一起写入
    config.json 与 metrics.jsonl（``{"step": "efficiency", ...}``）。
    """
    was_training = model.training
    raw_model = _unwrap_model(model)
    cfg = raw_model.cfg

    generator = torch.Generator().manual_seed(0)
    x, y = dataset.batch(
        "train",
        batch_size,
        generator,
        device,
    )

    use_amp = (
        amp_dtype is not None
        and device.type == "cuda"
    )
    autocast = torch.autocast(
        device_type="cuda",
        dtype=amp_dtype,
        enabled=use_amp,
    )

    flops = _count_forward_flops(raw_model, x, y)

    latency_seconds = None
    training_step_seconds = None
    inference_peak_mb = None
    training_peak_mb = None
    inference_timing_summary = _timing_summary([])
    training_timing_summary = _timing_summary([])

    try:
        model.eval()

        # 纯推理测量不回流训练图，与 evaluate 一致使用
        # inference_mode。
        with torch.inference_mode(), autocast:
            for _ in range(max(0, warmup)):
                model(x, y)

        if device.type == "cuda":
            torch.cuda.synchronize(device)

        timings: List[float] = []
        with torch.inference_mode(), autocast:
            for _ in range(max(1, iters)):
                if device.type == "cuda":
                    torch.cuda.synchronize(device)
                start = time.perf_counter()
                model(x, y)
                if device.type == "cuda":
                    torch.cuda.synchronize(device)
                timings.append(time.perf_counter() - start)

        timings.sort()
        latency_seconds = float(_percentile(timings, 0.5))
        inference_timing_summary = _timing_summary(timings)

        # 训练步计时（前向 + 反向，不含优化器更新）与推理
        # 计时使用同一 warmup/iters 口径，取中位数。
        model.train()
        if device.type == "cuda":
            torch.cuda.empty_cache()

        with autocast:
            for _ in range(max(0, warmup)):
                output = model(x, y)
                output["loss"].backward()
                model.zero_grad(set_to_none=True)

        if device.type == "cuda":
            torch.cuda.reset_peak_memory_stats(device)

        training_timings: List[float] = []
        with autocast:
            for _ in range(max(1, iters)):
                if device.type == "cuda":
                    torch.cuda.synchronize(device)
                start = time.perf_counter()
                output = model(x, y)
                output["loss"].backward()
                if device.type == "cuda":
                    torch.cuda.synchronize(device)
                training_timings.append(
                    time.perf_counter() - start
                )
                model.zero_grad(set_to_none=True)

            if device.type == "cuda":
                training_peak_mb = round(
                    torch.cuda.max_memory_allocated(device)
                    / 1e6,
                    3,
                )

        training_timings.sort()
        training_step_seconds = float(
            _percentile(training_timings, 0.5)
        )
        training_timing_summary = _timing_summary(
            training_timings
        )
        del output

        if device.type == "cuda":
            torch.cuda.reset_peak_memory_stats(device)
            with torch.inference_mode(), autocast:
                model(x, y)
            inference_peak_mb = round(
                torch.cuda.max_memory_allocated(device)
                / 1e6,
                3,
            )
    finally:
        model.train(was_training)

    tokens = int(x.numel())

    result: Dict[str, object] = {
        "n_params_total": int(
            sum(
                parameter.numel()
                for parameter in raw_model.parameters()
            )
        ),
        "n_params_non_embedding": int(
            _count_non_embedding_params(raw_model)
        ),
        "flops_per_forward": flops[
            "total_flops_per_forward"
        ],
        "flops_linear": flops["linear_flops"],
        "flops_attention": flops["attention_flops"],
        "flops_note": flops["flops_note"],
        "latency_ms_per_forward": (
            round(latency_seconds * 1e3, 4)
            if latency_seconds is not None
            else None
        ),
        "training_ms_per_step": (
            round(training_step_seconds * 1e3, 4)
            if training_step_seconds is not None
            else None
        ),
        "training_ms_note": (
            "前向+反向的中位计时；不含优化器更新/梯度裁剪"
        ),
        # 完整计时分布（毫秒）：median 之外给 p95/p99、std 与
        # 变异系数，并保留逐次原始样本供复核。单次中位数无法
        # 区分「稳定快」与「偶发长尾」。
        "latency_ms": inference_timing_summary,
        "training_ms": training_timing_summary,
        "timing_samples_seconds": {
            "inference": [
                round(float(value), 9)
                for value in timings
            ],
            "training": [
                round(float(value), 9)
                for value in training_timings
            ],
        },
        "throughput_tokens_per_sec": (
            round(tokens / latency_seconds, 2)
            if latency_seconds
            else None
        ),
        "inference_peak_memory_mb": inference_peak_mb,
        # 该值只覆盖前向+反向的合成训练步，不含优化器状态
        # （AdamW 一阶/二阶矩）与参数更新；真实训练循环的峰值
        # 另由 actual_training_peak_memory_mb 记录，跨运行
        # 对比优先使用后者。
        "training_peak_memory_mb": training_peak_mb,
        "training_peak_memory_note": (
            "前向+反向合成步峰值；不含优化器状态/更新，"
            "真实训练峰值见 actual_training_peak_memory_mb"
        ),
        "process_peak_rss_mb": _process_peak_rss_mb(),
        "batch_size": int(batch_size),
        "seq_len": int(x.size(1)),
        "tokens_per_forward": tokens,
        # 完整计算图口径与 KV cache 估计：论文要求 FLOPs、总参数
        # 与 KV cache 三者共同匹配；这里把解析成本与容量一起
        # 落盘，供 --compare / --budget-match 复核。
        "cost_profile": mode_cost_profile(cfg),
        "kv_cache_bytes_per_token": mode_cost_profile(cfg)[
            "kv_cache_bytes_per_token"
        ],
        "measured_flops_per_token": (
            round(
                float(flops["total_flops_per_forward"])
                / max(1, tokens),
                3,
            )
            if flops["total_flops_per_forward"] is not None
            else None
        ),
        "analytic_flops_per_token": mode_cost_profile(cfg)[
            "analytic_flops_per_token"
        ],
        "measurement": {
            "device": str(device),
            "amp_dtype": (
                str(amp_dtype)
                if amp_dtype is not None
                else None
            ),
            "warmup": int(warmup),
            "iters": int(iters),
            "mode": cfg.mode,
        },
    }

    return result


def print_efficiency(efficiency: Dict[str, object]) -> None:
    """打印效率测量摘要。"""
    def _format(value, unit="", spec=".3f"):
        if value is None:
            return "-"
        return _format_finite(value, spec) + unit

    print(
        "[efficiency] "
        f"params={efficiency.get('n_params_total')} "
        f"(non-embedding="
        f"{efficiency.get('n_params_non_embedding')}) | "
        f"FLOPs/forward="
        f"{_format(efficiency.get('flops_per_forward'), '', '.3e')} | "
        f"latency={_format(efficiency.get('latency_ms_per_forward'), 'ms')} | "
        f"train_step="
        f"{_format(efficiency.get('training_ms_per_step'), 'ms')} | "
        f"throughput="
        f"{_format(efficiency.get('throughput_tokens_per_sec'), 'tok/s')}"
    )
    for label, key in (
        ("inference", "latency_ms"),
        ("train_step", "training_ms"),
    ):
        summary = efficiency.get(key)
        if not isinstance(summary, dict) or not summary.get("n"):
            continue
        print(
            f"[efficiency] {label} 分布（n={summary['n']}）: "
            f"p50={_format(summary.get('median'), 'ms')} "
            f"p95={_format(summary.get('p95'), 'ms')} "
            f"p99={_format(summary.get('p99'), 'ms')} "
            f"std={_format(summary.get('std'), 'ms')} "
            "CV="
            f"{_format(summary.get('coefficient_of_variation'), '', '.1%')}"
            f" max={_format(summary.get('max'), 'ms')}"
        )
    print(
        "[efficiency] "
        f"inference_peak="
        f"{_format(efficiency.get('inference_peak_memory_mb'), 'MB')} | "
        f"fwd_bwd_peak="
        f"{_format(efficiency.get('training_peak_memory_mb'), 'MB')} | "
        f"actual_train_peak="
        f"{_format(efficiency.get('actual_training_peak_memory_mb'), 'MB')} | "
        f"process_peak_rss="
        f"{_format(efficiency.get('process_peak_rss_mb'), 'MB')}"
    )


# 等计算量对比：训练一步的 FLOPs 近似为 3×前向 FLOPs
# （前向 + 反向约等于 2 次前向）。该常数只用于把计算量换算成
# 「训练 FLOPs」的绝对量级，各运行共享同一常数，不改变共同
# 计算量点的位置。
_TRAIN_FLOPS_MULTIPLIER = 3.0

_COMPUTE_MATCHED_METRIC = "val_loss_at_matched_flops"

# 选型偏差的无偏对照：从周期验证曲线取共同训练步数处的即时
# 指标。``final`` 的 val 指标来自验证集选中的 checkpoint
# （best_val），同一批数据既选型又判定，最优值噪声会被当成
# 方法差异；周期验证点是「当时模型」的即时指标，不经过
# checkpoint 选择。与等计算量 loss 一样，它是分析期派生指标。
#
# 只给 loss 提供选型无关口径是不够的：类别不平衡时项目建议用
# macro F1 / PR-AUC 判定，假设也可能预注册 accuracy、precision
# 或 recall；这些指标同样会被 checkpoint 选择抬高。因此凡是
# 周期验证实际计算的 val 指标，都生成一份共同步数派生指标。
_COMMON_STEP_METRIC_SUFFIX = "_at_common_step"
_COMMON_STEP_CORE_BASE_METRICS: Tuple[str, ...] = (
    "val_loss",
    "val_ppl",
    "val_bits_per_byte",
    # 类平衡似然同样会被 checkpoint 选择抬高（选型指标若按
    # 频率加权 loss，稀有字节的表现不影响选型结果），因此
    # 也要有避开选型偏差的共同步数派生口径。
    "val_macro_nll",
    "val_token_accuracy",
    "val_micro_f1",
    "val_macro_f1",
    "val_weighted_f1",
    "val_precision_macro",
    "val_precision_weighted",
    "val_recall_macro",
    "val_recall_weighted",
)
# 排序指标（PR-AUC / lift / ROC-AUC）默认只在 final/test 计算；
# 显式选为选型指标或传 --periodic-auc 时，周期验证也会写出这些
# 键。它们同样需要避开 checkpoint 选型偏差的共同步数口径——
# 极度不平衡时项目建议以 PR-AUC 判定，若只有 final 版本，
# 判定指标恰恰是最容易被选型抬高、又没有选型无关复核的那个。
_COMMON_STEP_OPTIONAL_BASE_METRICS: Tuple[str, ...] = (
    "val_pr_auc_macro",
    "val_pr_auc_macro_lift",
    "val_roc_auc_macro",
)
_COMMON_STEP_BASE_METRICS: Tuple[str, ...] = (
    _COMMON_STEP_CORE_BASE_METRICS
    + _COMMON_STEP_OPTIONAL_BASE_METRICS
)
_COMMON_STEP_METRICS: Tuple[str, ...] = tuple(
    base + _COMMON_STEP_METRIC_SUFFIX
    for base in _COMMON_STEP_BASE_METRICS
)
_COMMON_STEP_METRIC = "val_loss_at_common_step"

# RQ1 里的「收敛速度」不能只由共同步数处的单点 loss 回答：
# 单点只描述某一时刻的质量，两个方法可以在该点相同、但整个
# 训练过程中的损失轨迹明显不同。这里新增一个分析期派生指标：
# 在共同的训练步数窗口上对周期验证曲线做梯形积分，再除以窗口
# 长度，得到「时均验证损失」（越低说明窗口内整体损失更低，
# 常与更早收敛一致，但不能单独分离速度与最终水平）。
#
# 它仍使用周期验证记录（不经过 checkpoint 选型），窗口起点取
# 各运行**第一个**周期验证步的最大值、终点取训练前固定的
# ``--common-step``（未固定时退回各运行最后验证步的最小值），
# 两端都在曲线范围内做线性插值，不做外推。窗口起点也是观测
# 端点：首段（0 到第一次验证）没有观测，不能凭空假设，因此
# 该指标回答的是「共同可观测窗口内谁的整体损失更低」，不是
# 从第 0 步开始的完整曲线面积。
_CURVE_MEAN_METRIC = "val_loss_curve_mean_to_common_step"
_CURVE_DERIVED_METRICS: Tuple[str, ...] = (
    _CURVE_MEAN_METRIC,
)


def _common_step_metric_name(base_metric: str) -> Optional[str]:
    """周期指标名 → 共同步数派生指标名；非周期指标返回 None。"""
    if base_metric not in _COMMON_STEP_BASE_METRICS:
        return None
    return base_metric + _COMMON_STEP_METRIC_SUFFIX


def _common_step_metric_base(metric: str) -> Optional[str]:
    """共同步数派生指标名 → 原始周期指标名。"""
    if not metric.endswith(_COMMON_STEP_METRIC_SUFFIX):
        return None
    base = metric[: -len(_COMMON_STEP_METRIC_SUFFIX)]
    return base if base in _COMMON_STEP_BASE_METRICS else None

# local_base 的第二轮为了与 A/B 对齐计算量，把 k1 个分支合并
# 成一次宽度 min(n_experts, k1*k2) 的路由；均衡损失约随路由
# 宽度线性增长，直接沿用会让「立即合并」臂的均衡强度高于
# 延迟合并臂。该常量记录本轮实现已把 local_base 第二轮的
# aux loss 折算回单分支宽度 k2，供均衡强度审计区分新旧运行。
_BALANCE_WIDTH_NORMALIZATION = (
    "local_base_second_round_scaled_to_k2"
)


def _is_deterministic_run(row: Dict[str, object]) -> bool:
    """
    该运行是否不使用随机性。

    统计基线 ngram 的计数、调参与固定窗口评估都是确定性的：
    换一个 --seed 重跑不会产生新的独立重复，只是同一估计的
    复制。把不同 seed 的 ngram 运行当成独立样本会虚增 n、
    把种子方差压成 0，甚至让检验出现假阳性。未来若有其他
    确定性基线，可在 config.json 写 deterministic=true。
    """
    if bool(row.get("deterministic")):
        return True
    return str(row.get("mode")) == "ngram"


def _finite_float(value: object) -> Optional[float]:
    """把数值/布尔以外的有限数值转成 float，否则返回 None。"""
    if isinstance(value, bool) or not isinstance(
        value, (int, float)
    ):
        return None
    try:
        numeric = float(value)
    except (OverflowError, TypeError, ValueError):
        # JSON 允许任意大整数；float(10**400) 会溢出。分析
        # 管线应把这种值当作不可用，而不是让整份报告崩溃。
        return None
    if not math.isfinite(numeric):
        return None
    return numeric


def _format_finite(
    value: object,
    spec: str = ".4f",
    scale: float = 1.0,
) -> str:
    """格式化有限数值用于终端展示；损坏/超范围值返回 "-"。

    报告里的数值可能来自手工编辑或旧版 JSON（含超出 float
    范围的整数与 NaN/Inf），单行坏记录不能中断整张对比表。
    """
    number = _finite_float(value)
    if number is None:
        return "-"
    scaled = number * scale
    if not math.isfinite(scaled):
        return "-"
    return format(scaled, spec)


def _nonnegative_int(value: object) -> int:
    """非负整数计数；bool/损坏值按 0 处理，供旧报告兼容。"""
    if isinstance(value, bool) or not isinstance(value, int):
        return 0
    return max(0, int(value))


def _as_dict(value: object) -> Dict[str, object]:
    """dict 原样返回；其余值（旧/损坏 config 字段）当空 dict。"""
    return value if isinstance(value, dict) else {}


def _path_is_dir(value: object) -> bool:
    """Path.is_dir 的容错版本：损坏/超长路径不能中断分析。

    ``Path.exists()/is_dir()`` 在文件名过长（ENAMETOOLONG）、
    权限或 IO 错误时会抛 OSError；来自手工编辑的 config 或
    命令行路径不应让整份对比/设计报告崩溃，按「不存在」处理。
    """
    try:
        return Path(value).is_dir()
    except (OSError, TypeError, ValueError):
        return False


def _path_exists(value: object) -> bool:
    """Path.exists 的容错版本；不可判定的路径按「不存在」处理。"""
    try:
        return Path(value).exists()
    except (OSError, TypeError, ValueError):
        return False


def _val_curve_points(
    run_dir: Path,
    flops_per_forward: float,
) -> List[Tuple[float, float]]:
    """
    从 metrics.jsonl 读出 (累计训练 FLOPs, val_loss) 验证曲线点。

    只使用周期验证记录（数值 step + 有限 val_loss）：final 记录
    是「验证集最优 checkpoint」的指标，不是该步的即时指标，把它
    混进曲线会让不同运行在相同计算量点比较时引入选型偏差。
    """
    points: Dict[float, float] = {}

    for record in read_metrics_records(
        run_dir / "metrics.jsonl"
    ):
        step = _finite_float(record.get("step"))
        loss = _finite_float(record.get("val_loss"))
        if step is None or step <= 0.0 or loss is None:
            continue
        # 实际推进过优化器的步数才是有效训练计算量：非有限
        # loss/梯度会跳过 optimizer.step，按 step 计算会虚增
        # 便宜/昂贵臂的累计 FLOPs。旧记录没有该字段时退回
        # step（并保留 note 说明口径）。
        optimizer_steps = _finite_float(
            record.get("optimizer_steps")
        )
        compute_steps = (
            optimizer_steps
            if optimizer_steps is not None
            and optimizer_steps >= 0.0
            else step
        )
        cumulative = (
            compute_steps
            * _TRAIN_FLOPS_MULTIPLIER
            * flops_per_forward
        )
        # 累计 FLOPs 也可能超出 float 范围（例如有限的前向
        # FLOPs 接近上限时再乘训练倍率/步数）。inf 作为曲线
        # 横坐标会让共同计算量变成 inf、比值变成 NaN，最终
        # 产出非法 JSON；这类点按不可用丢弃，而不是当作正常
        # 观测。
        if not math.isfinite(cumulative):
            continue
        # 同一步有多条验证记录（如 NaN 诊断附加记录）时保留
        # 最后一条；评估协议相同，值应一致。
        points[float(cumulative)] = loss

    return sorted(points.items())


def _val_step_curve_points(
    run_dir: Path,
    metric: str = "val_loss",
) -> List[Tuple[float, float]]:
    """
    从 metrics.jsonl 读出 (训练步数, 即时验证指标) 曲线点。

    与 ``_val_curve_points`` 相同，只使用周期验证记录；``final``
    记录是验证集最优 checkpoint 的指标，混入曲线会把选型偏差
    带进「共同步数」对照。同一步有多条记录时保留最后一条。
    ``metric`` 必须是周期验证实际写出的键；缺该键的记录跳过，
    不从其他指标换算，避免把不可得的口径伪装成观测。
    """
    points: Dict[float, float] = {}

    for record in read_metrics_records(
        run_dir / "metrics.jsonl"
    ):
        step = _finite_float(record.get("step"))
        value = _finite_float(record.get(metric))
        if step is None or step <= 0.0 or value is None:
            continue
        points[float(step)] = value

    return sorted(points.items())


def _interpolate_curve(
    points: List[Tuple[float, float]],
    x: float,
) -> Tuple[Optional[float], Optional[str]]:
    """
    在验证曲线上取 x 处的 loss：命中验证点则精确取值，
    否则在相邻两点间线性插值。x 落在曲线范围外时返回
    (None, 原因)，不静默外推。
    """
    if not points:
        return None, "没有周期验证曲线"
    if x < points[0][0] or x > points[-1][0]:
        return None, "共同计算量落在该运行的验证曲线范围之外"
    if x == points[0][0]:
        return points[0][1], "exact_eval_point"
    if x == points[-1][0]:
        return points[-1][1], "exact_eval_point"

    for index in range(1, len(points)):
        x_prev, y_prev = points[index - 1]
        x_next, y_next = points[index]
        if x <= x_next:
            if x == x_next:
                return y_next, "exact_eval_point"
            ratio = (x - x_prev) / (x_next - x_prev)
            direct = y_prev + ratio * (y_next - y_prev)
            if math.isfinite(direct):
                return direct, "linear_between_evals"
            # 两端一正一负且都接近 float 上限时，差值会先溢出；
            # 用两个已按比例缩放的端点相加，真实插值仍在范围内。
            scaled = (
                y_prev * (1.0 - ratio) + y_next * ratio
            )
            return (
                scaled if math.isfinite(scaled) else None,
                "linear_between_evals",
            )

    return None, "共同计算量落在该运行的验证曲线范围之外"


def annotate_compute_matched_metrics(
    rows: List[Dict[str, object]],
) -> Dict[str, object]:
    """
    为每个运行计算「等训练计算量」的验证 loss，并写回行级
    指标 ``val_loss_at_matched_flops``。

    动机：延迟合并 A/B 在分支创建后按 k1 倍分支执行后续计算，
    每训练步的 FLOPs 高于 smelt。只比较相同训练步数会把「机制
    收益」和「额外计算」混在一起；只报告效率倍率也不能回答
    「给基线同样的计算量，谁更好」。

    协议：
    - 每步训练 FLOPs ≈ _TRAIN_FLOPS_MULTIPLIER × 测量前向
      FLOPs（同一运行内的常数倍不改变曲线形状）；
    - 共同计算量取所有可比运行中「最后一个周期验证点累计
      FLOPs」的最小值——保证每个运行都在自己的验证曲线范围内
      有观测，不做外推；
    - 在共同计算量处对验证曲线做线性插值（命中验证点则精确
      取值），得到 val_loss_at_matched_flops；
    - 这是**分析期**派生指标，不用于训练期选型/早停；它直接
      进入 COMPARISON_METRIC_KEYS，可用于聚合、显著性检验与
      预注册主指标。

    没有效率测量（--skip-efficiency/旧运行）或没有周期验证
    曲线的运行不参与共同计算量，也不会被虚报指标；原因写入返回
    报告。统计基线 ngram 是查表模型，没有训练 FLOPs，同样排除。
    """
    report: Dict[str, object] = {
        "metric": _COMPUTE_MATCHED_METRIC,
        "train_flops_multiplier": _TRAIN_FLOPS_MULTIPLIER,
        "target_flops": None,
        "target_note": None,
        "runs": [],
        "excluded_runs": [],
        "advisories": [],
        "ok": False,
    }

    curves: Dict[int, List[Tuple[float, float]]] = {}
    for index, row in enumerate(rows):
        row.pop(_COMPUTE_MATCHED_METRIC, None)
        row.pop("matched_compute_target_flops", None)
        row.pop("matched_compute_ratio", None)

        # 数值失败运行已被聚合与检验排除，不能让它的（通常更
        # 早结束的）曲线决定共同计算量：否则所有正常运行都会
        # 被截断到故障运行的训练长度，结论不再代表完整对比。
        if row.get("numerical_status") == "failed":
            report["excluded_runs"].append({
                "run": row.get("run"),
                "reason": (
                    "数值失败运行已从聚合与检验排除，"
                    "不参与共同计算量"
                ),
            })
            continue

        flops = _finite_float(row.get("flops_per_forward"))
        if flops is None or flops <= 0.0:
            report["excluded_runs"].append({
                "run": row.get("run"),
                "reason": (
                    "缺少前向 FLOPs（旧运行或 "
                    "--skip-efficiency），无法换算训练计算量"
                ),
            })
            continue

        points = _val_curve_points(
            Path(str(row.get("path"))),
            flops,
        )
        if not points:
            report["excluded_runs"].append({
                "run": row.get("run"),
                "reason": (
                    "没有可用的周期验证曲线"
                    "（metrics.jsonl 缺数值 step + val_loss）"
                ),
            })
            continue
        curves[index] = points

    if not curves:
        report["advisories"].append(
            "没有任何运行同时具备前向 FLOPs 与周期验证曲线："
            "无法计算等训练计算量的 val_loss；请用未跳过"
            "效率测量的新版运行重跑"
        )
        return report

    target_flops = min(points[-1][0] for points in curves.values())
    report["target_flops"] = target_flops
    report["target_note"] = (
        "共同计算量 = 可比运行最后一个周期验证点累计训练 FLOPs "
        f"的最小值；训练 FLOPs≈{_TRAIN_FLOPS_MULTIPLIER:g}×"
        "前向 FLOPs；累计步数优先用 optimizer_steps（非有限"
        "跳步不计入），旧记录退回训练 step"
    )

    for index, points in curves.items():
        row = rows[index]
        value, method = _interpolate_curve(points, target_flops)
        if value is None:
            report["excluded_runs"].append({
                "run": row.get("run"),
                "reason": method,
            })
            continue

        row[_COMPUTE_MATCHED_METRIC] = value
        row["matched_compute_target_flops"] = target_flops
        row["matched_compute_ratio"] = (
            target_flops / points[-1][0]
            if points[-1][0] > 0.0
            else None
        )
        report["runs"].append({
            "run": row.get("run"),
            "mode": row.get("mode"),
            "seed": row.get("seed"),
            "value": value,
            "interpolation": method,
            "last_curve_flops": points[-1][0],
            "compute_ratio": row["matched_compute_ratio"],
        })

    if report["runs"]:
        report["ok"] = True
        # 便宜臂与昂贵臂在共同计算量处截断的程度不同：若最贵
        # 运行只能用到自身计算量的一小部分，说明比较点很早，
        # 结论只适用于该计算量点，不能外推到完整训练结束。
        ratios = [
            float(item["compute_ratio"])
            for item in report["runs"]
            if isinstance(item.get("compute_ratio"), (int, float))
            and not isinstance(item["compute_ratio"], bool)
        ]
        if ratios and min(ratios) < 0.5:
            report["advisories"].append(
                "等计算量点只覆盖最贵运行不到一半的训练计算量"
                f"（最小比例 {min(ratios):.1%}）：结论只适用于该"
                "计算量点，不能当作完整训练结束时的对比；如需完整"
                "计算量结论，请给便宜臂增加训练步数或增加昂贵臂"
                "前段评估密度"
            )
    else:
        report["advisories"].append(
            "没有运行能在共同计算量点提供验证 loss：无法做"
            "等计算量对比"
        )

    if report["excluded_runs"]:
        report["advisories"].append(
            "以下运行未参与等计算量对比（不虚报指标）: "
            + "; ".join(
                f"{item['run']}（{item['reason']}）"
                for item in report["excluded_runs"]
            )
        )

    return report


def annotate_common_step_metrics(
    rows: List[Dict[str, object]],
    target_step: Optional[float] = None,
) -> Dict[str, object]:
    """
    为每个运行计算「共同训练步数」处的即时验证指标，并写回
    行级派生指标 ``<metric>_at_common_step``。

    动机：``final`` 的 val 指标是验证集选中的最优 checkpoint
    的指标。同一批 val 数据既参与 checkpoint 选择/早停，又参与
    跨运行比较时，每个方法各自的「最优值」都会吸收一部分种子
    噪声（winner's curse）；噪声大的方法被高估得更多，显著性
    检验因此有偏。周期验证曲线记录的是各评估步当时的即时模型
    指标，不经过 checkpoint 选择，适合做方法对比的选型无关口径。

    协议：
    - 只使用周期验证记录（数值 step + 有限指标值），排除
      ``final``；
    - 共同步数以各运行最后一个周期验证步的最小值为准（以
      val_loss 曲线确定评估步，保证所有指标对齐同一点），
      保证每个运行都在自己的曲线范围内，不做外推；
    - 命中共有评估步则精确取值，否则在相邻评估点间线性插值；
    - 覆盖周期验证实际计算的全部 val 指标：loss / ppl / bpb /
      token accuracy / micro、macro、weighted F1 / precision /
      recall；若运行把 PR-AUC / lift / ROC-AUC 选为选型指标或
      显式传了 ``--periodic-auc``，周期记录里也会有这些排序
      指标，同样生成共同步数派生口径。没有任何运行写出某个
      排序指标时跳过该项，不把「没算」写成「缺失」。
      路由诊断只在最终评估计算，不能伪造共同步数口径；
    - 这是分析期派生指标，不用于训练期选型/早停；可直接作为
      ``--compare-metric`` 或预注册主指标。

    没有周期验证曲线的运行（旧运行或纯统计基线）不参与，也不会
    虚报指标；原因写入报告。
    """
    report: Dict[str, object] = {
        "metric": _COMMON_STEP_METRIC,
        "metrics": list(_COMMON_STEP_METRICS),
        "target_step": None,
        "target_note": None,
        "metric_reports": {},
        "runs": [],
        "excluded_runs": [],
        "advisories": [],
        "selection_bias_note": (
            "这些指标取自周期验证曲线，不经过验证集 checkpoint "
            "选择，因此避开了 best-checkpoint 的 winner's curse；"
            "但若共同步数由观察到的端点决定（默认 min-of-last），"
            "它仍是数据依赖的选择，不能称为无偏。预先固定 "
            "--common-step 后才是 selection-independent（在共同"
            "支持范围内）"
        ),
        "ok": False,
    }

    for row in rows:
        for metric in _COMMON_STEP_METRICS:
            row.pop(metric, None)
        row.pop("common_step_target_step", None)
        row.pop("common_step_ratio", None)

    failed_excluded: List[Dict[str, object]] = []
    loss_curves: Dict[int, List[Tuple[float, float]]] = {}
    for index, row in enumerate(rows):
        # 与 aggregate_runs 一致：数值失败运行不参与对比，不能
        # 用它的短曲线把共同步数拉到故障停止的位置。
        if row.get("numerical_status") == "failed":
            failed_excluded.append({
                "run": row.get("run"),
                "reason": (
                    "数值失败运行已从聚合与检验排除，"
                    "不参与共同步数"
                ),
            })
            continue
        points = _val_step_curve_points(
            Path(str(row.get("path")))
        )
        if not points:
            report["excluded_runs"].append({
                "run": row.get("run"),
                "reason": (
                    "没有可用的周期验证曲线"
                    "（metrics.jsonl 缺数值 step + val_loss）"
                ),
            })
            continue
        loss_curves[index] = points

    if not loss_curves:
        report["advisories"].append(
            "没有任何运行具备周期验证曲线：无法计算共同步数"
            "处的选型无关验证指标；请用未跳过周期验证的新版运行重跑"
        )
        return report

    if target_step is None:
        target_step = min(
            points[-1][0] for points in loss_curves.values()
        )
        target_step_rule = "min_last_validation_step"
        target_step_data_dependent = True
    else:
        # target_step 可能来自手工/旧记录或直接调用（如超大
        # JSON 整数），float() 会抛 OverflowError；非有限/非正
        # 步数也不能作为可观测的共同点。保留 float() 对数字
        # 字符串/布尔值的旧兼容性，只拒绝不可表示的值。
        try:
            target_value = float(target_step)
        except (TypeError, ValueError, OverflowError):
            target_value = None
        if (
            target_value is None
            or not math.isfinite(target_value)
            or target_value <= 0.0
        ):
            report["advisories"].append(
                "共同步数不是有限正数：无法计算共同步数处的"
                "选型无关验证指标"
            )
            return report
        target_step = target_value
        target_step_rule = "preregistered_fixed_step"
        target_step_data_dependent = False
    report["target_step"] = target_step
    report["target_step_rule"] = target_step_rule
    report["target_step_data_dependent"] = (
        target_step_data_dependent
    )
    report["target_note"] = (
        "共同步数 = "
        + (
            "训练前显式指定的固定步（--common-step）"
            if not target_step_data_dependent
            else "可比运行最后一个周期验证步的最小值"
        )
        + "；取各运行在该步的即时验证指标（不做外推）。"
        + (
            ""
            if not target_step_data_dependent
            else "该步由观察到的端点决定：早停/不等步数时与"
            "结果相关，不是选型无关口径；正式对比应预先固定 "
            "--common-step"
        )
    )

    metric_reports: Dict[str, Dict[str, object]] = {}
    for base_metric in _COMMON_STEP_BASE_METRICS:
        derived_metric = _common_step_metric_name(base_metric)
        if derived_metric is None:
            continue

        curves: Dict[int, List[Tuple[float, float]]] = {}
        metric_excluded: List[Dict[str, object]] = []
        for index, row in enumerate(rows):
            if row.get("numerical_status") == "failed":
                continue
            if base_metric == "val_loss":
                points = loss_curves.get(index)
            else:
                points = _val_step_curve_points(
                    Path(str(row.get("path"))),
                    base_metric,
                )
            if not points:
                metric_excluded.append({
                    "run": row.get("run"),
                    "reason": (
                        "没有可用的周期验证曲线"
                        f"（metrics.jsonl 缺数值 step + {base_metric}）"
                    ),
                })
                continue
            curves[index] = points

        # 排序指标是可选周期指标：本轮没有任何运行计算它们时
        # 直接跳过，不生成空报告，也不把「没算」混进
        # incomplete 告警。只要至少一个运行有记录，缺记录的
        # 运行仍会进入 excluded_runs 并如实披露。
        if (
            base_metric in _COMMON_STEP_OPTIONAL_BASE_METRICS
            and not curves
        ):
            continue

        metric_runs: List[Dict[str, object]] = []
        for index, points in curves.items():
            row = rows[index]
            value, method = _interpolate_curve(
                points,
                target_step,
            )
            if value is None:
                metric_excluded.append({
                    "run": row.get("run"),
                    "reason": method,
                })
                continue

            step_ratio = (
                target_step / points[-1][0]
                if points[-1][0] > 0.0
                else None
            )
            row[derived_metric] = value
            row["common_step_target_step"] = target_step
            row["common_step_ratio"] = step_ratio
            metric_runs.append({
                "run": row.get("run"),
                "mode": row.get("mode"),
                "seed": row.get("seed"),
                "value": value,
                "interpolation": method,
                "last_curve_step": points[-1][0],
                "step_ratio": step_ratio,
                "selected_model": row.get("selected_model"),
            })

        metric_reports[derived_metric] = {
            "base_metric": base_metric,
            "ok": bool(metric_runs),
            "runs": metric_runs,
            "excluded_runs": metric_excluded,
        }
        if base_metric == "val_loss":
            report["runs"] = metric_runs
            report["excluded_runs"] = metric_excluded

    report["metric_reports"] = metric_reports
    # val_loss 的 metric_excluded 会覆盖同名字段；显式并回数值
    # 失败运行，保证「为何未参与」在报告里始终可见。
    report["excluded_runs"] = (
        failed_excluded + list(report["excluded_runs"])
    )
    report["ok"] = bool(report["runs"])

    if report["runs"]:
        ratios = [
            float(item["step_ratio"])
            for item in report["runs"]
            if isinstance(item.get("step_ratio"), (int, float))
            and not isinstance(item["step_ratio"], bool)
        ]
        if ratios and min(ratios) < 0.5:
            report["advisories"].append(
                "共同步数只覆盖最长运行不到一半的训练步数"
                f"（最小比例 {min(ratios):.1%}）：该点代表较早的"
                "训练阶段，不能直接替代完整训练结束时的排序；"
                "如需完整训练结论，请统一各运行的验证步范围"
            )
    else:
        report["advisories"].append(
            "没有运行能在共同步数点提供验证 loss：无法做"
            "选型无关的即时验证对比"
        )

    if report["excluded_runs"]:
        report["advisories"].append(
            "以下运行未参与共同步数对比（不虚报指标）: "
            + "; ".join(
                f"{item['run']}（{item['reason']}）"
                for item in report["excluded_runs"]
            )
        )

    incomplete = [
        derived_metric
        for derived_metric, metric_report in metric_reports.items()
        if metric_report["excluded_runs"]
    ]
    if incomplete:
        report["advisories"].append(
            "以下共同步数指标未能覆盖全部运行（不虚报缺记录）: "
            + ", ".join(incomplete)
        )

    return report


def _curve_trapezoid_mean(
    points: List[Tuple[float, float]],
    start: float,
    end: float,
) -> Optional[Dict[str, object]]:
    """
    在 [start, end] 上对分段线性验证曲线做梯形积分并取均值。

    只对可观测窗口积分：起点/终点都通过相邻验证点线性插值，
    不把窗口外的点外推进来。用「每段权重×段内均值」而不是先
    求总面积再除以窗口长度，避免两个合法但极大的有限 loss
    在求和/相除时溢出；无法得到有限均值时返回 None，由调用方
    把运行标为缺失，而不是写入 ±inf。
    """
    if not points or not (
        math.isfinite(start)
        and math.isfinite(end)
        and end > start
    ):
        return None

    start_value, start_method = _interpolate_curve(points, start)
    end_value, end_method = _interpolate_curve(points, end)
    if start_value is None or end_value is None:
        return None

    breakpoints = [start]
    values = [start_value]
    for x, y in points:
        if start < x < end:
            breakpoints.append(x)
            values.append(y)
    breakpoints.append(end)
    values.append(end_value)

    window = end - start
    # 两端各自有限不代表差值有限：-1e308 到 1e308 的窗口
    # 宽度会溢出为 inf，此时 width/window 全是 0，会静默返回
    # 0.0 这种看似合法的损失。无法表示窗口就按缺失处理。
    if not math.isfinite(window) or window <= 0.0:
        return None
    terms: List[float] = []
    for index in range(1, len(breakpoints)):
        width = breakpoints[index] - breakpoints[index - 1]
        if not math.isfinite(width) or width < 0.0:
            return None
        # v1/2 + v2/2 避免先相加再除二造成的中间溢出。
        average = values[index - 1] / 2.0 + values[index] / 2.0
        fraction = width / window
        term = fraction * average
        if not math.isfinite(term):
            return None
        terms.append(term)

    try:
        mean = math.fsum(terms)
    except (OverflowError, ValueError):
        return None
    if not math.isfinite(mean):
        return None
    return {
        "mean": mean,
        "window_steps": window,
        "start_value": start_value,
        "end_value": end_value,
        "start_interpolation": start_method,
        "end_interpolation": end_method,
        "trapezoid_segments": len(terms),
    }


def annotate_curve_metrics(
    rows: List[Dict[str, object]],
    target_step: Optional[float] = None,
) -> Dict[str, object]:
    """
    为每个运行计算共同训练窗口内的「时均验证损失」。

    动机：RQ1 要比较「验证损失和收敛速度」，但
    ``val_loss_at_common_step`` 只是共同步数处的一个瞬时值：
    两条曲线可以在该点相同，前段轨迹却完全不同。这里把从
    第一个共同可观测验证步到共同终点的周期验证曲线做梯形
    积分，再除以窗口长度，得到不经过 checkpoint 选型的
    ``val_loss_curve_mean_to_common_step``（越低越好）。它直接
    回答「在相同训练预算的前半段，谁的整体损失更低」，可作为
    ``--compare-metric`` 或预注册主指标进入聚合与显著性检验。

    协议：
    - 只用周期验证记录中的有限 ``val_loss``，排除 ``final``；
    - 窗口起点 = 所有可比运行第一个验证步的最大值（首段
      0→第一次验证无观测，不外推）；
    - 窗口终点 = 训练前固定的 ``--common-step``；未给定时退回
      各运行最后验证步的最小值，并显式标记为数据依赖；
    - 端点落在两个验证点之间时线性插值，任何一端超出曲线
      范围都判为缺失，不裁剪、不外推；
    - 数值失败运行不参与，也不能用其短曲线缩短共同窗口；
    - 与共同步数单点指标一样，这是分析期派生指标，不用于
      训练期选型/早停。

    局限：时均损失同时受早期下降速度和最终水平影响，不能单独
    解释为「收敛速率」；必须与 ``val_loss_at_common_step`` /
    ``final`` 一起报告。窗口起点是观测端点，改变评估间隔会改变
    该指标，跨运行必须保持相同的验证调度。
    """
    report: Dict[str, object] = {
        "metric": _CURVE_MEAN_METRIC,
        "start_step": None,
        "end_step": None,
        "start_rule": "max_first_validation_step",
        "end_rule": None,
        "start_data_dependent": True,
        "end_data_dependent": None,
        "runs": [],
        "excluded_runs": [],
        "advisories": [],
        "ok": False,
    }

    curves: Dict[int, List[Tuple[float, float]]] = {}
    for index, row in enumerate(rows):
        for field in (
            _CURVE_MEAN_METRIC,
            "curve_mean_start_step",
            "curve_mean_end_step",
            "curve_mean_window_steps",
        ):
            row.pop(field, None)

        if row.get("numerical_status") == "failed":
            report["excluded_runs"].append({
                "run": row.get("run"),
                "reason": (
                    "数值失败运行已从聚合与检验排除，"
                    "不参与曲线时均指标"
                ),
            })
            continue
        points = _val_step_curve_points(
            Path(str(row.get("path")))
        )
        if not points:
            report["excluded_runs"].append({
                "run": row.get("run"),
                "reason": (
                    "没有可用的周期验证曲线"
                    "（metrics.jsonl 缺数值 step + val_loss）"
                ),
            })
            continue
        curves[index] = points

    if not curves:
        report["advisories"].append(
            "没有任何运行具备周期验证曲线：无法计算共同窗口内"
            "的时均验证损失；请用未跳过周期验证的新版运行重跑"
        )
        return report

    start_step = max(points[0][0] for points in curves.values())
    if target_step is None:
        end_step = min(
            points[-1][0] for points in curves.values()
        )
        end_rule = "min_last_validation_step"
        end_data_dependent = True
    else:
        end_value = _finite_float(target_step)
        if end_value is None or end_value <= 0.0:
            report["advisories"].append(
                "共同终点不是正有限数：无法定义曲线时均指标"
            )
            return report
        end_step = end_value
        end_rule = "preregistered_fixed_step"
        end_data_dependent = False

    report["start_step"] = start_step
    report["end_step"] = end_step
    report["end_rule"] = end_rule
    report["end_data_dependent"] = end_data_dependent
    if end_step <= start_step:
        report["advisories"].append(
            "共同窗口为空（终点不晚于各运行第一个共同验证步）："
            "无法计算时均验证损失；请增大 --common-step 或"
            "延长训练/提高验证密度"
        )
        return report

    for index, points in curves.items():
        row = rows[index]
        result = _curve_trapezoid_mean(
            points, start_step, end_step
        )
        if result is None:
            report["excluded_runs"].append({
                "run": row.get("run"),
                "reason": (
                    "验证曲线不覆盖共同窗口 "
                    f"[{start_step:g}, {end_step:g}]，"
                    "不裁剪也不外推"
                ),
            })
            continue

        row[_CURVE_MEAN_METRIC] = result["mean"]
        row["curve_mean_start_step"] = start_step
        row["curve_mean_end_step"] = end_step
        row["curve_mean_window_steps"] = result[
            "window_steps"
        ]
        span = points[-1][0] - points[0][0]
        curve_coverage = (
            result["window_steps"] / span
            if span > 0.0
            else None
        )
        if (
            curve_coverage is not None
            and not math.isfinite(curve_coverage)
        ):
            curve_coverage = None
        report["runs"].append({
            "run": row.get("run"),
            "mode": row.get("mode"),
            "seed": row.get("seed"),
            "value": result["mean"],
            "start_step": start_step,
            "end_step": end_step,
            "window_steps": result["window_steps"],
            "start_value": result["start_value"],
            "end_value": result["end_value"],
            "start_interpolation": result[
                "start_interpolation"
            ],
            "end_interpolation": result["end_interpolation"],
            "trapezoid_segments": result[
                "trapezoid_segments"
            ],
            "curve_coverage": curve_coverage,
            "selected_model": row.get("selected_model"),
        })

    report["ok"] = bool(report["runs"])
    coverages = [
        float(item["curve_coverage"])
        for item in report["runs"]
        if isinstance(item.get("curve_coverage"), (int, float))
        and not isinstance(item["curve_coverage"], bool)
    ]
    if coverages and min(coverages) < 0.5:
        report["advisories"].append(
            "共同窗口只覆盖某个运行不到一半的验证曲线"
            f"（最小比例 {min(coverages):.1%}）：结论只适用于该"
            "窗口，不能当作完整训练过程/最终收敛水平的替代"
        )
    if not report["runs"]:
        report["advisories"].append(
            "没有运行能在共同窗口内提供验证 loss：无法做曲线"
            "时均对比"
        )
    if report["excluded_runs"]:
        report["advisories"].append(
            "以下运行未参与曲线时均对比（不虚报指标）: "
            + "; ".join(
                f"{item['run']}（{item['reason']}）"
                for item in report["excluded_runs"]
            )
        )
    if end_data_dependent:
        report["advisories"].append(
            "共同终点取各运行最后验证步的最小值，由观察到的"
            "端点决定（早停/不等步数时与结果相关）；正式对比"
            "应在训练前固定 --common-step"
        )
    return report


def selection_bias_report(
    rows: List[Dict[str, object]],
    metric: str,
    common_step: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """
    审计跨运行判定指标是否来自验证集选中的 checkpoint。

    ``final`` 的 val 指标在训练结束后由 ``best.pt`` 重新评估，
    而 ``best.pt`` 正是按同一验证集指标（默认 val_loss）选出的。
    同一批数据既用于选型又用于判定时，点估计和显著性检验都会
    带乐观偏差，且偏差大小随各运行的种子噪声变化。报告必须
    点名这一风险，并给出可执行的选型无关口径（共同步数指标）。

    只把明确记录为 ``selected_model=best_val`` 的运行计入
    ``biased_runs``；旧运行缺选型记录时列入 unknown，不虚报。
    """
    report: Dict[str, object] = {
        "metric": metric,
        "applicable": metric in _SELECTION_BIASED_METRICS,
        "biased_runs": [],
        "eligible_runs": 0,
        "failed_runs_excluded": [],
        "last_step_runs": [],
        "unknown_selection_runs": [],
        "unbiased_metric": None,
        "unbiased_runs": 0,
        "available_unbiased_metrics": [],
        "advisory": None,
        # 选型机会：每个 best_val 运行参与「取最优」的验证点数。
        # 验证点越多，抽到极端低点的机会越多，best_val 的乐观
        # 偏差也越大；不同运行数量不等时，选型偏差本身在组间
        # 不可比。
        "selection_opportunities": [],
        "missing_selection_opportunity_runs": [],
        "opportunity_imbalance": None,
        "opportunity_advisory": None,
    }

    if not report["applicable"]:
        return report

    # 分母只统计真正参与选型判定的非确定性、非数值失败运行：
    # ngram 等确定性基线不做 checkpoint 选型；数值失败运行的
    # final 指标可能来自 fallback checkpoint，已被排除出聚合与
    # 检验。把两者算进分母都会稀释偏差比例，让「多少运行的
    # 指标来自选型后的验证集」被低估。
    eligible_runs = 0
    for row in rows:
        if _is_deterministic_run(row):
            continue
        if row.get("numerical_status") == "failed":
            report["failed_runs_excluded"].append(
                str(row.get("run"))
            )
            continue
        eligible_runs += 1
        name = str(row.get("run"))
        selected = row.get("selected_model")
        if selected == "best_val":
            report["biased_runs"].append({
                "run": name,
                "selection_metric": row.get("selection_metric"),
                "selected_step": row.get("end_step"),
                "trained_steps": row.get("trained_steps"),
                "n_eval_points": row.get("curve_n_eval_points"),
            })
        elif selected == "last":
            report["last_step_runs"].append(name)
        else:
            report["unknown_selection_runs"].append(name)

    report["eligible_runs"] = eligible_runs

    # best_val 是「在 T 个验证点里取最小」：T 越大，极值噪声
    # 带来的乐观偏差越大。跨运行比较时若各运行的 T 不同，
    # 偏差幅度也不同，必须把 T 一并披露。
    opportunities = []
    missing_opportunities: List[str] = []
    for entry in report["biased_runs"]:
        value = entry.get("n_eval_points")
        if (
            isinstance(value, int)
            and not isinstance(value, bool)
            and value > 0
        ):
            opportunities.append({
                "run": entry["run"],
                "n_eval_points": int(value),
            })
        else:
            missing_opportunities.append(str(entry["run"]))
    report["selection_opportunities"] = opportunities
    report["missing_selection_opportunity_runs"] = (
        missing_opportunities
    )
    if len(opportunities) >= 2:
        counts = [
            entry["n_eval_points"] for entry in opportunities
        ]
        low = min(counts)
        high = max(counts)
        if high > low:
            try:
                # 直接做整数真除法：两个超大但同量级的计数
                # 仍可能给出可表示的倍率，只有倍率本身越过
                # float 上限时才省略。
                ratio = high / low if low > 0 else None
            except (OverflowError, ValueError):
                ratio = None
            if ratio is not None and not math.isfinite(ratio):
                ratio = None
            report["opportunity_imbalance"] = {
                "min_eval_points": low,
                "max_eval_points": high,
                "ratio": ratio,
                "runs": opportunities,
            }
            report["opportunity_advisory"] = (
                "best_val 运行参与选型的验证点数不同（"
                f"{low}~{high}"
                + (
                    f"，最多相差 {ratio:.2f}×"
                    if ratio is not None
                    else ""
                )
                + "）：验证点更多的运行有更多机会抽到低点，"
                "选型乐观偏差也更大，且该偏差在组间不可比；"
                "请用共同步数指标复核方法差异"
            )
    elif report["biased_runs"] and not opportunities:
        report["opportunity_advisory"] = (
            "best_val 运行缺少验证点数量记录"
            "（curve_n_eval_points，旧运行）：无法核对各运行"
            "的选型机会是否相同"
        )
    if missing_opportunities and opportunities:
        partial_note = (
            "选型机会无法完整核对：以下 best_val 运行缺少"
            "验证点数量记录（curve_n_eval_points，旧运行）: "
            + ", ".join(missing_opportunities)
        )
        report["opportunity_advisory"] = (
            (
                str(report["opportunity_advisory"]) + "；"
                if report["opportunity_advisory"]
                else ""
            )
            + partial_note
        )

    metric_reports = (
        _as_dict(common_step).get("metric_reports")
        if common_step is not None
        else None
    )
    metric_reports = _as_dict(metric_reports)
    report["available_unbiased_metrics"] = sorted(
        derived_metric
        for derived_metric, metric_report in metric_reports.items()
        if _as_dict(metric_report).get("ok")
    )
    unbiased_metric = _common_step_metric_name(metric)
    if unbiased_metric is not None:
        unbiased_report = _as_dict(
            metric_reports.get(unbiased_metric)
        )
        if unbiased_report.get("ok"):
            report["unbiased_metric"] = unbiased_metric
            report["unbiased_runs"] = len(
                unbiased_report.get("runs", [])
            )

    if report["biased_runs"]:
        detail = (
            f"{len(report['biased_runs'])}/{eligible_runs} 个运行的"
            f" {metric} 来自验证集选中的 checkpoint（best_val）"
        )
        if report["unbiased_metric"]:
            detail += (
                "；同一验证集既选型又判定，存在乐观偏差。"
                f"选型无关复核请用 --compare-metric "
                f"{report['unbiased_metric']}（覆盖 "
                f"{report['unbiased_runs']} 个运行）"
            )
        else:
            detail += (
                "；同一验证集既选型又判定，存在乐观偏差。"
                "该指标没有曲线派生版本，跨运行结论只能作为"
                "描述性证据，正式结论应在独立评估集/固定步数"
                "口径上复核"
            )
        report["advisory"] = detail

    return report


def numerical_failure_report(
    rows: List[Dict[str, object]],
) -> Dict[str, object]:
    """
    跨运行暴露数值失败状态，并说明其不进入聚合/检验。

    一个训练到 NaN/Inf 或触发数值停止的运行，其最终 val 指标
    可能来自 fallback checkpoint，甚至已被跳过；把它与正常
    运行一起求均值/做 t 检验，相当于把故障当成方法效应。
    """
    failed = [
        {
            "run": str(row.get("run")),
            "mode": row.get("mode"),
            "seed": row.get("seed"),
            "curve_status": row.get("curve_status"),
            "nonfinite_events": row.get("nonfinite_events"),
            "numerical_stop": row.get("numerical_stop"),
            "numerical_polluted": row.get(
                "numerical_polluted"
            ),
            "prior_numerical_stop": row.get(
                "prior_numerical_stop"
            ),
        }
        for row in rows
        if row.get("numerical_status") == "failed"
    ]
    unknown = [
        str(row.get("run"))
        for row in rows
        if row.get("numerical_status") == "unknown"
    ]
    mode_counts: Dict[str, Dict[str, object]] = {}
    for row in rows:
        mode = str(row.get("mode"))
        entry = mode_counts.setdefault(mode, {
            "mode": mode,
            "attempted_runs": 0,
            "failed_runs": 0,
            "failed_run_names": [],
        })
        entry["attempted_runs"] = (
            int(entry["attempted_runs"]) + 1
        )
        if row.get("numerical_status") == "failed":
            entry["failed_runs"] = (
                int(entry["failed_runs"]) + 1
            )
            entry["failed_run_names"].append(
                str(row.get("run"))
            )
    by_mode: List[Dict[str, object]] = []
    for mode in sorted(mode_counts):
        entry = mode_counts[mode]
        attempted = int(entry["attempted_runs"])
        entry["failure_rate"] = (
            float(entry["failed_runs"]) / float(attempted)
            if attempted > 0
            else None
        )
        by_mode.append(entry)
    failure_rates = {
        float(entry["failure_rate"])
        for entry in by_mode
        if entry.get("failure_rate") is not None
    }
    imbalanced = (
        any(rate > 0.0 for rate in failure_rates)
        and len(failure_rates) > 1
    )

    report: Dict[str, object] = {
        "failed": failed,
        "excluded_run_count": len(failed),
        "unknown": unknown,
        "by_mode": by_mode,
        "mode_failure_rates_imbalanced": imbalanced,
        "advisory": None,
    }
    if failed:
        message = (
            f"{len(failed)} 个运行存在 NaN/Inf、数值停止、污染"
            "检查点续跑或 diverged 曲线：已从聚合与显著性检验中"
            "排除；请修复数值问题或从干净检查点重跑后再比较"
        )
        if imbalanced:
            message += (
                "。各 mode 的失败率不同（"
                + "; ".join(
                    f"{entry['mode']}={entry['failed_runs']}/"
                    f"{entry['attempted_runs']}"
                    for entry in by_mode
                )
                + "）：剔除失败运行后比较的是幸存者，"
                "失败率本身可能是方法稳定性差异，不能把幸存"
                "运行的优势归因到方法"
            )
        else:
            message += (
                "。注意：失败运行不是方法效果，但若某臂的失败"
                "率更高，仍属于方法稳定性差异，不能只看幸存"
                "运行的均值"
            )
        report["advisory"] = message
    return report


def failure_rate_report(
    rows: List[Dict[str, object]],
) -> Dict[str, object]:
    """
    按实验臂报告数值失败率与成功条件性能（防止幸存者偏差）。

    只比较成功运行会系统性掩盖「某个方法更容易数值失败」的
    稳定性成本。这里把「计划运行」（实际启动的运行目录数）
    作为分母，分别给出失败数、失败率、未知数，并在臂间失败
    率差超过阈值时点名 ``differential_failure``。失败运行仍
    不进入均值/检验（否则故障会被当成效应），但必须与失败率
    一起报告；成功条件下的指标已经由聚合表给出。

    重试规则：本仓库不自动重试。用同一个 seed 重跑成功路径会
    产生伪重复（独立种子数不增加）；失败后应换新 seed 或修复
    数值问题后整批重跑，并在报告中保留失败目录。
    """
    groups: Dict[str, Dict[str, object]] = {}
    for row in rows:
        mode = str(row.get("mode") or "unknown")
        arm = groups.setdefault(
            mode,
            {
                "mode": mode,
                "planned_runs": 0,
                "observed_runs": 0,
                "failed_runs": 0,
                "unknown_runs": 0,
                "failed_run_names": [],
                "success_runs": 0,
            },
        )
        arm["planned_runs"] = int(arm["planned_runs"]) + 1
        status = row.get("numerical_status")
        if status == "failed":
            arm["failed_runs"] = int(arm["failed_runs"]) + 1
            arm["failed_run_names"].append(str(row.get("run")))
        elif status == "unknown":
            arm["unknown_runs"] = int(arm["unknown_runs"]) + 1
        else:
            arm["success_runs"] = int(arm["success_runs"]) + 1
        arm["observed_runs"] = int(arm["planned_runs"]) - int(
            arm["failed_runs"]
        )

    arms = list(groups.values())
    for arm in arms:
        planned = int(arm["planned_runs"])
        failed = int(arm["failed_runs"])
        arm["failure_rate"] = (
            failed / planned if planned > 0 else None
        )

    rates = [
        (str(arm["mode"]), float(arm["failure_rate"]))
        for arm in arms
        if arm["failure_rate"] is not None
    ]
    differential = None
    if len(rates) >= 2:
        worst = max(rates, key=lambda item: item[1])
        best = min(rates, key=lambda item: item[1])
        if worst[1] - best[1] > 0.10:
            differential = {
                "worst_mode": worst[0],
                "worst_rate": worst[1],
                "best_mode": best[0],
                "best_rate": best[1],
                "gap": worst[1] - best[1],
                "note": (
                    "各臂失败率差异超过 10 个百分点：只比较成功"
                    "运行会掩盖失败率更高的方法的稳定性成本；"
                    "该方法的性能结论必须以「失败率 + 成功条件"
                    "指标」成对报告"
                ),
            }

    return {
        "arms": arms,
        "differential_failure": differential,
        "retry_policy": (
            "不自动重试；同一 seed 重跑成功路径属于伪重复，"
            "不增加独立种子数。失败后换新 seed 或修复数值问题"
            "后整批重跑，并保留失败目录"
        ),
        "note": (
            "planned_runs 为实际启动的运行目录数；失败运行不"
            "进入均值/检验，但失败率必须与成功条件指标一起"
            "报告"
        ),
    }


# 曲线诊断中可跨运行比较的数值字段（来自 metrics.jsonl 的
# curve_analysis 记录）。status 之外还必须带出这些量：只看
# 最终 val_loss 会把「训练更久/选型更晚」误当成方法更好，
# 而回归幅度、泛化 gap 与最优点位置才能说明收益是否来自
# 泛化改善还是过拟合前的短暂低点。
# 坏案例记录中可跨运行汇总的字段（metrics.jsonl 的
# ``step="bad_cases", split="val"``）。错误类别按错误 token
# 加权汇总，混淆对只覆盖各运行落盘的 top-10。
_BAD_CASE_ROW_FIELDS: Tuple[str, ...] = (
    "tokens_evaluated",
    "wrong_tokens",
    "token_accuracy",
    "error_category_counts",
    "error_category_shares",
    "top_confusions",
    "error_rate_by_position",
    "error_rate_by_train_frequency",
    "error_frequency_basis",
    "calibration",
    "label_noise_verification",
)

_CURVE_ROW_FIELDS: Tuple[str, ...] = (
    "best_val_step",
    "best_val_loss",
    "val_regression_from_best",
    "generalization_gap_ratio_last",
    "generalization_gap_trend",
    "recent_train_drop",
    "recent_val_drop",
    "last_lr_over_peak",
    "grad_norm_spike_ratio",
    "gap_widening_warning",
    "finite_diverging",
    "n_eval_points",
    "n_nonfinite_events",
)


def curve_diagnostics_report(
    rows: List[Dict[str, object]],
) -> Dict[str, object]:
    """
    汇总各运行的训练曲线数值诊断，供跨运行比较。

    ``status`` 是离散结论，无法回答「过拟合多严重」「最优点
    有多早」；这里保留每个运行的回归幅度、泛化 gap、近期
    训练/验证变化与梯度尖峰倍率。只读取已落盘的
    ``curve_analysis`` 记录，不重新训练、不改变任何选型。
    """
    runs = [
        {
            "run": str(row.get("run")),
            "mode": row.get("mode"),
            "seed": row.get("seed"),
            "status": row.get("curve_status"),
            **{
                key: _json_safe(row.get(f"curve_{key}"))
                for key in _CURVE_ROW_FIELDS
            },
        }
        for row in rows
        if row.get("curve_available")
    ]
    overfit_runs = [
        entry["run"]
        for entry in runs
        if entry.get("status") == "overfitting"
    ]
    return {
        "runs": runs,
        "n_runs_with_curve": len(runs),
        "overfitting_runs": overfit_runs,
        "note": (
            "best@ 是验证损失最优点；regr 是最终相对最优的"
            "回升幅度；gap 是最终 (val-train)/val。regr 大且"
            "best@ 早说明过拟合严重，不能只看最终 val_loss。"
        ),
    }


def bad_case_comparison_report(
    rows: List[Dict[str, object]],
) -> Dict[str, object]:
    """
    跨运行汇总坏案例的错误模式。

    单个运行的 top-N 案例可能只是偶然困难样本；真正值得据此
    改模型的证据是「多个种子/模式重复出现」的错误类别与混淆
    对。这里按错误 token 数加权汇总全量归因，并统计每个
    混淆对出现在多少个运行里。

    注意各运行只落盘 top-10 混淆对，合计计数是这些 top 对的
    求和，不是全量混淆矩阵；报告必须保留该覆盖上限，避免把
    「top 对里常见」误读成「全量里常见」。
    """
    available = [
        row for row in rows if row.get("bad_case_available")
    ]
    if not available:
        return {
            "n_runs_with_bad_cases": 0,
            "runs": [],
            "note": "没有运行带坏案例记录。",
        }

    category_names = list(_BAD_CASE_CATEGORIES)
    category_counts = {name: 0 for name in category_names}
    category_share_by_run: Dict[str, List[float]] = {
        name: [] for name in category_names
    }
    total_tokens = 0
    total_wrong = 0
    pair_totals: Dict[Tuple[int, int], int] = {}
    pair_run_counts: Dict[Tuple[int, int], int] = {}
    position_totals: Dict[str, List[int]] = {}
    frequency_totals: Dict[str, List[int]] = {}
    frequency_bases = set()
    runs = []

    def _safe_count(value: object) -> int:
        """把来自旧/损坏记录的计数转成非负整数，坏值按 0。

        bad_cases 记录是 metrics.jsonl 中的普通 JSON；手工编辑、
        旧版本或崩溃留下的半条记录可能把计数字段写成 NaN/
        Infinity/字符串/列表。对比报告必须跳过这些值而不是让
        整份 `--compare` 抛 ValueError/TypeError。
        """
        number = _finite_float(value)
        if number is None or number < 0.0:
            return 0
        return int(number)

    for row in available:
        tokens = _safe_count(
            row.get("bad_case_tokens_evaluated")
        )
        wrong = _safe_count(
            row.get("bad_case_wrong_tokens")
        )
        total_tokens += tokens
        total_wrong += wrong
        counts = _as_dict(
            row.get("bad_case_error_category_counts")
        )
        shares = _as_dict(
            row.get("bad_case_error_category_shares")
        )
        for name in category_names:
            count = _safe_count(counts.get(name))
            category_counts[name] += count
            share = _finite_float(shares.get(name))
            if share is not None:
                category_share_by_run[name].append(share)

        raw_pairs = row.get("bad_case_top_confusions")
        pairs = (
            raw_pairs
            if isinstance(raw_pairs, (list, tuple))
            else []
        )
        seen_pairs = set()
        valid_pairs = []
        for pair in pairs:
            if not isinstance(pair, (list, tuple)) or len(pair) < 3:
                continue
            target, predicted, count = pair[:3]
            if not all(
                isinstance(value, int)
                and not isinstance(value, bool)
                for value in (target, predicted, count)
            ):
                continue
            if target < 0 or predicted < 0 or count <= 0:
                continue
            key = (int(target), int(predicted))
            pair_totals[key] = pair_totals.get(key, 0) + int(count)
            seen_pairs.add(key)
            valid_pairs.append([target, predicted, count])
        for key in seen_pairs:
            pair_run_counts[key] = pair_run_counts.get(key, 0) + 1

        for field, sink in (
            ("bad_case_error_rate_by_position", position_totals),
            (
                "bad_case_error_rate_by_train_frequency",
                frequency_totals,
            ),
        ):
            raw_entries = row.get(field)
            entries = (
                raw_entries
                if isinstance(raw_entries, (list, tuple))
                else []
            )
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                name = entry.get("name")
                if name is None:
                    continue
                bucket = sink.setdefault(str(name), [0, 0])
                bucket[0] += _safe_count(entry.get("tokens"))
                bucket[1] += _safe_count(entry.get("wrong"))
        basis = row.get("bad_case_error_frequency_basis")
        if basis is not None:
            frequency_bases.add(str(basis))

        runs.append({
            "run": str(row.get("run")),
            "mode": row.get("mode"),
            "seed": row.get("seed"),
            "tokens_evaluated": tokens,
            "wrong_tokens": wrong,
            "token_accuracy": _finite_float(
                row.get("bad_case_token_accuracy")
            ),
            "error_category_counts": {
                name: _safe_count(counts.get(name))
                for name in category_names
            },
            # 旧/损坏记录的占比可能是 NaN/Inf/超范围整数；
            # 不能把这些值原样写进报告。
            "error_category_shares": {
                name: _finite_float(shares.get(name))
                for name in category_names
            },
            "top_confusion": (
                valid_pairs[0] if valid_pairs else None
            ),
        })

    category_shares: Dict[str, Optional[float]] = {}
    for name, count in category_counts.items():
        share = None
        if total_wrong > 0:
            try:
                ratio = count / total_wrong
            except OverflowError:
                # 损坏记录可能让单类计数远大于错误总数；真除法
                # 越过 float 上限时按缺失处理，而不是中断报告。
                ratio = None
            if ratio is not None and math.isfinite(ratio):
                share = round(ratio, 6)
        category_shares[name] = share
    n_runs = len(available)
    min_pair_runs = (
        1 if n_runs == 1 else max(2, (n_runs + 1) // 2)
    )
    persistent_pairs = [
        {
            "target": target,
            "predicted": predicted,
            # 同一运行只计一次，避免单个运行的重复计数
            # 把它伪装成跨运行稳定模式。
            "runs_present": pair_run_counts.get(
                (target, predicted), 0
            ),
            "top_count_sum": count,
        }
        for (target, predicted), count in sorted(
            pair_totals.items(),
            key=lambda item: (-item[1], item[0]),
        )
        if pair_run_counts.get((target, predicted), 0)
        >= min_pair_runs
    ][:10]

    def _stratified_summary(
        buckets: Dict[str, List[int]],
    ) -> List[Dict[str, object]]:
        rows_out = []
        for name, (tokens, wrong) in buckets.items():
            error_rate = None
            if tokens > 0:
                try:
                    ratio = wrong / tokens
                except OverflowError:
                    # 损坏记录可能让 wrong 远大于 tokens；无法
                    # 表示的错误率按缺失处理。
                    ratio = None
                if ratio is not None and math.isfinite(ratio):
                    error_rate = round(ratio, 6)
            rows_out.append({
                "name": name,
                "tokens": tokens,
                "wrong": wrong,
                "error_rate": error_rate,
            })
        return rows_out

    category_share_ranges = {}
    unstable_categories = []
    if n_runs >= 2:
        for name, values in category_share_by_run.items():
            if len(values) < 2:
                continue
            spread = max(values) - min(values)
            if math.isfinite(spread):
                category_share_ranges[name] = round(spread, 6)
                if spread >= 0.20:
                    unstable_categories.append(name)
            else:
                # 正负极大占比相减会溢出；没有可表示的极差。
                category_share_ranges[name] = None

    return {
        "n_runs_with_bad_cases": n_runs,
        "runs": runs,
        "tokens_evaluated": total_tokens,
        "wrong_tokens": total_wrong,
        "error_category_counts": category_counts,
        "error_category_shares": category_shares,
        "persistent_confusions": persistent_pairs,
        "persistent_confusion_min_runs": min_pair_runs,
        "error_rate_by_position": _stratified_summary(
            position_totals
        ),
        "error_rate_by_train_frequency": (
            _stratified_summary(frequency_totals)
            if len(frequency_bases) <= 1
            else []
        ),
        "category_share_ranges": category_share_ranges,
        "unstable_categories": unstable_categories,
        "coverage_note": (
            "混淆对只来自各运行落盘的 top-10 对，"
            "合计计数不是全量混淆矩阵；全量错误类别按错误"
            " token 加权汇总。"
        ),
        "note": (
            "跨运行重复出现的错误类别/混淆对才是稳定的改进"
            "线索；类别占比跨运行极差 ≥20pp 时说明失败模式"
            "主要由种子/运行差异驱动，不能当作单一方法缺陷。"
        ),
    }


def compare_runs(paths: List[str]) -> List[Dict[str, object]]:
    """
    汇总多个运行目录的 config 与最终指标。

    读取每个目录的 config.json（结构、参数量、efficiency）与
    metrics.jsonl（final/curve_analysis），输出统一口径的行。

    只汇总 val 口径指标：test 只在单个运行内解封评估一次，
    不进入跨运行对比（否则会诱发「挑 test 最好」的隐式
    测试集调参）。
    """
    rows: List[Dict[str, object]] = []

    for path in paths:
        run_dir = Path(path)
        row: Dict[str, object] = {
            "run": run_dir.name,
            "path": str(run_dir),
        }

        config_payload: Dict[str, object] = {}
        config_path = run_dir / "config.json"
        try:
            config_exists = config_path.exists()
        except OSError:
            config_exists = False
        if config_exists:
            try:
                with open(
                    config_path,
                    encoding="utf-8",
                ) as f:
                    loaded = json.load(f)
                if isinstance(loaded, dict):
                    config_payload = loaded
            except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                config_payload = {}

        # 逐窗口评估记录（eval_windows.json）：固定评估窗口在所有
        # 运行之间逐位相同，跨运行比较可以按窗口配对，给出
        # 「在这批固定评估窗口上」的配对证据。缺失（旧运行）时
        # 保持 None，窗口级分析整体跳过而不是静默当成没有差异。
        windows_path = run_dir / "eval_windows.json"
        try:
            windows_exists = windows_path.exists()
        except OSError:
            windows_exists = False
        if windows_exists:
            try:
                with open(
                    windows_path,
                    encoding="utf-8",
                ) as f:
                    loaded_windows = json.load(f)
                if isinstance(loaded_windows, dict):
                    row["eval_windows"] = loaded_windows
            except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                row["eval_windows"] = None

        # 确定性标记：ngram 统计基线换 seed 不会产生新的独立
        # 重复；聚合与检验必须据此折叠，而不是把复制运行当
        # 独立种子。
        row["deterministic"] = bool(
            config_payload.get("deterministic")
        )

        run_config = config_payload.get("config") or {}
        if isinstance(run_config, dict):
            row["mode"] = run_config.get("mode")
            row["ngram_tuning_metric"] = run_config.get(
                "ngram_tuning_metric"
            )
            row["ngram_tuning"] = run_config.get(
                "ngram_tuning"
            )
            row["top_k"] = run_config.get("top_k")
            row["k1"] = run_config.get("k1")
            row["k2"] = run_config.get("k2")
            row["balance_coef"] = run_config.get("balance_coef")
            row["dense_fnn_hidden"] = run_config.get(
                "dense_fnn_hidden"
            )
            row["n_experts"] = run_config.get("n_experts")
            row["expert_hidden"] = run_config.get(
                "expert_hidden"
            )

        run_args = config_payload.get("args") or {}
        if isinstance(run_args, dict):
            row["seed"] = run_args.get("seed")
            # 选型指标：旧运行没有该字段，历史行为是在
            # val_loss 上选 checkpoint；ngram 不训练，保持
            # None，不参与选型一致性检查。
            if str(row.get("mode")) == "ngram":
                row["selection_metric"] = None
            else:
                row["selection_metric"] = (
                    run_args.get("selection_metric") or "val_loss"
                )

        # 假设纪律：对比分析要能展示每个运行登记的科学假设，
        # 并把缺失假设（旧运行或显式跳过）单独标记出来，避免
        # 把「排列组合超参数」当成假设驱动的实验。
        row["hypothesis"] = config_payload.get("hypothesis")
        row["research_question"] = config_payload.get(
            "research_question"
        )
        row["hypothesis_check_skipped"] = bool(
            config_payload.get("hypothesis_check_skipped")
        )

        # 预注册的假设参数（--primary-metric / 方向 / 最小效应）：
        # 对比阶段据此核对「观测结果是否与训练前的预期一致」
        # 与「分析指标是不是预注册的主指标」，避免事后挑指标、
        # 事后解释方向。旧运行没有该记录时保持 None。
        preregistration = config_payload.get(
            "hypothesis_preregistration"
        )
        if not isinstance(preregistration, dict):
            preregistration = {}
        row["primary_metric"] = preregistration.get(
            "primary_metric"
        )
        row["hypothesis_direction"] = preregistration.get(
            "direction"
        )
        row["hypothesis_min_effect"] = preregistration.get(
            "min_effect"
        )
        # 预注册的等价界（--equivalence-margin 在训练前写入）：
        # TOST 的等价界越宽越容易判等价，看到数据后再放宽就能
        # 「制造」等价结论，因此分析期必须能核对它没有被改动。
        row["hypothesis_equivalence_margin"] = (
            preregistration.get("equivalence_margin")
        )
        # 预注册的对照基线（--hypothesis-baseline）：主指标/
        # 方向/最小效应都声明了，若对照臂可以事后挑，整个
        # 检验仍然可以被 baseline shopping 操纵。旧运行没有
        # 该字段时保持 None。
        row["hypothesis_baseline"] = preregistration.get(
            "baseline"
        )

        # 实验规模守卫（tokens_seen / tokens per param / epochs）：
        # 原型级结果不能外推为规模结论。
        row["scale_guard"] = config_payload.get("scale_guard")

        # 参考基线（uniform / unigram 在 val 上的同口径指标）：
        # 对比分析用它核对「所声明的基线是否真的强于无上下文
        # 预测器」，否则复杂模型战胜的只是稻草人。
        reference = config_payload.get("reference_baselines")
        row["reference_baselines"] = (
            reference if isinstance(reference, dict) else None
        )

        # 基线调参来源（--baseline-tuning-from 写入）：对比分析
        # 用它核对「基线是否真的被充分调过参」，没有该记录且
        # 又没有强于调优好的 n-gram 时，战胜基线说明不了问题。
        tuning = config_payload.get("baseline_tuning")
        row["baseline_tuning"] = (
            tuning if isinstance(tuning, dict) else None
        )

        # RQ3/RQ4 路由诊断（config.json 的 routing_analysis）：
        # 汇总两轮专家重合度与专家负载/路由熵，供跨运行对比。
        # 诊断只基于验证集固定窗口，测试集不参与；缺失时保持
        # None，不虚报指标。
        routing = config_payload.get("routing_analysis")
        row["routing_available"] = isinstance(routing, dict)
        for key in _ROUTING_ROW_FIELDS:
            row[key] = None
        if isinstance(routing, dict):
            rq3 = _as_dict(
                _as_dict(
                    routing.get("rq3_expert_overlap")
                ).get("summary")
            )
            rq4 = _as_dict(
                _as_dict(
                    routing.get("rq4_load_and_entropy")
                ).get("summary")
            )
            divergence = _as_dict(
                _as_dict(
                    routing.get("branch_divergence")
                ).get("summary")
            )
            row["routing_jaccard_branch"] = rq3.get(
                "second_round_jaccard_mean"
            )
            row["routing_slot_reuse_branch"] = rq3.get(
                "second_round_slot_reuse_mean"
            )
            row["routing_jaccard_token"] = rq3.get(
                "token_second_round_jaccard_mean"
            )
            row["routing_branch_self_reuse"] = rq3.get(
                "branch_self_reuse_share"
            )
            round1 = _as_dict(rq4.get("round1"))
            round2 = _as_dict(rq4.get("round2"))
            row["routing_r1_load_entropy"] = round1.get(
                "load_entropy"
            )
            row["routing_r2_load_entropy"] = round2.get(
                "load_entropy"
            )
            row["routing_r2_dead_experts"] = round2.get(
                "dead_experts"
            )
            row["routing_r2_router_entropy"] = round2.get(
                "router_entropy_mean"
            )
            row["routing_branch_cosine"] = divergence.get(
                "branch_cosine_mean"
            )

        # 受控变量协议：对比分析用它检查「除声明因子外，
        # 优化器 / 学习率 / 训练轮数 / 数据增强等设置是否一致」。
        row["protocol"] = experiment_protocol_from_payload(
            config_payload
        )
        # 记录原 config.json 中 comparison_protocol 实际写出的键：
        # 显式 null（如 cosine 调度下的 wsd_stable_steps、未启用
        # 文档 mask 时的 document_separator）是已记录的可比值，
        # 不能和旧运行缺少该键混为一谈。只有回退补齐的键才在
        # 值仍为 None 时标记为「未核对」。
        recorded_protocol = config_payload.get(
            "comparison_protocol"
        )
        row["protocol_recorded_keys"] = (
            sorted(str(key) for key in recorded_protocol)
            if isinstance(recorded_protocol, dict)
            else None
        )

        # 训练前初始化指纹与首批训练数据指纹：同种子下
        # 若两者不一致，结构/指标差异就不能全部归因于
        # 声明因子。旧运行没有这些记录时保持 None。
        initialization = config_payload.get("initialization")
        row["init_fingerprints"] = (
            initialization
            if isinstance(initialization, dict)
            else None
        )
        training_trace = config_payload.get("training_trace")
        row["training_trace"] = (
            training_trace
            if isinstance(training_trace, dict)
            else None
        )

        # 可复现性来源：代码指纹与数值环境（来自各运行
        # config.json 的 run_metadata）。跨代码版本或跨
        # Python/torch/CUDA/设备比较时，方法差异无法与实现/
        # 环境差异分离，对比分析必须能发现。
        metadata = config_payload.get("run_metadata")
        if not isinstance(metadata, dict):
            metadata = {}
        provenance_keys = (
            *_REPRODUCIBILITY_HARD_KEYS,
            *_REPRODUCIBILITY_INFO_KEYS,
            "pythonhashseed_at_start",
        )
        row["provenance"] = {
            key: metadata.get(key)
            for key in provenance_keys
        }
        row["provenance_recorded_keys"] = sorted(
            key for key in provenance_keys if key in metadata
        )

        # 执行顺序设计：套件父进程在训练前写入 design_plan.json，
        # 子进程把自己的分配（计划指纹/序号/区组位置）写入
        # config.json。分析期用它诊断时间漂移与「计划被替换」。
        assignment = config_payload.get("design_assignment")
        if not isinstance(assignment, dict):
            assignment = {}
        row["design_assignment"] = assignment or None
        row["design_plan_id"] = assignment.get("plan_id")
        row["design_plan_file_sha256"] = assignment.get(
            "plan_file_sha256"
        )
        row["design_order_scheme"] = assignment.get(
            "order_scheme"
        )
        row["design_order_seed"] = assignment.get("order_seed")
        row["design_order_index"] = assignment.get(
            "order_index"
        )
        row["design_block"] = assignment.get("block")
        row["design_block_position"] = assignment.get(
            "position_in_block"
        )
        original_metadata = config_payload.get(
            "original_run_metadata"
        )
        if not isinstance(original_metadata, dict):
            original_metadata = metadata
        row["run_started_utc"] = original_metadata.get(
            "timestamp_utc"
        )

        row["n_params"] = config_payload.get("n_params")

        efficiency = config_payload.get("efficiency") or {}
        if not isinstance(efficiency, dict):
            efficiency = {}
        row["latency_ms_per_forward"] = efficiency.get(
            "latency_ms_per_forward"
        )
        row["training_ms_per_step"] = efficiency.get(
            "training_ms_per_step"
        )
        row["flops_per_forward"] = efficiency.get(
            "flops_per_forward"
        )
        row["training_peak_memory_mb"] = efficiency.get(
            "training_peak_memory_mb"
        )
        row["actual_training_peak_memory_mb"] = (
            efficiency.get("actual_training_peak_memory_mb")
        )
        # 优先用真实训练循环峰值（含优化器状态）；旧运行没有
        # 该字段时才退回合成前向+反向峰值，最后才用进程 RSS。
        row["peak_memory_mb"] = (
            row["actual_training_peak_memory_mb"]
            if row["actual_training_peak_memory_mb"]
            is not None
            else (
                efficiency.get("training_peak_memory_mb")
                if efficiency.get("training_peak_memory_mb")
                is not None
                else efficiency.get("process_peak_rss_mb")
            )
        )

        records = read_metrics_records(
            run_dir / "metrics.jsonl"
        )
        final_record = None
        curve_record = None
        bad_case_record = None

        for record in records:
            step = record.get("step")
            if step == "final":
                final_record = record
            elif step == "curve_analysis":
                curve_record = record
            elif (
                step == "bad_cases"
                and record.get("split") == "val"
            ):
                # 只取 val：test 坏案例同样受尘封协议保护，
                # 不进入跨运行比较。
                bad_case_record = record

        row["val_loss"] = (
            final_record.get("val_loss")
            if final_record is not None
            else None
        )
        row["val_ppl"] = (
            final_record.get("val_ppl")
            if final_record is not None
            else None
        )
        row["val_bits_per_byte"] = (
            final_record.get("val_bits_per_byte")
            if final_record is not None
            else None
        )
        # 类平衡似然（macro NLL）：频率加权的 val_loss 之外，
        # 不平衡场景下必须有一份按类等权的似然口径。
        row["val_macro_nll"] = (
            final_record.get("val_macro_nll")
            if final_record is not None
            else None
        )
        row["val_macro_nll_chance"] = (
            final_record.get("val_macro_nll_chance")
            if final_record is not None
            else None
        )
        row["val_macro_nll_classes"] = (
            final_record.get("val_macro_nll_classes")
            if final_record is not None
            else None
        )
        row["val_token_accuracy"] = (
            final_record.get("val_token_accuracy")
            if final_record is not None
            else None
        )
        # micro F1 与 token accuracy 口径一致，但在 COMPARISON_
        # METRIC_KEYS 中被 --compare-metric 接受；缺这一行会让
        # val_micro_f1 的跨运行对比永远报「缺指标」。
        row["val_micro_f1"] = (
            final_record.get("val_micro_f1")
            if final_record is not None
            else None
        )
        row["val_macro_f1"] = (
            final_record.get("val_macro_f1")
            if final_record is not None
            else None
        )
        row["val_weighted_f1"] = (
            final_record.get("val_weighted_f1")
            if final_record is not None
            else None
        )
        # precision / recall（macro 与 weighted 口径）：假设以
        # 「召回率/精确率」判定时必须有对应指标可供对比。
        row["val_precision_macro"] = (
            final_record.get("val_precision_macro")
            if final_record is not None
            else None
        )
        row["val_precision_weighted"] = (
            final_record.get("val_precision_weighted")
            if final_record is not None
            else None
        )
        row["val_recall_macro"] = (
            final_record.get("val_recall_macro")
            if final_record is not None
            else None
        )
        row["val_recall_weighted"] = (
            final_record.get("val_recall_weighted")
            if final_record is not None
            else None
        )
        row["val_pr_auc_macro"] = (
            final_record.get("val_pr_auc_macro")
            if final_record is not None
            else None
        )
        # PR-AUC 随机水平（纳入类平均 prevalence）：不平衡下
        # PR-AUC 必须相对它解读，而不是当准确率看。
        row["val_pr_auc_macro_chance"] = (
            final_record.get("val_pr_auc_macro_chance")
            if final_record is not None
            else None
        )
        # PR-AUC lift = 绝对值 - 随机水平，是跨 prevalence
        # 可直接比较的一等口径；旧运行没有该字段时保持 None，
        # 不根据 chance 静默重算（最终指标可能来自旧评估）。
        row["val_pr_auc_macro_lift"] = (
            final_record.get("val_pr_auc_macro_lift")
            if final_record is not None
            else None
        )
        row["val_roc_auc_macro"] = (
            final_record.get("val_roc_auc_macro")
            if final_record is not None
            else None
        )
        # 多数类参考 accuracy（= 评估集中最高频类的 support 占比）：
        # 类别不平衡提示用，判断 accuracy/micro 口径是否被常数
        # 预测主导。
        row["val_majority_accuracy"] = (
            final_record.get("val_majority_accuracy")
            if final_record is not None
            else None
        )
        row["val_classes_present"] = (
            final_record.get("val_classes_present")
            if final_record is not None
            else None
        )
        row["curve_status"] = (
            curve_record.get("status")
            if curve_record is not None
            else None
        )
        # 曲线诊断数值：只看 status 只能知道「是否过拟合」，
        # 看不到过拟合多严重、最优点多早、泛化 gap 多大。
        # 这些字段直接来自 analyze_training_curve 的落盘结果，
        # 让跨运行比较能对齐「同一训练曲线口径」而不只是最终
        # 单点指标；旧记录缺字段时保持 None。
        row["curve_available"] = curve_record is not None
        for curve_key in _CURVE_ROW_FIELDS:
            row[f"curve_{curve_key}"] = (
                curve_record.get(curve_key)
                if curve_record is not None
                else None
            )

        # 坏案例记录（val）：供跨运行汇总稳定错误模式。旧运行
        # 只有部分字段时保持 None，不伪造缺失的归因。
        row["bad_case_available"] = bad_case_record is not None
        for bad_key in _BAD_CASE_ROW_FIELDS:
            row[f"bad_case_{bad_key}"] = (
                bad_case_record.get(bad_key)
                if bad_case_record is not None
                else None
            )

        # 数值完整性：失败的运行不能进入均值与显著性检验。
        # 旧记录没有新字段时用曲线里的 nonfinite 事件与
        # diverged 状态兜底；完全无记录则标 unknown，不臆测。
        def _record_value(name: str):
            if final_record is not None and name in final_record:
                return final_record.get(name)
            return None

        row["numerical_stop"] = _record_value(
            "numerical_stop"
        )
        row["numerical_polluted"] = _record_value(
            "numerical_polluted"
        )
        row["prior_numerical_stop"] = _record_value(
            "prior_numerical_stop"
        )
        final_nonfinite = _record_value("nonfinite_events")
        curve_nonfinite = (
            curve_record.get("n_nonfinite_events")
            if curve_record is not None
            else None
        )
        nonfinite_events = (
            final_nonfinite
            if final_nonfinite is not None
            else curve_nonfinite
        )
        row["nonfinite_events"] = nonfinite_events
        integrity = _record_value("numerical_integrity_ok")
        if integrity is not None:
            integrity = bool(integrity)
        failed = bool(
            row["numerical_stop"]
            or row["numerical_polluted"]
            or row["prior_numerical_stop"]
            or row["curve_status"] in ("diverged", "diverging")
            or (
                isinstance(nonfinite_events, int)
                and not isinstance(nonfinite_events, bool)
                and nonfinite_events > 0
            )
        )
        if integrity is False or failed:
            row["numerical_status"] = "failed"
        elif integrity is True:
            row["numerical_status"] = "ok"
        else:
            row["numerical_status"] = "unknown"
        row["numerical_integrity_ok"] = (
            False
            if row["numerical_status"] == "failed"
            else (
                True
                if row["numerical_status"] == "ok"
                else None
            )
        )
        row["early_stopped"] = (
            final_record.get("early_stopped")
            if final_record is not None
            else None
        )
        # 实际有效训练长度与选型结果：受控变量检查必须核对
        # 「实际训练了多久」而不只是计划步数，且 final/test
        # 指标是否来自验证集选型的模型要能从 final 记录恢复
        # （config 顶层记录可能因崩溃缺失）。
        row["trained_steps"] = (
            final_record.get("trained_steps")
            if final_record is not None
            else None
        )
        row["optimizer_steps"] = (
            final_record.get("optimizer_steps")
            if final_record is not None
            else None
        )
        row["end_step"] = (
            final_record.get("selected_step")
            if final_record is not None
            else None
        )
        row["selected_model"] = (
            final_record.get("selected_model")
            if final_record is not None
            else None
        )

        protocol = row.get("protocol")
        if isinstance(protocol, dict):
            if row["trained_steps"] is not None:
                protocol["trained_steps"] = row["trained_steps"]
            if row["optimizer_steps"] is not None:
                protocol["optimizer_steps"] = row["optimizer_steps"]
            if row["selected_model"] == "best_val":
                protocol["model_selection"] = (
                    "best_val_with_last_fallback"
                )
            elif row["selected_model"] == "last":
                protocol["model_selection"] = "last_step"

        # config/metrics 来自旧版本或手工编辑的文件，可能含
        # NaN/Inf（Python json 默认接受这些字面量）。它们进入
        # 对比报告后会让严格 JSON 落盘失败，也会污染下游聚合；
        # 统一把非有限浮点转成 None，保留字段与有限大整数精度。
        rows.append(_json_safe(row))

    return rows


def print_comparison(rows: List[Dict[str, object]]) -> None:
    """
    以对齐表格打印多个运行的汇总指标。

    只展示 val 口径指标（尘封协议：test 结果只随单个运行的
    metrics.jsonl 报告，绝不并排对比）；除 val loss 外同时
    给出类平衡似然（macroNLL，按出现类等权）、token accuracy
    （micro 口径）与 macro F1：字节分布高度不平衡时 accuracy
    会被高频字节抬高、频率加权的 loss 也几乎只反映高频字节，
    必须类平衡口径与分类指标一起看；完整口径（micro / macro /
    weighted、PR-AUC 等）见各运行 metrics.jsonl。

    """
    # 运行名与模式名不能截断：local_base 与 local_base_k2 在
    # 20/9 字符的固定列宽下会显示成同一前缀，读者无法区分
    # 不同实验臂。列宽按实际内容扩展。
    run_width = max(
        20,
        max(
            (len(str(row.get("run"))) for row in rows),
            default=3,
        ),
    )
    mode_width = max(
        9,
        max(
            (len(str(row.get("mode"))) for row in rows),
            default=4,
        ),
    )
    header = (
        f"{'run':<{run_width}} {'mode':<{mode_width}} "
        f"{'params':>9} "
        f"{'val_loss':>9} {'macroNLL':>9} {'val_bpb':>8} "
        f"{'acc':>6} "
        f"{'macroF1':>8} "
        f"{'lat(ms)':>9} {'train(ms)':>10} {'GFLOPs':>8} "
        f"{'mem(MB)':>9} {'numerical':<10} {'curve':<18}"
    )
    print(header)
    print("-" * len(header))

    def _value(value, spec=".4f", scale=1.0):
        # config/metrics 里的数值可能损坏（含超出 float 范围的
        # 整数或 NaN/Inf）；展示层按缺失值处理，不能让一行坏
        # 记录中断整张对比表。
        return _format_finite(value, spec, scale)

    for row in rows:
        flops = _finite_float(row.get("flops_per_forward"))
        gflops = (
            f"{flops / 1e9:.3f}"
            if flops is not None
            else "-"
        )
        print(
            f"{str(row.get('run')):<{run_width}} "
            f"{str(row.get('mode')):<{mode_width}} "
            f"{str(row.get('n_params')):>9} "
            f"{_value(row.get('val_loss')):>9} "
            f"{_value(row.get('val_macro_nll')):>9} "
            f"{_value(row.get('val_bits_per_byte'), '.4f'):>8} "
            f"{_value(row.get('val_token_accuracy'), '.4f'):>6} "
            f"{_value(row.get('val_macro_f1'), '.4f'):>8} "
            f"{_value(row.get('latency_ms_per_forward'), '.4f'):>9} "
            f"{_value(row.get('training_ms_per_step'), '.1f'):>10} "
            f"{gflops:>8} "
            f"{_value(row.get('peak_memory_mb'), '.1f'):>9} "
            f"{str(row.get('numerical_status')):<10} "
            f"{str(row.get('curve_status')):<18}"
        )

    # RQ3/RQ4 路由诊断：跨越单次运行的结论必须能看到每个运行的
    # 路由指标，而不是只留在各自 config.json 的定性诊断里。
    # 旧运行或 dense 基线没有路由记录时明确注明，不虚报。
    routing_rows = [
        row for row in rows if row.get("routing_available")
    ]
    if routing_rows:
        print()
        print(
            "[routing] RQ3/RQ4 路由诊断（val 固定窗口，"
            "测试集不参与；聚合与显著性检验见 --compare "
            "的对比分析）"
        )
        routing_run_width = max(
            20,
            max(
                (
                    len(str(row.get("run")))
                    for row in routing_rows
                ),
                default=3,
            ),
        )
        routing_header = (
            f"{'run':<{routing_run_width}} {'jac(branch)':>11} "
            f"{'slotReuse':>9} {'selfReuse':>9} "
            f"{'r1LoadH':>8} {'r2LoadH':>8} {'dead':>5} "
            f"{'routerH':>8} {'cosine':>8}"
        )
        print(routing_header)
        print("-" * len(routing_header))

        def _rv(value, spec=".4f") -> str:
            return _format_finite(value, spec)

        for row in routing_rows:
            print(
                f"{str(row.get('run')):<{routing_run_width}} "
                f"{_rv(row.get('routing_jaccard_branch')):>11} "
                f"{_rv(row.get('routing_slot_reuse_branch')):>9} "
                f"{_rv(row.get('routing_branch_self_reuse')):>9} "
                f"{_rv(row.get('routing_r1_load_entropy')):>8} "
                f"{_rv(row.get('routing_r2_load_entropy')):>8} "
                f"{_rv(row.get('routing_r2_dead_experts'), '.0f'):>5} "
                f"{_rv(row.get('routing_r2_router_entropy')):>8} "
                f"{_rv(row.get('routing_branch_cosine')):>8}"
            )
        missing_routing = [
            str(row.get("run"))
            for row in rows
            if not row.get("routing_available")
        ]
        if missing_routing:
            print(
                "  [note] 以下运行没有路由诊断记录（dense 基线"
                "无 MoE 路由，或旧运行/--skip-routing-analysis）："
                + "; ".join(missing_routing)
            )


# ============================================================
# Comparison analysis: controlled variables / seeds / statistics
# ============================================================

# 受控变量协议：对比 A 方法与 B 方法时，除声明为实验因子的
# 模块外，这些设置必须完全一致。每轮训练把这些值写进
# config.json 的 comparison_protocol 字段；--compare 逐项核对。
#
# comparison_family 把「神经网络运行」与「统计基线运行」
# （ngram，无优化器、无训练轮数）分开：受控变量检查只在
# 同一 family 内部进行。
COMPARISON_PROTOCOL_KEYS: Tuple[str, ...] = (
    # mode 是最核心的结构差异：它默认是实验因子，但调用方一旦
    # 用 --compare-factors 收窄因子列表而漏掉 mode，跨模式运行
    # 就会绕过受控变量核对。把它写进协议后，只有显式声明为
    # 因子时才允许不同。
    "mode",
    # 初始化方案决定同种子下共享层是否真的从同一组权重出发；
    # 跨方案比较会把初始化差异混入方法效应，必须受控。
    "init_scheme",
    "optimizer",
    "optimizer_betas",
    "optimizer_eps",
    "lr",
    "lr_schedule",
    # WSD（论文 3.1 节）的稳定期终点与衰减终点决定整条学习率
    # 轨迹；cosine 运行时这两个值为 None。
    "wsd_stable_steps",
    "wsd_final_lr_ratio",
    "warmup_steps",
    "total_steps",
    # 实际有效训练长度：total_steps 只是计划值，早停或
    # non-finite 跳步会让各臂实际执行的步数/优化器更新次数
    # 不同；这些字段在训练结束时由 compare_runs 从 final
    # 记录注入协议并逐项核对（缺失时显式列为未核对）。
    "trained_steps",
    "optimizer_steps",
    "weight_decay",
    "grad_clip",
    "batch_size",
    # 文档级 segment mask 改变注意力可见性；分隔符字节决定
    # 文档边界位置，两者都是模型语义的一部分。
    "document_masks",
    "document_separator",
    "data_augmentation",
    # 早停设置决定「实际训练轮数」：total_steps 相同但早停
    # patience 不同时，某个运行可能提前结束，与「训练同样久」
    # 不是同一口径，必须作为受控变量核对。
    "early_stop_patience",
    "early_stop_min_delta",
    # 数值条件与实现开关：混合精度 dtype 与设备类型会改变
    # 浮点归约/精度（同一方法在 CPU 与 GPU 上不是同一数值
    # 环境），activation checkpointing 与 torch.compile 会
    # 改写反传/内核路径，跨运行对比时应完全一致。
    "amp_dtype",
    "device_type",
    "allow_tf32",
    "grad_checkpoint",
    "compile",
    "seq_len",
    "d_model",
    "n_heads",
    # GQA 的 KV 头数决定注意力容量与 KV cache；同一 mode
    # 下换 KV 头数就是换架构，不能只按 mode 归组后被当成
    # 同一实验单元聚合。
    "n_kv_heads",
    "n_layers",
    "n_experts",
    "expert_hidden",
    "top_k",
    # k1/k2/balance_coef/dense_fnn_hidden 是最容易悄悄改变结果的
    # 结构/损失项：它们默认被声明为实验因子，但只要调用方把
    # --compare-factors 改成更窄的列表，就必须退化为受控变量
    # 逐项核对，否则「延迟合并」的对比会混入分支几何（k1/k2）
    # 或均衡强度（balance_coef）的差异。
    "k1",
    "k2",
    "balance_coef",
    # 注意：balance_width_normalization 依 mode 而变（只有
    # local_base 有折算问题），不能作为跨模式受控变量；
    # 新旧 local_base 的均衡强度差异由 balance_strength_report
    # 在有效宽度/强度层面点名。
    "dense_fnn_hidden",
    "residual_scale",
    # 循环区域残差缩放口径（paper=1/r vs global）直接改变
    # 架构语义；它不随 mode 唯一确定，必须作为受控变量。
    # loop_residual_scale / loop_count 由该口径与 mode 派生，
    # 不重复列入，避免跨模式对比被派生值误报为违规。
    "residual_scaling",
    "val_fraction",
    "test_fraction",
    # 切分口径（contiguous / chronological）决定“前缀”能否
    # 被解释为时间切分；同样的 split_sha256 也可能来自不同
    # 声明，必须逐项核对。
    "split_policy",
    "group_separator",
    "deduplicate_train_groups",
    "drop_train_shared_chunks",
    "drop_train_near_duplicate_groups",
    "near_duplicate_threshold",
    "near_duplicate_shingle_bytes",
    # 训练集清洗是否读取 test 内容：默认 False（test 尘封）；
    # True 会让训练样本集合依赖 test，必须作为协议差异核对。
    "clean_train_against_test",
    "drop_train_corrupt_groups",
    "drop_train_corrupt_bytes",
    "drop_train_degenerate_groups",
    "drop_train_degenerate_runs",
    # 源文件指纹相同不等于实际进入各 split 的字节段相同：
    # 群组吸附、清洗实现或切分代码变化都会改变 train/val/test
    # 的内容。逐 split 指纹把「同一文件 + 同一比例」背后的
    # 实际划分也纳入受控变量，避免两次运行在不同验证/测试
    # 数据上比较却显示协议一致。
    "split_sha256",
    # 清洗后的有效训练集指纹：同一 split/开关下清洗实现变化
    # 会改变实际参与训练的字节，必须能被跨运行核对。
    "effective_train_sha256",
    # 时序隔离记录：绝对边界与顺序让「按时间先后切分、无重叠」
    # 可以从 config 独立复核，而不是只靠比例与内容指纹推断。
    "split_isolation",
    # 泄露豁免会改变「允许哪些数据进入训练」的资格判断；
    # 同一对比里有的运行显式豁免、有的没有，不能算同一协议。
    "allow_data_leakage",
    # 允许 val/test 内容参与训练集清洗、允许实体跨 split 重叠，
    # 都是会改变训练数据边界的显式豁免。两个运行一个允许一个
    # 不允许时，split 指纹即使碰巧相同也不是同一数据口径，
    # 不能把差异归因到方法本身。
    "allow_eval_content_for_cleaning",
    "allow_entity_overlap",
    # 标签噪声豁免会改变 test 是否被封条拒绝；两个运行最终
    # 指标的可信资格不同，同样不能算同一评估口径。
    "allow_corrupt_test_labels",
    "allow_eval_duplicates",
    "eval_interval",
    "eval_batches",
    # bootstrap 重采样次数决定验证/测试置信区间的蒙特卡洛
    # 精度：不同运行用不同的 --eval-bootstrap 会得到不同宽度
    # 的误差线，跨运行比较误差线时口径不再一致。
    "eval_bootstrap",
    # 重采样单位（i.i.d. 窗口 vs 移动块）会改变区间宽度与
    # 自相关处理；同一 bootstrap 次数但 block 不同不是同一
    # 评估口径。
    "eval_bootstrap_block",
    # 周期验证是否计算 PR-AUC / lift / ROC-AUC：显式
    # --periodic-auc 与 AUC 选型都会生成共同步数选型无关 AUC 指标；
    # 一个跑有一个没跑时，敏感性分析的可比口径不同。
    "periodic_auc",
    "data_sha256",
    # final/test 评估所用模型的选型口径：旧运行（无记录）是
    # 最后一步参数，新运行是验证集选中的最优验证点；两者混在
    # 一起对比不是同一口径，必须被检查发现。
    "model_selection",
    # 选型/早停依据的指标：默认 val_loss，但预注册主指标是
    # macro F1 等分类指标时必须能按同一指标选 checkpoint，
    # 否则最终模型不是按假设的判定口径选出来的。
    "selection_metric",
)

