    parser.add_argument(
        "--allow-data-leakage",
        action="store_true",
        help=(
            "显式允许跨 split 重复内容继续运行：默认情况下"
            "只要审计发现 train/val/test 之间的重复窗口或"
            "重复群组（泄露级问题），训练入口和测试集解封"
            "都会直接拒绝。仅在你确认这些重复在业务上不是"
            "泄露时使用；豁免会记录进 config.json"
        ),
    )
    parser.add_argument(
        "--allow-corrupt-test-labels",
        action="store_true",
        help=(
            "显式允许在含非法 UTF-8/NUL/越界 token 的测试集上"
            "解封评估：测试集不参与清洗，默认拒绝在这种标签"
            "噪声上产出最终结论；仅当这些字节确实是目标分布"
            "的一部分时使用，豁免会记录进 config.json"
        ),
    )
    parser.add_argument(
        "--allow-eval-duplicates",
        action="store_true",
        help=(
            "显式允许在 val/test 内部含完全重复群组时继续运行："
            "重复评估样本会虚增有效样本量、让固定窗口 bootstrap "
            "区间偏窄，验证集重复还会放大选型过拟合。默认拒绝"
            "训练/拒绝解封测试集；仅当重复确实属于目标分布时"
            "使用，豁免会记录进 config.json"
        ),
    )

    parser.add_argument("--seq-len", type=int, default=128)
